import{a as p}from"./chunk-WWKXR2II.js";var g={aggregate_points_to_h3_cell:`<h2>Aggregate points to H3 cells</h2><p><strong>A geoprivacy teaching step.</strong> It takes points and gives back hexagonal cells, each carrying how many of the points fall in it, leaving out any cell with fewer than a stated number.</p><h3>What it does</h3><p>Each point is placed in its cell of the H3 grid, a fixed worldwide grid of hexagons, at the resolution you choose. Cells are counted, and a cell holding fewer points than the minimum is left out, so no released cell points at one or two households. A resolution 9 cell is about 0.1 km\xB2; a resolution 7 cell about 5 km\xB2.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>points</strong></td><td>the points to count</td></tr></tbody></table><p>Out come the cells, each with its count. Draw them on a Map.</p><h3>How to use it</h3><p>1. Connect the points. 2. In <strong>Configure\u2026</strong>, choose the resolution (0 coarsest, 15 finest) and the fewest points a cell must hold. 3. Run. The Result says how many cells were kept.</p><h3>What it will not do</h3><ul><li><strong>It counts locations, not what they carry.</strong> 250 addresses carrying 489 deaths give counts that add to 250.</li><li><strong>It does not make data safe to share.</strong> A cell with many points can still identify someone, and the points it leaves</li></ul><p>out are still in the project.</p><ul><li><strong>It does not choose the resolution.</strong> Coarser cells hide more and show less.</li></ul><h3>How it was checked</h3><p>The lab's <a href="https://digital-twin-ph.github.io/validation-lab/lab/index.html?path=21-hex-vs-h3py.ipynb" target="_blank" rel="noopener noreferrer">hex notebook</a> recounts the cells with h3-py.</p><h3>History</h3><h4>2026-11-26 \xB7 Map shades the cells by their count (0.7.0)</h4><p>Each cell carries its count of points, and Map shades and keys the cells by it, as <strong>Points in the cell</strong>, instead of drawing every released cell in one blue. Show me how ends on the same classes and ranges.</p><h4>2026-11-26 \xB7 Show me how ends on the scale (0.6.0)</h4><p>The last step colours each cell by the same classes Map uses for its count of homes, with a key giving each colour's range, where it was shaded with no key.</p><h4>2026-11-23 \xB7 Show me how (0.4.0)</h4><p><strong>Configure\u2026</strong> offers <strong>Show me how it works</strong>: six made-up homes in three H3 cells at the resolution set: the cells left out for holding too few, and the cells the step makes with their counts.</p><h4>2026-11-22 \xB7 On the standard (0.3.0)</h4><p>Moved to the standard Inspector: the resolution and the minimum count are in <strong>Configure\u2026</strong>, and the sentence says it is a teaching step, not a privacy guarantee.</p>`,apply_ruleset:"<h2>Apply ruleset</h2><p><strong>Rules over records.</strong> Each rule says <em>if</em> some conditions hold <em>then</em> a record gets a category, such as a band, or a new value computed from its columns. The rules are written in the step's dialog, or read from a published ruleset.</p><h3>What it does</h3><p>It checks every rule against every record and gives each record what the rules concluded, as new columns. A record no rule matched keeps no conclusion, and the run says how many.</p><h3>What you connect</h3><p><strong>Records</strong>: a table, points or polygons. Choose which under <em>Records arrive as</em>, in <strong>Configure\u2026</strong>, then the step that feeds it under <em>Inputs</em>. A table imported <strong>wide</strong>, one row per subject and a column per variable, is read that way: one record per subject, its columns as the file named them. It gives back the same records with the new columns.</p><h3>How to use it</h3><p><strong>Configure\u2026</strong> opens the step's dialog. On a new step, choose a published ruleset, or <em>Write rules for this step</em>, and <strong>Apply</strong>: rules of your own open in the rules dialog. There, <strong>Records and columns</strong> comes first: how the records arrive, each column's kind and its unit. Then the settings, the rules, and the otherwise. Nothing changes until <strong>Apply</strong>.</p><p><strong>A published ruleset reads named columns.</strong> Under <strong>Which column holds each</strong>, each input the ruleset declares has a menu of your records' columns; left as it is, the ruleset's own column name is read. <em>7-1-7 timeliness</em> reads four dates, emergence, detection, notification and early response complete: on a line list such as MERS-CoV, South Korea, 2015, choose <code>dt_onset</code>, <code>dt_diag</code> and <code>dt_report</code> for the first three. A chosen column the records do not carry stops the run, naming the columns they do. The run's record states which column was read for each input.</p><p><strong>Each part of a rule is a block</strong>, with its word and its colour, so a rule's shape reads at a glance:</p><table><thead><tr><th>Block</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>if</strong> (blue)</td><td>A column, a comparison (see <em>Comparisons</em> below) and a value: a typed number or one of the step's settings</td></tr><tr><td><strong>+ and</strong></td><td>Conditions in one <em>if</em> block, which must all hold</td></tr><tr><td><strong>or</strong> (purple)</td><td>An alternative <em>if</em> block, any of which will do</td></tr><tr><td><strong>then</strong> (green), a category</td><td>A new column and the value a matching record gets: <em>band</em> is <em>Short</em></td></tr><tr><td><strong>then</strong>, a computed value</td><td>A new column and a sum: <em>houses without a death</em> is <em>houses</em> minus <em>deaths</em>. Plus, minus, times or divided by; each side a column, a value another rule computed, or a typed number</td></tr><tr><td><strong>otherwise</strong> (amber)</td><td>A column's value for a record no rule gave one: <em>class</em> is <em>Cannot be classified</em></td></tr></tbody></table><p><strong>Make bands\u2026</strong> writes the rules for bands of a number: choose the number column, the value the first band starts at, and the cut points, rising. <em>0</em> and <em>1, 5, 10, 15</em> write five rules, <em>0</em>, <em>1 to 4</em>, <em>5 to 9</em>, <em>10 to 14</em> and <em>15 and over</em>, each at least its lower bound and less than its upper: no gap and no overlap. Whole numbers are labelled as age bands are written; decimals <em>1.5 to under 3</em>. The rules are then ordinary rules, to read and change; a value below the start gets no band.</p><p>Each block also has its own edge, solid, dotted, double or dashed, so the blocks are told apart without colour. <strong>The comparison in a condition is keyed by its family</strong> the same way: comparisons of numbers (<em>is more than</em>, <em>is at most</em>, <em>is less than</em>, <em>is at least</em>) teal; <em>is</em> and <em>is not</em> slate; <em>is recorded</em> and <em>is not recorded</em> rose, with a dotted edge.</p><p><strong>A rule can read a category another rule gave.</strong> Once a rule concludes <em>lab</em> is <em>positive</em>, <em>lab</em> is offered as a column a condition can read, by that name. A category reads in the table as it was typed: <em>Cannot be classified</em>.</p><p><strong>Is not</strong> matches a recorded value that differs: <em>rash is not No</em> matches <em>Yes</em> and <em>Unknown</em>. A value not recorded never matches <em>is not</em>; ask <em>is not recorded</em> for that.</p><p><strong>Otherwise</strong>, one per column, gives the column a value where no rule did. It waits for the columns its rules read: a <em>class</em> read from <em>lab result</em> takes its otherwise only after <em>lab result</em> has had its own. So an ordered classification, such as WHO's for measles, is written as columns in stages, each a few rules and an otherwise. The rulesets worked example builds one, <em>Which suspected cases meet the case definition?</em> An otherwise never settles two rules that disagree: that record stays without a value, and is named.</p><p><strong>+ Add a value computed for every record</strong> writes a rule with no condition: every record gets the value.</p><p><strong>A new column states its unit</strong>, and what it measures, in the two boxes after the sum: <em>deaths per 10,000 houses</em>. The table the step gives out carries both. A new column without a unit is said in the dialog and the run.</p><p><strong>Settings.</strong> <em>+ Add a setting</em> gives the step a number the rules compare against, such as a fever threshold of 38 degrees Celsius: a name, a value and a unit. A condition then reads <em>temperature_c is more than fever</em>, and the threshold can be changed without rewriting a rule.</p><p><strong>Kinds.</strong> Each column is read as a number, a date, a category, or true or false, offered from its values and changed under <em>Records and columns</em>. <strong>A date</strong> is written year-month-day; one date minus another gives <strong>days</strong>, said as the new column's unit: a serial interval, or the days from onset to report. A date is not added to, multiplied, or compared with a number, and a day that does not exist, such as 1861-02-30, is reported unreadable rather than moved into March. A file that stores counts as text, &quot;34&quot;, offers them as a category: say they are a number, and the text is reported unreadable at the run, where <strong>Data quality</strong> can read it as numbers.</p><p><strong>A date and time.</strong> A column can be read as a date and time, written <code>1940-04-19T00:30</code>. Where a line list writes the date and the time apart, and not in that form, a rule puts them together: choose <strong>a date and time</strong> as the conclusion, then the date column and how it writes dates (<em>month/day</em>, <em>day/month</em>, either with the year, or <em>year-month-day</em>), the year where the column has none, and the time column on its clock (<em>12-hour</em>, as <code>8:00 PM</code>, or <em>24-hour</em>, as <code>20:00</code>). Where every record shares one date the source gives, such as the evening of a church supper, choose <em>one date for every record</em> and type it. A value that does not fit what was declared is never guessed: the record gets no date and time, and the step says which record and what it saw, such as <code>&quot;12:00 AM*&quot; is not a 12-hour time</code>. Times have no time zone: they are the record's local times, as written. One date and time minus another names its unit, <strong>days, hours or minutes</strong>: Oswego's hours from the meal to onset, a median of 4. A date is not taken from a date and time, which would read the date as midnight.</p><p><strong>Units.</strong> Each column the rules read states its unit, under <em>Records and columns</em>. A setting compared with a column must be in the column's unit, and a sum or difference must be of two columns in the same unit; either is refused while the rule is written. Columns the rules do not read need no unit.</p><p><strong>One rule can read what another computed.</strong> <em>deaths per house</em> is deaths divided by houses; <em>deaths per 10,000 houses</em> is deaths per house times 10,000. The order the rules are listed in does not matter.</p><p><strong>A rule can read the previous row.</strong> <em>new cases</em> is <em>cumulative_cases</em> minus <em>cumulative_cases in the previous row</em>. Such a rule needs the records sorted, which is set above the rules:</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Sort by</strong></td><td>The column the rows are put in order by. Date columns are offered first. The file's own order is never used</td></tr><tr><td><strong>Within each</strong></td><td>The columns that say whose rows these are, such as the place: each place's rows are sorted, and a row's previous one is its own place's</td></tr><tr><td><strong>The previous row is</strong></td><td><em>The row recorded before</em>, or <em>the day</em>, <em>the week</em> or <em>the month before</em>. Where that period has no row, the value is empty, and counted</td></tr></tbody></table><p>The table comes out in this order. The preview is then <strong>Before</strong>, <strong>Sorted</strong> and <strong>After</strong>.</p><p><strong>Before and after.</strong> The dialog's Preview shows the records as they arrive and as these rules would leave them, on every edit: each new column, and which rule each record matched. Each rule's heading says how many records it matched. The first 50 records are drawn; the counts are of all of them.</p><h3>Comparisons</h3><table><thead><tr><th>In the editor</th><th>Means</th><th>Example</th><th>Matches</th></tr></thead><tbody><tr><td><strong>is (=)</strong></td><td>equal to</td><td><em>rash</em> is <em>Yes</em></td><td>records whose rash is Yes</td></tr><tr><td><strong>is not (\u2260)</strong></td><td>a recorded value other than this</td><td><em>rash</em> is not <em>No</em></td><td>Yes and Unknown; not a rash left blank</td></tr><tr><td><strong>is more than (&gt;)</strong></td><td>greater than</td><td><em>temperature_c</em> is more than <em>38</em></td><td>38.1 and over; not 38</td></tr><tr><td><strong>is at least (\u2265)</strong></td><td>greater than or equal to</td><td><em>days_to_detect</em> is at least <em>8</em></td><td>8 and over</td></tr><tr><td><strong>is less than (&lt;)</strong></td><td>less than</td><td><em>age</em> is less than <em>5</em></td><td>4.9 and under; not 5</td></tr><tr><td><strong>is at most (\u2264)</strong></td><td>less than or equal to</td><td><em>days_to_detect</em> is at most <em>7</em></td><td>7 and under: 7-1-7's target met</td></tr><tr><td><strong>contains any of</strong></td><td>the text holds one of the words, ignoring capitals</td><td><em>chief_complaint</em> contains any of <em>vomit, n/v, diarrh</em></td><td>&quot;N/V/D&quot;, &quot;Vomitting x2&quot;</td></tr><tr><td><strong>contains none of</strong></td><td>the text holds none of the words</td><td><em>chief_complaint</em> contains none of <em>pregnan</em></td><td>every complaint not naming pregnancy</td></tr><tr><td><strong>has an item starting with any of</strong></td><td>some code or word in the text, between <code>;</code>, <code>/</code>, <code>&amp;</code> or spaces, begins with one of the words</td><td><em>discharge_diagnosis</em> has an item starting with any of <em>J10, J11</em></td><td>&quot;R50.9;J10.1&quot;; not &quot;XJ10&quot;</td></tr><tr><td><strong>has no item starting with any of</strong></td><td>no code or word in the text begins with one of the words</td><td><em>discharge_diagnosis</em> has no item starting with any of <em>J10, J11</em></td><td>&quot;A08.1&quot;; not &quot;A08.1;J11.1&quot;</td></tr><tr><td><strong>is recorded</strong></td><td>the column has a readable value</td><td><em>dt_diag</em> is recorded</td><td>records with a diagnosis date</td></tr><tr><td><strong>is not recorded</strong></td><td>the column is blank or unreadable</td><td><em>dt_diag</em> is not recorded</td><td>records with no diagnosis date</td></tr></tbody></table><p>The four comparisons of size, &gt;, \u2265, &lt; and \u2264, are offered for numbers, and for the days between two dates; <em>is</em> and <em>is not</em> for categories and for true or false too; <em>contains any of</em>, <em>contains none of</em> and the two <em>item</em> comparisons for text, the words separated by commas. A word matches inside a longer one: <em>diarrh</em> finds <em>diarrhea</em> and <em>diarrhoea</em>. Put a word in double quotes to keep its spaces: <em>&quot; flu &quot;</em> finds <em>stomach flu today</em> and not <em>influenza</em>. The start and end of the text are not spaces, so <em>&quot; flu &quot;</em> does not find <em>stomach flu</em> alone. A starting word for the two <em>item</em> comparisons holds no spaces, <code>;</code>, <code>/</code> or <code>&amp;</code>, since those separate the items. A record whose column is not recorded matches none of the first six: it is neither more nor less than 7. Ask <em>is not recorded</em> for it.</p><h3>The rules as JSON</h3><p><strong>JSON</strong> beside <strong>Rules</strong> shows the same ruleset as text: its title, the columns it reads with their kinds, its settings, its rules and each column's default. Type in it, or <strong>Upload (JSON)</strong> a file; <strong>Download (JSON)</strong> keeps one.</p><ul><li><strong>Checked as you type.</strong> After a pause, the text is read and checked: where the JSON breaks (*line 20: a comma is</li></ul><p>missing after the value of &quot;comparator&quot;*), then whether the rules can run (a field not declared, a comparison that does not exist, words left out). Each problem is listed with its line and marked beside it; choosing one goes there.</p><ul><li><strong>The two views are one ruleset.</strong> Valid JSON is the rules, at once. While it has a problem, the rules stay as they</li></ul><p>were last valid, Apply waits, and the Rules view says so.</p><ul><li><strong>Brackets close themselves.</strong> Typing <code>{</code>, <code>[</code> or <code>&quot;</code> adds its partner; typing the partner steps over it; Backspace</li></ul><p>between a pair removes both; Enter between them opens an indented line; selected text is wrapped.</p><ul><li><strong>Colours.</strong> Names are bold and blue, text green, numbers brown, <em>true</em>, <em>false</em> and <em>null</em> purple; a line with a</li></ul><p>problem is tinted. Every colour is readable in both themes. <strong>Colours</strong> turns them off.</p><ul><li><strong>Start from a template\u2026</strong> loads a small ruleset that runs as it is, on this step's own columns where it has the kind</li></ul><p>each needs: categories from words, bands from a number, days between two dates against a target, or one column divided by another.</p><ul><li><strong>Arriving columns</strong>, beside the text: each column the connected step sends, with its kind and a few of its values,</li></ul><p>marked <em>declared</em> where <code>fields</code> names it. <strong>Add to fields</strong> writes its entry, spelled as the column is. A declared column that does not arrive is listed under <em>Declared but not arriving</em>, and the check names it, with the nearest arriving column.</p><p>A file is a ruleset a person wrote: what it must not be read as goes with it.</p><h3>Writing rules as JSON</h3><p>A ruleset is one object with these parts. <strong>Bold</strong> ones are required.</p><table><thead><tr><th>Part</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>What the rules decide, in words</td></tr><tr><td><strong>mustNotBeReadAs</strong></td><td>What the result must not be taken to mean, such as <em>a diagnosis</em></td></tr><tr><td><strong>fields</strong></td><td>The columns the rules read: <code>attribute</code> as the file spells it, <code>predicate</code> the name the rules use (<code>fwa:</code> and the column), and <code>kind</code>: <code>number</code>, <code>boolean</code>, <code>term</code> (text or a category), <code>date</code> or <code>datetime</code>. A number also gives its <code>unit</code></td></tr><tr><td>parameters</td><td>Settings: numbers a person can change without rewriting a rule, each with a <code>name</code>, its <code>meaning</code> and unit</td></tr><tr><td><strong>rules</strong></td><td>The rules, below</td></tr><tr><td>otherwise</td><td>A column's value where no rule gave it one</td></tr><tr><td>order</td><td>The order records are read in, where a rule reads the previous row</td></tr></tbody></table><p>A downloaded file starts with <code>&quot;$schema&quot;</code>, the address of the [schema](../../schemas/authored-ruleset.schema.json): an editor such as VS Code reads it and offers the parts, kinds and comparisons as you type.</p><h4>A rule</h4><p>A rule says <strong>when</strong> and <strong>then</strong>. <code>any</code> lists alternatives, and the rule holds when any one of them does; each alternative's <code>all</code> lists conditions that must all hold. <code>then</code> says what the rule gives.</p><p>``<code>json { &quot;title&quot;: &quot;Syndrome from the chief complaint&quot;, &quot;mustNotBeReadAs&quot;: &quot;a diagnosis&quot;, &quot;fields&quot;: [{&quot;attribute&quot;: &quot;chief_complaint&quot;, &quot;predicate&quot;: &quot;fwa:chief_complaint&quot;, &quot;kind&quot;: &quot;term&quot;}], &quot;rules&quot;: [ {&quot;any&quot;: [{&quot;all&quot;: [{&quot;field&quot;: &quot;fwa:chief_complaint&quot;, &quot;comparator&quot;: &quot;contains&quot;, &quot;value&quot;: &quot;vomit, diarrh, n/v&quot;}]}], &quot;then&quot;: [{&quot;predicate&quot;: &quot;fwa:syndrome&quot;, &quot;value&quot;: &quot;gastrointestinal&quot;}]} ], &quot;otherwise&quot;: [{&quot;predicate&quot;: &quot;fwa:syndrome&quot;, &quot;value&quot;: &quot;other&quot;}] } </code>``</p><p>Visits whose complaint holds <em>vomit</em>, <em>diarrh</em> or <em>n/v</em> are gastrointestinal; every other visit is other.</p><h4>Every comparison</h4><table><thead><tr><th><code>comparator</code></th><th>Means</th><th>For</th></tr></thead><tbody><tr><td><code>equals</code></td><td>is</td><td>every kind</td></tr><tr><td><code>notEquals</code></td><td>is not: a recorded value other than this one</td><td>every kind</td></tr><tr><td><code>greaterThan</code>, <code>notGreaterThan</code></td><td>is more than; is at most</td><td>numbers</td></tr><tr><td><code>lessThan</code>, <code>notLessThan</code></td><td>is less than; is at least</td><td>numbers</td></tr><tr><td><code>contains</code></td><td>holds any of the words, separated by commas, ignoring capitals</td><td>text</td></tr><tr><td><code>notContains</code></td><td>holds none of the words</td><td>text</td></tr><tr><td><code>startsWith</code></td><td>has an item starting with any of the words: each part of the text between <code>;</code>, <code>/</code>, <code>&amp;</code> or spaces is an item, such as each code in a list of diagnoses</td><td>text</td></tr><tr><td><code>notStartsWith</code></td><td>has no item starting with any of the words</td><td>text</td></tr></tbody></table><p>A word in double quotes keeps its spaces. <code>&quot; flu &quot;</code> finds <em>stomach flu today</em> and not <em>influenza</em>, which holds <em>flu</em> with no space either side. The start and end of the text are not spaces: <code>&quot; flu &quot;</code> does not find <em>stomach flu</em> alone. A starting word for <code>startsWith</code> and <code>notStartsWith</code> holds no spaces, <code>;</code>, <code>/</code> or <code>&amp;</code>: those separate the items, so it could start none.</p><h4>Codes in a list</h4><p>A column of discharge diagnoses holds several codes, such as <code>J10.1;R50.9</code>. <code>startsWith</code> reads each code on its own, so <code>J10, J11</code> finds a visit with any influenza code and not one with a code that only contains those letters.</p><p>``<code>json { &quot;title&quot;: &quot;Influenza by diagnosis&quot;, &quot;mustNotBeReadAs&quot;: &quot;a diagnosis made here: the codes are the ones the visit was given&quot;, &quot;fields&quot;: [{&quot;attribute&quot;: &quot;chief_complaint&quot;, &quot;predicate&quot;: &quot;fwa:chief_complaint&quot;, &quot;kind&quot;: &quot;term&quot;}, {&quot;attribute&quot;: &quot;discharge_diagnosis&quot;, &quot;predicate&quot;: &quot;fwa:discharge_diagnosis&quot;, &quot;kind&quot;: &quot;term&quot;}], &quot;rules&quot;: [ {&quot;any&quot;: [{&quot;all&quot;: [{&quot;field&quot;: &quot;fwa:discharge_diagnosis&quot;, &quot;comparator&quot;: &quot;startsWith&quot;, &quot;value&quot;: &quot;J10, J11&quot;}]}, {&quot;all&quot;: [{&quot;field&quot;: &quot;fwa:chief_complaint&quot;, &quot;comparator&quot;: &quot;contains&quot;, &quot;value&quot;: &quot;influenza, \\&quot; flu \\&quot;&quot;}]}], &quot;then&quot;: [{&quot;predicate&quot;: &quot;fwa:influenza&quot;, &quot;value&quot;: &quot;yes&quot;}]} ] } </code>``</p><h4>Two conditions, and an alternative</h4><p>Conditions in one <code>all</code> must all hold; another object in <code>any</code> is an alternative. A fever with a cough, or the word <em>influenza</em>:</p><p>``<code>json { &quot;title&quot;: &quot;Influenza-like illness&quot;, &quot;mustNotBeReadAs&quot;: &quot;a diagnosis&quot;, &quot;fields&quot;: [{&quot;attribute&quot;: &quot;chief_complaint&quot;, &quot;predicate&quot;: &quot;fwa:chief_complaint&quot;, &quot;kind&quot;: &quot;term&quot;}], &quot;rules&quot;: [ {&quot;any&quot;: [ {&quot;all&quot;: [{&quot;field&quot;: &quot;fwa:chief_complaint&quot;, &quot;comparator&quot;: &quot;contains&quot;, &quot;value&quot;: &quot;fever, fevr&quot;}, {&quot;field&quot;: &quot;fwa:chief_complaint&quot;, &quot;comparator&quot;: &quot;contains&quot;, &quot;value&quot;: &quot;cough&quot;}]}, {&quot;all&quot;: [{&quot;field&quot;: &quot;fwa:chief_complaint&quot;, &quot;comparator&quot;: &quot;contains&quot;, &quot;value&quot;: &quot;influenza&quot;}]}], &quot;then&quot;: [{&quot;predicate&quot;: &quot;fwa:ili&quot;, &quot;value&quot;: &quot;yes&quot;}]} ], &quot;otherwise&quot;: [{&quot;predicate&quot;: &quot;fwa:ili&quot;, &quot;value&quot;: &quot;no&quot;}] } </code>``</p><h4>A setting in place of a number</h4><p>Write <code>{&quot;setting&quot;: &quot;name&quot;}</code> where a number would go, and declare the setting: the number is then set on the step, and changed without touching the rule.</p><p>``<code>json { &quot;title&quot;: &quot;A fever&quot;, &quot;mustNotBeReadAs&quot;: &quot;a diagnosis&quot;, &quot;fields&quot;: [{&quot;attribute&quot;: &quot;temperature_c&quot;, &quot;predicate&quot;: &quot;fwa:temperature_c&quot;, &quot;kind&quot;: &quot;number&quot;, &quot;unit&quot;: &quot;http://qudt.org/vocab/unit/DEG_C&quot;, &quot;unitLabel&quot;: &quot;degrees Celsius&quot;}], &quot;parameters&quot;: [{&quot;name&quot;: &quot;fever_from&quot;, &quot;meaning&quot;: &quot;The lowest temperature counted as a fever&quot;, &quot;unit&quot;: &quot;http://qudt.org/vocab/unit/DEG_C&quot;, &quot;unitLabel&quot;: &quot;degrees Celsius&quot;}], &quot;rules&quot;: [ {&quot;any&quot;: [{&quot;all&quot;: [{&quot;field&quot;: &quot;fwa:temperature_c&quot;, &quot;comparator&quot;: &quot;notLessThan&quot;, &quot;value&quot;: {&quot;setting&quot;: &quot;fever_from&quot;}}]}], &quot;then&quot;: [{&quot;predicate&quot;: &quot;fwa:fever&quot;, &quot;value&quot;: &quot;yes&quot;}]} ] } </code>``</p><h4>When two rules disagree</h4><p>A record two rules give different values to gets none, and the step names it. Keep rules apart with a condition that rules the other out: a fever that is not gastrointestinal.</p><p>``<code>json { &quot;title&quot;: &quot;Syndromes, kept apart&quot;, &quot;mustNotBeReadAs&quot;: &quot;a diagnosis&quot;, &quot;fields&quot;: [{&quot;attribute&quot;: &quot;chief_complaint&quot;, &quot;predicate&quot;: &quot;fwa:chief_complaint&quot;, &quot;kind&quot;: &quot;term&quot;}], &quot;rules&quot;: [ {&quot;any&quot;: [{&quot;all&quot;: [{&quot;field&quot;: &quot;fwa:chief_complaint&quot;, &quot;comparator&quot;: &quot;contains&quot;, &quot;value&quot;: &quot;vomit, diarrh&quot;}]}], &quot;then&quot;: [{&quot;predicate&quot;: &quot;fwa:syndrome&quot;, &quot;value&quot;: &quot;gastrointestinal&quot;}]}, {&quot;any&quot;: [{&quot;all&quot;: [{&quot;field&quot;: &quot;fwa:chief_complaint&quot;, &quot;comparator&quot;: &quot;contains&quot;, &quot;value&quot;: &quot;fever&quot;}, {&quot;field&quot;: &quot;fwa:chief_complaint&quot;, &quot;comparator&quot;: &quot;notContains&quot;, &quot;value&quot;: &quot;vomit, diarrh&quot;}]}], &quot;then&quot;: [{&quot;predicate&quot;: &quot;fwa:syndrome&quot;, &quot;value&quot;: &quot;influenza-like&quot;}]} ] } </code>``</p><h4>Rules in stages</h4><p>A later rule can read a column an earlier one gave, by its name: here a band first, then whether the band is a child.</p><p>``<code>json { &quot;title&quot;: &quot;Children&quot;, &quot;mustNotBeReadAs&quot;: &quot;a finding: the cut points are a choice&quot;, &quot;fields&quot;: [{&quot;attribute&quot;: &quot;age&quot;, &quot;predicate&quot;: &quot;fwa:age&quot;, &quot;kind&quot;: &quot;number&quot;, &quot;unit&quot;: &quot;http://qudt.org/vocab/unit/YR&quot;, &quot;unitLabel&quot;: &quot;years&quot;}], &quot;rules&quot;: [ {&quot;any&quot;: [{&quot;all&quot;: [{&quot;field&quot;: &quot;fwa:age&quot;, &quot;comparator&quot;: &quot;lessThan&quot;, &quot;value&quot;: 18}]}], &quot;then&quot;: [{&quot;predicate&quot;: &quot;fwa:band&quot;, &quot;value&quot;: &quot;under 18&quot;}]}, {&quot;any&quot;: [{&quot;all&quot;: [{&quot;field&quot;: &quot;fwa:band&quot;, &quot;comparator&quot;: &quot;equals&quot;, &quot;value&quot;: &quot;under 18&quot;}]}], &quot;then&quot;: [{&quot;predicate&quot;: &quot;fwa:child&quot;, &quot;value&quot;: &quot;yes&quot;}]} ] } </code>``</p><h4>What the editor says, and what to do</h4><table><thead><tr><th>It says</th><th>Do</th></tr></thead><tbody><tr><td><em>A comma is missing after the value of &quot;title&quot;</em></td><td>Put a comma at the end of that line</td></tr><tr><td><em>A comma is left before &quot;]&quot;</em></td><td>Remove the comma after the last item</td></tr><tr><td><em>JSON writes names and strings in double quotes</em></td><td>Change <code>'</code> to <code>&quot;</code></td></tr><tr><td><em>fwa:age is not a declared field</em></td><td>Add the column to <code>fields</code>, or correct the name</td></tr><tr><td><em>&quot;Age&quot; is not a column of \u2026 Did you mean &quot;age&quot;?</em></td><td>Spell <code>attribute</code> as the column arrives, or choose <strong>Add to fields</strong></td></tr><tr><td><em>&quot;comparator&quot; is one of \u2026</em></td><td>Use one of the comparisons above</td></tr><tr><td><em>write the words to look for</em></td><td>Give <code>contains</code> its words, separated by commas</td></tr><tr><td><em>\u2026 is a number, so it holds no words</em></td><td>Look for words in a text column (<code>kind</code> <code>term</code>)</td></tr></tbody></table><h3>Combining conditions</h3><p><strong>+ and</strong> puts conditions in one <em>if</em> block, all of which must hold; <strong>or</strong> adds another <em>if</em> block, any of which will do. Every rule is one or more <em>if</em> blocks joined by <em>or</em>, each holding conditions joined by <em>and</em>. Any combination of <em>and</em>, <em>or</em> and <em>not</em> can be written that way:</p><table><thead><tr><th>You want</th><th>Write it as</th><th>In the editor</th></tr></thead><tbody><tr><td>A and B</td><td>one <em>if</em> block</td><td><em>if</em> A <strong>+ and</strong> B</td></tr><tr><td>A or B</td><td>two <em>if</em> blocks</td><td><em>if</em> A <strong>or</strong> <em>if</em> B</td></tr><tr><td>(A and B) or (C and D)</td><td>two <em>if</em> blocks of two conditions</td><td><em>if</em> A <strong>+ and</strong> B <strong>or</strong> <em>if</em> C <strong>+ and</strong> D</td></tr><tr><td>A and (B or C)</td><td>the A repeated in each block</td><td><em>if</em> A <strong>+ and</strong> B <strong>or</strong> <em>if</em> A <strong>+ and</strong> C</td></tr><tr><td>a range, 5 \u2264 x \u2264 10</td><td>two conditions in one block</td><td><em>if</em> x is at least 5 <strong>+ and</strong> x is at most 10</td></tr><tr><td>outside a range, x &lt; 5 or x &gt; 10</td><td>two blocks</td><td><em>if</em> x is less than 5 <strong>or</strong> <em>if</em> x is more than 10</td></tr><tr><td>not (A and B)</td><td>each condition turned round, joined by <em>or</em></td><td><em>if</em> not-A <strong>or</strong> <em>if</em> not-B</td></tr><tr><td>not (A or B)</td><td>each condition turned round, joined by <em>and</em></td><td><em>if</em> not-A <strong>+ and</strong> not-B</td></tr><tr><td>x is not more than 7</td><td>the comparison turned round</td><td><em>if</em> x is at most 7</td></tr></tbody></table><p>A condition is turned round by its opposite comparison: <em>is</em> and <em>is not</em>, <em>is more than</em> and <em>is at most</em>, <em>is less than</em> and <em>is at least</em>, <em>is recorded</em> and <em>is not recorded</em>. There is no <em>not</em> around a whole block: it is written as in the last three rows. When nothing else applies, <strong>otherwise</strong> gives the value.</p><h3>What it says instead of guessing</h3><ul><li><strong>A division by zero</strong> gives an empty value, and is counted and named: *1 record has an empty value, from a division</li></ul><p>by zero: Harbour.*</p><ul><li><strong>A value to compute from that is missing</strong> gives no value, and is named.</li><li><strong>Two rules giving one record different values</strong> give it none, and both rules are named.</li><li><strong>The first row of a place has no previous one.</strong> Its value is empty, counted and named.</li><li><strong>Two rows for one period</strong> have no single previous row: both, and every later row of their place, get no value</li></ul><p>rather than a guessed one, and are named.</p><ul><li><strong>A value that fell</strong> below the previous row's, such as a cumulative count corrected down, is kept as computed and</li></ul><p>named.</p><ul><li><strong>A number without a unit</strong> stops the rules from running until its unit is stated, and a rule comparing two</li></ul><p>different units is refused while it is being written.</p><ul><li><strong>A record that took an otherwise</strong> is counted by column, so a default is never read as a rule's conclusion: *2</li></ul><p>records took class's otherwise, because no rule gave class a value.*</p><p>On a wide table, a computed value is a new variable of each subject: in the table it is one more row per subject, named for the new column, as <strong>Derive a value</strong> adds it.</p><p><strong>A published ruleset</strong> opens in its own dialog: the ruleset, its settings, and as the preview what it decides, its basis and what it obliges. <em>Read them in the rule editor</em> shows its rules there, every control disabled. A newer version is under <strong>Decisions</strong>: the step stays on the version it was built on until you choose.</p><h3>What it will not do</h3><ul><li>Order the rules. Every rule is checked against every record; an otherwise is a default, not a last rule.</li><li>Settle two rules that disagree. The record gets no value, and both rules are named.</li><li>Guess a unit, a kind or a column from its name.</li><li>Change a published ruleset in place. A copy can be edited on the step.</li></ul><h3>What this does not establish</h3><p>That a rule is right for its question. Rules do exactly what they say, including what was meant and not written.</p>",buffer_point:"<h2>Geometry buffer</h2><p><strong>A study area drawn around one place.</strong> Everything within a stated distance of a well, a clinic or a city centre.</p><h3>What it does</h3><p>It takes one named point and draws a circle of the radius you set around it, as a polygon of 128 sides, 32 to each quarter. That polygon becomes a study area, which any step that takes a study area can use.</p><h3>What you connect</h3><table><thead><tr><th>Input</th><th>What it takes</th></tr></thead><tbody><tr><td><strong>Points</strong></td><td>a point layer that holds the point, named by its name or its id</td></tr></tbody></table><h3>How to use it</h3><p><strong>Configure\u2026</strong> sets two things, and nothing is written until <strong>Apply</strong>:</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Point in \u2039layer\u2030 that defines the area</strong></td><td>chosen from the points the connected layer carries. One point arriving is the choice; several, and the list opens on <em>Choose a point</em>. A layer that holds no records of its own and has not run offers none, and the name is typed in until it has</td></tr><tr><td><strong>Radius in metres</strong></td><td>above 0 and up to 50,000. The radius is a claim about reach, so give the figure your evidence supports and say where it came from in Methods</td></tr><tr><td><strong>Where several areas are drawn</strong></td><td>combine them into one study area, or keep each one separate as a polygon layer</td></tr></tbody></table><p><strong>Show me how it works</strong>, in the dialog, draws a made-up well and the area around it, step by step, with the radius you have set.</p><p><strong>Result</strong> gives the size of the area drawn at the last run.</p><h3>What it will not do</h3><ul><li><strong>It will not keep the buffers apart and call them a study area.</strong> Combined, they are one scope; kept apart, they are a polygon layer, and only a scope can be connected to the clip, the street network or a facility search.</li><li><strong>It will not follow roads or terrain.</strong> The distance is straight, on the ground; for travel time, use a travel-time</li></ul><p>step.</p><ul><li><strong>It will not draw more than 50,000 metres.</strong> A study area is held to one degree as well, which a radius reaches at about 55.6 km; beyond that, keep the buffers as a polygon layer or draw the area under Study area.</li></ul><h3>Where it is used</h3><p>No worked example uses it today.</p><h4>2026-11-24 \xB7 The preview shows the ground and the point (0.6.0)</h4><p>The picture now draws <strong>the points the area is drawn around</strong>, and puts OpenStreetMap ground behind them where it can be fetched. A radius is a claim about reach <em>from</em> something, and a picture of the reach without the thing it reaches from cannot be checked against the ground or against the pin on the map. With no network the preview keeps its plain background and says the ground is not shown.</p><p>Its caption also no longer contradicts the setting above it. One area was captioned &quot;kept apart&quot; under a step set to <strong>combine into one study area</strong>, because nothing is dissolved when there is nothing to dissolve and the caption read that absence as the layer setting.</p>",case_series:"<h2>Cases by period</h2><p><strong>An epidemic curve's counts.</strong> Cases per day, week or month, or by day of the week or month of the year, by a date whose kind you state: onset, report, death, specimen collection, or a date of unstated kind.</p><h3>What it does</h3><p>It counts the records in each period, or adds up a count each record carries, and keeps every period between the first and the last, empty ones as zero. A gap in a curve is a fact about the outbreak, so it is not closed up.</p><h3>What you connect</h3><p><strong>Records arrive as</strong> decides the input:</p><ul><li><strong>points, one per record</strong>: a line list with a date, such as Hagelloch's 188 measles cases. Each record is one case,</li></ul><p>or carries its count in <strong>Cases per record</strong>.</p><ul><li><strong>a table, each row a count</strong>: a table with a date key column, such as Snow's deaths by day or Brazil's notified</li></ul><p>cases by municipality and week. Each row adds its value column to its period.</p><ul><li><strong>a table, each row one case</strong>: a line list that arrives as a table, such as MERS's cases with their recorded</li></ul><p>sources. Each row counts once, and its value column is not read: MERS's is age. Where a case has a row for each recorded source, choose <strong>Each case is named in</strong> and each case counts once, at its date; two rows for one case with different dates are refused, naming the case.</p><p>Changing it disconnects the input, because points and a table are not the same shape.</p><p>It gives back a table of periods and counts. <strong>\uFF0B Add epidemic curve</strong> draws it as a Chart.</p><h3>How to use it</h3><p>The step's panel holds its <strong>Name</strong>, its input, one sentence saying what it counts, and <strong>Configure\u2026</strong>, where these are set and applied with <strong>Apply</strong>:</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Records arrive as</strong></td><td>Points, one per record; a table, each row a count; or a table, each row one case</td></tr><tr><td><strong>Date column</strong></td><td>The column holding the date, written as an ISO 8601 date (2024-01-07)</td></tr><tr><td><strong>Which date is it?</strong></td><td>Onset, report, death, specimen collection, or other. It is written on the chart's axis and caption</td></tr><tr><td><strong>Period</strong></td><td>Hour, for dates and times; day; week, starting Monday (ISO 8601); week, starting Sunday (the epidemiological week); month; day of the week; or month of the year</td></tr><tr><td><strong>Cases per record</strong></td><td>Points only, optional: a column holding how many cases each record stands for</td></tr></tbody></table><p><strong>Choose the week your data uses.</strong> Brazil's notification system and the United States count epidemiological weeks from Sunday, and Brazil's <code>data_iniSE</code> is that Sunday. Counted by the Monday week instead, each Sunday falls into the week of the Monday six days before it, and every bar is labelled a day early. A week is labelled by its first day: <em>Week beginning 2024-01-07</em>.</p><p><strong>By day of the week</strong>, the dates are counted Monday to Sunday, all seven kept, so a weekly rhythm can be seen: a clinic closed on Sundays, reports filed on Mondays. It is a cycle, not a time axis, and it does not say whether the differences between days are more than chance. Hagelloch's 188 prodrome dates: Monday 23, Tuesday 21, Wednesday 25, Thursday 34, Friday 30, Saturday 27, Sunday 28.</p><p><strong>By month of the year</strong>, the dates are counted January to December, every year's January together, all twelve kept: a season across several years of data. Over less than a year it shows only the months the outbreak lasted, and a month counted in more years than another holds more cases for that reason alone.</p><p><strong>When the source does not say which date it is</strong>, choose <em>other</em>. The chart then says <em>a date of unstated kind</em>. Brazil's weekly counts are notified cases by epidemiological week, and the source does not say whether the week is of onset or of notification.</p><p>The chart's line under the title gives the total and what it was counted from: <em>423,795 cases from 4,692 records</em> when each record carries a count, <em>188 records</em> when each record is one case.</p><h4>Counted for each value of a column</h4><p><strong>Count each value of</strong> names a column of the records, such as a school class. Each period is then counted for each of its values, every period kept for every value, a blank its own value; the table is keyed by period and the column, and Chart draws it in panels or, with <strong>Draw</strong> <em>Stacked bars</em>, as one bar per period divided by the values. Hagelloch's <em>Who fell ill?</em> counts its cases by week for each school class. For points, and for a table whose rows are each one case: MERS's curve by generation splits its cases by the <code>generation</code> column <strong>Transmission chains</strong> adds. Not for a table of counts.</p><h3>What it will not do</h3><p><strong>It will not treat one kind of date as another.</strong> A curve by date of death is not a curve by date of onset, so the kind of date is required and is written on the chart.</p><p><strong>It will not guess a date.</strong> A value that is not an ISO 8601 date is left out and counted, never read as day-first or month-first.</p><p><strong>It will not restrict the curve to a period.</strong> Use <strong>Select rows by value</strong>, a range of dates, before it.</p><p><strong>It will not join places to dates.</strong> Snow's map has places and no dates, and his table has dates and no places.</p><h3>What this does not establish</h3><p>That the kind of date chosen is the one the counts were made by: that is the source's to say. And that a weekly count is complete: late notifications reach the last weeks after the data were taken.</p><h3>By the hour</h3><p><strong>Hour</strong> counts dates and times, <code>1940-04-19T00:30</code>, by the hour, every hour between the first and the last kept. A date with no time cannot be placed in an hour, so it is listed with the records without a usable date, as written, never put at midnight. Oswego's <em>When did they fall ill?</em> counts 44 cases from 3 PM on 18 April to 10 AM on 19 April, the date and time put together from the line list's two columns by Apply ruleset.</p><h3>History</h3><h4>2026-11-26 \xB7 The Preview follows the input type you are choosing (0.10.0)</h4><p>Switching this step from points to a table left the Preview counting the points still connected \u2014 a reading of records that applying the change would discard along with the connection.</p><p>It follows the choice in front of you now. Where the type you have chosen has nothing on it yet, it says what to connect instead of counting something else.</p><h4>2026-11-25 \xB7 The Preview counts, instead of repeating the settings (0.9.0)</h4><p>Its Preview read the settings back, so it looked like a preview while showing nothing of the records connected.</p><p>It now runs this step's own counting on those records, before any run: the total, how many periods, the span, and the busiest one. Records whose date it cannot read are counted and named, because a count by date drops them in silence and the curve is then drawn as though they had never been there.</p><h4>2026-11-22 \xB7 A blank count is not zero, and what is left out is counted (0.8.0)</h4><p>Found by the stress tests of the table operations. A row with an empty count made its period's total 0; it is now refused, saying how many rows have none, since a count is not guessed. Dates it cannot read as ISO 8601 were said to be excluded and counted, without the count: the sentence now gives how many, of how many, and what they held, such as &quot;06/01/2026&quot;. And a date range too long to draw, which one mistyped year can make, names its first and last date.</p>",chart_output:"<h2>Chart</h2><p><strong>An output widget.</strong> It draws bars: a set of labelled categories with a number each. It creates a named tab in Results and changes nothing about the data it is given.</p><h3>What it does</h3><p>It takes whatever you connect and draws a bar per category, or an estimate with its interval.</p><p><strong>A table</strong>, on the <strong>Table</strong> port. One bar per row. The table already says which column names the categories and which number goes on the bar, so nothing is asked of you: a rate of deaths per 1,000 people across 32 sub-districts is 32 bars, labelled by sub-district, each as tall as its own rate. Any table works \u2014 a rate, a total within groups, a derived value, a related column, a two-by-two, a case series. A case series is drawn as a curve over its periods.</p><p><strong>A summarised polygon layer</strong>, on the <strong>Polygon summaries</strong> port. One bar per polygon, carrying the count of locations inside it or the total of a numeric field, whichever the summary holds.</p><p>Connect one of them. The chart draws what it is given, so there is no mode to set first and no question to answer before you have the shape.</p><p><strong>What a bar's number is</strong> travels with the chart. A count of records is a count; a rate is a rate, printed as the number it is rather than rounded to a whole one, and the axis is titled with the unit the table declared \u2014 &quot;per 1,000 people&quot; \u2014 instead of &quot;Recorded count&quot;.</p><p><strong>A table's own chart is preferred</strong> where it has one. A rate carries a chart that knows things the rows alone cannot say: that the numerator and the denominator come from different vintages, and how many groups had too small a denominator to report. Those appear in the caption.</p><p><strong>Rows with no value are drawn at zero and counted in the caption.</strong> A group whose rate was suppressed is not a group whose rate is zero, and a chart that quietly dropped it would be shorter than the table beside it.</p><h3>How to use it</h3><p>1. Add <strong>Chart</strong> and select it. Name the Results tab under <strong>Name</strong>, and choose where it goes in the write-up. 2. Under <strong>Inputs</strong>, pick what it should draw: <em>Table</em> or <em>Polygon summaries</em>. 3. Press <strong>Configure\u2026</strong>. Everything else is set there, and <strong>Apply</strong> writes it: - <strong>Draw</strong>: what to draw, listed by the question each form answers. Once the workflow has run, the forms that suit the data come first, under <em>Suits these data</em>, and the reason for the one chosen is written beneath it: <em>Who infected whom? Transmission tree</em> is offered first for a table with a column naming each case, one naming its source and a date. Forms that need other data follow, with what they need. The choice is yours; nothing is drawn until you pick. - If the table keys on more than one column, which one labels the bars. - The mark: bars, dots, or a <strong>line</strong>, which runs along the categories in their order, upright, with a dot at each value. And the orientation, for bars and dots. Bars read best horizontally when the labels are long or there are many of them; 32 sub-districts is many. - A title, a subtitle, axis titles and a source note, if you want them in the figure. Each may take words from the workflow, below. - Optionally the category legend, which colours each bar. It holds at most six categories, because the validated palette is six hues; past that, group the tail upstream rather than ask for a seventh colour. 4. Run the workflow. Afterwards, <strong>Configure\u2026</strong> shows a <strong>Preview</strong> at the bottom: the last run drawn with the settings as you change them, before <strong>Apply</strong>. Nothing is run again.</p><h4>Words from the workflow</h4><p>A title, subtitle, axis title or source note may say <strong>{country}</strong>, <strong>{units}</strong>, <strong>{unit}</strong> or <strong>{census}</strong>. Each is filled from the workflow where the figure is drawn: the study area's country, what its units are called (stated on the study area, or its boundary's own name for them), and the year of a census read from <strong>Census tables</strong>. A copy of the workflow over another country reads that country. A word the workflow does not state is written as such, for example <em>[country not stated]</em>, never guessed. The dialog says what each reads here.</p><h4>Who infected whom: a transmission tree</h4><p>Connect a table, or a point layer, with one row per case: a column naming the case, one naming its infector, and a date. In <strong>Configure\u2026</strong>, set <strong>Draw</strong> to <em>Who infected whom? Transmission tree</em> and name the three columns.</p><p>Each case is a dot at its date, on a row of its own. A line runs from its infector's date down to its row and across to its own date, so the length across is the <strong>serial interval</strong>. A case naming no infector starts a chain; its children are drawn beneath it, earliest first, so generations read left to right and chains top to bottom. <strong>Colour is the generation</strong>: the first case in a chain is darkest, and each generation after it lighter, from deep violet to coral. The same colours mark generations on Map's lines between records, so generation 3 is one colour in both. <strong>Shape is what the case is</strong>: a circle for a case whose infector is listed, a square for no infector recorded, and so on, named in the key.</p><p>Drawn by Vega-Lite, as other charts are, so it exports as SVG with its title and source note; hover a point for the case, its date, its infector and its generation, and a line for its serial interval.</p><p>Nothing is dropped, and each is counted and said:</p><table><thead><tr><th>A case that</th><th>is drawn</th></tr></thead><tbody><tr><td>names no infector</td><td>starting a chain</td></tr><tr><td>names an infector the table does not hold</td><td>starting a chain, counted apart</td></tr><tr><td>sits in a loop (A infected by B, B by A)</td><td>starting a chain, counted as in a loop, which no chain can be</td></tr><tr><td>has no readable date</td><td>at its infector's date, outlined</td></tr><tr><td>records more than one source, one row per source</td><td>under the first source listed, each other recorded link dashed, counted</td></tr></tbody></table><p><strong>More than one recorded source.</strong> A table may hold a case in several rows, one per source recorded for it, as Relate's <em>keep one row per match</em> makes from MERS's contacts. The case is drawn once, under the first source listed; each other recorded link is drawn as a dashed line, and the cases and links are counted. <strong>Written where no source is recorded</strong> names a value, such as <em>none recorded</em>, that means no source; an empty cell always does.</p><p>Hagelloch, 1861: 188 cases in 4 chains, 184 links; the largest chain starts with case 184 and holds 173 cases over 6 generations. The tree draws the reconstruction of who infected whom that the table holds; it does not estimate one.</p><h4>A date marked on the curve</h4><p>Where the chart's axis is dates, as an epidemic curve's is, <strong>Configure\u2026</strong> has <strong>Marked dates</strong>: a day and a label in your own words, such as <em>Pump handle removed</em>, and <strong>+ Add a date</strong> for more. Each is drawn as a dashed line at the day, in the bar that holds it for a weekly or monthly curve, with its label beside it, by the enhanced renderer; the classic bars do not draw them. A day of the week or a month of the year is a cycle, not a date, and is not offered. The run's receipt records each date and its label. John Snow's <em>When did people die?</em> marks 8 September 1854.</p><h4>A curve divided by a column: stacked bars</h4><p>Where Cases by period counts each value of a column, as Hagelloch's school classes, <strong>Draw</strong> <em>When, and of which kind? Stacked epidemic curve</em> gives one bar per period, its height the total, divided by those values in one colour each, the first at the bottom, with a key. More values than the six colours that can be told apart is refused, naming how many; draw panels instead, which is what the chart does where Draw is left at bars. Hagelloch's <em>Who fell ill?</em> stacks its curve by school class.</p><h4>What the columns were declared to be</h4><p>Where a column was described at its source, in Tabular data's or Point data's <strong>Describe columns\u2026</strong>, Chart reads that before the values, for any column that reaches it under the same name. A column declared as <strong>categories in an order</strong> draws its bars, and the panels or stack of a curve divided by it, in that order, and each code with its meaning beside it: <em>0 preschool</em>, <em>1 1st class</em>. One declared <strong>in no order</strong> is never offered as a pyramid's bands, however much its values look like ages. A column a step computes, such as a count, carries nothing from the source. Only accepted descriptions are read, never a dictionary's proposals.</p><h4>Two groups back to back: a population pyramid</h4><p>In <strong>Configure\u2026</strong>, <strong>Draw</strong> <em>How are two groups spread across ages? Population pyramid</em>, then name the column whose two values sit left and right, such as gender. Each band of the category column, such as age, is a row, the youngest at the bottom; one group's counts run left and the other's right, and the axis reads as a count on both sides. Rows where the column is blank are not drawn, and the subtitle says how many. A column with other than two values is refused, naming them. Hagelloch's <em>Who fell ill?</em> draws its cases by age and gender this way.</p><h4>Several series in one panel: series together</h4><p><strong>Draw \u2192 Series together</strong> draws the values of one column as series in a single panel, on one scale: one line for each syndrome, or a day's count as bars with its threshold dashed over them. For each series choose <strong>Bars</strong>, <strong>A line</strong>, <strong>A dashed line</strong>, or leave it <strong>Not drawn</strong>; until one is chosen, every series is a line. <strong>Mark the periods where a series is 1</strong> puts a triangle on another series wherever that one is 1, with your label in the legend: Detect unusual counts' <code>signal</code> is 1 on the days it signals.</p><p>One scale says the series measure the same thing. Draw a count with its threshold together; draw a count and a standardized statistic in panels (below), each on its own scale.</p><h4>Variables moving together through time: one panel each</h4><p>When a table carries several variables in one column \u2014 what Table input's <strong>Wide</strong> shape makes of a file with a column per variable \u2014 set <strong>One panel per</strong> to that column. Each variable gets its own panel and its own scale, stacked on one shared axis, so a reader runs down one date and reads every series, and a lag shows as an offset between panels.</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>One panel per</strong></td><td>The key column whose values become panels. <em>No panels</em> is one chart, as before</td></tr><tr><td><strong>Mark for</strong> each panel</td><td>Bars or a line. <em>Automatic</em> is bars up to 60 points and a line beyond</td></tr><tr><td><strong>Shade a period</strong>, From and To</td><td>Dates shaded behind every panel, both days included. Offered when the axis is dates</td></tr></tbody></table><p>A value missing from a panel is a gap in its line, never a zero. Panels draw up to 250,000 points, the same as a table holds; measured in Chromium, 100,000 points took about 10 seconds to draw and 250,000 about 30 (experiment 175). They are drawn by the Vega-Lite renderer; the plain renderer and the write-up figure say so instead of drawing them on one scale. Experiment 174.</p><p><strong>Or one panel per column.</strong> When the variables are separate columns of numbers in one table, tick them under <strong>Or one panel per column</strong>: each is its own panel, on its own scale, along the category column. A column holding a blank or a word is not offered, and a cell with no number is a gap. Under each ticked column, <strong>A dashed line at</strong> draws a line at a value you state, with <strong>Its label</strong>. Hagelloch's daily scan draws each evening's p-value with a line at 0.05, labelled <em>p = 0.05</em>, over the cases known by then: the line is where a reader would call a cluster, and the subtitle says that 78 evenings were looked at with no adjustment for looking every day.</p><p><strong>Two y axes on one plot are not offered.</strong> The ratio between two axes is arbitrary, so it can make any two series look correlated. <strong>Aligned panels show timing, not effect</strong>: that visits rose with PM2.5 in the same week is not a measure of how much PM2.5 raises them.</p><h4>An estimate with its interval: a lag-response or forest plot</h4><p>A table that declares an interval, as every <strong>Regression</strong> table does, is drawn as a point at each estimate with a whisker from the lower to the upper limit. Choose the <strong>Category column</strong> the estimates are placed at. Keep one term upstream with <strong>Select rows by value</strong>; a table holding several terms gets one point per term, labelled with it.</p><p><strong>For a ratio, a log scale and a dashed line at 1 are on by default.</strong> On a log scale a ratio and its inverse, 0.5 and 2, sit equally far from 1, and the line marks no association. The figure says both on its subtitle, with the interval's level. <strong>Log scale</strong> and <strong>A dashed line at 1</strong> in the Inspector turn them off.</p><p><strong>A category declared a number is placed as one.</strong> Append rows can declare its labels numbers in a unit, so lags of 0, 1, 2, 4 and 8 weeks sit at their distances and the axis is titled with the unit. Otherwise the categories are evenly spaced, in the table's order.</p><p>The Brazil dengue example's fourth workflow draws its five lag models this way: five Regression tables stacked by <strong>Append rows</strong>, the temperature term kept, one point per lag. Validation Lab check 36 rebuilds the stack and the points with pandas and agrees with every number. Experiment 181.</p><p><strong>Each point is what the table holds, and no more.</strong> Five points from five separate models are not adjusted for each other, and a figure cannot add what the models left out.</p><h4>It states its own shape in the write-up</h4><p>Every run machines a note into <strong>Results</strong> on the Notes tab stating what this chart is made of. It carries the line the chart already states rather than writing over it, and adds the number of bars, the column they are one per, and a warning where a bar sits at zero \u2014 because a withheld value and a measured zero are drawn the same way.</p><p><strong>The caption is yours.</strong> A caption states the subject, the population, the place and the period in your words, and none of that can be read off a chart. What this writes is what the chart declares about itself \u2014 the material you write the caption from, sitting beside it in the same section.</p><p><strong>And it carries no number.</strong> A figure's number depends on where it sits in the write-up and on the venue you are preparing \u2014 set one figure aside and the ones after it move up \u2014 so the number is worked out when the document is rendered. Nothing here says &quot;Figure 1&quot;.</p><p>Edit it and it forks into a note of your own, like any machined note; the machined one goes on being rewritten by every run.</p><h4>Where it goes in the write-up</h4><p><strong>In the write-up, under</strong>, just below <strong>Results tab name</strong> in the Inspector, chooses the part of the Notes write-up this output's figure and its note go in: Introduction, Methods, Results or Discussion. <strong>Results</strong> is the default. A map of the study area belongs in the Introduction; a figure that shows how the analysis was done can go in Methods. References is not offered, because it holds works and not figures. The run's receipt states the section and whether you chose it, and a validation rule checks that the note describing the figure is filed in that same section.</p><p><strong>Not in the write-up</strong>, the last choice, keeps the figure in Results and out of Notes and the publication: the run writes no note for it, and its receipt says it was left out. Hagelloch's day-by-day map is left out this way.</p><h3>What it will not do</h3><p><strong>It will not aggregate.</strong> One bar per row, per category or per polygon \u2014 it never adds rows together. If you want totals, total them upstream with <strong>Total within groups</strong>, where the arithmetic is visible and ends up in the receipt.</p><p><strong>It will not choose a column for you.</strong> Where a table keys on several columns and you name none, it uses the first, and says which in the caption. Nothing is guessed from a column's name.</p><p><strong>It will not merge two rows that share a category.</strong> They stay as two bars. Adding them would be a total nobody asked for, and rates cannot be added at all.</p><p><strong>It will not draw more than 100 bars or estimates</strong>, and will not colour more than six categories.</p><p><strong>It will not put a count and a concentration on one scale.</strong> Use panels.</p><p><strong>It is not a time series by itself.</strong> Connect <strong>Cases by period</strong> and the periods come with it; a plain table of dates is a table, and its rows are drawn in the order they are in.</p><p><strong>It does not filter, weight or reinterpret.</strong> Every record it is given is counted once, and the receipt records the renderer, its version, the specification and what each bar's number means.</p><h3>Worked examples that use it</h3><p><strong>NYC child asthma and ozone, 2016 to 2025</strong> draws daily visits, ozone, PM2.5 and temperature as four aligned panels for May to July 2023, with the June smoke days shaded.</p><p><strong>Snow's South London water supply study, 1854</strong> draws the 32 registration sub-districts as bars of deaths per 1,000 people, from the rate's own chart, so the figure carries the vintage caveat with it.</p><h3>History</h3><h4>2026-11-26 \xB7 Its code out of app.ts (0.25.3)</h4><p>The Inspector moved into <code>src/chart-ui.ts</code>, beside Configure\u2026. Nothing it shows or does changed.</p><h4>2026-11-23 \xB7 No trailing zeros on a panel's axis (0.25.2)</h4><p>A panel whose values were all 0 labelled its axis 0.000000. It now reads 0.</p><h4>2026-11-22 \xB7 Squares in a series chart's legend (0.25.1)</h4><p>A series chart's legend showed a line series as a short stroke, hard to tell apart at six syndromes. Each series is now a filled square in its colour, as in the bar charts' legend.</p><h4>2026-11-19 \xB7 The source line ends at its source (0.23.1)</h4><p>A chart's default source line read &quot;Source: \u2026 \xB7 See N3 &amp; evidence for method.&quot;, and the pointer, an instruction for someone in the application, was printed in every figure and draft. The default is now &quot;Source: \u2026&quot; and nothing more. A source line written in Configure is printed as written. Found by the target outputs audit ([audit](../audits/target-outputs-audit.md)).</p><h4>2026-11-21 \xB7 Series together (0.25.0)</h4><p>The values of a column as series in one panel, each as bars, a line or a dashed line, and the periods where one series is 1 marked with triangles: what syndromic surveillance needs to show a day's count against its threshold, and its signals. Its settings moved, with the rest of Configure\u2026, out of the application's main file into the widget's own.</p><h4>2026-11-20 \xB7 Words from the workflow (0.24.0)</h4><p>The title, subtitle, axis titles and source note take {country}, {units}, {unit} and {census} from the workflow, so a copy over another country reads its own. A copy of a workflow leaves the subtitle empty: it was the original's finding.</p>",clip_points_to_area:"<h2>Keep points inside the area</h2><p><strong>A spatial operation.</strong> It takes a layer of points and a mask \u2014 <strong>a study area or a polygon layer</strong> \u2014 and passes on the points that are inside it.</p><h3>What it does</h3><p>Every point is tested against the mask's outline, and the ones inside come out the other side. The ones outside are counted and reported, not passed on.</p><p><strong>The mask is a study area or a polygon layer.</strong> Connect one or the other \u2014 connecting both is refused, because a point inside the area and outside every polygon would have no single answer.</p><p>A polygon layer is <strong>many</strong> masks, so a point kept by one records <strong>which</strong> polygon held it, in a column you can name. &quot;Inside the buffer&quot; is not enough when the buffer is 32 stretches of a border and you want to know which stretch a facility is near. A study area has one mask and nothing to name, so it writes nothing.</p><p>This matters beyond tidiness. A buffer wide enough to be interesting often cannot be a study area at all \u2014 a 10-mile buffer around 656 km of border spans more than three degrees, and a study area windows every raster a workflow reads. Kept as a polygon layer it has no such limit, and this is what lets you clip by it.</p><p>The test is the same one the coverage check and the map use. A point counted inside here is inside there, and a figure you quote from one agrees with the other.</p><h3>Why you need it</h3><p>A source gives you what its own request asked for, and almost every source is bounded by a <strong>rectangle</strong>: OpenStreetMap's query takes a bounding box, a cloud dataset is read by extent, a country export is clipped to one. A rectangle is not a jurisdiction. Draw North Kivu \u2014 long, curved, a province of the DRC \u2014 and its bounding box covers large parts of Uganda and Rwanda; a facility search inside it returned 961 places of which 526 stood in the neighbouring countries.</p><p>This widget is where that is decided, visibly, on the canvas. Before it existed the decision was made privately inside whichever widget happened to need it, which meant it could not be seen, changed, or recorded.</p><h3>How to use it</h3><p>1. Connect the study area to the <strong>area</strong> port and the point layer to the <strong>points</strong> port. Both are required: the question is about these points against that area. 2. In <strong>Configure\u2026</strong>, leave <strong>Keep points that sit exactly on the outline</strong> ticked unless you need strict containment. <strong>Show me how it works</strong> shows a point inside, one on the outline, one outside and one with no location, and what happens to each. 3. Run. The step reports how many were inside, how many sat on the boundary and how many fell outside, and passes the kept points on to whatever you wire next.</p><p>If every point falls outside, the step refuses and says so with the counts \u2014 that usually means the area is not the one you meant, or the points are somewhere else entirely.</p><h3>The one setting</h3><p><strong>Keep points that sit exactly on the outline.</strong> On by default. A point on the border is in that jurisdiction's edge, and silently folding it into one side or the other answers a question nobody asked. Turn it off for strict containment \u2014 which is what the OGC predicate <code>sfWithin</code> means, and it gives a different count on exactly the data where it matters.</p><h3>Seeing what it set aside</h3><p><strong>Show the excluded points on a connected map.</strong> On by default. They are drawn in the colour the map already uses for points outside the area, and they are <strong>not</strong> passed to anything downstream \u2014 the next widget receives only what is in the area.</p><p>The count tells you how many were set aside. Seeing them tells you whether setting them aside was right: 526 facilities in a tight cluster over one border is a different fact from 526 scattered in every direction, and no number distinguishes those.</p><h3>What it records</h3><p>The receipt names the predicate the kept set answers to, whether boundary points were kept, and three counts: inside, on the boundary, outside. A reader can tell how many the source offered and how many this area accepted, which is the number a reviewer asks for.</p><h3>What it will not do</h3><p>It does not change a point. Nothing is moved, snapped or rounded; a point either is in the area or is not.</p><p>It does not know why a point is outside. A facility across a border, a coordinate entered the wrong way round and a geocoding error all look the same to a membership test. The coverage check is the widget for asking what to do about them, with reasons recorded.</p><p>It does not clip polygons or rasters. Those have their own widgets, and they take a study area as their mask.</p><p>It does not take two masks. A study area and a polygon layer connected together are refused rather than resolved by a rule nobody chose.</p><h3>Worked examples that use it</h3><p>None yet. It was built on 2026-10-20, from a defect found in a real study area.</p><h3>History</h3><h4>2026-11-24 \xB7 The mask may be a polygon layer (0.4.0)</h4><p>Until now every clip in Fieldwork masked by a <strong>study area</strong> \u2014 this one, Clip polygons and Clip raster alike \u2014 and nothing could clip by a polygon layer. That left a dead end: a buffer spanning degrees cannot be a study area, because a study area windows every raster a workflow reads, so it can only be a polygon layer, and no step would take one as a mask.</p><p>Both ports are now offered and neither is required on its own; connecting one is how the mask is chosen. A point kept by a layer records which polygon held it.</p><h4>2026-11-22 \xB7 On the standard, with Show me how (0.2.0)</h4><p>Its two settings moved into <strong>Configure\u2026</strong>, with <strong>Show me how it works</strong>, and its Inspector became the standard one: name, inputs, one sentence, and what the last run counted.</p>",clip_polygons:"<h2>Clip polygons</h2><p><strong>Polygons cut to the study area.</strong> Catchments or districts that spill past the reporting area, kept only where they fall inside it.</p><h3>What it does</h3><p>It cuts each polygon to the study area. A polygon wholly inside is kept as it is; one across the study area's edge is cut along the edge, and only the part inside is kept; one outside is left out. What each polygon carries is kept with the part that remains.</p><h3>What you connect</h3><table><thead><tr><th>Input</th><th>What it takes</th></tr></thead><tbody><tr><td><strong>Study area</strong></td><td>the area to clip to</td></tr><tr><td><strong>Polygons</strong></td><td>the polygons to clip</td></tr></tbody></table><h3>How to use it</h3><p>Connect both inputs; there is nothing to set, and <strong>Configure\u2026</strong> says so. <strong>Show me how it works</strong>, in that dialog, clips three made-up units, one inside, one across the edge and one outside, step by step.</p><p><strong>Result</strong> gives how many polygons the last run kept.</p><h3>What it will not do</h3><ul><li><strong>It will not keep a polygon outside the study area</strong>, even one that touches its edge at a single point.</li><li><strong>It will not recompute what a polygon carries.</strong> A count or a population stays the whole polygon's, though only</li></ul><p>part of it is kept: a step after this one that needs the part's share must compute it.</p><ul><li><strong>It will not change the study area.</strong></li><li><strong>It does not cut on a projection.</strong> Edges are cut as straight lines in longitude and latitude, which is close</li></ul><p>enough for a district and not for an area spanning hundreds of kilometres.</p><h3>Where it is used</h3><p>The John Snow examples clip their pump catchments to the illustrative Soho reporting rectangle.</p><h3>History</h3><h4>2026-11-21 \xB7 Configure\u2026, with Show me how (0.3.0)</h4><p><strong>Configure\u2026</strong> says there is nothing to set and holds <strong>Show me how it works</strong>, which was in the panel; its drawing, all black, now shows each shape as its key says.</p>",clip_raster:"<h2>Clip raster</h2><p><strong>A raster cut to a boundary, cell by cell.</strong> The population living inside a district rather than in its bounding box.</p><h3>What it does</h3><p>It keeps the cells of a raster that fall inside a boundary, at the raster's own resolution, and sets every other cell to no data. Nothing is resampled, reprojected or filled. Cells outside are still in the grid, marked as no data, so the grid keeps its shape and its place on the ground.</p><h3>What you connect</h3><table><thead><tr><th>Input</th><th>What it takes</th></tr></thead><tbody><tr><td><strong>Raster to clip</strong></td><td>a Raster input, or another Clip raster</td></tr><tr><td><strong>Study area</strong></td><td>the area whose boundary is copied as the cutline</td></tr></tbody></table><h3>How to use it</h3><p><strong>Configure\u2026</strong> sets three things, and none of them is written until <strong>Apply</strong>:</p><table><thead><tr><th>Setting</th><th>Choices</th></tr></thead><tbody><tr><td><strong>Keep a cell when</strong></td><td><em>the boundary covers any part of it</em> (all touched), or <em>its centre is inside the boundary</em></td></tr><tr><td><strong>Margin beyond the boundary</strong></td><td>0 to 1 cell. A margin needs the raster to reach that far past the boundary; Raster input's one-cell margin gives it that.</td></tr><tr><td><strong>Boundary</strong></td><td>the study area's, or this step's own once one has been drawn</td></tr></tbody></table><p><strong>Draw the boundary on the map\u2026</strong> opens the study area's shape over the raster, to adjust it for this step alone. The study area is not changed. The map previews how many cells would be kept as the boundary moves. It edits a single polygon; a boundary with holes or several parts is kept but cannot be edited there.</p><p><strong>Result</strong> says how many cells the last run kept inside the boundary, and how many of them hold a value. <strong>Download GeoTIFF</strong> gives the clipped grid without a run; <strong>Add raster map</strong> puts a Map after it.</p><h3>What it will not do</h3><ul><li><strong>It will not fill no data</strong>, inside the boundary or in the margin.</li><li><strong>It will not weight a cell by how much of it is inside.</strong> A cell is kept whole or not at all.</li><li><strong>It will not resample or reproject.</strong> The raster must be in latitude and longitude, as Raster input keeps it.</li><li><strong>It will not change the study area</strong> when its own boundary is drawn.</li></ul><h3>How it was checked</h3><p>Compared with rasterio 1.5.2 and GDAL 3.12.2 over a synthetic grid and a concave cutline. <em>Centre inside</em> agrees exactly. <em>All touched</em> differs by 2 of 146 cells, both kept by GDAL only, where a boundary corner lies exactly on a cell border. The margin has no GDAL equivalent and is checked only against a model of it, so it is not validated.</p><h3>Where it is used</h3><p>No worked example uses it today. The Old Naledi example did, until it was retired on 2026-11-11 ([audit](../audits/old-naledi-audit.md)).</p><h3>History</h3><h4>2026-11-18 \xB7 The standard Inspector (1.2.0)</h4><p>Moved to the Inspector every touched widget takes (experiment 186): Name, Inputs, Settings with Configure\u2026, Result. The inclusion rule and the margin had been edited directly in the panel and saved on each change; they are now in Configure\u2026 with the choice of boundary, and saved together on Apply. The panel's description of its processing parameters was removed, and Result now reports the cells kept.</p><h4>2026-11-19 \xB7 A streamed raster is not clipped (1.2.1)</h4><p>A raster too large to keep is streamed (Raster input, History), and a clip of it would be as large. Clip raster says so and points to Sample a raster, which reads a streamed raster over areas or at points.</p><h4>2026-11-20 \xB7 The boundary named by its digest (1.3.0)</h4><p>The receipt names the boundary by the SHA-256 of its GeoJSON, which anyone holding the project can recompute, instead of writing out its coordinates.</p>",compare_point_sets:"<h2>Compare point sets</h2><p><strong>A process widget.</strong> It takes a set of points and the same points moved, and gives back a table of distances: how far the mean centre moved, how far each mean centre is from its nearest reference point, and how far a point moved.</p><h3>What it does</h3><p>A mask that moves each location, such as donut geomasking, is meant to hide where people were without changing what the map says. This step measures what the move did to the pattern as a whole: whether the centre of the points moved, and whether it moved nearer to or further from a reference such as a pump.</p><h3>What you connect</h3><table><thead><tr><th>Connect</th><th>What it needs</th></tr></thead><tbody><tr><td><strong>Original points</strong></td><td>the points before they were moved</td></tr><tr><td><strong>Moved points</strong></td><td>the same points after, as many and in the same order</td></tr><tr><td><strong>Pumps, for reference</strong></td><td>the reference points each mean centre is measured to</td></tr><tr><td><strong>Original mean centre</strong> and <strong>Moved mean centre</strong></td><td>optional: a Mean center step on each set, in the same UTM zone</td></tr></tbody></table><p>Out comes a table, one row per measure, in metres. Connect it to a Table to read it. Connect the points and the mean centres to a Map to see them: a Mean center is drawn as one point, named by its step.</p><h3>How to use it</h3><p>1. <strong>Connect</strong> the original points, the moved points and the pumps, and, if you want them, a Mean center on each set. 2. <strong>Configure\u2026</strong> sets the UTM zone the distances are measured in: the zone the points lie in. Each Mean center step connected must use the same zone. 3. <strong>Run the workflow.</strong> The panel's Result says how far the mean centre moved.</p><h3>What it will not do</h3><ul><li><strong>It keeps the original locations.</strong> The comparison, and the Map and Table made from it, hold the original</li></ul><p>coordinates, and pairing each point with its moved copy is exactly what the mask exists to break. They are for teaching, not for sharing.</p><ul><li><strong>A centre that barely moves does not establish privacy</strong>, nor that each location is still accurate.</li><li><strong>The pumps give geographic context.</strong> They do not establish that anyone used a pump.</li></ul><h3>Worked examples that use it</h3><table><thead><tr><th>Example</th><th>What it does there</th></tr></thead><tbody><tr><td><strong>John Snow: can the locations be shared safely?</strong></td><td>measures what donut geomasking did to the 250 death locations</td></tr></tbody></table><h3>History</h3><h4>2026-11-20 \xB7 A table of distances (0.3.0)</h4><p>It hands on a table of what it found, in place of the comparison Comparison map drew, which retired into Map and a Table. Its panel moves to the standard, with the UTM zone in Configure\u2026 and how far the mean centre moved as its Result.</p>",deduplicate_points:"<h2>Deduplicate records</h2><p><strong>A comparison.</strong> It takes two or more point layers from different sources, finds the records that are the same place, and merges the pairs that agree. The pairs it is unsure about it gives to you.</p><h3>What it does</h3><p>Two sources over one study area draw the same hospital twice. A count of facilities is then wrong by however many of those there are, and no amount of care downstream fixes it, because nothing downstream knows which records were the same place.</p><p>This compares records <strong>across</strong> sources and asks two questions of every pair it considers:</p><ul><li><strong>Do the names agree?</strong> Either exactly, after normalising, or by similarity.</li><li><strong>Are they in the same place?</strong> Within a distance you set.</li></ul><p>Each question that answers yes is worth one point. A pair scoring two merges on its own. A pair scoring one <strong>waits for you</strong>, because the two questions disagree and that is a judgement rather than a calculation. A pair scoring none was never a candidate.</p><h3>Rows of one table</h3><p>Choose <strong>Rows of one table</strong> under <strong>The records are</strong>. The widget then takes one table and compares rows that share the columns identifying a row, by default the table's declared primary key. These are the rows Data quality reports as repeating a key.</p><table><thead><tr><th>Pair</th><th>What happens</th></tr></thead><tbody><tr><td>Identical on every compared column</td><td>One record entered twice: the later row is left out on its own</td></tr><tr><td>Any compared column differs</td><td>Waits for you. Choose <strong>Two records</strong>, or <strong>Same record</strong> and which row to keep</td></tr></tbody></table><p>The rows left out are named in the receipt, and the input table is not changed. A row is never dropped because it came second: keeping the first row of a pair that disagrees would silently delete a case.</p><h3>What you connect</h3><p>Two or more <strong>point</strong> layers, each from a different source. One layer has nothing to compare with, so two is the floor rather than the shape; use <strong>Add point input</strong> for a third and a fourth.</p><h3>How to use it</h3><p>The step's panel holds its <strong>Name</strong>, its <strong>Inputs</strong>, one sentence saying what it compares, and <strong>Configure\u2026</strong>. After a run, <strong>Result</strong> says what it found: the pairs counted, the records merged away, and <strong>Review pairs</strong> where some wait for you. Under that, <strong>Manual</strong>, <strong>Evidence</strong> and <strong>Version</strong>, then <strong>Duplicate</strong> and <strong>Remove</strong>.</p><p><strong>Configure\u2026</strong> opens the step's dialog, where every setting is. <strong>The records are</strong> chooses <em>Points, in two or more sources</em> or <em>Rows of one table</em>; the settings below follow it. Nothing changes the workflow until <strong>Apply</strong>.</p><p>To match the names of one table to another's, such as a line list's districts to the boundaries', use <strong>Relate a column from another table</strong> and allow for spelling there.</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Name attribute</strong></td><td>Which attribute carries the name. <code>name</code> for most sources.</td></tr><tr><td><strong>Name comparison</strong></td><td><em>Exact</em> after normalising, or <em>Jaro\u2013Winkler similarity</em>.</td></tr><tr><td><strong>Similarity at or above</strong></td><td>The similarity at which two names count as agreeing.</td></tr><tr><td><strong>Compare pairs within</strong></td><td>Pairs further apart than this are never compared at all.</td></tr><tr><td><strong>Count as the same place within</strong></td><td>The distance at which two records are in one place.</td></tr><tr><td><strong>Merge automatically at a score of</strong></td><td>Two means both questions must agree.</td></tr><tr><td><strong>Ask me at a score of</strong></td><td>One means a single agreement brings the pair to you.</td></tr></tbody></table><h4>Choosing the distances</h4><p>These are the two numbers worth measuring rather than accepting. Sources digitise a facility differently \u2014 one marks the building, another the compound gate, a third the signpost on the road \u2014 so how far apart two records of one facility sit is a property of <strong>your</strong> sources. Run it once with a generous <em>compare pairs within</em>, read the distances on the pairs it offers you, and set <em>count as the same place within</em> from what you see.</p><h4>Deciding a pair</h4><p>Select the widget and choose <strong>Review pairs</strong>. The dialog shows one pair at a time, with:</p><ul><li><strong>Both records side by side</strong>, each under the name of the source it came from.</li><li><strong>Every attribute either record carries</strong>, lined up in one table, with the fields that agree</li></ul><p>marked apart from the fields that differ. This is usually what settles it: a second field agreeing, or a second field flatly disagreeing. A field missing on one side shows as a gap, because a missing value is not agreement.</p><ul><li><strong>How far apart</strong> the records are, <strong>how closely the names matched</strong>, and which of the two tests</li></ul><p>agreed.</p><p>Answer <strong>The same place</strong> or <strong>Different places</strong>, and say why. The reason is required: a judgement nobody can read six months later is not a record of one. It is kept with the decision, and the decision is pinned to the records as they were \u2014 <strong>edit either record and the judgement lapses</strong>, rather than a stale answer riding on changed data. A decision can be taken back from the same dialog.</p><h3>Reading what you get</h3><p>A point layer with one record per place. A merged record keeps the first source's values and carries a <code>mergedFrom</code> attribute naming every record that went into it. Records with no usable location pass through untouched \u2014 they were never candidates, and nothing has been said about them.</p><p>The receipt records the whole rule: the name method and its threshold, both distances, both score thresholds, how many pairs were compared, how many the blocking rule withheld, how many matched, how many are still waiting, and for every candidate its score, its distance and its name similarity. A figure that reports a deduplicated count can therefore say what produced it.</p><h3>What it will not do</h3><ul><li><strong>It will not look inside one source.</strong> Comparison is across sources, so a layer's duplicates of</li></ul><p>itself are not found.</p><ul><li><strong>It will not read abbreviations.</strong> <code>HGR Goma</code> and <code>H\xF4pital G\xE9n\xE9ral de R\xE9f\xE9rence de Goma</code> are one</li></ul><p>facility and this will not say so: there is no nickname dictionary, no transliteration, no phonetic key and no learned model. That pair reaches you in the review band, which is where the judgement belongs.</p><ul><li><strong>It will not merge on a name alone</strong>, at the settings it ships with. Two clinics in one town can</li></ul><p>share a name; two unrelated facilities can stand twenty metres apart.</p><ul><li><strong>It will not decide for you.</strong> A pair in the review band stays two records until somebody</li></ul><p>answers. The gate is on the merge, not on the run.</p><ul><li><strong>It cannot tell you the thresholds are right.</strong> They are declarations about your data, and the</li></ul><p>only way to know is to look at the pairs it offers.</p><h3>Where the method comes from</h3><p>The contracts are those of an earlier record-linkage command \u2014 blocking before comparison, binary contributions rather than a blended score, three classes rather than merge-or-not, and a missing value that never agrees with another missing value. This widget adds the spatial comparison and the merge the thresholds licence.</p><h3>History</h3><h4>2026-11-22 \xB7 Blank on both sides is not agreement (0.4.0)</h4><p>Found by the stress tests of the table operations. Two rows with no name, in the same district, were merged as one record entered twice. A pair whose compared column is empty in both now waits for you, and the review says the column is empty in both. Its Inspector and dialog moved out of the application's main file, unchanged.</p>",derive_value:"<h2>Derive a value</h2><p><strong>Arithmetic.</strong> It takes a table, combines two of its values with one operation, and gives the table back with a new value added for every group of rows.</p><h3>What it does</h3><p>A table here is <strong>long</strong>: every row carries one value, under key columns. So two numbers about the same subject are two rows, not two columns. Snow's Table IX holds</p><table><thead><tr><th>supplier</th><th>measure</th><th>count</th></tr></thead><tbody><tr><td>Southwark and Vauxhall Company</td><td>houses</td><td>40,046</td></tr><tr><td>Southwark and Vauxhall Company</td><td>deaths</td><td>1,263</td></tr></tbody></table><p>and the number a 2\xD72 needs \u2014 <strong>houses without a death</strong> \u2014 is in neither row. It is <code>houses</code> minus <code>deaths</code>, and until this widget existed the only way to get it was to compute it somewhere else and import the answer.</p><p>This step computes it once per group: all the rows sharing the other key columns are one group, and <code>measure</code> is the column holding the names of the values to combine.</p><h3>Seeing what this step did</h3><p>After a run, <strong>View this table</strong> at the top of the Inspector opens the output. <strong>Before</strong> and <strong>After</strong> switch between the table that came in and the one that went out, and After says how many rows and columns there were before.</p><h3>What you connect</h3><p><strong>records</strong> \u2014 a table. It gives back the same table with the derived rows added.</p><h3>How to use it</h3><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Key column holding the values</strong></td><td>Which column names the values. In Snow's table, <code>measure</code>.</td></tr><tr><td><strong>First value</strong></td><td>The left operand, e.g. <code>houses</code>.</td></tr><tr><td><strong>Operation</strong></td><td>minus, plus, times, divided by.</td></tr><tr><td><strong>Second value</strong></td><td>The right operand, e.g. <code>deaths</code>.</td></tr><tr><td><strong>Name for the derived value</strong></td><td>What the new rows are called, e.g. <code>houses without a death</code>.</td></tr></tbody></table><p>The values are offered as a list wherever the chain ends in a table this canvas holds, including through an earlier <em>Derive a value</em> or <em>Select rows by value</em>. Where it does not, you type them.</p><h3>What it refuses, and why</h3><p><strong>A group missing either value gets no row, and is named in the evidence.</strong> A supplier whose house count nobody recorded has an <em>unknown</em> number of houses without a death. Writing a zero there would be a measurement the table never made.</p><p><strong>A name the column already uses is refused.</strong> Two rows would then share a key, and a table with two values for one key is one nobody can read.</p><p><strong>Dividing by zero is unknown, not infinite.</strong></p><h3>What it will not do</h3><p>It will not tell you whether the two values can be combined. Subtracting deaths from houses works because both count houses; subtracting a rate from a count is equally allowed here and is nonsense. Check that yourself before reading the answer.</p><p>It will not fill in a group whose values are incomplete. Those groups come back named, with no derived row, and any figure you draw from the result is missing them \u2014 count them before you present it.</p><p>It will not reach across tables. Both values must already be in the one table you connect.</p><h3>What this does not establish</h3><p>The widget does not know what its numbers count. Subtracting deaths from houses is sound only because both count houses; subtracting a rate from a count is equally permitted here and is nonsense. Nothing checks that the two values are commensurable, because nothing in the table says so \u2014 the unit belongs to the table as a whole, not to each measure.</p><p>A derived value is also not a measurement. <code>houses without a death</code> was never observed; it is an inference from two things that were, and it inherits every error in both.</p>",donut_geomask:"<h2>Move points in a donut</h2><p><strong>A geoprivacy teaching step.</strong> It takes points and gives back the same number of points, each moved a random distance in a random direction, between a least and a most distance from where it was.</p><h3>What it does</h3><p>Each point is moved somewhere in a ring, a &quot;donut&quot;, around its true position: never less than the least distance, so no point stays where it was, and never more than the most, so the pattern stays readable. Each moved point gets a new name and id, and nothing else of the record is carried.</p><p>The <strong>seed</strong> makes the moves repeatable: the same seed moves the same points the same way.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>points</strong></td><td>the points to move</td></tr></tbody></table><p>Out come the moved points. Compare them with the originals with <strong>Mean center</strong> and <strong>Compare point sets</strong> to see what the move cost.</p><h3>How to use it</h3><p>1. Connect the points. 2. In <strong>Configure\u2026</strong>, set the least and most distance in metres (up to 5,000) and the seed. 3. Run, and compare the moved points with the originals.</p><h3>What it will not do</h3><ul><li><strong>It does not make data safe to share.</strong> Whether a mask protects anyone depends on the population around each point,</li></ul><p>and that is not calculated here. The seed is predictable, so anyone with it can repeat the moves.</p><ul><li><strong>It does not keep attributes.</strong> A moved point has a new name and id only, so it cannot be weighted afterwards.</li><li><strong>It does not remove the original.</strong> The source stays in the project and in the run's evidence.</li></ul><h3>How it was checked</h3><p>No lab notebook checks it yet. The browser test asserts that every point moved within the stated ring.</p><h3>History</h3><h4>2026-11-23 \xB7 Show me how (0.3.0)</h4><p><strong>Configure\u2026</strong> offers <strong>Show me how it works</strong>: a made-up home: the distance it will not stay within, the distance it will not pass, and where the seed set moves it.</p><h4>2026-11-22 \xB7 On the standard (0.2.0)</h4><p>Moved to the standard Inspector: the distances and the seed are in <strong>Configure\u2026</strong>, and the sentence says it is a teaching step, not a privacy guarantee.</p>",find_health_facilities:"<h2>Find health facilities</h2><p><strong>A source of facility points</strong>, two ways: every facility a source records inside a study area, or the facility each row of a list names.</p><h3>What it does</h3><p>Inside a study area, it fetches the health facilities a source records there. From a list, it finds the facility each row names in a national register, and marks how sure the match is. Either way it hands on points, each carrying where it came from.</p><h3>How to use it</h3><p>Add it from the library, then choose the way in under <strong>Configure\u2026</strong>: <em>Inside the study area</em> or <em>From a list</em>. Each is described below.</p><h3>Inside the study area</h3><p>Connect a <strong>Study area</strong>: it is the scope of the query. In <strong>Configure\u2026</strong>, choose the source (OpenStreetMap live, the Humanitarian OpenStreetMap Team's country export, or Overture Maps Places), the kinds of facility, and whether to keep only named ones; each source's licence is shown before anything is fetched. Then <strong>Retrieve facilities</strong>. The Result says how many were kept and how many were dropped, and why.</p><h3>From a list</h3><p>For a list that names facilities, such as a line list's organisation units. In <strong>Configure\u2026</strong>, choose <em>From a list</em>, then:</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Column naming the facility</strong></td><td>The list's column holding each row's facility name</td></tr><tr><td><strong>Column naming its area</strong></td><td>Optional: a district or similar, to tell apart two facilities of one name</td></tr><tr><td><strong>Registers, matched in this order</strong></td><td>Facility lists from the registers declared in the ontology: GRID3 for Sierra Leone, Nigeria and DR Congo, and OpenStreetMap for any country. A name is looked for in the first register, then the next. A register that cannot be read is shown and cannot be chosen</td></tr><tr><td><strong>Country to read OpenStreetMap for</strong></td><td>Shown when OpenStreetMap is chosen. It starts as the other registers' country</td></tr><tr><td><strong>Spelling allowed</strong></td><td>How similar a name must be to count as a spelling of another, 0.88 to start</td></tr><tr><td><strong>Words that mark a name as an area</strong></td><td>Such as <em>Communities</em>: a reporting unit for an area, which has no point</td></tr></tbody></table><p>Then <strong>Fetch the registers</strong>: a register is fetched once and kept on this device.</p><p><strong>OpenStreetMap is matched by name only.</strong> It has no facility types, so a name it matches allowing for spelling is held for your review under Decisions. It has no point until you choose. A name it matches exactly is handed on. Put it after a national register, for what that register does not have. Its points are under the Open Database License, which is share-alike: anything made from them is under it too.</p><p><strong>Every row gets one outcome, and none is dropped:</strong></p><table><thead><tr><th>Outcome</th><th>What it means</th></tr></thead><tbody><tr><td>matched exactly</td><td>The name and its type are one facility's</td></tr><tr><td>matched allowing for spelling</td><td>One facility's name within the tolerance, the same type. From OpenStreetMap, held for your review</td></tr><tr><td>type differs</td><td>The name matches and the type does not, as MCHP against CHP: for your review</td></tr><tr><td>ambiguous</td><td>Several facilities could be the one named: choose, under Decisions</td></tr><tr><td>an area, not a facility</td><td>No point, said</td></tr><tr><td>not found</td><td>In no register chosen</td></tr></tbody></table><p>The dialog's <strong>Preview</strong> counts them, by name and by row, before you apply. <strong>Decisions</strong> lists each ambiguous name, each type that differs and each spelling held, with its candidates, so you choose the facility it means, or none. Rows with a facility become points carrying the outcome, the register's name and identifier, and the score.</p><h3>What it will not do</h3><ul><li>Place anyone at home. A point is where the register places the facility.</li><li>Guess. A type that differs, an ambiguous name, a spelling held, an area and a name not found have no point until you decide.</li><li>Geocode an address or a place that is not a facility.</li></ul><h3>What this does not establish</h3><p>That a source records every facility that exists: an absence is not evidence of absence. That 0.88 suits every country's names: it was checked by hand on Sierra Leone's. That OpenStreetMap's spellings can be trusted anywhere: on Sierra Leone's names, 4 of 7 that could be checked against GRID3 were the wrong facility.</p><h3>History</h3><h4>2026-11-24 \xB7 The Inspector on the standard (0.5.0)</h4><p><strong>Configure\u2026</strong> now sits alone in Settings, the way it does on every other step. <strong>Retrieve facilities</strong> \u2014 or <strong>Fetch the registers</strong>, when you are matching a list \u2014 has moved down to <strong>Result</strong>, beside the facilities it produces. It is the highlighted button until there is something, and highlighted again when what the step holds is not what the settings now ask for.</p><p>The two used to share a row, swapping which of them looked like the thing to press. They are not the same kind of act: Configure\u2026 opens a dialog, and Retrieve reaches out to the source and changes what the step holds.</p><p>The dialog also used to send you to retrieve &quot;under Settings&quot;, which was not where the button was. It names Result now, and says to apply your settings first.</p><h4>2026-11-23 \xB7 Moved out of the application's main file (0.4.3)</h4><p>Its Inspector moved into this widget's own module. <strong>Retrieve facilities</strong>, on a step that named no country, filled in the study area's country and then refused the retrieval, saying the workflow had changed while it ran. It now fills in the country first, so the retrieval goes ahead.</p>",space_time_scan:"<h2>Space-time scan</h2><p>Looks for places where cases came closer together in time than the rest of the line list would lead you to expect. It is the space-time permutation scan that SaTScan runs, for a line list of cases with a date and a place, and no population.</p><h3>What it does</h3><p>The scan tries every circle around every place, and every run of days or weeks. For each circle and run it counts the cases in both, and compares that with how many would be expected if when a case happened had nothing to do with where:</p><p>&gt; expected = the circle's cases over the whole period \xD7 the run's cases everywhere \xF7 all cases</p><p>The circle and run that are most unusual, by the likelihood ratio, is the <strong>most likely cluster</strong>. To test it, the scan shuffles the dates across the places many times and, each time, finds the highest score anywhere. The p-value is how often a shuffle scored as high, plus one, over the shuffles plus one.</p><p><strong>Secondary clusters</strong> follow, in order of score. Each shares no place with a cluster before it, and each is tested against the same shuffles, which is conservative.</p><h3>What you connect</h3><ul><li><strong>Cases, with a date and a place</strong>: a point layer. Each record needs a date and a location.</li></ul><h3>How to use it</h3><p>1. Connect a point layer of cases. 2. Press <strong>Configure\u2026</strong> and choose <strong>Each case's date</strong>. 3. Choose <strong>Count by</strong>: day or week. 4. Leave the limits at SaTScan's defaults, or change them: - <strong>Largest circle</strong>: a share of all cases, at most 0.5; - <strong>Largest radius</strong>, in km, if any; - <strong>Longest run</strong>: a share of the study period, at most 0.5; - <strong>Study period</strong>: blank means the first to the last date. 5. <strong>Shuffles of the dates</strong> is 999 by default. The <strong>seed</strong> is shown, so the same run gives the same p-values. 6. Press <strong>Apply</strong>, then <strong>Run</strong>. A progress bar shows the shuffles.</p><p>Connect the scan to <strong>Map</strong> to draw the clusters as circles, and to <strong>Table</strong> to list them.</p><h4>Day by day, as the outbreak unfolded</h4><p>Under <strong>How to scan</strong>, choose <strong>Day by day</strong>. Each day, the scan looks only at the cases known by then, and only at runs that end that day: is something happening now? This is SaTScan's prospective scan, run once a day.</p><p>The result is one row per day: that day's most likely cluster, its counts and its p-value. The step says the first day the p-value was at or under 0.05, and at or under 0.01.</p><p><strong>To watch it day by day</strong>, connect it to a Map set to <strong>Interactive map</strong>, with the cases. Press <strong>Play</strong>, or drag the slider: each day shows that day's circle, only the cases with a date up to that day, and what the scan said in words. Hagelloch's <em>Was there a cluster?</em> has this map: <em>The outbreak, day by day</em>.</p><ul><li><strong>Each day's p-value is that day's alone.</strong> Looking every day raises the chance of a false alarm, and this does not</li></ul><p>correct for it.</p><ul><li>A day with fewer than 4 cases, 2 places or 2 days is too early to scan, and is listed as skipped.</li><li>Cases count on the day of their date, which is not the day they were reported.</li></ul><h4>In the write-up</h4><p>Both ways write a note under Methods: the expected count and the score, worked on the most likely cluster, and how the p-value was found. The method's paper reaches References: Kulldorff M, Heffernan R, Hartman J, Assun\xE7\xE3o R, Mostashari F. A space-time permutation scan statistic for disease outbreak detection. PLoS Medicine. 2005;2(3):e59. It is open access.</p><h4>Reading what you get</h4><p>Each cluster carries its first and last day, its places, its radius, the cases observed and expected, their ratio, the log likelihood ratio and the p-value. The case ids inside it are listed.</p><ul><li>The <strong>p-value</strong> is reported as computed. Which threshold to read it against is yours to state, in your write-up.</li><li>A cluster at <strong>one place</strong> has no radius. It is drawn as a ring 15 m round that place, red for the most likely and blue otherwise, outline only, so what is under it shows.</li><li>Records <strong>without a date or a location</strong>, or outside the study period, are not scanned. They are counted and named.</li></ul><h4>How to read the cluster map</h4><ul><li><strong>A circle is a group of places and a run of days together.</strong> Its cases fell ill closer together, in those places and</li></ul><p>on those days, than the whole outbreak's timing and places would lead one to expect. It is not a boundary of spread.</p><ul><li><strong>The most likely cluster</strong> is the one least likely to be chance; the others are <strong>secondary</strong>, each with its own</li></ul><p>p-value. A p-value near 1 says that cluster is what shuffling the dates gives routinely.</p><ul><li><strong>A cluster at one house is a ring round it</strong>, red for the most likely and blue for a secondary one, so the</li></ul><p>house shows through and the ring stands out on a black-and-white sheet; its size is not an area. Hagelloch's most likely cluster is one house: 8 children of three families, the outbreak's first case among them, ill from 30 October to 18 November 1861, where 0.55 were expected, p = 0.001.</p><ul><li><strong>It says where and when, not who infected whom.</strong> That is the transmission tree's question.</li><li><strong>A cluster over several houses is filled</strong>, in its rank's colour. Neither colour nor ring says the p-value: read it</li></ul><p>from the table of clusters.</p><h3>Worked examples that use it</h3><table><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Hagelloch \xB7 was there a cluster?</strong></td><td>188 measles cases by day of prodrome; the most likely cluster is one house, 8 cases where 0.55 were expected, 30 October to 18 November 1861, p = 0.001. Replayed day by day, first flagged at p \u2264 0.05 on 21 November</td></tr></tbody></table><h3>What it will not do</h3><ul><li><strong>It does not see where people live.</strong> Only the timing is compared across places, so a crowded street is not a</li></ul><p>cluster here. A rise everywhere at once is not a cluster either.</p><ul><li><strong>It does not say a cluster is an outbreak.</strong> A cluster is a place and time to look at, not a finding.</li><li><strong>It does not use a population.</strong> That is the Poisson scan, not built yet.</li><li><strong>Day and week can disagree.</strong> On Hagelloch the second cluster has p = 0.07 by day and 0.01 by week. Choose the unit</li></ul><p>for the question, before you look.</p><p>Experiment 200.</p><h3>History</h3><h4>2026-11-25 \xB7 No limit shorter than the scan can run (0.8.0)</h4><p>The shortest run the scan ever applies is one period. The Preview worked the share out on its own and could reach zero \u2014 five days at a tenth read <em>up to 0 days</em> of a scan that runs one-day windows.</p><h4>2026-11-25 \xB7 The Preview says what the shares come to (0.7.0)</h4><p>Every setting here but two is a share, and a share says nothing on its own: circles up to 20% of the cases means two over ten cases and two thousand over ten thousand. The dialog held the numbers and left the arithmetic to be done.</p><p>It now counts the cases carrying a date it can read, the period they span, and what each share works out to in the units of the thing it limits \u2014 cases for a circle, days or weeks for a run. The scan itself is not run here: it shuffles the dates hundreds or thousands of times, which belongs in the run.</p><h4>2026-11-22 \xB7 Out of the application's main file (0.6.2)</h4><p>Its Inspector and its dialog moved into a module of their own. Nothing it does changed.</p>",group_table:"<h2>Total within groups</h2><p><strong>Addition, or a count.</strong> It takes a table, keeps the key columns you name, and adds up the values of every row that agrees on them, or counts those rows.</p><h3>What it does</h3><p>32 sub-districts, each with a population and a death count, each belonging to one of three water supply categories. Totalling within the supply category and the measure turns 64 rows into six: the people and the deaths in each category. That six-row table is a contingency table, and it is what the next steps turn into a two-by-two.</p><h3>Shares within groups</h3><p>Tick <strong>Add each group's share, %</strong> and every group gets its share beside its count or total. Under <strong>Share within</strong>, tick the columns whose groups each make 100%: a line list counted by classification and by what was recorded, with the share within classification, shows how a classification's cases divide. Tick none and each share is of the whole table.</p><p>The result has a column <code>statistic</code> naming each number, the count and the share, and the table view shows them side by side. A share is held to one decimal place, so a classification can total 99.9 or 100.1. A share is offered with <strong>Sum</strong> and <strong>Count rows</strong>, which add up to a total, and not with a minimum or a maximum. A share of a total that is unknown, because a group summed over an empty cell, is unknown too.</p><h3>Seeing what this step did</h3><p>After a run, <strong>View this table</strong> at the top of the Inspector opens the output. <strong>Before</strong> and <strong>After</strong> switch between the table that came in and the one that went out, and After says how many rows and columns there were before.</p><h3>What you connect</h3><p><strong>records</strong> \u2014 any table.</p><h3>How to use it</h3><p>Connect a table, then open <strong>Configure\u2026</strong>. The <strong>Preview</strong> shows the table your settings make, and nothing changes until <strong>Apply</strong>.</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Key columns to keep</strong></td><td>The key columns that survive. Rows agreeing on all of them become one row.</td></tr><tr><td><strong>Aggregate</strong></td><td>Sum, Minimum, Maximum, Count rows, Mean or Median</td></tr><tr><td><strong>Column to total</strong></td><td>The table's value column, or a key column that holds numbers, such as one a rule computed</td></tr><tr><td><strong>Total what is present, excluding empty cells</strong></td><td>Off: a group holding an empty cell totals to nothing known. On: what was recorded is totalled, and the receipt and the write-up say so</td></tr><tr><td><strong>Add each group's share, %</strong></td><td>A share beside each count or total</td></tr><tr><td><strong>Share within</strong></td><td>The columns whose groups each make 100%. None ticked: the whole table</td></tr></tbody></table><h4>Why you name what is kept rather than what is dropped</h4><p>Because files change. Name the columns you keep and a column added to the file later is simply dropped, leaving you the same groups you had before. Name the columns you drop and that new column silently becomes a grouping key, splitting your groups without telling you.</p><h4>Counting a line list</h4><p>A line list has no count in it: Oswego's 75 people are a row each, with a Y or an N under every food. Choose <strong>Count rows</strong> and each group holds how many rows agree, which is what a two-by-two needs. Keep the exposure and the outcome and the four cells come out.</p><p>Count rows never reads the value, so a blank is still a row and the result's value is called <code>rows</code>. <strong>It counts rows, not people.</strong> Import one value column from a line list: two value columns give two rows per person, and each person then counts twice. The step cannot detect that.</p><h4>Adding, and what does not add</h4><p>Adding counts gives you a count. Adding <strong>rates</strong> gives you a number with no referent \u2014 deaths per 1,000 in three sub-districts do not add up to deaths per 3,000 in one. This step cannot tell a count from a rate, and will add up rates if asked.</p><p><strong>Mean</strong> and <strong>Median</strong> summarise the values present in each group: an incubation period or a serial interval is usually reported as a median. Neither is offered with a share, because neither adds up to a total.</p><h4>Totalling a column other than the value</h4><p>A table holds one value column, and that is what is totalled unless you choose another. A key column holding numbers can be chosen instead: the days from exposure to onset that a rule computed for every case, say, with <strong>Median</strong> by outcome. Its blank cells are empty cells, as in the value column; a cell that is not a number stops the run and names the row. The result carries no unit, because the unit the table declares is its value column's.</p><p><strong>Every column kept, one column chosen to total.</strong> Keeping every other column makes each row its own group, and the step still does one thing: the chosen column becomes the value the table hands on. Salmonella's map uses this. Each Land arrives with its count of cases as a column brought from another table, and <strong>Sum</strong> of <code>cases</code> within <code>bula</code> and <code>iso</code> makes that count what Join a table to the study area draws. Without a column chosen, keeping every column is refused, because nothing would change.</p><h3>Reading what you get</h3><p>One row per group, and a receipt stating which columns were kept, which were dropped, how many rows collapsed into how many groups, and every group that held an empty cell.</p><h3>What it will not do</h3><ul><li><strong>It will not treat an empty cell as a zero.</strong> A group holding any empty value totals to</li></ul><p><strong>nothing known</strong>, and is named in the receipt. This is the whole risk of the operation: summing over an empty cell gives a total that is too small by an amount nobody can state, and a stratum whose population was never recorded should come out <em>unknown</em> rather than <em>small</em>.</p><ul><li><strong>It will not check that the rows belong together.</strong> You named the columns; it adds up what</li></ul><p>agrees on them. If you ask it to total a column of rates it will do that, and the number will mean nothing.</p><ul><li><strong>It will not group by everything.</strong> That is a no-op, and it says so rather than handing back</li></ul><p>your table unchanged.</p><h3>Where it is used</h3><p>The South London example: <em>Were deaths more common with one water supply than the other?</em> The MERS-CoV example: <em>How long from exposure to onset, and from onset to death?</em>.</p><h3>What this does not establish</h3><p>That a share is the measure you need. A share of rows is not a rate: it has no denominator of people unless each row is one person.</p><h3>How it was checked</h3><p>Validation Lab check <strong>29</strong>, <code>29-group-table-vs-pandas.ipynb</code>, against a pandas groupby. All six totals of the Snow contingency table agree exactly \u2014 they are integer counts, so the tolerance is zero rather than small.</p><p>The empty cell is the case worth checking, and <strong>pandas has no option for the rule this widget states</strong>. <code>min_count=1</code> reads like it and is the first thing anyone writes: it bounds how many values must be <em>present</em>, not whether any are <em>absent</em>, so on eleven numbers and one empty cell it returns the eleven. On this data that is 147,945 people instead of nothing known \u2014 short by the one sub-district nobody recorded. The comparison that does hold is a per-group <code>sum(skipna=False)</code>.</p><p>Validation Lab check <strong>39</strong>, <code>39-group-shares-vs-pandas.ipynb</code>, recomputes the shares with pandas on the same table: each company's share of the people and of the deaths, a count's share of all, and one emptied cell. Every number agrees exactly, in CPython and in the browser kernel.</p><p>What no check can verify is the protection that matters most here: summing is the only operation offered, because this step cannot tell a count from a rate.</p><h3>History</h3><h4>2026-11-22 \xB7 What the keys hide, said (0.7.0)</h4><p>Found by the stress tests of the table operations. Rows whose key was blank were totalled as a group with nothing to name it, and &quot;South&quot; and &quot;south&quot; were totalled apart without a word. Both are now said in the step's sentence of what it did, and nothing is merged or dropped: which spellings are one place is yours to say.</p><h4>2026-11-19 \xB7 Shown on a made-up example (0.6.0)</h4><p><strong>Show me how it works</strong>, in Configure\u2026, steps through five made-up rows gathered into two regions under the summary you have chosen; a group with an empty cell has an unknown total unless empty cells are left out, and a count of rows counts the empty one. Back, Step and Play; nothing moves where reduced motion is asked for. Its last step is the table this step makes from the same rows. Experiment [223](../experiments/223-a-table-step-shown-on-a-small-example.md).</p>",isochrone:`<h2>Network isochrone</h2><p><strong>A process widget.</strong> It draws the area you can reach on foot within a stated time, walking along real streets, from one or more sites.</p><h3>What it does</h3><p>From each site it walks outward along the street network until the time runs out, then draws a band around every street it reached. The result is one region per site \u2014 not a circle, because streets are not straight and do not go everywhere.</p><p>A walk has three parts and this charges for all three: <strong>to</strong> the nearest junction, <strong>along</strong> the streets, and <strong>off</strong> the street at the end to reach a door.</p><h3>What you connect</h3><table><thead><tr><th>Connect</th><th>What it needs</th></tr></thead><tbody><tr><td>your sites</td><td>the points to walk from \u2014 pumps, clinics, depots</td></tr><tr><td>a street network</td><td>from the <strong>Street network</strong> widget</td></tr></tbody></table><p>Out come polygons, one per site. Draw them on a Map, or count your records into them with <strong>Summarize points in polygons</strong>.</p><h3>How to use it</h3><p>1. <strong>Add it</strong> from the palette, under Catchments. 2. <strong>Connect your sites and a street network.</strong> 3. <strong>Open Configure\u2026 and set the budget.</strong> <em>Minutes</em> \xD7 <em>metres per minute</em> is how far someone can walk \u2014 5 minutes at 75 m/min is 375 m of street. 4. <strong>Set the final walk off the street</strong> \u2014 how far from a street someone can get to a door. The band is this wide where there is time left and narrower where there is not. 5. <strong>Set the snap limit</strong> \u2014 how far a site may be from the nearest street before the result says so. 6. <strong>Check the zone.</strong> Measuring happens in metres, so the UTM zone is part of the answer, and every measuring step in one workflow must agree on it. The dialog suggests the zone that fits your data, and the run is refused by name if the steps disagree. 7. <strong>Run the workflow</strong>, then read the regions on a map and the alert in the Inspector.</p><h3>How the travel time is spent</h3><p>Shortest paths are Dijkstra over the network's directed edges and the metre lengths it supplies, including the partial length of a curved edge where the budget runs out part-way along it.</p><p>All three legs of the journey are charged against the same budget:</p><table><thead><tr><th>Leg</th><th>What it costs</th></tr></thead><tbody><tr><td>the straight walk from the site onto the network</td><td>distance to the snapped street, at walking speed</td></tr><tr><td>the streets</td><td>the shortest path, by directed edge and supplied length</td></tr><tr><td>the final walk off the street to a door</td><td>the band width where time allows it, narrower where it does not</td></tr></tbody></table><p>Charging the last leg rather than adding it is what stops a region overshooting the time it is drawn for. The off-street band is an approximation of coverage beside the streets, and holes inside it remain unless infill is enabled.</p><p>Two cases are marked rather than dropped, and the widget names both:</p><ul><li><strong>A site further from a street than the snap limit</strong> is routed anyway and marked off-network.</li><li><strong>A site whose walk onto the network alone spends the budget</strong> gets no catchment at all.</li></ul><p>A site snapped to the network before this step keeps the junction and the distance it arrived with. Nothing is projected for it, and the settings for attaching origins are not used.</p><p>Coverage can also be cut short by the graph itself: a region stops where the downloaded network stops, which is a property of the extent that was downloaded and not of the travel time.</p><h3>Worked examples that use it</h3><table><thead><tr><th>Example</th><th>What it does there</th></tr></thead><tbody><tr><td><strong>John Snow \xB7 walking catchments</strong></td><td>five-minute walking regions around the eight Soho pumps, drawn as a plot and as an interactive map, with the 1854 deaths counted into them</td></tr></tbody></table><h3>What it will not do</h3><ul><li><strong>It will not certify a traveller.</strong> The travel mode is checked against the speed, and an obvious mismatch is</li></ul><p>refused; nothing more. Public transport is not a mode, because it follows routes and a timetable rather than the street network.</p><ul><li><strong>It will not treat inbound and outbound as the same.</strong> Inbound reverses every street, so it answers who can reach</li></ul><p>the site rather than where the site can reach. On one-way streets the two differ.</p><ul><li><strong>It is not a service area or a routed travel time.</strong> It is an approximation of shape, drawn</li></ul><p>to be read. Nobody agreed to it and no router produced it.</p><ul><li><strong>It assumes the ground beside a street can be walked</strong>, at walking speed, in any direction.</li></ul><p>Near the edge of the budget that is where the region is most generous.</p><ul><li><strong>It does not drop a site that is far from the streets.</strong> Such a site is routed anyway, with</li></ul><p>the straight line to the nearest junction charged against its budget. Its region is marked, the widget glows red, and the Inspector names the leg. That straight line assumes you can cross whatever lies between, so the region reaches further than the ground allows.</p><ul><li><strong>A site whose walk to the street would spend the whole budget gets no region at all.</strong> It</li></ul><p>reaches nothing in the stated time, which is the answer. It is named in the alert, and the note on the result says the counts are over the sites that reached something.</p><h4>The direction it misleads</h4><p>All of the above push the same way: <strong>a poorly connected place looks better served than it is.</strong> Streets and footpaths are mapped unevenly, and informal settlements least of all. Read a region over sparsely mapped ground as optimistic, check the alert for sites routed off the network, and check how far each site had to go to reach a street.</p><h3>Checking it yourself</h3><p>The lab's <a href="https://digital-twin-ph.github.io/validation-lab/lab/index.html?path=19-snap-vs-pyproj.ipynb" target="_blank" rel="noopener noreferrer">snapping notebook</a> measures the displacement on the example data, and the corridor check rebuilds the region from the stated rule with Shapely.</p><h3>History</h3><h4>2026-11-25 \xB7 Show me how draws the streets the walk covers (0.7.0)</h4><p>The walk said it went &quot;along the streets in every direction&quot; and then showed only the finished region \u2014 so the thing that makes this different from drawing a circle was stated and never shown.</p><p>You now see the streets the walk actually covers, darker than the rest, growing out from the junction the clinic snaps to. Every metre is counted along a street, never across the ground, and the region is what those streets grow into.</p><h4>2026-11-23 \xB7 Show me how (0.6.0)</h4><p><strong>Configure\u2026</strong> offers <strong>Show me how it works</strong>: a made-up street grid spaced to the time set: the walk onto the nearest junction, the streets walked until the time is spent with the ground either side, and the region the step makes.</p><h4>2026-11-22 \xB7 On the standard (0.5.0)</h4><p>Moved to the standard Inspector: one sentence of direction, times, speed and last walk, and every setting in <strong>Configure\u2026</strong>, which says how far the time goes at the stated speed and holds Apply on a setting the run would refuse. The Result names the regions drawn and the sites that reached nothing or were routed off the network.</p>`,join_table_to_area:"<h2>Join a table to the study area</h2><p><strong>A join.</strong> It takes a table of values and a study area whose parts are named, matches each row to the part it names, and hands on polygons that carry the value. A map downstream can then shade them.</p><h3>What it does</h3><p>A rate per sub-district and a boundary of sub-districts are two separate things until something puts one onto the other. Without that, the only map you can draw from a table of measures is a map of where the rows are, which for most data is a map of where people live.</p><p>What is being joined is <strong>a table and another table with geometry</strong>. A GeoJSON feature, a shapefile row and a GeoDataFrame row are each a row with a geometry column, so a boundary file carries attributes exactly as a CSV does. This widget matches the two on one named column.</p><h3>What you connect</h3><ul><li><strong>records</strong> \u2014 a table. Any widget that emits one will do: an imported table, a rate, a case</li></ul><p>series. The column you match on must be one of its key columns.</p><ul><li><strong>area</strong> \u2014 a study area whose parts carry names. An area drawn by hand has no named parts, so</li></ul><p>there is nothing to key on and this says so rather than drawing an empty choropleth that looks like a finding.</p><p><strong>Or a polygon layer.</strong> Connect a <em>Polygon layer</em> in place of a study area when there are many parts. A study area is one extent of about 26,000 vertices, and Nigeria's 774 LGAs are about 218,000. The layer's name property is what rows are matched on. Connect one or the other.</p><p><strong>Joining twice</strong> adds a column: what a polygon holds is kept. Join coverage and then zero-dose counts and each LGA carries both, which is what a rule needs to read both. A layer joined this way can be matched on a code, which matters where names repeat: 5 of Nigeria's LGA names belong to two places each.</p><h3>How to use it</h3><p>Select the step. Its panel says what it will do, or, before a run, that the column naming each part is still to be chosen. Press <strong>Configure\u2026</strong>:</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Column naming each part</strong></td><td>Which of the table's columns holds the part's name. Where none is chosen, the column naming the most parts is proposed, saying how many it names: a census from Census tables carries <code>geoboundaries_name</code>, which names a study area from geoBoundaries. A run with none chosen joins on the proposed column where it names each part once. A column of the parts' IDs, such as <code>geoboundaries_id</code>, is matched on the IDs, so two parts with one name each take their own row.</td></tr><tr><td><strong>Match names</strong></td><td><em>Ignoring capitals, punctuation and spacing</em>, or <em>Exactly as written, capitals aside</em>.</td></tr><tr><td><strong>Frames from</strong></td><td>Optional: a column whose values are frames (below).</td></tr><tr><td><strong>Shade by a class</strong></td><td>Optional: a column whose values are classes, not quantities.</td></tr></tbody></table><p><strong>Before</strong> shows the table as it reaches the step and the study area's parts by name. <strong>After</strong> shows each part with the value it takes, how many take one, the rows that name no part, and anything else found, such as a name given by two rows. Both change as the settings do; nothing reaches the workflow until <strong>Apply</strong>. The parts of a polygon layer are known once the workflow has run. The study area's own panel lists its parts too, under <strong>View the parts</strong>.</p><p><strong>Show me how it works</strong>, in <strong>Configure\u2026</strong>, walks three made-up parts and a table of three rows through the matching chosen: a row that matches as it is, one that matches only once punctuation is set aside, one that names no part, and a part no row names. The two tables joined, the study area's parts and the table, stand beside the drawing, each row marked in words with what happened to it.</p><h4>Choosing how names are matched</h4><p>Names are compared for <strong>equality</strong>, never for resemblance. There is no similarity score and no threshold to set, because a name either is the name of that part or it is not.</p><p>Ignoring punctuation and spacing is what matches <code>St. George, Camberwell</code> to <code>St. George  Camberwell</code>. On Snow's South London files it is the difference between <strong>23 of 32</strong> rows matching and <strong>32 of 32</strong>: the nine that fail differ only by a comma. It will <strong>not</strong> match an abbreviation to a full name, or a historical spelling to a modern one, and it says so rather than guessing.</p><p>If your files differ by more than punctuation, this widget is the wrong tool and will tell you which rows it could not place. Fix the names at the source, where the correction is a fact about the data rather than a setting on a node.</p><h3>Reading what you get</h3><p>Polygons, one feature per part, each carrying the matched row's value and the rest of its columns. The parts are kept separate rather than dissolved.</p><ul><li><strong>A part no row names</strong> is drawn and left empty, in a neutral shade \u2014 never in the lowest class.</li></ul><p>An unmatched boundary drawn pale reads as a finding of low incidence, which is the opposite of what it means.</p><ul><li><strong>Two parts sharing a name</strong> both take the value. That is true of a rate and is <strong>not</strong> true of a</li></ul><p>count: Streatham is two polygons, and both carry its rate, which is why Snow's 32 sub-districts draw as 33 parts.</p><ul><li><strong>The parts of one unit are not two places.</strong> A municipality of several islands is one unit of several parts:</li></ul><p>each part takes the value, and none of this is reported as a repeated name. Rio de Janeiro state's 92 municipalities draw as 155 parts.</p><p>The receipt records the column matched on, the normalisation used, how many rows matched, how many did not, and every part left without a value, so a figure made from this can say what produced it.</p><h3>What it will not do</h3><ul><li><strong>It will not guess at a name.</strong> No similarity, no threshold, no review band. A row it cannot</li></ul><p>place is reported, not approximated.</p><ul><li><strong>It will not aggregate.</strong> Two rows naming the same part are a duplicate-key problem in the</li></ul><p>table, and are reported as one rather than quietly summed or averaged.</p><ul><li><strong>It will not join a finer table on its first rows.</strong> With no column chosen, a table naming each part in several</li></ul><p>rows (Nigeria's 774 LGAs, each with its state, joined to the 37 states) stops the run, saying the table is finer than the study area: use a table with one row per part, or a study area at the table's level.</p><ul><li><strong>It will not decide whether the number is worth mapping.</strong> Whether the rate was computed over</li></ul><p>the right denominator, whether the classes are honest, and whether a reader will take area for magnitude are questions this widget does not answer.</p><h3>How it was checked</h3><p>Validation Lab check <strong>31</strong>, <code>31-area-join-vs-pandas.ipynb</code>, against a pandas left merge. Every part takes the value a merge gives it, nulls included, and the counts agree \u2014 33 of 33 parts and 32 of 32 rows after folding, with Streatham's two parts carrying one value between them.</p><p><strong>What the folding bought, measured.</strong> On the raw strings only 23 of 32 rows match. The nine that need folding are all a comma: the table writes <code>St. George, Camberwell</code> where the boundary file writes <code>St. George  Camberwell</code>. A join on raw keys would have drawn a choropleth missing 28% of its sub-districts. The check also confirms the folding touched nothing <em>but</em> punctuation \u2014 it is not reimplemented there, because a second copy by the same author is not a second opinion, so what is checked is the property it must satisfy.</p><p><strong>And the data cannot supply a negative control</strong>, which is worth knowing when you rely on this. Snow's table and these boundaries contain no pair differing by more than punctuation, so nothing in the example tests a name that <em>ought</em> not to match \u2014 32 of 32 is also what a rule that matched too readily would score. The check constructs one: a part renamed to <code>Camberwell Green</code>, which this join reports unmatched. Jaro-Winkler to <code>Camberwell</code> is 0.925, so a similarity-based linkage at the usual 0.90 threshold would have accepted it. That figure is what having no threshold here is worth.</p><h3>Frames</h3><p><strong>Frames from</strong> names a key column whose values are frames, such as <code>measure</code> holding <code>dtp1_2005</code> to <code>dtp1_2024</code>. Each part then carries one value per frame, and an interactive map can play through them. The part's single value is the last frame's. A key repeated across frames is expected; a key repeated within a frame is reported.</p><h3>History</h3><h4>2026-11-21 \xB7 The levels said before a run, and IDs joined on (0.6.0)</h4><p>A census table from Census tables connected to a study area at another level is said to be, in the panel and in <strong>Configure\u2026</strong>, before anything runs: <em>The table is Nigeria's census at ADM2, 774 rows; the study area is at ADM1</em>, naming the census table at the area's level. The table's level is the one Census tables matched it on, its area's from its boundary's ID. A table from a file or another address states no level, and is checked by its rows when it runs.</p><p>A column giving the parts' IDs, as <code>geoboundaries_id</code> does, is joined on the IDs. Matched by name, Nigeria's five LGA names held by two LGAs each (Obi, Bassa, Ifelodun, Irepodun, Surulere) gave both one row's count.</p><h4>2026-11-21 \xB7 A run proposes the column (0.6.0)</h4><p>A run with no column chosen joins on the column the dialog would propose, where it names each part once. Joining Nigeria's LGA table to its 37 states, with no column chosen, stopped on <em>The table has no column &quot;&quot;</em>. Now it stops on what is wrong: the table names each state in about 21 rows, because it is finer than the study area. The dialog says the same beside its proposal.</p><h4>2026-11-21 \xB7 Show me how shows both tables (0.5.0)</h4><p><strong>Show me how it works</strong> shows the study area's parts and the table beside the drawing, each row marked with what happened to it; it drew only the parts, all black. The parts are drawn as districts with uneven borders, and each part keeps its value as the next row is joined. It is in <strong>Configure\u2026</strong> only, where it was also in the panel.</p><h4>2026-11-20 \xB7 On the standard (0.4.0)</h4><p>Every setting moves to <strong>Configure\u2026</strong>, with the table and the parts <strong>Before</strong> and each part's value <strong>After</strong>. The column naming the most parts is proposed where none is chosen, and the panel says before a run when none is: a run used to stop on an empty column name. <strong>Show me how it works</strong> is new.</p>",map_image_input:"<h2>Georeferenced map image</h2><h3>What it does</h3><p>Draws a scanned or published map <strong>underneath</strong> your workflow, in your workflow's own projection, so a modern result sits over historical ground.</p><p>It was built for John Snow's 1855 Map 2, whose blue, red and purple washes show which company supplied which part of south London \u2014 and whose purple intermingled zone is the whole point of his design. Put the sub-district boundaries over it and a reader can see for themselves whether the two agree.</p><h3>What you connect</h3><p>Nothing goes in. It is a source: you give it an image and a georeference.</p><p>Its output goes to a <strong>Map</strong>, on the <code>ground</code> port.</p><h3>How to use it</h3><p>1. Add it and choose the image \u2014 a JPEG or PNG of a map. 2. Give it the georeference, either as a world file (<code>.jgw</code>, <code>.pgw</code>, <code>.wld</code>) or as four corners in degrees: west, south, east, north. 3. Connect it to a Map, and set the opacity so you can read what is drawn on top.</p><h3>Reading what you get</h3><p>The figure says which plate it drew, where it came from, and <strong>about how many metres one of its pixels covers</strong>. Snow's plate over south London is about 16 metres per pixel: enough to recognise the river and the parish outlines, not enough to read a street.</p><p>The receipt records the image's digest, its pixel size, the four bounds, that ground resolution, and <code>layerRole &quot;context&quot;</code>.</p><h3>What it will not do</h3><ul><li><strong>It will not let you measure it.</strong> The output carries its own port type, so it cannot be</li></ul><p>connected to Clip raster or Sample raster at all. A plate's pixels are a printer's ink: sampling them returns the colour of a line, which is a number with no referent. This is the one thing the widget refuses by construction rather than by warning.</p><ul><li><strong>It will not join anything to what the map shows.</strong> A boundary drawn on an 1855 plate is a</li></ul><p>picture of a boundary. Use a study area for the frame.</p><ul><li><strong>It will not draw a rotated plate.</strong> If the world file carries rotation terms, it stops and says</li></ul><p>so. Drawing a rotated image as an upright rectangle would put the map in the wrong place while looking entirely correct.</p><ul><li><strong>A world file is read as CRS84 degrees.</strong> Corners outside the world usually mean a projected georeference, and it</li></ul><p>refuses rather than reading one datum's coordinates as another's. <strong>A GeoTIFF is read in its own projection</strong> (see below); a projection it does not read is named and refused.</p><ul><li><strong>It will not tell you the georeference is right.</strong> It draws where you said, or where the file says. The preview over</li></ul><p>today's map, with the sheet's graticule dashed, is how a misplacement is seen; matched pairs measure it.</p><h3>Where it is used</h3><p>The South London example: Snow's Map 2 under the sub-district choropleth.</p><h3>How it was checked</h3><p>Unit tests over the world-file reader, the bounds it derives from it, the ground resolution, and each refusal \u2014 a rotated world file, a flipped image, crossed corners and corners outside the world. A browser test places a plate under a figure and confirms it is drawn beneath the workflow's own layers rather than over them.</p><p>What no test establishes is whether the georeference is <strong>correct</strong>. See [experiment 143](../experiments/143-a-georeferenced-plate-as-ground.md), which records that measuring the residual at the plate's four control points against modern boundaries is what would close it, and that it has not been done.</p><h3>Placing an image by matching points</h3><p>Where there is no world file, an image can be placed by features found twice: on the image, and on today's map.</p><p>1. Select the step and press <strong>Configure\u2026</strong>. Choose the image. 2. Under <strong>How to place it</strong>, choose <strong>By matching points on the image and today's map</strong>. 3. Choose <strong>Turned and stretched as needed</strong> (three points or more) or <strong>North up, no turning</strong> (two or more). 4. Press <strong>+ Add a point</strong>. Click the feature on the image, then find the same feature on the map and <strong>Shift + click</strong> it: on the map a plain drag moves the map, and with Shift held the pointer is a crosshair. To move a point you have placed on the map, <strong>press and hold</strong> it, then drag. Or type its position: x and y on the image, longitude and latitude on the map. Name it. 5. Add more points, spread across the image. Each shows its error in metres; with more points than the fit needs, a pair whose error is much larger with that pair left out is marked <strong>check this pair</strong>. 6. Press <strong>Apply</strong>, then <strong>Run</strong>.</p><p><strong>Good pairs</strong> are things that have not moved: a church, a bridge, an old road junction, the corner of a building still standing. Where a sheet prints its own grid or frame with known coordinates, use those first. Once three points are matched, clicking a feature on the image shows a ring on the map where the fit expects it.</p><p><strong>In a worked example</strong>, the example names the features to find, in order, and why each was chosen. A slow pulse marks where to look, on the image and on the map, sized to the feature: the exact click is yours. Under each name the dialog says whether your click landed on the feature. It fills nothing in. <strong>Show where to look</strong> turns the pulse off; with reduced motion set on your device, the ring stays still.</p><p><strong>Zooming the image.</strong> A crosshair marks the centre of the image pane. Scroll until what you want is under it, then press <strong>Zoom in</strong>: it stays under the crosshair. The pane keeps its place after each click. Without a mouse, press Tab until the image pane is outlined, then scroll it with the arrow keys.</p><p><strong>While you match pairs</strong>, a box under the table says:</p><ul><li>how far the pair you just made is from where your other pairs put it;</li><li>what the placement implies: metres a pixel across and down, and how far the image is turned. Check these against</li></ul><p>the sheet's scale bar; a sheet drawn north up should be turned little;</p><ul><li>the overall error each time a pair was added. When it stops changing, more pairs add little.</li></ul><p>Over today's map it also shows how far your cursor is from where the other pairs expect the feature. <strong>Find the feature by looking first</strong>: the distance checks a click; it does not show where the feature is, and it is only as good as the pairs behind it.</p><p><strong>Preview on today's map</strong> draws the image as placed over today's map. Slide <strong>See through the image</strong> to compare the streets and buildings underneath. Each pair is drawn twice, where the placement puts it and where you clicked, joined by its error.</p><p>The map pane fetches OpenStreetMap's tiles, which sends the area you view to its servers.</p><p>A world file that turns the image is drawn turned.</p><h3>An image a worked example has already placed</h3><p>A worked example can ship an image already placed: its placement, its control points and the digest of its image, but not the image's bytes. When the workflow runs, the image is fetched from beside the application, checked against the digest, and kept on this device; a file that does not match is refused. Hagelloch's cluster map has the 1824 cadastral sheet under it this way, placed from the same four junctions the sheet workflow asks a learner to match. The sheet workflow itself still waits for the learner to choose and place the image.</p><h3>A scanned sheet as a GeoTIFF</h3><p>Choose a <code>.tif</code> and the widget reads its tags first:</p><ul><li><strong>Whether it is a picture.</strong> Three colour bands of 8 bits, or one band with a palette, is a scan of something</li></ul><p>printed. One band of numbers is a measurement, and the widget sends you to Raster input.</p><ul><li><strong>Its projection</strong>, from the tags: longitude and latitude; UTM by its code on WGS 84, NAD83 or NAD27; or a projection</li></ul><p>the file defines itself, polyconic, transverse Mercator, Lambert conformal or Albers, as published sheets use. NAD27 is carried to WGS 84 by its mean shift for the conterminous United States, good to a few metres.</p><ul><li><strong>The part over the study area</strong>, with a quarter of its size again on every side, redrawn north up. A sheet of 6,600</li></ul><p>pixels is not decoded whole.</p><p>The dialog then opens <strong>on the file's own placement</strong>, before any pair, and its preview over today's map draws the sheet's <strong>graticule</strong> dashed, on the sheet's own datum: the printed ticks and the sheet's edge should lie on it. Where they do not, the tags are wrong. Choose <strong>Moved from the file's own placement</strong> and match a pair or two; one moves it, a second says how far the pairs agree. For a printed corner, click where the dashed lines cross on today's map rather than typing its printed numbers, which are on the sheet's datum. Both placements are kept, the file's and the corrected one, with the pairs.</p><p><strong>Keep only the printed sheet</strong> cuts the image to the sheet's printed edge in its final placement, rounded from the file's extent to 7\xBD\u2032, 15\u2032 or 30\u2032, so its margin covers no neighbouring sheet.</p><p>USGS's <em>Oswego East, NY, 1943</em>: its tags place it 652 m east-west off its printed corners. One pair at its north-east corner moves it 652 m east and 11 m south, the same as measured from its pixels. <em>West of Texas, NY, 1943</em>, the sheet north of it, is placed correctly by its tags.</p><h3>History</h3><h4>2026-11-22 \xB7 Moved out of the application's main file (0.8.1)</h4><p>Its Inspector and its Configure\u2026 moved into a module of their own, unchanged. Nothing it does changed.</p>",map_output:"<h2>Map</h2><p><strong>An output widget.</strong> It draws what your workflow produced. It computes nothing, changes nothing and decides nothing \u2014 if a number looks wrong on the map, the step that produced it is where to look.</p><h3>What it does</h3><p>A map is a stack of <strong>layers</strong>, drawn in order from the ground up:</p><p>1. a <strong>basemap</strong>, if you choose one \u2014 streets or terrain, under everything else 2. a <strong>study area</strong>, as the ground your results sit on 3. <strong>polygons</strong> \u2014 catchments, hulls, cells or bands 4. <strong>points</strong> \u2014 your records, sites, or anything with a location 5. a <strong>raster</strong> or a <strong>street network</strong>, where you have one</p><p>You connect what you want drawn. There is no setting that says what kind of map this is.</p><h3>What you connect</h3><table><thead><tr><th>Connect</th><th>To draw</th></tr></thead><tbody><tr><td>a study area</td><td>the boundary your work is inside; without one, the study areas a polygon layer was read from</td></tr><tr><td>a point layer</td><td>records with locations \u2014 up to eight separate layers</td></tr><tr><td>a polygon layer</td><td>areas: districts, catchments, cells or bands \u2014 up to six separate layers</td></tr><tr><td>a raster</td><td>prepared or clipped cells</td></tr><tr><td>a street network</td><td>the streets themselves</td></tr><tr><td>a line layer</td><td>routes, tracks and borders, over the area and under the points</td></tr></tbody></table><h3>How to use it</h3><p>1. <strong>Add the Map</strong> from the palette, under Outputs. 2. <strong>Connect your first layer.</strong> Drag from any step that produced something drawable onto the map's <strong>+ Add a layer</strong> port, or pick it from <strong>Add a layer</strong> under <em>Inputs</em> in the Inspector. The map works out which port it belongs to. 3. <strong>Add more layers</strong> the same way. A second point source gets a layer of its own rather than replacing the first. 4. <strong>Open Configure\u2026</strong> for everything about how it is drawn. Nothing changes until <strong>Apply</strong>, and Apply redraws the map without running the workflow again. The settings are in groups: Presentation, Basemap, Layers, the marks, Lines between records, and Title, key and note. Once the workflow has run, the dialog draws the map beside its settings, as it will look with them: change a mark's size or the basemap and see it before Apply. On an interactive map, <strong>Import tiles</strong> (PMTiles, for a basemap that works offline) is under Basemap. 5. <strong>Choose how it is drawn.</strong> <em>Static plot</em> exports as an SVG with a scale bar and a north arrow. <em>Interactive map</em> can be panned and zoomed. 6. <strong>The basemap is OpenStreetMap</strong> unless you choose otherwise. On a static plot its tiles are fetched once and drawn into the figure, with their credit, so the SVG and PNG carry them. Choose <em>None</em> to keep the map working with no connection at all. With your own CARTO or Esri key in your credentials, an interactive map also offers CARTO's light, Voyager and dark styles, or Esri's satellite imagery, streets and outdoor maps, while your credentials are unlocked. See <em>Credentials</em> for how to get a key. A static plot draws OpenStreetMap in their place. 7. <strong>Title it</strong>, and write the source note. Both appear on the map and in its export. 8. <strong>Run the workflow.</strong> The map appears as a Results tab. <strong>Manage layers\u2026</strong> orders, names and groups the layers it draws.</p><h4>Reading what you get</h4><ul><li>The <strong>key</strong> names every layer drawn.</li><li>The <strong>scale bar</strong> and <strong>north arrow</strong> appear on a static plot. An interactive map has no</li></ul><p>single scale, so it shows neither.</p><ul><li>The <strong>source note</strong> carries whatever you wrote, plus the licence of anything the map used.</li></ul><h4>Symbols and colour</h4><p>Two things about a point are shown at once, in two separate channels, so neither has to be read off the other.</p><ul><li><strong>Colour says which layer the point came from.</strong> Each point layer you connect gets its own hue</li></ul><p>from the categorical palette, so two searches of two different sources are told apart on the map and listed separately in the layer control, where either can be switched off. To choose a layer's colour, open <strong>Configure\u2026</strong>: each point layer has a <strong>Colour</strong> menu beside its mark and size, offering the same six colour-blind-safe colours by name (blue, vermillion, bluish green, orange, reddish purple, sky blue), or <strong>Default</strong>. Over a black-and-white scan, such as an old sheet map, pick a strong colour such as vermillion so the points stand apart from the drawing.</p><ul><li><strong>Fill says where the point stands.</strong> Filled inside the study area, hollow outside it, grey when</li></ul><p>the record has no usable location \u2014 those are not drawn on the map and are listed instead.</p><ul><li><strong>Each layer also gets a mark</strong>: circle, square, triangle, star, cross or X. A mark is chosen per</li></ul><p>layer in this widget's settings, and the legend draws the same mark the map draws. Colour alone is not readable by every reader, and a figure printed in greyscale has no colour at all.</p><ul><li><strong>Every symbol carries a dark outline</strong>, so it reads over any basemap \u2014 a terrain basemap runs</li></ul><p>through the same colours the palette uses, and a hollow mark over one is hard to pick out. It is a neutral, not a seventh colour, and a checkbox turns it off for a pale ground or a printed figure.</p><ul><li><strong>Ordered values use an ordered ramp.</strong> Travel-time bands run light to dark through one hue,</li></ul><p>which is a ColorBrewer sequential scheme. A category palette on an ordered variable invites the reader to see difference where there is sequence.</p><p>The map's receipt records all of this \u2014 which channel carries which variable, the palette and the authority it comes from, and each layer's mark and colour with whether you chose it or the map derived it \u2014 so a figure in a publication can be attributed.</p><h4>Marks sized by a number: proportional symbols</h4><p>In <strong>Configure\u2026</strong>, under a point layer's symbol, <strong>Size by</strong> offers each attribute that holds a number on its records. Choose one, such as <code>DEATHS</code>, and each mark's area is in proportion to its value: four times the value, four times the area, twice the radius. The largest value takes three times the layer's mark radius. Large marks are drawn first and are partly transparent, so a small one is never hidden under a large one. The key says what the size shows and over what range, such as <em>the area of each mark shows DEATHS, 1 to 15</em>. A count suits it; a rate or a share belongs on areas, as shading. John Snow's <em>Where were the deaths?</em> draws each address this way.</p><h4>Marks coloured by a number</h4><p>Where places are close together, a large mark hides its neighbours: MERS's hospitals sized by their cases put Samsung Medical Center's circle over the hospitals near it. <strong>Colour by</strong>, under Size by, draws every mark one size and colours it by its value instead, in five classes from light to dark, the highest drawn on top. The classes hold about equal numbers of marks, as a shaded map's quantile classes do, and the key gives each class's range and how many marks are in it, such as <em>coloured by cases: 1 (4)</em>. A mark with no value is drawn grey. Choosing Colour by clears Size by, and the other way round.</p><h4>Where it goes in the write-up</h4><p><strong>In the write-up, under</strong>, in <strong>Configure\u2026</strong>, chooses the part of the Notes write-up this output's figure and its note go in: Introduction, Methods, Results or Discussion. <strong>Results</strong> is the default. A map of the study area belongs in the Introduction; a figure that shows how the analysis was done can go in Methods. References is not offered, because it holds works and not figures. The run's receipt states the section and whether you chose it, and a validation rule checks that the note describing the figure is filed in that same section.</p><p><strong>Not in the write-up</strong>, the last choice, keeps the figure in Results and out of Notes and the publication: the run writes no note for it, and its receipt says it was left out. Hagelloch's day-by-day map is left out this way.</p><h3>Worked examples that use it</h3><table><thead><tr><th>Example</th><th>What the map shows</th></tr></thead><tbody><tr><td><strong>John Snow: where were the deaths?</strong></td><td>the deaths where they fell and the eight pumps, as Snow drew them</td></tr><tr><td><strong>John Snow: which pump was nearest?</strong></td><td>one catchment per pump, with deaths overlaid</td></tr><tr><td><strong>John Snow: who lived within a walk of the pump?</strong></td><td>travel-time bands, as a plot and as an interactive map</td></tr><tr><td><strong>John Snow: how far did it spread?</strong></td><td>the outline of 250 death locations, with the pumps</td></tr><tr><td><strong>Sea-level rise at Manila\u2019s health facilities</strong> (its own repository)</td><td>the study area, 194 facilities and the eight AR6 tide gauges</td></tr><tr><td><strong>Geoprivacy</strong></td><td>the same records before and after being moved</td></tr><tr><td><strong>Hagelloch \xB7 who infected whom</strong></td><td>a line from each infector's house to the case's</td></tr></tbody></table><h4>It states its own shape in the write-up</h4><p>Every run machines a note into <strong>Results</strong> on the Notes tab stating what this map is made of. The layers bottom to top, their feature counts, and any layer that is connected and <strong>not</strong> drawn \u2014 which is a fact about the figure a reader is owed. It is read off the same layer list the figure and the key draw from, so it cannot disagree with the picture.</p><p><strong>The caption is yours.</strong> A caption states the subject, the population, the place and the period in your words, and none of that can be read off a map. What this writes is what the map declares about itself \u2014 the material you write the caption from, sitting beside it in the same section.</p><p><strong>And it carries no number.</strong> A figure's number depends on where it sits in the write-up and on the venue you are preparing \u2014 set one figure aside and the ones after it move up \u2014 so the number is worked out when the document is rendered. Nothing here says &quot;Figure 1&quot;.</p><p>Edit it and it forks into a note of your own, like any machined note; the machined one goes on being rewritten by every run.</p><h4>Words from the workflow</h4><p>A map's title, subtitle or source note may say <strong>{country}</strong>, <strong>{units}</strong>, <strong>{unit}</strong> or <strong>{census}</strong>. Each is filled from the workflow where the figure is drawn: the study area's country, what its units are called (stated on the study area, or its boundary's own name for them), and the year of a census read from <strong>Census tables</strong>. A copy of the workflow over another country reads that country. A word the workflow does not state is written as such, for example <em>[country not stated]</em>, never guessed. The dialog says what each reads here.</p><h3>What it will not do</h3><ul><li><strong>It cannot draw everything at once.</strong> A map with both a raster and polygons connected draws</li></ul><p>the raster. The layers stay connected; only one is drawn. A street network is no longer one of these cases: points, a study area and a street network wired to one map are all drawn together, on the interactive presentation.</p><ul><li><strong>The static plot does not draw a street network beside points.</strong> The streets are drawn in a</li></ul><p>frame of their own size, so a map carrying both draws the points in the plot and says where the streets are. Set the presentation to interactive to see all of it in one picture.</p><ul><li><strong>A layer of more than 2,000 marks gives up its marks' names.</strong> On the static figure its marks of one colour are one</li></ul><p>shape, so a mark cannot be focused or picked in the records table. On the interactive map a click still opens a mark's details.</p><ul><li><strong>The interactive map draws at most 100,000 marks as squares, triangles, stars or crosses.</strong> Past that they are drawn</li></ul><p>as circles in their colour, and the map says so; the static plot draws their shapes. Circles are drawn to 250,000. The interactive map's large layers are drawn by the graphics card with MapLibre, which is fetched only when online. Offline, or on a computer without WebGL, they are drawn as circles in their colour, and the map says so.</p><ul><li><strong>An interactive map's basemap is not included in its export.</strong> Its tiles come from an outside service as you</li></ul><p>look at the map, so it exports as a static plot. A static plot's OpenStreetMap or OpenTopoMap tiles are drawn into the figure and its SVG and PNG.</p><ul><li><strong>A CARTO or Esri basemap needs your own key, unlocked.</strong> Someone opening your project without one sees</li></ul><p>OpenStreetMap. The key is never kept in the project, but it is visible in the address of every tile.</p><ul><li><strong>A basemap sends the area you are viewing to its service</strong>, and OpenStreetMap is the default. Everything else</li></ul><p>about this map works offline. For maps of sensitive locations, choose <em>None</em> first.</p><ul><li><strong>It cannot tell you whether a map is honest.</strong> Emphasis, framing and colour all change how a</li></ul><p>map reads, and none of them changes a number. See the layers you connected, and say in the source note what the map is about.</p><h4>2026-11-20 \xB7 A study area named by its digest; words from the workflow (0.38.0)</h4><p>The receipt names a study area's shape by the SHA-256 of its GeoJSON instead of writing out its coordinates. The title, subtitle and source note take {country}, {units}, {unit} and {census} from the workflow; a copy of a workflow leaves the subtitle empty.</p><h4>2026-11-24 \xB7 A locator's marks sit where its areas do (0.48.1)</h4><p>On a map carrying a <strong>polygon layer</strong>, a locator inset drew the areas zoomed to its box while the point marks, the link lines and the basemap stayed at the whole map's extent. The two frames describe different maps, so an area drawn around a pin appeared about <strong>six times too wide and off to one side</strong> of the pin it belongs to.</p><p>Reported from a 50 km buffer around the Kibali mine, and seen by two readers before it was found. The buffer was not at fault: its circle is centred on the pin to within a millionth of a degree. The boundary renderer had always picked the frame this way; the polygon renderer never did, which is why it showed only on a map carrying a polygon layer <em>and</em> a point layer.</p>",mean_center:`<h2>Mean center</h2><p><strong>A spatial operation.</strong> It takes points and gives back one point: their average position, each point counted once or in proportion to a number it carries.</p><h3>What it does</h3><p>Each point is projected to metres in the UTM zone you choose, the positions are averaged, and the average is returned as longitude and latitude. With a weight, a point carrying 5 deaths counts five times as much as a point carrying 1: 250 addresses carrying 489 deaths have two different centres.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>points</strong></td><td>the points to find the centre of</td></tr></tbody></table><p>Out comes one point. <strong>Compare point sets</strong> reads two of them to say how far a centre moved.</p><h3>How to use it</h3><p>1. Connect the points. 2. In <strong>Configure\u2026</strong>, choose a number to weight by, if any. The numeric columns of the arriving points are offered. 3. Check the UTM zone. The dialog says which zone this workflow's coordinates suggest. 4. Run. The Result gives the centre, the points used and, when weighted, the total weight.</p><h3>What it will not do</h3><ul><li><strong>It does not read a missing weight as 0.</strong> Records without a usable number are counted, and the run is refused with</li></ul><p>how many there are. Points moved by <strong>Move points in a donut</strong> carry no attributes, so they cannot be weighted.</p><ul><li><strong>It is not a place anyone was.</strong> A centre can fall between houses, or in a river.</li><li><strong>It does not measure spread.</strong> Two very different patterns can share a centre.</li></ul><h3>How it was checked</h3><p>The lab's <a href="https://digital-twin-ph.github.io/validation-lab/lab/index.html?path=06-mean-center-vs-pyproj.ipynb" target="_blank" rel="noopener noreferrer">mean centre notebook</a> recomputes the centre with pyproj.</p><h3>History</h3><h4>2026-11-23 \xB7 Show me how (0.4.0)</h4><p><strong>Configure\u2026</strong> offers <strong>Show me how it works</strong>: four made-up houses: the centre with each counted once, the centre counted by the weight, and the point the step makes as set.</p><h4>2026-11-22 \xB7 On the standard (0.3.0)</h4><p>Moved to the standard Inspector: the weight, chosen from the arriving points' columns, and the UTM zone are in <strong>Configure\u2026</strong>; the Result gives the centre and the points used.</p>`,measure_area:"<h2>Calculate area</h2><p><strong>How large the study area is.</strong> The denominator of a density, in the unit you choose.</p><h3>What it does</h3><p>It measures the study area on the curved Earth, not on the flat map: Turf's spherical polygon area, with a mean Earth radius of 6,371,008.8 m. It passes the same study area on, with its size attached, so a later step or a map can state it.</p><h3>What you connect</h3><table><thead><tr><th>Input</th><th>What it takes</th></tr></thead><tbody><tr><td><strong>Study area</strong></td><td>the area to measure</td></tr></tbody></table><h3>How to use it</h3><p>Choose the study area under <strong>Inputs</strong>. <strong>Configure\u2026</strong> sets the <strong>Area unit</strong>: square metres, square kilometres, hectares, square feet, acres or square miles. Nothing is written until <strong>Apply</strong>. <strong>Show me how it works</strong>, in the dialog, measures a made-up district step by step in the unit you have chosen.</p><p><strong>Result</strong> gives the area calculated at the last run.</p><h3>What it will not do</h3><ul><li><strong>It will not measure on a projection.</strong> An area measured on a flat map differs, more so far from the equator.</li><li><strong>It will not subtract water or uninhabited land.</strong> The area is the polygon's, as drawn.</li><li><strong>It will not change the shape.</strong> The area passed on is the one it was given.</li></ul><h3>Where it is used</h3><p>No worked example uses it today.</p>",measure_distance:"<h2>Measure distance</h2><p><strong>For each point, the nearest of a set of candidates, and how far it is.</strong> Each facility's nearest tide gauge; each sampled location's nearest clinic.</p><h3>What it does</h3><p>It measures the straight-line distance from every point to every candidate and keeps the nearest, on a sphere of 6,371.0088 km (Haversine). It gives one row per point: the point, its nearest candidate, and the distance.</p><h3>What you connect</h3><ul><li><strong>Points to measure from</strong>: any point layer.</li><li><strong>Candidates, the nearest of which is found</strong>: any point layer.</li></ul><p>A step that reads a table, such as <strong>Relate</strong>, <strong>Select rows</strong> or <strong>Table</strong>, reads the result as a table with these columns:</p><table><thead><tr><th>Column</th><th>Holds</th></tr></thead><tbody><tr><td><code>point_id</code></td><td>The point</td></tr><tr><td><code>nearest_id</code></td><td>Its nearest candidate</td></tr><tr><td><code>nearest_&lt;attribute&gt;</code></td><td>Each of that candidate's own attributes: <code>nearest_name</code>, <code>nearest_site_id</code></td></tr><tr><td><code>distance</code></td><td>The distance, in the unit chosen</td></tr></tbody></table><p>So <strong>Relate</strong> can bring a value that belongs to the candidate onto each point: the sea-level example matches <code>nearest_site_id</code> to the projections' <code>site_id</code>.</p><h3>How to use it</h3><p>The step's panel holds its <strong>Name</strong>, its two inputs, one sentence saying what it measures, and <strong>Configure\u2026</strong>:</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Distances in</strong></td><td>kilometres or metres</td></tr><tr><td><strong>Eligible candidates</strong></td><td>Conditions on a candidate's own attribute: its value is, or is not, one of those you list. A candidate without the attribute does not match</td></tr></tbody></table><h3>What it will not do</h3><ul><li><strong>It will not follow roads or water.</strong> A straight-line distance is not a travel distance.</li><li><strong>It will not say a point belongs to its nearest candidate.</strong> Nearest is a fact about distance; what it means is yours</li></ul><p>to state.</p><ul><li><strong>A point with no location keeps its row</strong>, with no nearest candidate and no distance, so it is counted.</li></ul><h3>Where it is used</h3><p>The sea-level example (each facility's nearest tide gauge).</p><h3>History</h3><h4>2026-11-26 \xB7 Its code out of app.ts (0.7.1)</h4><p>The Inspector, its sentence and Configure\u2026 moved into <code>src/distance-ui.ts</code>. Nothing they show or do changed.</p><h4>2026-11-25 \xB7 The Preview counts the candidates a condition keeps (0.7.0)</h4><p>The conditions are the setting on the screen, and the one number they exist to change \u2014 how many candidates survive them \u2014 could be seen only by running the workflow and reading the receipt. The Preview named the conditions back.</p><p>It now runs this step's own search, so the eligible count moves as a condition is typed, beside the nearest, median and furthest distance. Points left with no distance are counted: a condition that keeps nothing leaves every point without one, which a table of distances shows only as a column of gaps.</p>",network_input:"<h2>Street network</h2><p><strong>An input widget.</strong> It supplies the streets that walking-distance work is measured along: a graph of points joined by segments, each with a length.</p><h3>Three ways in</h3><p>Choose one in <strong>Configure\u2026</strong>. The Inspector then shows only what that way needs: a download button, a file to choose, or an extract to read.</p><p><strong>Upload a network file.</strong> A GraphML or JSON graph prepared elsewhere. It keeps its own extent.</p><p><strong>Download from OpenStreetMap.</strong> The study area's bounds go to overpass-api.de, which is asked to count what it would send before anything is sent, so an area past the limit is refused rather than transferred and discarded. One request at a time, 60 seconds minimum between them plus 30 seconds per megabyte received: the service is donated and the pause is the courtesy.</p><p><strong>Read an extract on this device.</strong> A published <code>.osm.pbf</code> \u2014 Geofabrik's country files, or any other OSM extract \u2014 chosen with the file picker. The file is read where it sits and is never copied into this browser's storage; the study area's bounding box is applied while the extract is decoded, so a country file yields one province's streets. Most countries have no province-level extract published, which is the point: the same file serves every province and every workflow after the first, and nothing is downloaded twice.</p><p>The travel mode belongs to all three. Walking keeps footways, paths and steps; driving keeps roads and honours vehicle one-ways. At the scale of a province the choice decides how much there is to read; at the scale of a district it decides what the question means. An acquired ADM1 or ADM0 study area defaults to driving, because nobody walks across a province.</p><h3>What it does</h3><p>It gives the workflow a walkable street network, either downloaded from OpenStreetMap for your study area or uploaded from a file you prepared elsewhere.</p><p>A downloaded network keeps the ways people can walk on \u2014 residential streets, footways, paths, steps, tracks, service roads and the ordinary road classes \u2014 and leaves out anything tagged as closed to pedestrians. Each way becomes a run of segments between the points it was drawn with.</p><p><strong>Graph limit.</strong> The limit counts every point in the graph, including each bend a street was drawn with, not only the places two streets meet. A town can hold three points for every real intersection and a road following a coastline can hold seventeen, so the same limit allows very different amounts of street in different places. The download size allowed follows this number, so raising it raises what can be fetched.</p><h3>What you connect</h3><p>It takes an <code>area</code> \u2014 the study area that says where to download \u2014 and emits a <code>network</code>, which the isochrone, the junction reachability step, the corridor and the snapping step all accept. A map can draw one directly.</p><h3>How to use it</h3><p>1. Connect a <strong>Study area</strong>, then select the Street network step. 2. In <strong>Configure\u2026</strong>, choose where the network comes from, the travel mode, the margin around the study area and, for a download, the pause between requests and the graph limit. Apply. 3. Press <strong>Check endpoint status</strong> if you want to know what the servers can do right now: it reports free slots and, when there are none, when the next one frees. 4. Press <strong>Download and save OSM network</strong>. This is a separate action \u2014 running the workflow does not start a download. 5. If the area is large or the streets dense, raise the graph limit in <strong>Configure\u2026</strong> and download again.</p><p>Downloads are paced: one at a time, with a pause afterwards that grows with the size of what you received. A busy server is waited for rather than treated as a failure. A network you have already downloaded is kept, so asking the same question again costs no request at all.</p><h3>What it will not do</h3><p>It does not download while you run the workflow. Acquisition is always something you ask for.</p><p>An area too large for one request is asked for in several, automatically. The single request is tried first; if the service's own count says it will not fit, the panel says so \u2014 <em>&quot;Too much for one request \u2014 working out how many parts it takes&quot;</em> \u2014 and then works through the tiles, reporting each. The grid comes from that count, so a dense city is divided more finely than an empty district of the same size, and a sparse area is still one request. Tiles overlap by the download margin so a street crossing a seam keeps both ends, and parts of the grid that miss your study area are never requested at all. <strong>Stop</strong> ends the whole sequence, and the pause earned is charged once for the total rather than once per part.</p><p>Whatever route it took, the result is clipped to your <strong>study area polygon</strong>, not to the box around it. A junction outside the outline is not in the network unless it falls within your download margin, which is fetched on purpose so journeys near the border still work; a road is cut at the border rather than trailing beyond it. The widget records how many junctions and segments that removed.</p><p>It does not stop a download that is arriving. A request that never begins to answer is given three minutes, which is a limit on waiting, not on downloading. Once the first bytes arrive there is a download in progress and no clock ends it, however long it takes: press <strong>Stop</strong> when you want to give up, and the panel says how much had arrived and that none of it was kept. While it runs the panel shows how much has arrived and how fast, averaged over the last few seconds, so a transfer in trouble reads as a falling number rather than a frozen one. If it goes quiet for ninety seconds the panel says that too, with how much had arrived, and keeps waiting for you to decide.</p><p>It does not offer to hand-edit a large graph. The <strong>Edit bounded network JSON</strong> box is for the kind of network a person writes or fixes by hand \u2014 the Soho graph is about 28 KB. Above 20,000 nodes-plus-edges it is not offered, and the panel says so. Serialising a province into that box cost 41.8 MB of pretty-printed JSON and 59.7 MB again after escaping, rebuilt every time the panel redrew, which was enough to kill the browser tab while nothing was being done. The file input beside it stays, so a large graph can still be replaced by a small one, and nothing about the graph itself changes: it is held, drawn, run and exported at any size. The limit is declared as the cap <code>json-editor-elements</code>, queryable in the ontology like the rest.</p><p>It does not guess your area. Without a connected study area there is nothing to bound the request.</p><p>It downloads one travel mode at a time. Choose walking or driving before you download, because the two are different graphs and not two labels on one:</p><table><thead><tr><th></th><th>Walking keeps</th><th>Driving keeps</th></tr></thead><tbody><tr><td>Footways, paths, steps, pedestrian ways</td><td>yes</td><td>no</td></tr><tr><td>Motorways, trunk roads and their slip roads</td><td>no</td><td>yes</td></tr><tr><td>Ordinary streets \u2014 residential, unclassified, tertiary to primary</td><td>yes</td><td>yes</td></tr><tr><td>One-way restrictions it obeys</td><td>the ones that apply on foot</td><td>vehicle one-ways, and roundabouts</td></tr></tbody></table><p>A saved graph keeps the mode it was downloaded for, and the widget says which. To change mode, change it here and download again: the new graph replaces the old one. A widget further down the workflow that asks for a mode this graph cannot carry refuses the run and says so, rather than reporting minutes for a journey the streets do not support.</p><p>Distances along it are distances on those streets, and a network downloaded today describes the streets today, not the streets of whatever period your data comes from.</p><p>Before anything large is downloaded, the widget asks the service <strong>how much is there</strong>. Overpass answers that question directly, and an area holding more street data than this widget can take is refused with the number \u2014 after one cheap request rather than after several large ones that fail. An area so large that the service will not even count it is refused the same way, because that is what a public instance says when an area is beyond what it will process.</p><p>A saved network is kept beside the workflow rather than inside it, in the larger store your browser offers, so the size of a graph is no longer limited by what a workflow may hold. If that store is unavailable \u2014 private browsing, for instance \u2014 the application says &quot;small store only&quot; when it saves, and a large network may then be refused.</p><p>A driving graph carries no speed limits, no junction delay and no congestion. Travel time over it is one speed applied to every street, which is the same model walking uses and a weaker one for a car.</p><h3>Worked examples that use it</h3><p><strong>John Snow: who lived within a walk of the pump?</strong>, in the 1854 Cholera Outbreak in London project, uses a prepared Soho network to draw what each pump could be reached from on foot.</p><h3>History</h3><h4>2026-11-23 \xB7 On the standard (0.14.0)</h4><p>Moved off the old panel to the standard Inspector: one sentence of what it holds and where it comes from, the download, file or extract that way needs, and <strong>Configure\u2026</strong> for every setting. The Result gives the junctions and streets held, the picture of them and where they came from.</p>",point_input:"<h2>Point data</h2><p><strong>An input widget.</strong> It brings located records into a workflow \u2014 one row per thing, each with a position and whatever attributes came with it.</p><h3>What it does</h3><p>It holds a set of points and the values attached to them: cases, households, facilities, pumps, sample sites. Everything downstream that works on points starts here.</p><p>Records arrive three ways. <strong>Import a file</strong> \u2014 GeoJSON, a CSV with longitude and latitude columns, a GeoPackage, or the waypoints a GPS device exports as GPX, KML or KMZ. <strong>Place pins</strong> by clicking a map, for a handful of locations you know. <strong>Connect a source</strong> that produces points, such as a facility search.</p><p><strong>Coordinates in degrees</strong> may be written as decimal numbers, such as <code>-5.9333</code>, or as degrees, minutes and seconds, such as <code>05\xB0 56' 00&quot; S</code>. The second are converted to decimal degrees for the point, and the column keeps its text as written. S and W, or a minus sign, mean south and west. A value with no hemisphere is read as north or east, and the step says how many there were, because in much of Africa a missing S puts a place on the wrong side of the equator. A value that cannot be read, such as 90 seconds or two hemispheres, leaves its record without a position, and the step says which and why.</p><p>A record may have no position. That is kept rather than dropped, because a case with no recorded address is still a case, and steps that need geometry say how many they had to leave out instead of quietly working with fewer.</p><p><strong>Columns and their kinds.</strong> Each attribute has a declared kind \u2014 number, text, or a term from a list you give. The data quality panel profiles a column, shows which values do not match its kind, and offers a repair. A repair is recorded with the node and appears in the run evidence; it never overwrites what the file held.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>records</strong></td><td>optional: a table with longitude and latitude columns, read as one point per row</td></tr><tr><td><strong>area</strong></td><td>optional: the study area to generate synthetic points in, offered first in <strong>Configure\u2026</strong>; a Study area, or an area another step made, such as a <strong>Combined area</strong> across a border, once the workflow has run</td></tr></tbody></table><p>Its output is <code>points</code>, which nearly everything accepts: maps, tables, distance measurement, catchments, summaries, rates, case series and the geoprivacy steps. A step that takes a table reads it as one too: each point a row of its attributes, without its location.</p><h3>How to use it</h3><p>The step's panel holds its <strong>Name</strong>, its input, one sentence saying what it holds, <strong>Configure\u2026</strong>, and the records.</p><table><thead><tr><th>In Configure\u2026</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Points held here</strong></td><td>import a CSV, GeoPackage, GeoJSON, GPX, KML or KMZ file, generate synthetic points, or place pins on the map</td></tr><tr><td><strong>Points from a table</strong></td><td>when a table is connected: the columns holding <strong>x (longitude)</strong> and <strong>y (latitude)</strong>, named, never guessed; a <strong>Record ID</strong> and a <strong>Label</strong>, optional</td></tr></tbody></table><p>Then check the column kinds, open <strong>Data quality</strong> to see what is missing or malformed, and name the step for what the records are, not where they came from.</p><p><strong>What the columns mean.</strong> For points held here, <strong>Describe columns\u2026</strong> works as it does in Tabular data: a label, a unit, a description, what kind of values each column holds, and its codes, typed or proposed from a data dictionary. A dictionary chosen there is kept with the records, and <strong>View the data dictionary</strong> shows it as published. Points from a table take their meanings from that table's Tabular data step.</p><p>Hagelloch's cases carry their source's dictionary, the outbreaks package's, so every column arrives proposed. <code>class</code> arrives as categories in no order, because the package calls it a factor; whether pre-school, first and second class are in order is yours to say.</p><p><strong>Where the points came from.</strong> Points can carry a provenance record, as Tabular data does: what they are, the work or authority they came from, its address and its licence. A step with one writes a source note in Methods, and its work is listed in References. Hagelloch's cases cite Pfeilsticker's 1863 thesis this way.</p><h3>Placing pins</h3><p>In <strong>Configure\u2026</strong>, choose <strong>Place pushpins on map</strong>.</p><table><thead><tr><th>To</th><th>Do this</th></tr></thead><tbody><tr><td>Add a pin where you are standing</td><td><strong>Add a pin at my location</strong>. The browser asks first whether this page may know your location</td></tr><tr><td>Move the chosen pin to where you are</td><td><strong>Move this pin to my location</strong></td></tr><tr><td>Add a pin by eye</td><td>Click the map</td></tr><tr><td>Move a pin</td><td>Drag it, or type its longitude and latitude</td></tr><tr><td>Choose a pin</td><td>Click it, pick it from the list, or choose its row in the table under the map</td></tr><tr><td>Type a position</td><td>Decimal degrees, such as -5.9333, or degrees, minutes and seconds, such as 5\xB0 56' 00&quot; S</td></tr><tr><td>Find a town or district</td><td><strong>Find a place</strong> asks OpenStreetMap's Nominatim, only when you press Find; the words you type are sent there. A result moves the map; it does not place a pin</td></tr><tr><td>See houses</td><td><strong>Basemap</strong>: OpenStreetMap, OpenTopoMap, or a CARTO or Esri style on your own key, Esri's satellite imagery among them</td></tr><tr><td>See the ground around the pin</td><td><strong>Full screen</strong> gives the map the whole window, with the pin's form still beside it. Press it again, or Escape, to come back</td></tr><tr><td>Read the ground closely</td><td><strong>Magnifier</strong> puts a glass over the cursor showing the basemap enlarged, without moving the map. A click under the glass still places a pin. It needs a basemap: with the basemap off there are no tiles to magnify, and it stops at the depth the provider's tiles go to</td></tr><tr><td>Take back a change</td><td><strong>Undo</strong>, the last 30 changes, before Apply. Above 20,000 records Undo is off</td></tr><tr><td>Put the form's questions in order</td><td>Under <strong>Add a form field</strong>, <strong>Move up</strong> and <strong>Move down</strong> beside each field; every pin's form follows</td></tr><tr><td>Show some study areas, not all</td><td><strong>Study areas shown</strong>: a checkbox for each study area's outline; <strong>Fit pins and study area</strong> fits the ones shown</td></tr></tbody></table><p><strong>Where each position came from.</strong> Every pin says how it was placed: from this device, on the map by eye, or typed. A position from the device keeps the accuracy the device stated, in metres, and when it was taken. Dragging or typing the position again replaces both, because the device's accuracy no longer describes it. The three are kept with the pin as <code>positionSource</code>, <code>positionAccuracyM</code> and <code>positionFixedAt</code>, and reach the tables and the evidence like any other value. The stated accuracy is the device's own estimate; it is not checked.</p><p><strong>Fields on every pin.</strong> <strong>Add a form field</strong> gives each pin the same question: a key, a label, a type (text, number, whole number, yes/no, date, or date and time), an optional default and an optional list of allowed values, which become a dropdown. <strong>Required on every pin</strong> marks the field as one each pin should answer. A pin without it is named in the summary and in the table; the pins are still saved, because a pin with a missing answer is still a place someone recorded. A date and time is kept as it was entered, to the minute, with no time zone.</p><p><strong>Photos.</strong> Each pin can hold up to ten photos, each with a caption. On a phone, <strong>Add photos</strong> can open the camera. A photo is reduced to 2,048 px on its long side and kept as a JPEG; the original is not kept. Where a phone wrote the place a photo was taken, and the pin has no position yet, the editor offers to place the pin there, and the pin then says its position came from its photo. Otherwise it says how far from the pin the photo was taken. Either way the location, and the camera's details, are not in the copy kept. Photos stay on this device and go into encrypted backups only: a plain copy and a shared project name each photo by its digest and caption, without the picture.</p><p><strong>Pins on homes identify people.</strong> Back the project up encrypted, and mask the points with <strong>Donut geomasking</strong> before sharing a map of them.</p><p><strong>The table and the markers.</strong> The table under the map lists every pin, 25 a page: its label, Category, position, where the position came from, and any required value it lacks. Markers are coloured by <strong>Category</strong>, each category its own colour with its first letter, and a pin with no category is grey. The legend names each category and how many pins it has. Beyond eight categories, the rest share the grey.</p><h3>Waypoints from a GPS device</h3><p>Choose <strong>Import GPX from a GPS device</strong> or <strong>Import KML or KMZ</strong>. Each waypoint, or each placemark that is a point, becomes a record with its name, and its time, elevation (<code>elevation_m</code>), description and symbol where the file gives them; a KML placemark's extended data become columns. Both formats are longitude and latitude on WGS84, so nothing is converted. Tracks, routes and shapes are lines or areas: the editor counts them and says they were not imported, because Point data holds points.</p><h3>Editing a value by hand</h3><p><strong>Data quality</strong>'s <strong>Records</strong> tab shows the records as the steps after this one read them, a page at a time, each value in a box. Change a value and leave the box: it is kept as an <strong>edit</strong> on this step, with the value it replaced and when, and the run applies it to a copy of the records. The file is not changed. An empty value can be filled the same way; such edits are counted apart, because a supplied value is not a reading. <strong>Edits (n)</strong> lists every edit, newest first, each with <strong>Remove</strong>, which takes it back.</p><p>An edit is applied only where the record still holds the value it was made against. If the data has changed under it, after a new import, the edit is not applied and Data quality says so. The run's record states each edit, before and after (<code>fw:CellEdit</code>). Experiment 214.</p><h3>What it will not do</h3><p>It does not clean data silently. Nothing is coerced, dropped or filled in; what cannot be read is reported and left for you to decide.</p><p>It does not join one set of records to another. Two sets that share no key stay two sets.</p><p>It does not know what a row means. Whether 250 rows are 250 people or 250 addresses carrying 489 events is something your labels and your weights have to say.</p><h3>Worked examples that use it</h3><p><strong>John Snow: where were the deaths?</strong> loads 250 death locations and eight pumps. <strong>Measles in Hagelloch, 1861</strong> loads a 188-case line list.</p><h3>History</h3><h4>2026-11-26 \xB7 Its code out of app.ts (0.19.1)</h4><p>The Inspector, its sentence and the dialog naming a table's longitude and latitude columns moved into <code>src/point-data-ui.ts</code>. Nothing they show or do changed.</p><h4>2026-11-23 \xB7 An Excel workbook (0.16.0)</h4><p><strong>Import Excel</strong> reads a workbook's first sheet carrying a header row, exactly as a CSV is read, and proposes the longitude and latitude columns by name. A spreadsheet of sites had to be saved as a CSV first.</p><h4>2026-11-23 \xB7 The table's coordinate columns are proposed (0.15.0)</h4><p>Reading points from a table, <strong>Configure\u2026</strong> proposed nothing: both selects opened on <em>Choose a column\u2026</em> though the step's own CSV import has always proposed by name. It now proposes the longitude, the latitude, the record ID and the label from those same names. They are shown in the selects and can be changed, and a run still reads the mapping stored here rather than guessing.</p><h4>2026-11-23 \xB7 A CSV that is not UTF-8 (0.14.1)</h4><p>A CSV whose bytes are not UTF-8 is read as Windows-1252, as Excel on Windows writes it, so an accented place name reads as it should rather than as replacement characters.</p><h4>2026-11-22 \xB7 The form's order (0.14.0)</h4><p>A pin's form listed its fields in the order they were added. Each can now be moved up or down, and every pin's form follows. Experiment 09's last open item.</p><h4>2026-11-22 \xB7 Pins in the field (0.13.0)</h4><p>A pin was placed by eye on the map or typed, and nothing said which. Now a pin can be added where the device is, and every pin says where its position came from, with the device's stated accuracy. A form field can be required, a field can hold a date and a time, the editor lists the pins as a table, and markers are coloured by Category. A position can be typed in degrees, minutes and seconds, a place found by name, a satellite basemap chosen, and a change undone. Pins hold photos. GPX, KML and KMZ waypoints import. The editor is the standard dialog: Cancel and Apply where Save Edits was. Experiment 09's open items 1 to 14.</p><p><strong>What it does not establish:</strong> not tried on a phone, with a real GPS fix, a real phone photo or a real handheld's GPX; the tests give the browser a position, a photo and a file.</p><h4>2026-11-21 \xB7 A study area connected to generate in (0.12.0)</h4><p>Its generator chose from a list of the workflow's Study areas, with nothing on the canvas to say which. Now an area connected to it is offered first, and an area another step made (a Combined area of two countries) can be generated in after a run. Unconnected, the list is as before.</p><h4>2026-11-19 \xB7 Up to 250,000 records (0.11.0)</h4><p>Point data took at most 2,000 records from a file, pins, generated points or reprojection, and files of at most 5 MB: numbers chosen when the widget was new. It now takes 250,000 records and files of up to 40 MB, the limits measured for tables, and every place it reads points follows the one number. The maps and tables it feeds were measured at the same sizes; Map's manual has the times.</p><p><strong>What it does not establish:</strong> a 250,000-row CSV imported through this dialog was not timed; the measurement read the points from a workflow file and from a table.</p>",polygon_input:"<h2>Polygon layer</h2><p><strong>An input widget.</strong> It supplies a layer of polygons \u2014 many areas, each with its own name and attributes \u2014 as distinct from a study area, which is the single boundary your work sits inside. Sub-districts, water bodies, supply zones, parishes, building footprints: anything that is a set of areas rather than one frame.</p><h3>Three ways in</h3><p>All are in <strong>Configure\u2026</strong>. Choosing one shows that method's steps and hides the others', so the dialog describes the path you are on. Nothing is read until <strong>Apply</strong>, which is the read.</p><p><strong>A published GeoJSON layer.</strong> A <code>FeatureCollection</code> of polygons and multipolygons you already have. It is read exactly as published.</p><p><strong>Areas from a published <code>.osm.pbf</code> extract.</strong> An OpenStreetMap extract \u2014 Geofabrik's country and region files, or any other \u2014 chosen with the file picker. You say which kinds of area you want and the widget reads those, within your study area's bounds.</p><p><strong>The parts of connected study areas.</strong> No file: each part of each study area you connect is a feature, named, with its geoBoundaries ID, and with the country and level its boundary states (<code>COD-ADM2-\u2026</code>). Connect one study area per country, each at the level you want, with <strong>+ Add a study area</strong> for the next, or drop each study area onto the layer's input on the canvas, where each takes the next input: DR Congo's provinces and South Sudan's counties become one layer across the border. <strong>After</strong> lists the parts before anything runs. A table of cases by unit can then be joined onto the layer on the IDs, which are unique across countries where names are not. Parts at different levels are said to be: a count compares only units at one level, and a rate compares across them. To make one study area of several instead, for a raster or a street network over the whole outbreak, use <strong>Combined area</strong>.</p><h3>What it does</h3><p>It reads polygons into the workflow and emits them as a polygon layer, which maps, tables, charts and every polygon step already accept.</p><p><strong>Read as published.</strong> Nothing is clipped, simplified or reprojected. A file whose coordinates are not longitude and latitude in degrees is refused rather than converted, because a converted shape is not the shape its author published.</p><p><strong>Which property names each feature</strong> is yours to choose, and is never guessed from a property name. Leave it unset and the features are numbered. Name a property the file does not carry and the import is refused rather than silently leaving the names blank.</p><p><strong>Reading from an extract</strong> needs a study area connected, because the study area is the scope: its bounds, widened by the margin you set, are the box the widget reads. The extract file is read where it sits and is never copied into this browser \u2014 only the areas it yields are kept, and they are kept on this device by digest rather than inside the workflow, so a large layer does not crowd out everything else you have saved.</p><p><strong>Which kinds of area</strong> is a closed list, because each entry is a claim about which OpenStreetMap tags mean an area of that kind. Water covers lakes, rivers, basins and docks. Buildings covers anything tagged as a building. Nothing is matched on a feature's name.</p><p><strong>A vertex threshold.</strong> A kind on its own is usually too coarse: water over a London-sized box returns about a thousand features, most of them ponds, basins and ornamental lakes. Setting a minimum number of vertices keeps the large features and leaves the small ones unread. If what you asked for is more than a layer can hold, the refusal tells you which threshold would fit, worked out from the features actually found rather than guessed, so the second attempt is informed.</p><p><strong>The licence travels with the layer.</strong> Areas read from an OpenStreetMap extract are ODbL, which is share-alike: a figure built on them carries the same terms, and its credits must name OpenStreetMap. The panel and the run's receipt both say so, and the attribution is attached to the layer rather than remembered separately.</p><h3>How to use it</h3><p>The step's panel holds its <strong>Name</strong>, its <strong>Study area</strong>, one sentence saying what it holds, and <strong>Configure\u2026</strong>. Under <strong>Result</strong>, the layer it read.</p><p><strong>From a file.</strong> Add the widget and press <strong>Configure\u2026</strong>. Leave the method on <em>A GeoJSON file</em>, choose your file, and if your features carry a name, type that property's name into <em>Which property names each feature</em>. The features appear under <strong>Preview</strong> as soon as the file is chosen, so you can choose among them before <strong>Apply</strong>. The panel then shows how many features and vertices it read.</p><p><strong>Opened again,</strong> Configure\u2026 says which file the layer holds, and <strong>Apply</strong> needs no file: choose a file only to replace the features. A different naming property names the held features again.</p><p><strong>From an extract.</strong></p><p>1. Add <strong>Study area</strong> and define it, press <strong>Configure\u2026</strong> and choose it under <em>Study area to read inside</em>. The dialog shows the box it will read from, so you can see what the margin does before anything is read. 2. Tick the kinds you want. 3. Set the margin if the features you need reach outside your bounds. A river's course, a reservoir or a lock can sit kilometres beyond the edge of a study area and still belong to the question. There is no ceiling: a larger box costs you a slower read, and the read is local. 4. If you do not have an extract, use the download button the dialog offers. It names the smallest catalogued file that covers your box and your browser downloads it directly \u2014 this application cannot fetch it for you, because that host does not permit it. Come back to the file picker when it has landed. 5. Choose the file, then press <strong>Apply</strong>. The read reports each stage in the dialog, which stays open until the layer is kept; if the read fails, the dialog says why and nothing on the step changes. 6. Read what the panel says came back: how many features, how many vertices, how many were below your threshold, and how many fell outside the box. If the counts surprise you, change the threshold and read again.</p><p><strong>Moving the study area afterwards.</strong> A layer read for one study area is refused for another: if the area grows past the box the layer was read for, the run stops and says so rather than drawing a map with a hole in it. Read the extract again. The file is not kept, so this means choosing it again \u2014 the panel records its name and digest so you know which file to look for.</p><h3>What it will not do</h3><p><strong>It will not clip.</strong> The box decides which features are read, in or out; it never cuts one. A feature that crosses the edge of your study area arrives whole. Clipping is a separate step you choose and a receipt records.</p><p><strong>It will not reproject.</strong> A layer in metres, a national grid or any projected system is refused. Convert it before you bring it in, so the conversion is yours and is recorded.</p><p><strong>It will not find features by name.</strong> Searching an extract for &quot;Thames&quot; is not available, and is not an oversight: a name is not a reliable statement of what something is. You ask for a kind, and you get every area of that kind in the box.</p><p><strong>It will not fetch an extract for you.</strong> The file has to be on your device. The widget works out which published file covers your box and links it; your browser does the downloading.</p><p><strong>It will not keep the extract.</strong> Only the areas read out of it are kept. Reading again means choosing the file again.</p><p><strong>How many features is not a limit.</strong> What refuses is vertices \u2014 two hundred thousand of them, because that is the thing that costs. A read of Greater London's water areas returns six hundred features and comes through. If a layer does pass the vertex budget, the refusal tells you which vertex floor would fit, read off the features the read actually found.</p><h3>Choosing which features to keep</h3><p>A read of a published extract gives you everything of the kinds you asked for inside your box. Greater London's water areas are 606 features; the Thames is two of them. The rest are ponds, basins and a boating lake.</p><p>Under <strong>Preview</strong> in Configure\u2026, every feature the read returned is a row, beside a map of all of them. An extract's areas are listed once they are read: press <strong>Apply</strong>, then open Configure\u2026 again. Select a row and its polygon is marked on the map, so you can tell which one it is before deciding. Clear a row's box and that feature leaves the layer when you press <strong>Apply</strong>; <strong>Cancel</strong> leaves the layer as it was.</p><p>Nothing is deleted. The read is unchanged, so a feature you set aside comes back by ticking it again rather than by reading 124 MB a second time. The receipt records how many the read returned and how many you set aside, because a layer of two drawn from a read of 606 is a choice, and a reader of your evidence should be able to see that you made it.</p><p>Setting every feature aside is refused: a layer that holds nothing is not a layer.</p><p><strong>Three reductions, and a name.</strong></p><table><thead><tr><th></th><th>What it does</th></tr></thead><tbody><tr><td><strong>Keep or discard</strong></td><td>Choose features on the map or in the list, then keep only those or discard them. Or clear a single row's box.</td></tr><tr><td><strong>Clip to the box</strong></td><td>Cut every feature to the box the read used. What falls wholly outside drops; what straddles the edge is cut at it.</td></tr><tr><td><strong>Merge</strong></td><td>Union the features you chose into one, keeping the group's first name. Two reaches of one river, or a dock drawn as four touching basins, are one thing your workflow counts once.</td></tr></tbody></table><p>Adjacency is not checked before a merge. Features that do not touch become one feature of two parts, which is a real answer \u2014 a river above and below a lock is one river whether or not the data drew it sharing an edge \u2014 and refusing it would need a tolerance nobody has measured.</p><p><strong>And you can name them.</strong> Type over any feature's name. A map whose polygons read &quot;Feature 37&quot; names nothing a reader can use, and the file does not always carry a property worth naming them by. <strong>Set aside the unnamed</strong> does it in bulk: it asks whether the property you nominated carried a value for each feature, never whether the name looks automatic.</p><p>All four are decisions applied when the workflow runs, not edits to the data. The read stays as it was published, so every one of them is reversible, and the receipt records what you chose.</p><p><em>Why looking rather than typing:</em> the first design for this filtered at read time by a property name and a list of values. You cannot name values you have not seen, and nobody knows in advance what OpenStreetMap calls the boating lake.</p><h3>Worked examples that use it</h3><p><strong>Snow's South London water supply study, 1854</strong> reads the registration sub-districts and the two reaches of the Thames as layers inside one study area, which is what lets the tidal and non-tidal reaches be drawn as separate exposures.</p><h3>History</h3><h4>2026-11-22 \xB7 Moved out of the application's main file (0.8.1)</h4><p>Its Inspector and its Configure\u2026 moved into a module of their own, unchanged. Nothing it does changed.</p><h4>2026-11-22 \xB7 Study areas dropped on the canvas (0.8.0)</h4><p>A second study area connected on the canvas replaced the first, so a layer of several areas could be made only in Configure\u2026. Now a study area dropped on an input another one holds takes the next input, a new one added when all are held, up to six. A layer read from a file or an extract keeps its one area, which says where to read.</p><h4>2026-11-21 \xB7 The parts of connected study areas (0.7.0)</h4><p>A study area could feed this widget only as the box an extract is read inside, so its own shape could not become a layer, and two countries' areas could not be drawn or joined to as one layer for an outbreak across a border. A third source makes a layer of the connected study areas' parts, up to six study areas, each part with its name, geoBoundaries ID, country and level.</p>",raster_input:"<h2>Raster input</h2><p><strong>A window of a GeoTIFF or NetCDF grid around the study area, kept in the project.</strong> A population surface, a terrain model, a geoid.</p><h3>What it does</h3><p>It reads a single-band GeoTIFF in latitude and longitude (WGS84, EPSG:4326), or one grid from a NetCDF-4 file, and keeps only the cells around the connected study area, at the file's own resolution. Nothing is resampled or reprojected. What it keeps travels with the project, so a run needs neither the file nor the connection again.</p><h3>What you connect</h3><p><strong>Study area</strong>: the window kept is the area's bounding box, with an optional margin of one cell.</p><h3>How to use it</h3><p><strong>Population from WorldPop, for the study area's country.</strong> Configure\u2026 offers WorldPop's population raster for the country the study area states, in either release, under <em>Population source</em>:</p><table><thead><tr><th>Release</th><th>Years</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Global2 R2025A</strong></td><td>every year, 2015 to 2030</td><td>Constrained to settlements, 100 m, national totals scaled to the UN World Population Prospects 2024. An alpha release (September 2025) that WorldPop says may change. 242 countries. Cite doi:10.5258/SOTON/WP00839</td></tr><tr><td><strong>Global1</strong></td><td>every year, 2000 to 2020</td><td>Unconstrained, 100 m</td></tr></tbody></table><p>Choose the year your project needs; a year chosen in one release stays chosen in the other where both publish it. The download link gives the file's size, where it is known, and the time it takes. The country is set once, on the study area; where the area states none, Configure\u2026 asks for it and keeps it there. <strong>Across a border</strong>, where the study area states several countries, Configure\u2026 offers those, one file at a time: this step reads one file, so the part of the area in another country has no population from it.</p><p><strong>Or from GRID3</strong>, under <em>Population source</em>: GRID3's 2025 estimates for the 52 countries of sub-Saharan Africa, one file per country (Botswana's is 11.6 MB, against WorldPop's 293 MB). They are modelled top-down, from national projections spread over settled areas; they are not official government statistics and carry no uncertainty layer. Where GRID3 publishes nothing for the country, the dialog says so. The download is your browser's, as WorldPop's is.</p><p><strong>A window travels as its source, not its cells.</strong> A country's window is hundreds of megabytes, so a workflow file or project carries where the window came from, which part was kept, and its digest, not the cells. A GeoTIFF chosen on this computer keeps the file's digest too. Opened on another computer, the step's Result says the window is not on this device yet. <strong>Configure\u2026</strong> then opens on <strong>The kept window</strong>: <strong>Read the window again</strong> for one read at a web address, or a file chooser naming the same file, which is not the chooser for a new file below it. The file is checked against the digest first, and the window read again against the window that was kept; either differing is refused, and nothing is kept.</p><p><strong>The kept window is in the dialog.</strong> Once it is on this device, <strong>Configure\u2026</strong> shows its record (where it came from, the part kept, its digest) and <strong>Download GeoTIFF</strong>, the kept window at native resolution with its georeferencing and source metadata.</p><p><strong>The WorldPop or GRID3 file you were pointed to is recognised.</strong> Chosen from disk under the name WorldPop gave it, its source record fills in: the country and year, the release, WorldPop as provider, its licence, and its units, <em>people per pixel</em>, which WorldPop's files do not carry themselves. Change any of it that says otherwise. A file under any other name is not guessed at.</p><p><strong>Or GHS-POP</strong>, the JRC's global population grid, for any country and every five years from 1975 to 2030 (2025 and 2030 are projections). Choose the year and press <strong>Read the window from JRC's copy</strong>: only the part of the global grid over your study area is read, from JRC's copy on Amazon Web Services, so nothing is downloaded first, and the area read is sent to that server. It counts residential population, spread over the volume of residential buildings, so it is weaker where buildings are hard to see, and should not be set against GHS-BUILT in the same analysis.</p><p>The step's panel holds its <strong>Name</strong>, its study area, one sentence saying what it keeps, and <strong>Configure\u2026</strong>, the standard dialog: <strong>Settings</strong>, then <strong>Preview</strong> (the file's size in cells and the window kept), then <strong>Decisions</strong>. <strong>Apply</strong> reads the window and keeps it, with a bar showing how much of the window has been read, then how much of a chosen file has been checked; <strong>Cancel</strong> or \xD7 leaves the step as it was. A NetCDF file shows the words without the bar.</p><table><thead><tr><th>In Configure\u2026</th><th>What it does</th></tr></thead><tbody><tr><td><strong>GeoTIFF or NetCDF file</strong></td><td>Choose a file on this device. A large file is read in parts: only the window is read</td></tr><tr><td><strong>Variable</strong></td><td>Shown for a NetCDF file holding more than one grid: choose which. DTU25MSS, for one, holds the mean sea surface and its uncertainty</td></tr><tr><td><strong>Or a GeoTIFF at a URL</strong></td><td>Give its address and press <strong>Read</strong>. Only the header and the window are fetched</td></tr><tr><td><strong>Download the whole file</strong></td><td>Offered with a URL, with the file's name, source and size: keep it on this laptop and choose it above to work without the connection</td></tr><tr><td><strong>Extra source coverage</strong></td><td>One cell more around the area, for clipping or for reading a value between cells near the edge</td></tr><tr><td><strong>Source metadata and citation</strong></td><td>Who made it, its terms, and how to cite it: entered by you, kept with the window</td></tr></tbody></table><p><strong>A grid whose values sit at nodes</strong>, as a geoid grid's do, is read as the cells around those nodes, half a cell out, and the panel says so. A NetCDF grid always is: its latitudes and longitudes are where its values sit.</p><p><strong>A NetCDF file</strong> must be NetCDF-4 (HDF5 inside), with one-dimensional coordinates named <code>latitude</code> or <code>lat</code> and <code>longitude</code> or <code>lon</code>, evenly spaced, west to east. Its fill value, scale factor and offset are applied. It works offline once Fieldwork has been opened online, since its reader is saved with the application.</p><p><strong>WorldPop's list of countries and years</strong> is kept with Fieldwork, since WorldPop's site does not let a browser read it. It is checked against WorldPop's folders every week; a change comes as a pull request to the repository, and a newer release is reported for a person to read before it is offered.</p><p><strong>A file at a URL is read in about twenty parts</strong>, and the dialog says how far it has got. A part whose connection drops is tried again, up to four times, with a longer pause each time. If the connection stays down, the dialog says where it stopped; what was read is kept while the page is open, and <strong>Apply</strong> again carries on from there.</p><p><strong>A study area reaching past the raster</strong> keeps the part the raster covers. The dialog says how far past which edge, and the run records it as a data issue, <em>Area beyond the raster</em>. Two outlines of one country rarely agree at the border: Botswana's provinces from geoBoundaries reach a little past WorldPop's file for Botswana. Only an area that does not overlap the raster at all is refused.</p><h3>What it will not do</h3><ul><li><strong>It will not reproject.</strong> A GeoTIFF in another coordinate system is refused, named.</li><li><strong>It will not read a picture.</strong> A GeoTIFF of colour bands, such as a scanned map, is named as one and sent to</li></ul><p>Georeferenced map image, which draws it as ground; its colours are ink, not values to measure.</p><ul><li><strong>It will not read a file at a URL whose host forbids it.</strong> A browser can read another site's file in parts only if</li></ul><p>that site allows it. Where it does not, <strong>Download the whole file</strong> still works, and the file is then chosen from this device.</p><ul><li><strong>It will not read classic NetCDF-3</strong>, a satellite swath, or a grid on another projection. A NetCDF-3 file can be</li></ul><p>converted with <code>nccopy -k nc4</code>. <strong>A NetCDF file at a URL</strong> is not read yet: keep it on this laptop and choose it.</p><ul><li><strong>It will not keep more than 166.4 million cells</strong>, nor a window of more than 1.1 GB. Past either, the raster is</li></ul><p><strong>streamed</strong>: what is kept, and drawn on a map, is a copy in blocks (10 by 10 cells for a country at 100 m), each block summed for a count such as people and averaged for a value such as elevation. Sample a raster reads the full cells from the source at each run, a strip at a time. Read from an address, that works on any device; read from a file on this computer, the file is chosen again in each new session, from the run's stop message or here, and checked against the file first chosen; Chrome and Edge remember it, and ask only to allow reading it again. A NetCDF file is not streamed yet.</p><h3>Where it is used</h3><p>The sea-level example (EGM2008, the mean sea surface and DeltaDTM around Manila).</p><h3>History</h3><h4>2026-11-23 \xB7 A copy on this device, where the window came from an address (0.15.0)</h4><p>A window read from a web address could only be read again from that address, so a practitioner holding the file still sent the study area to the host at every re-read. <strong>Configure\u2026</strong> now offers <em>Or the same file on this device</em> beside <strong>Read the window again</strong>. The file is read where it sits and never copied, and the window read from it is checked against the window that was kept: another file is refused by name, and nothing is kept. A raster too large to keep then reads its full cells from that copy at each run.</p><h4>2026-11-23 \xB7 The picker starts at what the step holds (0.14.1)</h4><p><strong>Configure\u2026</strong> offers where to get a population file. On a step that already held a window, it started at WorldPop's newest year, whatever the step held: a GRID3 2025 step's dialog read <em>Population (WorldPop)</em>, with 2026 offered. It now starts at the step's own source and year. Nothing the step held was changed by it.</p><h4>2026-11-19 \xB7 A window too large to keep is streamed (0.13.0)</h4><p>GHS-POP over DR Congo was refused: about 519 million cells of 8 bytes, 4.2 GB, past the 2.1 GB a tab decodes at once (found running the population rasters example). WorldPop's 4-byte cells fit; GHS-POP's did not. Chosen over holding GHS-POP's cells in 4 bytes, which would have changed its values in the eighth figure. A window past either limit is now kept as a copy in blocks and read from its source in strips by Sample a raster. Checked on a small GeoTIFF read by terrio (<code>tests/raster-stream.test.mjs</code>): the blocks equal their cells' sums and means. On DR Congo in Node.js, the copy in blocks of 10 took 6.3 s (Sample a raster's manual, History). <strong>Not yet measured in a browser tab.</strong></p><h4>2026-11-20 \xB7 Streamed by file or by address; chosen again from the stop message (0.14.0)</h4><p>A window past what a tab holds, 166.4 million cells or 1.1 GB, is streamed rather than refused, by file or by address: GHS-POP's 12.3 GB global file over DR Congo's provinces is applied in about a minute and a half. A window saved before under the old limit is still read and drawn. When a run needs a streamed file again, its stop message offers to choose it; Chrome and Edge remember the file across sessions. <strong>Configure\u2026</strong> always opens, even where the kept bytes cannot be read on this device.</p><h4>2026-11-24 \xB7 A coverage placed by a matrix is read (0.16.0)</h4><p>A GeoTIFF says where its cells sit in one of two ways: a pixel scale with a tie point, or one 4\xD74 matrix. Only the first was read. The second was refused with <em>&quot;Use a north-up GeoTIFF without a rotated transform&quot;</em> \u2014 which named a rotation that, in the ordinary case, is not in the file.</p><p>The cost was larger than it looks. <strong>GeoServer's WCS writes the matrix form</strong>, so a raster window pulled from any WCS was refused, and the message sent you hunting for a rotation that was not there. Found pulling the Malaria Atlas Project's walking friction surface for a Nigeria microplanning example: its matrix is a pure scale and shift, every rotation and shear term exactly zero, and Fieldwork was already reading the correct origin and resolution from it before refusing the file.</p><p>A matrix that <strong>turns or shears</strong> the grid is still refused, because a cell is then not a rectangle in longitude and latitude and every window, clip and sample here places cells by arithmetic on an origin and a resolution. It is now refused for being unfit, and says so: <em>&quot;This GeoTIFF is turned or sheared on the ground.&quot;</em></p>",rate:"<h2>Rate with a denominator</h2><p><strong>Counts divided by a population at risk, with what the population counts said.</strong> Cases per 100,000 people, deaths per 1,000 houses.</p><h3>What it does</h3><p>It divides a numerator, what was counted, by a denominator, the units at risk, for each group, and multiplies by 1, 100, 1,000, 10,000 or 100,000. The denominator's unit, the period the numerator covers and the vintage of the denominator travel with the result, because a rate whose denominator is unstated cannot be compared with any other.</p><h3>What you connect</h3><p><strong>Records arrive as</strong> decides the input:</p><ul><li><strong>points, one per subject</strong>: each point carries the numerator and the denominator as attributes.</li><li><strong>a table</strong>, in one of two forms, chosen under <strong>The table holds</strong>:</li></ul><p>- <strong>one row per measure, named in a key column</strong>: Snow's South London table, where <code>measure</code> says population or deaths, or Brazil's, where <code>variable</code> says <code>casos</code> or <code>pop</code>. - <strong>both numbers on each row, as columns</strong>: Sierra Leone's cases by district, with the 2021 census brought beside each count by <strong>Relate a column from another table</strong>.</p><p>Changing <strong>Records arrive as</strong> disconnects the input, because points and a table are not the same shape. So choose it first, apply, then connect.</p><p>It gives back a table of groups and rates, which <strong>Join a table to the study area</strong> can map and <strong>Chart</strong> can draw.</p><h3>How to use it</h3><p>The step's panel holds its <strong>Name</strong>, its input, one sentence saying what it divides by what, and <strong>Configure\u2026</strong>, where every setting is. The dialog's preview shows each group's numerator, denominator and rate before you apply, once the table can be read.</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Numerator</strong></td><td>What is counted: a measure's name, or a column</td></tr><tr><td><strong>Denominator</strong></td><td>The units at risk: a measure's name, or a column</td></tr><tr><td><strong>The denominator counts</strong></td><td>people, houses, households, person-time, or other</td></tr><tr><td><strong>Kind</strong></td><td><strong>proportion</strong>, where the numerator is part of the denominator and cannot exceed it; or <strong>ratio</strong>, events per unit, which can</td></tr><tr><td><strong>Per</strong></td><td>1 to 100,000</td></tr><tr><td><strong>Group by</strong></td><td>The column each rate is for, such as a district; none gives one rate for everything</td></tr><tr><td><strong>Band width</strong></td><td>For a numeric grouping, the width of each band</td></tr><tr><td><strong>Smallest denominator that gets a rate</strong></td><td>Groups below it report their counts and no rate</td></tr><tr><td><strong>Period the numerator covers</strong>, <strong>Vintage of the denominator</strong></td><td>Recorded and compared</td></tr></tbody></table><h3>What it will not do</h3><ul><li><strong>It will not compute a rate from a value it cannot read.</strong> A row without a number for the numerator or the</li></ul><p>denominator stops the run and names the row.</p><ul><li><strong>It will not let a proportion exceed one.</strong> That is a ratio, or a numerator that is not part of its denominator.</li><li><strong>It will not give a rate for a small denominator.</strong> Below the stated minimum, a rate is unstable rather than</li></ul><p>precise, so the counts are reported and the rate is not.</p><ul><li><strong>It will not decide whether the numerator's period and the denominator's vintage match.</strong> It records both; a</li></ul><p>2019\u20132023 count over a 2021 census is a choice you state.</p><h3>Where it is used</h3><p>South London (deaths per 1,000 people, by sub-district), Brazil (notified cases per 100,000 residents, by municipality), and Sierra Leone (cases per 100,000 people by district, over the 2021 census).</p><h3>History</h3><h4>2026-11-24 \xB7 The two vintages are compared on the year (0.6.0)</h4><p>A census of <strong>2022-08</strong> and cases of <strong>2022</strong> are the same year. They used to be reported as two different vintages, because the two fields were compared as text \u2014 so you were shown a disagreement and had to work out that it wasn't one. Census tables states its reference dates at four precisions, so this was the ordinary case, not an odd one.</p><p>Where the two really are apart, the figure now says <strong>how far</strong>: &quot;vintages 3 years apart&quot; rather than &quot;different vintages&quot;. One year and forty-one are not the same finding, and DR Congo's census is of 1984.</p><p>If you write something no year can be read from \u2014 &quot;the 1854 outbreak&quot; \u2014 the two fields are compared as words, exactly as before, and no distance is claimed.</p><p>You still type both periods. Filling them from what the source already states is the rest of [experiment 230](../experiments/230-years-carried-and-compared.md).</p><h4>2026-11-22 \xB7 A denominator of zero gives no rate (0.5.0)</h4><p>Found by the stress tests of the table operations. A group counted against a population of 0 was refused as a proportion above one, which is not what is wrong with it. It now has no rate, and says how many were counted against the zero, so the two columns can be checked.</p>",reachable_nodes:`<h2>Reachable junctions</h2><p><strong>A spatial operation.</strong> It takes sites and a street network and gives back the street junctions each site can reach within a travel time, each junction carrying the time and distance it took and the budget left on arrival.</p><h3>What it does</h3><p>The travel time and the speed make a budget in metres: 10 minutes at 80 metres a minute is 800 m. From each site's junction, the step follows the streets, cheapest route first, and keeps every junction it reaches within the budget. <strong>To each site</strong> reverses every street, so it answers who can reach the site rather than where the site can reach. On one-way streets the two differ.</p><p>Each junction reached is a point carrying the site it was reached from, the metres and minutes travelled, and <code>remainingM</code>, the budget left. <strong>Reachable corridor</strong> reads that to draw where the time runs out between junctions.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>sites</strong></td><td>the sites to travel from or to, snapped to the network or not</td></tr><tr><td><strong>network</strong></td><td>a street network, from <strong>Street network</strong></td></tr></tbody></table><h3>How to use it</h3><p>1. Connect the sites and the network. 2. In <strong>Configure\u2026</strong>, choose the direction, the travel time, how people travel and the speed. The speed must suit the mode: walking is 30 to 110 metres a minute, cycling 100 to 400, driving 150 to 1,200. 3. Sites that <strong>Snap sites to the network</strong> has moved need nothing else. For sites that have not been snapped, set the UTM zone and hemisphere this step attaches them in, and a snap limit if you want sites far from a street marked. 4. Run. The Result counts the junctions reached, the sites that reach nothing in the time and the sites past the snap limit.</p><h3>What it will not do</h3><ul><li><strong>It does not follow a timetable.</strong> Public transport is not a mode here: it follows routes and a timetable, not the</li></ul><p>street network.</p><ul><li><strong>It does not vary the speed.</strong> Every time is a street length divided by one speed, an assumption about one place</li></ul><p>in one period.</p><ul><li><strong>It does not tell a far junction from a missing street.</strong> A junction can be unreached because it is too far or</li></ul><p>because the downloaded network stops short of it. The two look the same.</p><ul><li><strong>It does not re-measure the streets.</strong> Lengths are the network's, as supplied.</li></ul><h3>What this does not establish</h3><p>That the speed holds where you use it, or that the network is complete. A site set back from the road spends its walk to the junction first, so it reaches less than one on the road.</p><h3>How it was checked</h3><p>The lab's <a href="https://digital-twin-ph.github.io/validation-lab/lab/index.html?path=07-reachability-vs-networkx.ipynb" target="_blank" rel="noopener noreferrer">reachability notebook</a> recomputes the junctions with networkx.</p><h3>History</h3><h4>2026-11-25 \xB7 The Preview says what it is waiting for, exactly (0.7.0)</h4><p>Its Preview multiplied the minutes by the speed, which is the two numbers just typed: the same sentence whether the network reaches a thousand junctions or none.</p><p>The budget sentence stays, because it is what the two settings mean, and what that budget buys is counted where the sites and the network can both be read. Where they cannot, what is missing is said exactly: a port with nothing on it is waiting to be connected, while a downloaded street network is held outside the page and read when the workflow runs. Asking for a street network over a connected one sends you to fix something that is not broken.</p><h4>2026-11-23 \xB7 On the standard (0.6.0)</h4><p>Moved off the old catchment panel to the standard Inspector: one sentence of what it finds, every setting in <strong>Configure\u2026</strong>, which holds Apply while the speed is outside the mode's range, and the run's counts in the Result.</p>`,relate_table:"<h2>Relate a column from another table</h2><p><strong>A join, narrowly.</strong> It takes two tables that name the same subjects, and brings a <em>category</em> from the second one onto the rows of the first.</p><h3>What it does</h3><p>Two tables often describe the same subjects and carry different things about them. John Snow's Table VIII gives each of 32 South London sub-districts its population and its cholera deaths; his Table XII gives each of the same 32 sub-districts the company that supplied its water. Neither table alone can answer <em>how many people died in the sub-districts supplied by one company</em>, and until this widget existed the application could not put them together \u2014 so the example repository carried that answer as a table somebody had computed by hand.</p><p>Relating Table XII's <code>water_supply</code> onto Table VIII gives every row a supply category. Nothing is added up yet; that is the next step.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>records</strong></td><td>the table being added to</td></tr><tr><td><strong>related</strong></td><td>the table being read from</td></tr></tbody></table><p>Both are tables, or point layers read as tables: each point a row of its attributes, without its location. The order matters: the first keeps its rows and gains a column, the second is only read. <strong>One table can go into both</strong>, to relate its rows to each other: Hagelloch's cases, each matched on <code>infector</code> to its infector's <code>case_ID</code>.</p><h3>How to use it</h3><p>The step's panel holds four things: its <strong>Name</strong>, its two <strong>Inputs</strong> (<em>Table being added to</em> and <em>Table read from</em>), one sentence saying what it will do, and <strong>Configure\u2026</strong>. After a run it says, in one line, how many rows related and which were dropped. Under that, <strong>Manual</strong>, <strong>Evidence</strong> and <strong>Version</strong>, then <strong>Duplicate</strong> and <strong>Remove</strong>.</p><p><strong>Configure\u2026</strong> opens the step's dialog, where everything is set. It has three parts, top to bottom:</p><ul><li><strong>Settings</strong>, below;</li><li><strong>Preview</strong>: the join these settings would make, before anything is applied;</li><li><strong>Decisions</strong>: what happens to rows that did not match, which the step will not choose for you.</li></ul><p>Nothing changes the workflow until <strong>Apply</strong>. <strong>Cancel</strong>, <strong>\xD7</strong> and the Escape key leave the step as it was; if you have changed something, the dialog asks before discarding it.</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Matched on, in the first table</strong></td><td>the column holding the names or codes, such as <code>sub_district</code></td></tr><tr><td><strong>The same, in the second table</strong></td><td>the second table's column for them; the column of the same name where there is one. A line list's <code>Residential District</code> against a population's <code>district</code></td></tr><tr><td><strong>And also matched on</strong></td><td>more shared columns, where one column does not identify a subject: a monitor's reading is one row per <code>site</code> <strong>and</strong> <code>date</code>. A row relates only where every chosen column agrees</td></tr><tr><td><strong>Bring across</strong></td><td>the second table's column to add, such as <code>water_supply</code>, or its <strong>value column</strong>, such as a monitor's reading in ppb or a district's census population, which arrives as written and <strong>as a number</strong>, with its unit, so <strong>Rate with a denominator</strong> can divide by it</td></tr><tr><td><strong>Bring it in as</strong></td><td>the name the brought column is written under. Needed where the first table already has a column of that name, as when a table is related to itself: <code>date_of_prodrome</code> brought in as <code>infector_prodrome</code>. Left empty, the column keeps its own name</td></tr><tr><td><strong>Where a key matches several rows</strong></td><td><em>Stop, and say which key</em>, as before; or <em>keep one row per match</em>: the row is repeated once for each, and the step says how many keys matched several rows and how many rows that added. MERS's cases related to their recorded sources: SK_39 becomes three rows</td></tr><tr><td><strong>Compare keys</strong></td><td>folding punctuation and case; exactly after trimming; or allowing for spelling, and dropping words</td></tr><tr><td><strong>A date within a period</strong></td><td>optional; see below</td></tr><tr><td><strong>Shifts, in days</strong></td><td>optional; see below</td></tr></tbody></table><h4>Compare keys</h4><p>Two sources spell names differently. Snow's own tables agree with each other, because both transcribe the same book \u2014 but his sub-district names against the published boundaries match <strong>23 of 32</strong> exactly and <strong>32 of 32</strong> once punctuation is folded, and every one of the nine differences is a single comma. So folding is the default, and the choice is recorded in the evidence.</p><p>Tighten it to <strong>exactly</strong> when a punctuation difference means two different subjects. Loosen it when it means one subject written twice.</p><p><strong>Allowing for spelling, and dropping words.</strong> Sources also differ by more than punctuation. A line list writes &quot;Bo District&quot; where the boundaries write &quot;Bo&quot;, and &quot;Falaba District&quot; where they write &quot;Fabala&quot;. With this chosen:</p><ul><li><strong>Words to drop</strong> are taken out of both columns before comparing, as whole words: <code>District</code> takes &quot;Bo District&quot;</li></ul><p>to &quot;bo&quot;, and leaves &quot;Districtville&quot; alone. Separate several with commas.</p><ul><li><strong>Spelling allowed</strong> is the similarity a name must reach to match one spelled differently: 0.88 to start, from</li></ul><p>0.5 to 1. Higher allows fewer differences; 1 allows none. It is Jaro-Winkler, as Deduplicate records uses.</p><p>Each name is matched once. The preview lists every name, how it was compared, what it matched and how: <strong>matched exactly</strong>, <strong>matched allowing for spelling</strong> with its score, <strong>ambiguous</strong> where two names are as close, or <strong>not found</strong>. An ambiguous name is listed under <strong>Decisions</strong> with its candidates: choose one, or none. A name not found, or left undecided, is an unmatched row, decided as any is.</p><p>The result gains a column saying how each row matched, such as <code>Residential District match</code>. You can bring the second table's own column across, such as <code>district</code>, to have its spelling on every row.</p><p>Check the spelling matches in the preview. A close spelling is not always the same place: &quot;Fabala&quot; is Falaba because the boundaries hold no other district like it, which you can see and the step cannot.</p><h4>The preview</h4><p>The dialog's <strong>Preview</strong> shows three things, and they change together as you choose:</p><p>1. <strong>The shape of the join</strong> \u2014 a bar of the keys only in the first table, in both, and only in the second. Keys, not rows: a table here holds several rows per subject, so counting rows would say that nine unmatched sub-districts are eighteen unmatched things. 2. <strong>The effect on each numeric variable</strong> \u2014 what each one totals over the whole table, over the rows that matched, and the share retained. Read this before anything else; see below. 3. <strong>The Methods note</strong> this step will machine, and a <strong>preview of the table</strong> that will travel on, with the key columns marked <strong>Matched on</strong> and the column added <strong>Brought across</strong>, as in <strong>View this table</strong>.</p><p>Then <strong>Apply</strong>. Nothing is written until you press it.</p><h4>What the shares are telling you</h4><p>If two variables keep different shares, the rows that did not match are <strong>not a random sample</strong> of what you are measuring. On Snow's Table VIII against the published boundaries, 68.2% of population is retained against 61.2% of deaths \u2014 so a mortality rate computed on the matched rows comes out at <strong>89.6% of its value over the whole table</strong>, 2.787 per 1000 against 3.109.</p><p>That multiplier is arithmetic and not an estimate: a rate of one variable over another is multiplied by exactly the ratio of their retained shares. It runs backwards too. If the figure you expected and the figure you are looking at differ by that ratio, you are looking at a number produced by a join you did not intend \u2014 and the shares say which one.</p><p>Had both variables kept the same share, the exclusion would cost precision and leave the estimate alone.</p><h4>The rows that did not match</h4><p>Where any key of the first table has no row in the second, <strong>the step will not run until you say what to do</strong>, under <strong>Decisions</strong> in the dialog. Neither choice is ticked to begin with: the two answers give different totals and the result cannot be read for which one you got, so nothing here chooses for you.</p><table><thead><tr><th>Choice</th><th>What you get</th></tr></thead><tbody><tr><td><strong>Drop them</strong></td><td>only the matched rows, and the totals the shares describe</td></tr><tr><td><strong>Keep them under a category I name</strong></td><td>every row, and the totals of the whole first table</td></tr></tbody></table><p>Keeping needs a name, and it has to be yours \u2014 nothing here will invent a stratum the data never measured, and a name already used by the second table is refused so that unmeasured rows cannot join a measured group.</p><p><strong>A name that is a number is written as that number</strong>, and the column stays a number, so it can be added up. Use one only where no match means none. Hagelloch's cases, counted by <code>infector</code> and related back on <code>case_ID</code>: the 126 children nobody names as infector infected no one recorded, so they are kept as <code>0</code>, and 188 rows add up to 184. A word, such as <code>none recorded</code>, keeps the column a category.</p><p>Your decision is stored with a signature of the gap it was made about. Edit either table, or change how keys are compared, and the decision lapses rather than riding on data it was not made about.</p><h4>Why it brings a category and not a number</h4><p>A table in this application is <strong>long</strong>: it has key columns, which hold labels, and one value column, which holds numbers. A water supply company is a label, so it can only arrive as a key column \u2014 and a key column lands on every row, which is why <strong>the row count does not change.</strong></p><p>Bringing <em>numbers</em> across would mean adding rows instead, and that is a different operation with a different way of going wrong: two tables can disagree about the same measure. It is not built.</p><h3>A date within a period, and a lag</h3><p>Some tables do not share a date. Weekly cases have a week; a satellite product has an 8-day period with a start and an end. <strong>Match a date within a period</strong> relates each row to the row of the second table whose start and end hold its date, alongside the columns matched on as usual (the municipality, say).</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Date, in the first table</strong></td><td>the date to place, such as <code>data_iniSE</code>, the Sunday a week starts</td></tr><tr><td><strong>Period start</strong> and <strong>Period end</strong>, in the second</td><td>the span each row of the second table covers</td></tr><tr><td><strong>Shifts, in days</strong></td><td><strong>+ Add a shift</strong>, then the days added to the date before it is placed: <strong>+3</strong> takes a week's Sunday to its Wednesday, and a lag of <em>k</em> weeks is 7*k* days fewer, so a 2-week lag from the Wednesday is <strong>\u221211</strong></td></tr></tbody></table><p>The result keeps the shifted date and the matched period's start on every row, so each match can be checked. A date that falls inside two periods of the second table, such as two satellites' rows for one period, is refused by name: keep one row per period first. A date in no period is a row with no match, decided as any other.</p><p><strong>Several shifts in one step.</strong> Add two or more shifts and the column is brought once per shift, each as a column of its own named by the shift: <code>LST_Day_1km_-11d</code>, <code>LST_Day_1km_-25d</code>. Every row is kept. A row with no value at a shift has that column left empty, and the preview and the run count the empties per shift. So there is no decision about unmatched rows to make: nothing is dropped. Several shifts need a date within a period, each a whole number of days, none listed twice. There is no limit on how many: each shift takes about half a second on 77,740 rows.</p><p><strong>A table can be related to itself, shifted.</strong> Rainfall two weeks before each case week is the weekly table's own rainfall, 14 days earlier: choose the week's start as the date, the period's start and its end. The first table already has that column, so the matched week is written as <code>data_iniSE_matched</code> and the first table's own date is kept. A second shift on a table that already holds one is written as <code>data_iniSE_shifted_2</code>, beside the first.</p><p><strong>A decision about unmatched rows is kept as a short digest</strong> of the rows it was made about, so it lapses when they change. Sixteen years of weekly cases left 58,401 rows unmatched in one join; the decision used to be stored with all of them written out, and seven such joins filled the browser's storage. A decision saved that way before 0.41.0 still holds.</p><h3>Reading what you get</h3><p>The same table with one more column, and, on the step after a run, one line saying <strong>what the join did</strong>: for example <em>4 of 6 rows related; 2 dropped, with no district in supply.csv: Charlie.</em></p><p>Read the dropped count first. A row that found no match is <strong>absent from the table that travels on</strong>, so the result is internally consistent whether it holds all of your rows or two thirds of them. The line names the keys that did not match, so you can go and look at the second table rather than only know that something is missing. Where nothing was dropped it says so, because &quot;none&quot; is the claim you need and a zero is easy to pass over. With several shifts, the line counts the empty rows per shift instead.</p><p><strong>View this table</strong> repeats the column origins above each column heading, so a wide related table says which half of the row came from where. It also marks the join's own columns: each key column <strong>Matched on</strong>, tinted, in every <em>Before</em> and in <em>After</em>, and the column added <strong>Brought across</strong> in <em>After</em>.</p><h4>The Methods note</h4><p>This step machines a note for the <strong>Methods</strong> section of a write-up: what was brought from where, on what key, compared how, how many keys appeared in both tables, and \u2014 where rows were excluded \u2014 which keys those were and what share of each variable survived. A join is a thing you did to the data, and the count of what it excluded is Methods prose in an epidemiology paper rather than a limitation.</p><p>The dialog's preview shows the note each choice would produce, so you can read the sentence before applying it. The run records it in the evidence.</p><h3>What it will not do</h3><ul><li><strong>It will not choose between two answers.</strong> If the second table gives one key two different</li></ul><p>values of the column being brought across, this refuses and names the key. Taking the first would produce a grouping that is wrong in a way no total reveals, and the ambiguity is usually telling you the key does not identify what you think it identifies.</p><ul><li><strong>It will not invent a category.</strong> A key the second table has no row for is <strong>reported by name</strong></li></ul><p>and those rows are dropped. Filling in &quot;unknown&quot; would put a stratum in your table that nobody measured.</p><ul><li><strong>It will not match approximately unless you ask.</strong> Keys are compared exactly after trimming, or with</li></ul><p>punctuation and case folded, unless you choose <strong>allowing for spelling</strong> (see <strong>Compare keys</strong>). Even then it will not choose between two names equally close: you do.</p><ul><li><strong>It will not allow for spelling on a date within a period.</strong> Choose one or the other.</li><li><strong>It will not tell you the two tables describe the same subjects.</strong> That is your judgement. The</li></ul><p>widget checks that the keys line up, not that they mean the same thing.</p><h3>Where it is used</h3><p>The South London example: <em>Were deaths more common with one water supply than the other?</em> The NYC example: <em>Did the satellite see the city's NO\u2082?</em>, which matches satellite and ground readings on <code>site</code> and <code>date</code> together and brings the ground reading, the second table's value, across.</p><h3>How it was checked</h3><p>Validation Lab check <strong>28</strong>, <code>28-relate-table-vs-pandas.ipynb</code>, against a pandas left merge of Snow's Table XII onto his Table VIII. There is no arithmetic to check, so what was recomputed is the matching: the same category on the same row, the row count unchanged at 64, and the same rows dropped and named when a sub-district is withheld.</p><p>The case worth an outside eye is the ambiguous key. A merge resolves it by <strong>multiplying rows</strong> \u2014 66 rows out of a 64-row table \u2014 so the sub-district's population would appear under both companies with no total revealing it. This refuses instead, and the check records the merge's row count as the measure of what the refusal prevents.</p><p>What it does not reach: Snow's two tables spell every sub-district identically, so a name differing by punctuation or case \u2014 the case you will actually meet \u2014 is never exercised.</p><h3>History</h3><h4>2026-11-24 \xB7 Show me how keeps the rows it has matched (0.15.0)</h4><p>When a key is found twice and you have chosen to stop, the walkthrough said <em>&quot;the step will stop once every row is checked&quot;</em> \u2014 and emptied the result beside it at the same moment. Both could not be true, and the earlier steps, which had added Alpha and St. Ann one at a time, were made to look as though they had been lying.</p><p>The rows now stay while the walk goes on, because the step really does go on matching them, with a line underneath: <strong>None of this will be passed on.</strong> That is the thing worth learning here \u2014 the matching is fine and the outcome is still nothing. The last step is unchanged: no table, nothing passed on.</p><h4>2026-11-22 \xB7 Keys proposed from their values, and an empty cell is one of a key's values (0.14.0)</h4><p>It matched a column only by its name. Now, with nothing chosen to match on, Configure\u2026 proposes the pair of columns whose values link most, one from each table, after the same folding the match uses: &quot;LGA&quot; in one table and &quot;lga_name&quot; in the other, where both name the same places. It says how many keys the pair links, and the choice stays yours. Every other pair sharing values is listed beside it, with the counts, and <strong>Match on these</strong> chooses one. Where no pair links anything and one column holds codes, such as P-codes, while the other holds names, it says so: relating them needs a table that holds both.</p><p>Also found by the stress tests of the table operations: where the second table held North twice, once with 4 and once with an empty cell, North was related as 4: a choice nobody made. The empty cell now counts as one of North's values, so the step stops as it does for any key with two values, and says &quot;4&quot; and an empty cell. A key whose only values are empty still brings nothing.</p><h4>2026-11-19 \xB7 Shown on a made-up example (0.13.0)</h4><p><strong>Show me how it works</strong>, in Configure\u2026, steps through a join of two made-up tables, with the choices made in the dialog and not yet applied: a plain match, a name with a full stop in one table and not the other, a name the second table does not have, a name it has twice, and a name only the second table has. Back, Step and Play; nothing moves where reduced motion is asked for. Its last step is the table this step makes from the same rows, or the words it stops with. Experiment [223](../experiments/223-a-table-step-shown-on-a-small-example.md).</p><h4>2026-11-19 \xB7 The example's own names (0.13.1)</h4><p>Show me how it works follows the choice to keep unmatched rows and writes the example's own name, &quot;Not known&quot;, not the person's, which is about their data. Found in use on Hagelloch's <em>Each case's infector</em> step.</p><h4>2026-11-20 \xB7 What each table holds, when nothing matches (0.13.2)</h4><p>When no key of the first table appears in the second, the message names both columns and shows a few keys from each, so two kinds of key are seen side by side: DR Congo's 1984 regions beside today's provinces.</p>",sample_raster:`<h2>Sample a raster at points or over areas</h2><p><strong>A grid's value at each point, or its total over each area.</strong> The ground's height at each clinic; the people a population grid places in each district; the satellite's NO\u2082 over each monitor, day by day.</p><h3>What it does</h3><p>What it gives back follows what you connect, and the step says which it is doing.</p><p>It has two inputs, on the canvas and in the Inspector: <strong>Raster</strong>, for a Raster input, Clip raster or satellite files, and <strong>Read at</strong>, for points, a polygon layer or a study area. Each is named for what is connected to it, and connecting a second kind of place replaces the first.</p><table><thead><tr><th>Connect</th><th>It gives back</th><th>Each place carries</th></tr></thead><tbody><tr><td>A <strong>Raster input</strong> (or <strong>Clip raster</strong>) to <strong>raster</strong>, and points to <strong>points</strong></td><td>the points</td><td>the cell's value, as a new attribute</td></tr><tr><td>A <strong>Raster input</strong> to <strong>raster</strong>, and a <strong>Polygon layer</strong> to <strong>areas</strong> or a <strong>Study area</strong> to <strong>area</strong></td><td>the areas, as polygons</td><td>the total of the cells inside, how many cells that was, how many had no data, and how many lay beyond the raster</td></tr><tr><td><strong>Search a satellite catalog</strong> to <strong>files</strong>, and points or areas</td><td>a table</td><td>one row per place and file period, with its quality</td></tr></tbody></table><p>Points and areas are not mixed in one step.</p><p><strong>Over a study area, each named part is one area</strong>, all of its pieces together: a district drawn as a main outline and a sliver beside it is totalled once. With <strong>Also give each area's zonal statistics</strong> in Configure\u2026, each area also carries its cells' mean, median, standard deviation, smallest and largest (of the cells with a value), how many cells are above zero and their share, its size in km\xB2 and the total per km\xB2. The cells' statistics are per cell: a latitude-longitude grid's cells are not all the same size.</p><p>The areas, with their totals, can go on to a table step, such as Total within groups or Append rows, as a table: one row per area, its name and its numbers.</p><p><strong>Configure\u2026 says what arrived first:</strong> the raster's name, how many cells were kept and how wide each is, its no-data value, and what its values measure where its source record or the file says so, which then fills <em>What those values measure</em>. It says what the raster is read at, or that nothing is connected yet and what to connect. Where a study area is on the canvas, <strong>Read it over</strong> <em>its name</em> connects it and reads the raster over its named parts, or over the whole area where it has none, and moves a Map's or Table's input from points to polygons.</p><h3>At points, from a raster</h3><p>For each point, it reads the raster at the point and writes the value onto it as a new attribute: the value of the cell containing the point, or a value interpolated between the four nearest cells. The points keep everything else they carried.</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Attribute to write</strong></td><td>The new attribute's name, which must not already be on the layer</td></tr><tr><td><strong>What those values measure</strong></td><td>Its unit and surface, in your words: &quot;metres above EGM2008&quot;</td></tr><tr><td><strong>Read each value as</strong></td><td><strong>the cell containing the point</strong>, or <strong>between the four nearest cells (bilinear)</strong></td></tr></tbody></table><p>Bilinear suits a smooth field, such as a geoid or a mean sea surface, and is how PROJ reads EGM2008. Keep a margin of one cell in the Raster input's window so points near its edge have four cells around them.</p><h3>Over areas, from a raster</h3><p>Each area is given the <strong>total</strong> of the cells whose centre is inside or on it, the rule <strong>Clip raster</strong> uses. For a population grid, such as WorldPop, GRID3 or GHS-POP, that total is the grid's estimate of the people in the area.</p><table><thead><tr><th>Column</th><th>What it holds</th></tr></thead><tbody><tr><td>the attribute you name, <code>total</code> by default</td><td>the sum of the cells with a value; empty where no cell had one</td></tr><tr><td><code>cells</code></td><td>how many cells were added</td></tr><tr><td><code>cells_no_data</code></td><td>cells inside the area the raster marks as no data: they add nothing, and are not zero</td></tr><tr><td><code>cells_outside_raster</code></td><td>cells of the area beyond the raster's window: the window does not cover that part of the area</td></tr><tr><td><code>cell_mean</code>, <code>cell_min</code>, <code>cell_max</code></td><td>only when asked for: the mean, smallest and largest of the cells with a value</td></tr></tbody></table><p><strong>Also the mean, smallest and largest cell.</strong> Tick <em>Also give each area's mean, smallest and largest cell value</em> in <strong>Configure\u2026</strong> and each area carries three more columns, <code>cell_mean</code>, <code>cell_min</code> and <code>cell_max</code>, of the cells with a value. They suit a grid of heights or temperatures more than one of people. A mean of cells is per cell, not per square kilometre: on a latitude-longitude grid, cells shrink towards the poles. An area with no cell holding a value has none of the three.</p><p><strong>Read the last two columns before the total.</strong> An area with cells outside the raster has a total for only part of itself; widen the Raster input's window to cover it. Areas come from a <strong>Polygon layer</strong>, or from a <strong>Study area</strong>: its units, such as districts picked from an administrative boundary, or the whole boundary as one area.</p><p><strong>A cell counts whole, or not at all.</strong> It is not split by the area's edge. A 100 m cell matters little to a district and more to a ward of a few hectares.</p><h3>From satellite files</h3><h4>What it reads</h4><p>For each point and each file the search kept, it reads the value of the pixel whose centre is nearest the point. It fetches only the parts of each file it needs, by HTTP range, in the browser. The result is a long table: one row per point per overpass, plus one row per point for each day with no overpass.</p><table><thead><tr><th>Column</th><th>What it holds</th></tr></thead><tbody><tr><td><code>point_id</code>, <code>point</code></td><td>The point, as the point layer names it. Where Point data read its ids from a table column, the id column takes that column's name, <code>site</code> for the NYC monitors, so the result relates back to the source on it</td></tr><tr><td><code>date</code>, <code>overpass_time</code></td><td>The day, and the time the pixel was scanned</td></tr><tr><td><code>stream</code>, <code>orbit</code></td><td>The processing stream (<code>OFFL</code> offline, <code>NRTI</code> near real time) and the orbit</td></tr><tr><td><code>scanline</code>, <code>ground_pixel</code></td><td>Which pixel of the swath was read</td></tr><tr><td>the variable, e.g. <code>nitrogendioxide_tropospheric_column</code></td><td>The value, <strong>only where it passed the quality rule</strong>, in the unit the file states (<code>mol m-2</code>)</td></tr><tr><td><code>value_as_read</code></td><td>The value read, whether or not it passed</td></tr><tr><td><code>qa_value</code></td><td>The pixel's quality value, 0 to 1</td></tr><tr><td><code>passes_quality</code></td><td><code>yes</code> or <code>no</code></td></tr><tr><td><code>gap</code></td><td>Where there is no usable value: <code>no overpass</code>, <code>no retrieval</code> or <code>below quality threshold</code></td></tr></tbody></table><h4>Over areas</h4><p>Connect a polygon layer to <strong>areas</strong> instead of points: municipalities from <strong>Join a table to the study area</strong>, or a <strong>Polygon layer</strong>. Or connect a <strong>Study area</strong> to <strong>area</strong>: its units, such as municipalities picked from an administrative boundary, are read as they are. One kind of place per node. This works for gridded products, which today means <strong>MODIS land surface temperature</strong> (8-day, 1 km) and <strong>MODIS vegetation</strong>, NDVI and EVI (16-day, 250 m). Sentinel-5P is still read at points only.</p><p>Each area is read by the cells whose centre is inside it, the rule <strong>Clip raster</strong> uses. A municipality made of several parts, such as one with islands, is one area. Where an area spans two of MODIS's tiles, both are read and added before the mean is taken.</p><table><thead><tr><th>Column</th><th>What it holds</th></tr></thead><tbody><tr><td>the place column</td><td>the area's name; call it as the table you will relate it to does, such as <code>municipio</code></td></tr><tr><td><code>period_start</code>, <code>period_end</code></td><td>the period the file covers: 8 days for temperature, 16 for vegetation</td></tr><tr><td><code>platform</code></td><td><code>terra</code> (mid-morning pass) or <code>aqua</code> (early afternoon), never pooled</td></tr><tr><td><code>layer</code></td><td>daytime or night-time; NDVI or EVI</td></tr><tr><td><code>cells</code>, <code>cells_with_value</code>, <code>cells_passing</code></td><td>how many cells the area holds, how many had a value, and how many passed the quality rule: <strong>the mean rests on the last</strong></td></tr><tr><td><code>value_min</code>, <code>value_max</code></td><td>the range of the passing cells, in the unit chosen</td></tr><tr><td><code>clear_days</code></td><td>how many of the 8 days were clear, on average, behind the passing cells; empty for vegetation, which gives no such count</td></tr><tr><td><code>LST_Day_1km</code>, <code>LST_Night_1km</code>, <code>NDVI_250m</code> or <code>EVI_250m</code></td><td>the mean of the passing cells, in the unit chosen; NDVI and EVI have none</td></tr><tr><td><code>gap</code></td><td><code>no cell in the area</code>, <code>no retrieval</code> or <code>below quality threshold</code></td></tr></tbody></table><p><strong>The unit.</strong> The files state kelvin. <strong>Report temperature in</strong> offers degrees Celsius (K \u2212 273.15), the default, degrees Fahrenheit (K \xD7 9/5 \u2212 459.67) or kelvin. The conversions are exact, and the result says which was applied. How the unit is known: each file states it, with its scale factor, in its own tags, and every file opened is checked. A file that states another unit stops the run and is named.</p><p><strong>The quality rule for MODIS.</strong> Its documents explain its quality bits and recommend no rule. The default keeps cells the product made, of good or other quality, whose average temperature error is 2 K or less. <em>Good quality only</em> and <em>everything produced</em> are the alternatives.</p><p><strong>Vegetation</strong> is read by its pixel reliability, whose meanings are in each file: 0, good data, <em>&quot;use with confidence&quot;</em>; 1, marginal, <em>&quot;useful, but look at other QA information&quot;</em>; 2, snow or ice; 3, cloudy. The default keeps 0 and 1; <em>good data only</em> is the alternative. Each value is a 16-day composite, the best view of each cell in those days, not a mean of them. The files give the scale as 10000, a divisor, where temperature's files give 0.02, a multiplier; each is read as its own files state it.</p><p><strong>Read the counts.</strong> Over Rio de Janeiro in February 2024 each 8-day value rested on about two clear days, and one week's value for Rio de Janeiro city came from 26 of its 1,400 cells. A mean is reported wherever any cell passed; whether that is enough is the analyst's call, and the numbers to make it are on the row.</p><h4>How to use it</h4><p>1. Build the search first: <strong>Find satellite products</strong> (choose the Sentinel-5P NO\u2082 product on Planetary Computer), then <strong>Search a satellite catalog</strong> over your area and dates, and press <strong>Search</strong>. 2. Add <strong>Sample a raster at points or over areas</strong>. Connect your point layer, for example the monitors from <strong>Point data</strong>, to <strong>points</strong>, and the search to <strong>files</strong>. 3. Select the step and press <strong>Configure\u2026</strong>. Check the <strong>Quality rule</strong>: for Sentinel-5P it is set to the product manual's, <code>qa_value</code> at or above 0.75; for MODIS, choose the <strong>Layer</strong>, the <strong>Quality rule</strong>, <strong>Report temperature in</strong> and the <strong>Name of the place column</strong>. Press <strong>Apply</strong>. 4. Connect a <strong>Table output</strong>, and run the workflow. The files are read during the run. A year of files takes minutes: while they are read, a panel at the foot of the page names the step and counts the files read so far, <em>Reading satellite files: 40 of 92</em>, and the run's state beside the canvas says the same.</p><p><strong>Several files are read at once</strong>: six MODIS files, three Sentinel-5P. Three months of MODIS over Rio de Janeiro's 92 municipalities took 70 s one file at a time in Chromium and 23 s this way. A browser opens at most six connections to the MODIS server, so more would not help. A file that fails is tried three times; if it still fails, the run stops and names it.</p><p><strong>What a file gave is kept on this device.</strong> A file read before, the same way at the same places, is not read again: not after a change downstream, not after a reload, not the next day. What is kept is the reading, a few numbers per place, not the file: 180 MODIS files over 92 municipalities come to about a megabyte. The result says how many files were taken from the device, <em>Every file was taken from readings saved on this device from an earlier run</em>, and the receipt records it as <code>fw:filesFromDevice</code>. Change the layer, the quality rule or the places, and those files are read again. <strong>Configure\u2026</strong> shows how many readings are kept, and offers <strong>Read every file again on the next run</strong> and <strong>Forget every saved reading on this device</strong>.</p><h4>The three gaps</h4><table><thead><tr><th>Gap</th><th>What happened</th></tr></thead><tbody><tr><td><strong>no overpass</strong></td><td>No file kept for that day, or the point is outside the file's swath</td></tr><tr><td><strong>no retrieval</strong></td><td>The satellite passed over, and no value was retrieved at that pixel: usually cloud</td></tr><tr><td><strong>below quality threshold</strong></td><td>A value was retrieved, and the product's own rule says not to use it</td></tr></tbody></table><p>They are kept apart because they mean different things for a study: cloud is not random, and a day the satellite missed is not a day it saw and rejected.</p><h4>The quality rule</h4><p>The NO\u2082 product's documents disagree, and only at exactly 0.75: the readme says <em>above</em> 0.75, the product user manual's table <em>at or above</em>. The Inspector lets you choose, and the result and its receipt say which was applied.</p><p><code>qa_value</code> is stored as an integer from 0 to 100 and a scale factor of 0.01, so the rule compares the integers. The scale factor is stored as 0.0099999998, so a value stored as 75 multiplies out to 0.74999998, which would wrongly fail &quot;at or above 0.75&quot;.</p><h4>What it will not do</h4><ul><li><strong>It will not fill a gap.</strong> Imputation is a separate, declared step (experiment 179, provisional statement 2).</li><li><strong>It will not interpolate.</strong> The value is the nearest pixel's, on pixels of about 3.5 \xD7 5.5 km at the centre of the</li></ul><p>swath and wider at its edges. A pixel is not the value at the point.</p><ul><li><strong>It will not turn a column into a concentration.</strong> NO\u2082 here is a tropospheric column, molecules in the air above the</li></ul><p>pixel, not a surface concentration a monitor measures.</p><ul><li><strong>It will not read other products yet.</strong> Sentinel-5P NO\u2082 (at points), MODIS land surface temperature and MODIS</li></ul><p>vegetation (at points or over areas), all on Planetary Computer, have readers. Ozone and aerosols say so when connected.</p><ul><li><strong>It will not weight by population or by how much of a cell lies in an area.</strong> A cell counts whole, or not.</li></ul><h4>What it costs</h4><p>The cost is in chunks, not pixels. An offline NO\u2082 orbit file is about 600 MB and stores each variable in compressed chunks of 2,086 \xD7 225 pixels, so the first pixel of a chunk costs the whole chunk: about 2 MB each for latitude, longitude and quality, and 3 MB for the value, measured on 7 June 2023. <strong>Expect roughly 10\u201315 MB per overpass</strong>, much the same for 2 points as for 50 when they fall in one chunk. A month of daily overpasses is a few hundred MB.</p><h4>How it was checked</h4><p>The lab's <a href="https://github.com/digital-twin-ph/validation-lab" target="_blank" rel="noopener noreferrer">check 35</a> reads a Sentinel-5P-shaped file with h5py, a different HDF5 reader, and recomputes every point's pixel by comparing every centre in the swath, then rebuilds the table row by row for both quality rules. It agrees. Against 0.2.0 it found a point near the edge of one of the file's chunks read from the pixel across the edge from the nearest one: fixed in 0.2.1. The file is synthetic, so this says nothing about a real orbit's content.</p><p><strong>Vegetation, against the dataset, 2026-11-18.</strong> NDVI over Rio de Janeiro's 92 municipalities from the six Terra and Aqua periods touching February 2024 (12 files, 13 s in Node), compared with the Brazil example's own <code>NDVI_mean</code> for February. Default rule: all 552 rows had a value; correlation across municipalities 0.949; Fieldwork higher by 0.04 on average, from \u22120.02 to +0.14 (Nil\xF3polis 0.57 against 0.43). Good data only: 10 rows with none passing, correlation 0.924. <strong>Not established:</strong> which is nearer the truth. The dataset does not say which satellite, which periods or which cells make its month, or whether it applied a quality rule; its <code>NDVI_mean</code> is never missing, which a satellite index rarely is.</p><h4>Where it comes from</h4><p>Admitted, built and measured in [experiment 179](../experiments/179-eo-and-stac-for-the-nyc-monitors.md). The files are read with <a href="https://github.com/usnistgov/h5wasm" target="_blank" rel="noopener noreferrer">h5wasm</a> 0.10.3, from the US National Institute of Standards and Technology, whose notice travels with Fieldwork in <code>vendor/h5wasm-0.10.3-LICENSE.txt</code>.</p><h4>Where it is used, from satellite files</h4><p>The NYC example, <em>Did the satellite see the city's NO\u2082?</em>: Sentinel-5P NO\u2082 at the four NO\u2082 monitors over 1 to 14 June 2023, related to their daily readings on <code>site</code> and <code>date</code>.</p><h3>What it will not do</h3><ul><li><strong>It will not set a missing value to zero.</strong> A point on no data, outside the raster, or without a location keeps no</li></ul><p>value and is counted, under <strong>Result</strong>; over areas, no data and cells outside are counted apart.</p><ul><li><strong>It will not overwrite an attribute</strong> the layer already has.</li><li><strong>It will not call a cell value a measurement at the point.</strong> It is the raster's value there, at its resolution.</li><li><strong>It will not weight a cell by how much of it lies in an area.</strong></li></ul><h3>Where it is used</h3><p>The sea-level example: the ground's height at each facility, and the geoid and the sea surface at the gauge. Brazil dengue and New York ozone read satellite files with it.</p><h3>History</h3><h4>2026-11-22 \xB7 Its satellite dialog moved (0.10.1)</h4><p>The dialog for reading satellite files, with the sentence that summarises it, moved out of the application's main file into this widget's own module, unchanged.</p><h4>2026-11-22 \xB7 Show me how (0.10.0)</h4><p><strong>Configure\u2026</strong> offers <strong>Show me how it works</strong>: the reading chosen, at points (the cell's value, or between the four nearest) or over areas, on a made-up grid of 12 cells with one cell of no data and a point off the raster.</p><h4>2026-11-18 \xB7 Vegetation (0.7.0)</h4><p>MODIS NDVI and EVI (MOD13Q1 and MYD13Q1, 16-day, 250 m) are now read over areas and at points, as temperature is. One file's own tags were read first. Two findings: the files' <code>scale_factor</code> is 10000, a divisor, where temperature's 0.02 is a multiplier, so each product states which it is rather than the reader guessing; and pixel reliability is stored unsigned with fill 255, where LP DAAC's table says int8 with fill \u22121. The quality rules a step offers are now its product's own, and a layer or rule from another product is not carried over when the files change.</p><h4>2026-11-19 \xB7 A streamed raster read at full resolution (0.8.0)</h4><p>A raster too large to keep (Raster input, History: streamed) is read here from its source a strip of rows at a time, added up in the Rust kernel (<code>kernel/src/zonal.rs</code>) by the same rule, a cell counted when its centre is inside or on the area. Each area's median is found exactly by reading again: a histogram finds the bins holding the middle ranks, and their values are collected and sorted; where the middle rank falls on a run of one value, such as zeros, nothing need be collected. At points, only the points' cells are read. Checked against totals held in memory, on an offset window with no data, zeros, a hole and an area reaching past the window: every total, count, mean, median and deviation equal (<code>tests/raster-stream.test.mjs</code>).</p><p><strong>On DR Congo, in Node.js on the development Mac, not in a browser tab:</strong> GHS-POP 2025 (R2023A, 3 arcseconds, the 12.3 GB global file read from disk) over GADM's 240 districts, 73,509 vertices. The window, 22,926 by 22,607 = 518 million cells of 8 bytes, would be 4.2 GB whole. The kept copy, in blocks of 10 (2,293 by 2,261), took 6.3 s; every district's total, cells, statistics and exact median took 20.7 s over 5 passes, the process at most 1.2 GB. 109,087,372 people over 273.6 million cells; Kinshasa 13.5 million, its median cell 0. Found on the way: Node's <code>openAsBlob</code> reports a file over 4 GB with its size wrapped at 2^32, and reads past 4 GB come back empty; the first run failed for that, and was read with positioned reads. A browser's File has no such limit.</p><p><strong>Not yet measured:</strong> the same in a browser tab, through Raster input's dialog; and read by range from an address.</p><h4>2026-11-20 \xB7 The unit reaches the table (0.9.0)</h4><p>Over areas, the unit stated in <strong>Configure\u2026</strong> is the unit of the table it makes. It had been kept in a label only, so Append rows refused a census that stated &quot;people&quot; beside it.</p>`,append_rows:"<h2>Append rows</h2><p><strong>A summary step.</strong> It stacks the rows of two or more tables, one after another, as pandas <code>concat</code> does.</p><h3>What it does</h3><p>Two or more tables become one, with every row of each, in the order of the ports. Columns are lined up by name, or as you line them up under <strong>Columns</strong>. A column some tables lack is empty on their rows, and the run says which column, which table and how many rows, because empty there means the question was not asked.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>records</strong></td><td>the first table, whose rows come first</td></tr><tr><td><strong>records_2</strong></td><td>the second table, whose rows follow</td></tr><tr><td><strong>records_3</strong>, ...</td><td>each further table, added with <strong>\uFF0B Add a table</strong> in Configure\u2026</td></tr></tbody></table><h3>How to use it</h3><p>Connect the tables, then open <strong>Configure\u2026</strong>. The <strong>Preview</strong> shows the stacked table your settings make, and nothing changes until <strong>Apply</strong>.</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Name the source of each row</strong></td><td>Adds a column holding a label for each table's rows</td></tr><tr><td><strong>Column naming the source</strong></td><td>That column's name, <code>source</code> unless you change it</td></tr><tr><td><strong>\uFF0B Add a table</strong> and <strong>Remove the last table</strong></td><td>How many tables it stacks: one port each, two at least</td></tr><tr><td><strong>Label for rows of</strong> each table</td><td>What that column holds on that table's rows</td></tr><tr><td><strong>The labels are numbers</strong>, and <strong>Their unit</strong></td><td>Says the labels are numbers, such as a lag in weeks, so a chart places them as numbers and titles its axis with the unit</td></tr><tr><td><strong>Create a new primary key</strong></td><td>Adds a column numbering every row 1 to N, and makes it the primary key</td></tr></tbody></table><h4>Columns</h4><p>Once the workflow has run, <strong>Columns</strong> shows one row per column of the stacked table, and for each table the column that fills it, or <em>none</em>: that table's rows are then empty there.</p><ul><li><strong>A table's own name for a column.</strong> Choose its column in that table's box, and it is stacked under the row's name.</li></ul><p>DR Congo's census names its provinces <code>province</code>; the population models name theirs <code>name</code>. Stacked as they are, the census rows would have no <code>name</code>. Choose <code>province</code> under <code>name</code> in the census's box.</p><ul><li><strong>Rename a stacked column</strong> in its first box: every table's column in that row takes the new name.</li><li><strong>Start again from what the tables hold</strong> clears every choice made here, back to what is lined up without asking.</li><li><strong>A suggestion</strong> appears where a table lacks a column and one of its own seems to hold the same names: how many of</li></ul><p>its names are in that column of the other tables is shown beside it.</p><ul><li><strong>Lined up without asking</strong> where every one of its names is there: the grid and the run say which column went</li></ul><p>under which, and any of it can be changed. Where only some match, the step asks.</p><p>Below, <strong>Before</strong> shows each table as read, with where each column goes, and <strong>After</strong> the stacked table.</p><p>A table holding the same names as the others under a column of its own stops the step, naming the column to stack it under. The name most of the tables use is the one offered, whatever the order of the inputs: three tables naming their areas <code>name</code> and one naming them <code>province</code> are lined up under <code>name</code>.</p><h4>When the old keys would repeat</h4><p>Each table's own <code>id</code> is unique, but two tables stacked can share an <code>id</code>. Where both declare the same primary key, the stacked table's key is:</p><table><thead><tr><th>Options on</th><th>Primary key</th><th>Also unique</th></tr></thead><tbody><tr><td>Neither</td><td>the old key; any repeat is a Data quality finding</td><td></td></tr><tr><td>Source named</td><td>source with the old key</td><td></td></tr><tr><td>New key</td><td>the new key</td><td></td></tr><tr><td>Source named and new key</td><td>the new key</td><td>source with the old key</td></tr></tbody></table><p>The old key column is always kept.</p><p>The Salmonella example stacks 32 cases, selected from the complete file, on the 81 matched panel controls from the second file, so the two-by-two can compare them.</p><h4>Many tables, one step</h4><p>Five models, one per lag, are five tables. One Append rows stacks them all: add a port for each with <strong>\uFF0B Add a table</strong>, rather than chaining four steps. The Brazil dengue example stacks five Regression tables this way and labels each table's rows with its lag, <code>0</code>, <code>2</code>, <code>4</code>, <code>6</code> and <code>8</code>.</p><p><strong>The labels are numbers</strong> only when you say so. Nothing is read off the labels. A label that is not a number, such as <code>2 weeks</code>, is a data quality finding naming its rows, and the rows are kept. A chart cannot place those on a numeric axis.</p><p>An estimate's interval, declared by Regression, survives the stacking when every table declares it the same way, so <strong>Chart</strong> can draw each estimate with its interval.</p><h3>What it will not do</h3><ul><li>Stack tables whose value columns or units differ. They measure different things, and one column cannot mean both.</li><li>Stack a table whose names are held under another column than the others', until you line it up.</li><li>Use a source column name any table already has, or one label for two tables.</li><li>Check that the two tables were collected the same way. Two surveys with different questions stack without</li></ul><p>complaint if their value column has one name.</p><ul><li>Find a primary key repeated across the tables.</li><li>Read a label as a number unless you say the labels are numbers.</li></ul><h3>History</h3><h4>2026-11-24 \xB7 The years you are stacking are said (0.6.0)</h4><p>Stack a 2025 model under a 2022 census and the step now says so: <em>three years apart</em>. Each table's period is carried on the result, one per source, named the way the source column names each row.</p><p>This is said, not refused \u2014 unlike a unit difference, which is. Counts of people under counts of houses is wrong; 2022 under 2025 is ordinary field epidemiology, and what you need is to be able to see it.</p><p>The <strong>widest</strong> gap is the one reported. Three tables of 1984, 2022 and 2025 are forty-one years apart at their extremes, and calling that &quot;three years apart&quot; would be true of a pair and false of the stack.</p><p>Where no table says anything about its period, the step says nothing \u2014 otherwise the line would appear every time and mean only that nobody had told Fieldwork anything. Where some do and others do not, the silent ones are named.</p><h4>2026-11-23 \xB7 One column under two names (0.5.1)</h4><p>Where the other tables hold the same names in two columns, as Botswana's population models do in <strong>id</strong> and <strong>name</strong>, a table's one column of names now fills both. It was moved under one and lost from the other, so Botswana's census had no <strong>id</strong> and the step stopped, asking for it.</p><h4>2026-11-22 \xB7 Columns whose values match (0.5.0)</h4><p>Configure\u2026 now lists, for each table after the first, its columns whose values match a column of the first table under another name, with how many values they share, ignoring capitals, punctuation and spacing. <strong>Stack under</strong> puts the one under the other's name. The line-up made without asking, where every name matches, is unchanged.</p><h4>2026-11-19 \xB7 Shown on a made-up example (0.3.0)</h4><p><strong>Show me how it works</strong>, in Configure\u2026, steps through two made-up tables stacked, one lacking a column the other has, so its rows are empty there, not zero, and a district appearing once from each; with rows naming their table if you have chosen that. Back, Step and Play; nothing moves where reduced motion is asked for. Its last step is the table this step makes from the same rows. Experiment [223](../experiments/223-a-table-step-shown-on-a-small-example.md).</p><h4>2026-11-19 \xB7 The example's own names (0.3.1)</h4><p>Show me how it works follows the choice to name each row's table and uses the example's own column and labels, not the person's. Found in use on Hagelloch's <em>Each case's infector</em> step.</p><h4>2026-11-20 \xB7 Columns lined up in a grid (0.4.0)</h4><p>Under <strong>Columns</strong>, one row per column of the stacked table, and for each table the column that fills it, or none. A stacked column can be renamed, for every table at once, and a table's own column can be stacked under another's name: DR Congo's census names its provinces in &quot;province&quot;, the population models in &quot;name&quot;. Below it, each table as read, with where each column goes; the stacked table follows. A table holding the others' names under another column is refused, naming the column to stack it under, where it had been stacked with its names in a column of their own and every later step found none; one whose every name matches is lined up without asking, and said. A table whose value column or unit differs is named, with where to change it; &quot;persons&quot; and &quot;people&quot; are one unit.</p>",select_rows:"<h2>Select rows by value</h2><p><strong>A selection.</strong> It keeps the rows whose chosen column holds one of the values you name, in the order you name them, and drops the rest.</p><h3>What it does</h3><p>What a figure should show is often less than what a table carries. After <em>Derive a value</em> computes <code>houses without a death</code>, Snow's Table IX holds three measures \u2014 <code>houses</code>, <code>deaths</code> and <code>houses without a death</code> \u2014 and only the last two belong in a 2\xD72, because <code>houses</code> is the <strong>total the other two partition</strong>. Leaving it in gives the grid a third column and a totals row that counts every house twice.</p><p>Keeping <code>deaths</code> and <code>houses without a death</code> leaves exactly the 2\xD72, and its totals come out as the houses supplied.</p><h3>Seeing what this step did</h3><p>The Inspector says in one sentence what the step keeps, such as <em>Keeps the rows with date from 2023-06-01 to 2023-06-14, both ends included</em>, and after a run, in one line, how many rows it kept and left out, and any value named that the table does not hold.</p><p><strong>View this table</strong> at the top of the Inspector opens the output. <strong>Before</strong> and <strong>After</strong> switch between the table that came in and the one that went out, and After says how many rows and columns there were before.</p><h3>What you connect</h3><p><strong>records</strong> \u2014 a table. It gives back the same table with fewer rows. Key columns, value field and unit are unchanged, because selecting rows does not change what a table measures.</p><h3>How to use it</h3><p><strong>Configure\u2026</strong> in the Inspector opens the step's settings. They show what they keep as you change them: how many rows of how many, and the table. Nothing changes until <strong>Apply</strong>; <strong>Cancel</strong>, <strong>\xD7</strong> or Escape leave the step as it was, and ask first if you changed something.</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Key column to choose by</strong></td><td>Which column the values belong to.</td></tr><tr><td><strong>Keep</strong></td><td><strong>The values I tick</strong>, <strong>Every value except those I tick</strong>, or <strong>A range of dates</strong> (or numbers). The range is offered only when every value in the column is a date, or every one a number.</td></tr><tr><td><strong>Values to keep</strong></td><td>Ticked from the values on offer, or typed one per line. A list of more than 12 can be searched, and <strong>Ticked only</strong> shows what you have kept.</td></tr><tr><td><strong>From</strong> and <strong>To</strong></td><td>The range. Both ends are kept; leave one empty to run from the start or to the end.</td></tr></tbody></table><p><strong>Leaving values out keeps the table's order</strong>, and every row whose value is not one of those ticked. The Brazil sixteen-year workflow leaves out the twelve weeks the file holds twice, with twelve ticks instead of 821. A value ticked that the table does not hold is reported, as when keeping.</p><p><strong>A range keeps the table's order</strong>, and a row with no value in the column is outside every range. For 1 to 14 June 2023 out of ten years of days, that is two fields instead of fourteen ticks. Dates compare as dates written year-month-day; numbers as numbers, so 9 comes before 10. A column of names gets no range, because any order for it would be one the application made up.</p><p><strong>Order matters.</strong> The rows come out in the order you name the values, so a 2\xD72 reads the way you asked for rather than the way the file happened to be written. Unticking a value and ticking it again moves it to the end, which is how you reorder without a second control.</p><h3>What it refuses, and why</h3><p><strong>A value the table does not hold is reported, not ignored.</strong> Asking for a row that is not there is usually a typo, or a table upstream that changed. Quietly returning fewer rows than you asked for is how a figure loses a category nobody noticed.</p><p><strong>Keeping nothing the table holds is refused</strong> in the settings, where <strong>Apply</strong> waits until it is changed, rather than handing back an empty table. So is a range that keeps nothing, which says where the column runs from and to; a range written backwards; and an end that is not a date, or not a number, when the column holds those.</p><h3>What it will not do</h3><p>It will not tell you whether what you kept is a fair selection. Dropping the categories that disagree with you looks exactly like dropping a double-counted total. Decide which you are doing, and say so where a reader can see it.</p><p>It will not add a value that is missing. Naming a value the table does not hold leaves it out and reports it; it does not create an empty category to hold a place in a figure.</p><p>It will not change what the rows mean. The unit, the value field and the key columns are the table's, and they come back as they went in.</p><h3>What this does not establish</h3><p>That a selection is an honest one. Keeping a subset of categories is exactly how a figure misleads, and this widget cannot tell a partition from a cherry-pick: it will drop the rows that disagree with you as readily as the ones that double-count. The evidence records which values were kept and how many rows went, so the choice is at least visible to a reader.</p><h3>History</h3><h4>2026-11-19 \xB7 Shown on a made-up example (0.5.0)</h4><p><strong>Show me how it works</strong>, in Configure\u2026, steps through a made-up table checked row by row under the way of choosing you have picked: values to keep, values to leave out, or a range; a row with an empty cell is set aside by keeping values and kept by leaving one out, as this step does. Back, Step and Play; nothing moves where reduced motion is asked for. Its last step is the table this step makes from the same rows. Experiment [223](../experiments/223-a-table-step-shown-on-a-small-example.md).</p>",snap_to_network:`<h2>Snap to network</h2><p><strong>A process widget.</strong> It moves each of your sites onto the nearest junction of a street network, so that steps which travel along streets have somewhere to start.</p><h3>What it does</h3><p>A route has to begin on the street network. Your sites almost never sit exactly on a junction \u2014 a pump is in a yard, a clinic is set back from the road \u2014 so this widget finds the nearest junction to each one and puts it there.</p><p>It also records <strong>how far each site moved</strong>, which is the number to watch.</p><h3>What you connect</h3><table><thead><tr><th>Connect</th><th>What it needs</th></tr></thead><tbody><tr><td>your sites</td><td>the points to move</td></tr><tr><td>a street network</td><td>from the <strong>Street network</strong> widget</td></tr></tbody></table><p>Out come the same sites, at junctions, each carrying the distance it travelled. Feed them to <strong>Reachable junctions</strong> or a walking-catchment step.</p><h3>How to use it</h3><p>1. <strong>Add it</strong> from the palette, under Catchments. 2. <strong>Connect your sites and a street network.</strong> 3. <strong>Set the snap limit</strong> \u2014 how far a site may be from the network before the result says so. 4. <strong>Run the workflow</strong>, then read the snap distances in the output or the Inspector.</p><h3>Worked examples that use it</h3><table><thead><tr><th>Example</th><th>What it does there</th></tr></thead><tbody><tr><td><strong>John Snow \xB7 walking catchments</strong></td><td>puts the eight pumps onto the Soho street network before travel times are computed</td></tr></tbody></table><h3>What it will not do</h3><ul><li><strong>It will not leave your data where it was.</strong> Every site comes out at a junction. The output</li></ul><p>is derived data, not observations any more, and the furthest any site moved is recorded in the run evidence.</p><ul><li><strong>It will not drop a site that is far from the network.</strong> A site past the snap limit is still</li></ul><p>moved to its nearest junction and is <strong>marked</strong>: its first leg crosses ground no street covers. The widget glows red on the canvas and the Inspector lists each one with its distance. The limit decides whether the result says so, not whether the site is in it.</p><ul><li><strong>It will not tell you the move was acceptable.</strong> If a site travelled 200 m to reach a</li></ul><p>junction, everything measured afterwards starts 200 m from where it should, and that error appears nowhere in the final numbers. Check the snap distance every time.</p><p>When sites are marked, you have three honest options: raise the limit, extend the street network where it stops short, or accept the list and say so in what you publish.</p><h3>Checking it yourself</h3><p>The lab's <a href="https://digital-twin-ph.github.io/validation-lab/lab/index.html?path=19-snap-vs-pyproj.ipynb" target="_blank" rel="noopener noreferrer">snapping notebook</a> checks the junction choice against pyproj and measures each displacement against a five-minute walking budget \u2014 one of the eight example pumps was decided by 0.43 m.</p>`,study_area:`<h2>Study area</h2><p><strong>An input widget.</strong> It defines where your work takes place: one shape, kept on this device, that every later step can be scoped to.</p><h3>What it does</h3><p>A study area holds one piece of geography and makes it available to the rest of the workflow. You can draw it, or take it from a published administrative boundary.</p><p><strong>Drawn.</strong> A bounding box, a polygon you click out, or a circle around a point. Quick, and it is yours \u2014 nothing outside the workflow knows what it means.</p><p>A drawn shape cannot be fetched by anybody else, so the thing worth recording about it is <strong>who drew it</strong>. If a GitHub login is set on the area, the receipt names that person as the author of the geometry and says whether the login was simply entered here or confirmed by GitHub. With no login set, nobody is named: the receipt reports the shape and leaves the author blank rather than assuming it was whoever opened the file. This also applies if you take a published boundary and then move it \u2014 the source is credited for what the shape came from, and you are credited for the shape.</p><p><strong>From a boundary source.</strong> Chosen by country and level from geoBoundaries: ADM1 is usually a province or region, ADM2 a district or city, and what each level means differs by country. The level is checked before anything is downloaded, so you see how many units there are and how detailed they are before committing. You then pick the units you want, and the shape you get is the one the source published, vertex for vertex.</p><p>The shape is stored in longitude, latitude order (CRS84). Applying it writes N3 facts you can read in the <strong>N3 &amp; evidence</strong> tab.</p><h3>What you connect</h3><p>It has no input. Its output is an <code>area</code>, which the map, the buffer, the raster window, the facility search, the point grid, the coverage check and the area measurement all accept.</p><h3>How to use it</h3><p>The step's panel holds its <strong>Name</strong>, one sentence saying what shape it holds, its <strong>Countries</strong> with <strong>Configure countries\u2026</strong> where they were not taken from a boundary, and <strong>Select area on map</strong>, which opens the map where the area is chosen. <strong>Result</strong> says what it holds, what the boundary repair removed, and every extent it has had. Under that, <strong>Manual</strong>, <strong>Evidence</strong> and <strong>Version</strong>.</p><p><strong>Countries, one or more.</strong> A study area can lie in several countries, at a border. In <strong>Configure countries\u2026</strong>, add them from the list, or press <strong>Find the countries</strong>: it proposes the countries the area falls in, each with the share of the area inside it (<em>86% Botswana, 14% South Africa</em>). Tick the ones to keep, press <strong>Use the ticked countries</strong>, then <strong>Apply</strong>. Nothing is kept until you apply it. A share is of the area as drawn, not of the people in it. The proposal comes from Natural Earth's outlines, which are generalised to about 10 km, and the share from each country's national outline from geoBoundaries; a country without a published outline is listed but not measured. Each widget that needs a country reads the list.</p><p>1. Add the node and open it in the Inspector. 2. Press <strong>Select area on map</strong>. Pan to where you are working. 3. Either draw \u2014 <strong>Bounding box</strong>, <strong>Polygon</strong> or <strong>Point and radius</strong> \u2014 or open <strong>Use an administrative boundary</strong>, enter a country, pick a level, press <strong>Check this level</strong>, and choose the units you need. Or open <strong>Use a boundary file you already have</strong>, name the property holding each boundary's name, and choose a GeoJSON file. 4. Press <strong>Apply study area</strong>. 5. Give it a label that says what it is. The label travels into the receipts.</p><p><strong>Its parts.</strong> An area acquired as administrative units keeps each unit as a part, named as its boundary names it. The panel's Result says how many, and <strong>View the parts</strong> lists each part's name and id. A table joined to the area is matched against these names.</p><p><strong>What a level holds.</strong> geoBoundaries numbers its levels ADM1, ADM2 and so on, and the number says nothing of the units: in one country ADM2 holds counties, in another districts. <strong>Check this level</strong> says the level's own name where geoBoundaries states one, and, where Census tables holds the country's census, how many units each census level counts beside this level's. Where no census level, or two together, has as many units, it says so: check what the level holds before relating the census to it.</p><p>Changing the shape later keeps the old one: the Inspector lists every extent you have kept and restores any of them, which records a new extent carrying the old shape rather than overwriting anything.</p><h4>The boundary repair</h4><p>Published boundaries sometimes carry two faults that change no outline, and that this step would otherwise refuse:</p><table><thead><tr><th>Fault</th><th>What is removed</th></tr></thead><tbody><tr><td>A point written twice in a row</td><td>The second copy</td></tr><tr><td>A zero-width spike: the outline goes out along a line and comes straight back along it</td><td>The vertex at the tip</td></tr></tbody></table><p>Neither changes the area any outline encloses. Every other vertex is kept as published. The repair runs on every boundary as it is read, a downloaded level or a file, and the dialog says what it removed, by district for a spike.</p><p><strong>It is recorded, so it can be redone.</strong> The evidence says how many of the published vertices were removed, by this rule, and lists each one by unit, kind and position. OCHA's districts of Sierra Leone are the case it was found on: 84 repeated vertices across 14 districts, and one spike about a metre long in Bonthe.</p><p>A ring that touches itself anywhere else is not repaired, and is still refused, because that is a different shape.</p><h4>Boundaries Fieldwork holds</h4><p>Some levels are held in <a href="https://github.com/digital-twin-ph/boundaries" target="_blank" rel="noopener noreferrer">boundaries</a>: those the worked examples use, among them DR Congo's provinces and territories, Rwanda's districts, Brazil's municipalities and the United States' counties. Choosing one reads it from there, as geoBoundaries published it, checked against what this version names, and keeps it on this device, so choosing it again needs no network. The status line says so. Any other level is asked of geoBoundaries, as is a held one that cannot be read.</p><h4>What its units are called</h4><p>Beside its countries, <strong>Its units are called</strong> says, once, what the area's units are: <em>provinces</em>, <em>districts</em>. Charts and maps read it where their text says {units} or {unit}. Where it is left empty, the boundary's own name for its level is used, if it gives one; geoBoundaries gives <em>Unknown</em> for some, and a file read from disk none. Editing the area on the map keeps it, and the countries.</p><h3>What it will not do</h3><p>It does not simplify a boundary you took from a source. A published polygon is a claim about where a jurisdiction is, and thinning it would quietly change that claim. The boundary repair above removes only what encloses no area, and says so.</p><p>It does not fetch data by itself. It says <em>where</em>; a source widget says <em>what</em>.</p><p>A drawn shape is not a jurisdiction. If your result needs to be about a named place, take the boundary from a source so the receipt can say whose line it is.</p><p>Several selected units stay several shapes. They are not merged into one outline and never become a bounding box around the group.</p><p>It does not refuse units that share a border, or rings that meet at a single point, such as an island touching another at a corner or a hole touching its outline. Both are valid shapes, and Brazil's municipalities have them. It refuses shapes whose interiors overlap, and rings that cross or run along each other.</p><h3>Worked examples that use it</h3><p><strong>Measles in Hagelloch, 1861</strong> uses the village. The four <strong>1854 Cholera Outbreak in London</strong> workflows each use their own Soho extent, which is why three of them differ.</p><h3>History</h3><h4>2026-11-23 \xB7 The country outline, for context (0.13.0)</h4><p>A province acquired on its own was drawn with nothing around it, which makes it hard to place. Picking a level below <strong>ADM0</strong> now offers <strong>Include the country outline, for context</strong>. It is read from the same geoBoundaries release as the units, as the simplified geometry \u2014 DR Congo's outline is 339 KB against 2.4 MB, and a line drawn for context needs no more \u2014 and it carries its own licence, which is not the unit's to inherit.</p><p>It is drawn under everything as a line with no fill, and it can be switched off in the layer list like any other layer. Nothing clips, counts or joins to it: it says where the country is and nothing else. If it cannot be read, the units are unaffected and the dialog says so.</p><h4>2026-11-22 \xB7 A second study area's picker starts empty (0.12.1)</h4><p>Adding a fourth study area, Rwanda, after South Sudan, DR Congo and Uganda, the boundary could not be applied: the dialog, reused for every study area, still showed the last one's country, units and terms, with none of what was behind them, so a unit chosen there answered &quot;Select at least one unit&quot;. Each opening now starts the picker empty.</p><h4>2026-11-19 \xB7 Holes that touch are accepted (0.9.4)</h4><p>Rwanda, chosen by a colleague as a study area, was refused with &quot;Interior rings must not contain one another&quot;. Two holes in an outline can meet, and the check asked whether one hole was inside the other from a single corner that lay on the other's edge, where a point can read as inside. It now asks from a corner that is not on the other hole. A hole inside another hole is still refused.</p><h4>2026-11-20 \xB7 Large boundaries quick to choose; the shape named by its digest (0.10.0)</h4><p>DR Congo's 26 provinces are chosen, applied and reopened in about a second each, where each took 5 to 7 seconds and Chrome called the page unresponsive. Every receipt names the shape by the SHA-256 of its GeoJSON instead of writing out its coordinates, 4.3 MB for those provinces. The dialog's summary counts several polygons. <strong>Its units are called</strong> is new, read by figures as {units}; an edit on the map no longer drops the countries the area states.</p><h4>2026-11-20 \xB7 Boundaries Fieldwork holds (0.11.0)</h4><p>A level held in the boundaries repository, the worked examples' ten, is read from there, pinned and checked by digest, and kept on this device, before geoBoundaries is asked. The study area records where its shapes were read.</p><p><strong>Check this level</strong> says what the level holds: its own name where geoBoundaries states one, and its units beside each level of the country's census in Census tables, saying where none has as many.</p><h4>2026-11-20 \xB7 Its parts, by name (0.12.0)</h4><p>A study area acquired as administrative units says how many parts it holds, and <strong>View the parts</strong> lists each one's name and id: the names a table joined to the area is matched against.</p>`,summarize_combined_area:"<h2>Combined area</h2><p>Takes areas and gives back one area, or takes polygons and gives back one polygons result. It combines whatever kind it is given, and hands back the same kind.</p><h3>What it does</h3><p><strong>Given two study areas</strong> \u2014 say two adjacent provinces \u2014 it carries both outlines through as the parts of one study area. That area can then be given to everything a study area feeds: the street network, the facility sources, the clip, the buffer.</p><p><strong>Given a polygons result</strong> \u2014 catchments, hulls, buffers \u2014 it dissolves the ones that overlap or touch into single polygons and leaves separate ones separate, in a metric projection you choose.</p><h3>What you connect</h3><table><thead><tr><th>port</th><th>what it takes</th></tr></thead><tbody><tr><td><code>polygons</code></td><td>a polygons result, to dissolve</td></tr><tr><td><code>area</code> and <code>area2</code></td><td>two study areas, to combine</td></tr></tbody></table><p>Every port is always there. What the widget <em>yields</em> follows what you wire: connect areas and the output is an area; connect polygons and it is a polygons result. Nothing to set.</p><h3>How to use it</h3><p><strong>To combine two study areas.</strong> Add the widget, then connect one study area to <code>area</code> and the other to <code>area2</code>. The output becomes an area the moment the first one is wired, so it can be given to a Street network, a facility source, a clip or a buffer exactly as a single study area would be. Name it if you want; unnamed, it takes the parts' names joined with a plus.</p><p><strong>To dissolve a polygons result.</strong> Connect it to <code>polygons</code> and set the metric zone and hemisphere for the projection the dissolve is computed in. Overlapping and touching polygons become one; separate ones stay separate, and the count of each is reported.</p><h3>What it assumes</h3><p><strong>That a touching border should not be dissolved when combining areas.</strong> Two provinces that share a border come through as two parts, not one welded outline. A published outline is an authority's record of where a boundary lies; two authorities describe a shared border differently, and welding them would assert a third line that neither drew while still citing both as the source. Every question this application asks of a study area \u2014 is this point inside, what does an extract clip to, what are the bounds \u2014 is answered identically by two parts. What they do not do is pretend the border is gone.</p><p><strong>That dissolving IS right for polygons.</strong> A catchment is this application's own construction, not somebody's record of where a line is, so two that overlap are one reachable region and are merged.</p><p><strong>That the first area's spatial reference is the combination's.</strong> Combining areas held in different projections is a question nobody has asked here yet, and guessing an answer would bury it.</p><h3>What it will not do</h3><ul><li>It will not dissolve areas, for the reason above.</li><li>It will not combine an area with a polygons result. They are different kinds and the output</li></ul><p>would have to be one of them.</p><ul><li>It will not reproject. The metric projection on the polygons path is yours to set; the area path</li></ul><p>carries the first part's reference through unchanged.</p><h3>What the receipt says</h3><p>On the area path: <code>fw:AreaCombination</code> as the activity, <code>prov:used</code> for each part, <code>fw:partCount</code>, and <code>fw:ringCount</code> on the geometry \u2014 so a reader can see the parts were kept rather than merged.</p><h3>Checked against</h3><p>The polygons path is checked against shapely/GEOS in the validation lab (<code>12-combined-area</code>, agrees: combined area 701,662.61 m\xB2 against 701,662.61 m\xB2, zero symmetric difference). <strong>That check covers the polygons path only.</strong> The area path, added 2026-10-22, has no external check yet, and no Dive Deeper lesson \u2014 those are two different repositories and two different questions: the lab recomputes what this widget computed, and a lesson teaches what the method IS.</p>",summarize_hull:`<h2>Observed extent (convex hull)</h2><p><strong>A process widget.</strong> It takes points and gives back one polygon: the smallest convex outline that contains them, with the area it encloses.</p><h3>What it does</h3><p>Stretch an elastic band around all your points and let it go. The shape it settles into is the convex hull \u2014 the outline of where your observations are, with no dents.</p><p>Along with the shape you get two measurements the rest of your workflow can read: the <strong>area</strong> it encloses, in square metres, and its <strong>span</strong>, the distance across its longest axis.</p><h3>What you connect</h3><table><thead><tr><th>Connect</th><th>What it needs</th></tr></thead><tbody><tr><td>a point layer</td><td>at least three points that have locations</td></tr></tbody></table><p>Out comes one polygon. Connect it to a Map to see it, a Table to read its numbers, or a Ruleset to make a judgement about its size.</p><h3>How to use it</h3><p>1. <strong>Add it</strong> from the palette, under Summaries. 2. <strong>Connect a point layer.</strong> Points without a location sit the step out, and the notes say how many took part. 3. <strong>Check the zone, in Configure\u2026.</strong> The widget measures in metres, so it projects your points first, and the UTM zone it uses is part of the answer. The dialog suggests the zone that fits your data and says what the chosen one stretches; Settings says so when they disagree. 4. <strong>Run the workflow</strong>, then read the area on the output or draw the outline on a map.</p><h3>Worked examples that use it</h3><table><thead><tr><th>Example</th><th>What it does there</th></tr></thead><tbody><tr><td><strong>John Snow: how far did it spread?</strong></td><td>outlines the 250 death locations: 0.139 km\xB2, 498 m at its widest</td></tr></tbody></table><h3>What it will not do</h3><ul><li><strong>It will not follow the shape of your data.</strong> A hull is convex, and cases along a river or</li></ul><p>facilities along a coast are not. The outline fills in the space between them, so it claims ground where nothing was observed. If that matters, do not use a hull.</p><ul><li><strong>It is not a boundary.</strong> It is an outline of what was <em>seen</em> \u2014 not a service area, not a</li></ul><p>catchment, not anything anyone agreed to. Where your observation stopped is not where the thing you were observing stopped.</p><ul><li><strong>Three points in a line enclose nothing</strong>, and the widget refuses rather than returning an</li></ul><p>area of zero.</p><ul><li><strong>Watch the span against the area.</strong> A hull much longer than it is wide is close to a line</li></ul><p>and should be read as one. The widget says so in its notes when it happens.</p><h3>Checking it yourself</h3><p>The lab's <a href="https://digital-twin-ph.github.io/validation-lab/lab/index.html?path=10-hull-vs-shapely.ipynb" target="_blank" rel="noopener noreferrer">hull notebook</a> recomputes the outline and the area with Shapely and compares them to this widget's.</p><h3>History</h3><h4>2026-11-23 \xB7 Show me how (0.3.0)</h4><p><strong>Configure\u2026</strong> offers <strong>Show me how it works</strong>: six made-up cases: the band caught on the outermost, the one inside that does not shape it, and the outline the step makes with its area and widest span.</p><h4>2026-11-22 \xB7 On the standard (0.2.0)</h4><p>Moved to the standard Inspector: name, inputs, one sentence, and the area and span of the last run. The UTM zone is in <strong>Configure\u2026</strong>, with the zone the data suggests; Settings says when the two disagree.</p>`,summarize_points_to_polygon:"<h2>Summarize points to polygons</h2><p><strong>A summary.</strong> It takes polygons and points, and gives back the same polygons, each carrying how many of the points fall in it and, where you name one, the total of a number they carry.</p><h3>What it does</h3><p>Each point is tested against each polygon's outline, the same test Keep points inside the area and the map use. Each polygon gets a <strong>count</strong> of the points in it and, with a number chosen, a <strong>total</strong> of that number: 250 death locations and their deaths, counted into eight catchments, is John Snow's.</p><ul><li>A point <strong>on an edge</strong> is counted in every polygon it touches, or in none, as you choose. Where two polygons share an</li></ul><p>edge, counted in both, it is said as counted twice.</p><ul><li>A point <strong>in no polygon</strong> is counted apart, as outside every one.</li><li>A point with <strong>no location</strong> is counted apart.</li><li>A point with <strong>no value</strong>, or one that is not a number, is still counted as a point; its value is counted apart,</li></ul><p>never as 0.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>polygons</strong></td><td>the polygons to count in: catchments, districts, a layer of study areas' parts</td></tr><tr><td><strong>points</strong></td><td>the points to count</td></tr></tbody></table><h3>How to use it</h3><p>1. Connect the polygons and the points. 2. In <strong>Configure\u2026</strong>, choose what happens to a point on an edge, and a number to add up, if any. 3. <strong>Show me how it works</strong> shows both choices on two made-up units sharing an edge. 4. Run. Each polygon carries its count and total; the step's sentence says how many points fell outside every polygon, how many had no location and how many had no value.</p><h3>What it will not do</h3><ul><li>It does not move a point to the nearest polygon. A point outside every polygon is counted as outside.</li><li>It does not divide a count by anything. A rate needs its denominator, from <strong>Rate</strong>.</li><li>It does not measure on a map projection: points and polygons are compared in longitude and latitude.</li></ul><h3>How it was checked</h3><p>The Validation Lab's check 14 recomputes every polygon's count and total with Shapely: exact over 250 locations in 8 polygons, release 0.2.0.</p><h3>History</h3><h4>2026-11-26 \xB7 Map shades the polygons by what was counted (0.7.0)</h4><p>Each polygon carries the total of the chosen field, or the count of points where none is chosen, and Map shades and keys the polygons by it, as <strong>Total</strong> and the field's name, or <strong>Points inside</strong>. Before, Map drew each unit in a colour of its own, keyed by its name. Show me how ends on the same classes, colours and ranges Map draws for its made-up output, and its labels stay inside the drawing, measured once drawn.</p><h4>2026-11-26 \xB7 Show me how ends on the scale (0.6.0)</h4><p>The last step shaded North and South by how dark one green was, and nothing said what a shade meant. Now each unit takes its colour from the same classes Map uses for the totals, and a key below the drawing gives each colour's range. A house the step has set aside is drawn without its label, so the house the step is about can be read.</p><h4>2026-11-22 \xB7 On the standard, with Show me how (0.3.0)</h4><p>Its settings moved into <strong>Configure\u2026</strong>, with the arriving points' numeric columns offered for the total, and <strong>Show me how it works</strong> added. Its Inspector is the standard one: name, inputs, one sentence, and what the last run said.</p>",table_input:`<h2>Tabular data</h2><p><strong>A source.</strong> It reads a CSV, Excel or Stata file into a table.</p><h3>What it does</h3><p>It reads a CSV, Excel (<code>.xlsx</code>) or Stata (<code>.dta</code>) file in wide or long shape and hands a table to the next step. An absent value is kept as unknown, never read as zero.</p><h3>How to use it</h3><p>The Inspector says in one sentence what the step reads: the file, its shape, its value columns and its unit. <strong>Configure\u2026</strong> opens the import.</p><p>1. Choose where the table comes from, in the tabs <strong>Your file</strong>, <strong>From an address</strong>, <strong>Census tables</strong>, <strong>Tide gauges</strong> or <strong>DHIS2</strong>, and say whether it is wide or long. 2. Tick the key columns and choose the value column or columns. 3. Under <strong>What identifies a row?</strong>, mark any primary and secondary keys. 4. <strong>Apply.</strong> Nothing changes until you do; <strong>Cancel</strong> or <strong>\xD7</strong> leaves the step as it was.</p><p>After it, the Inspector's <strong>Result</strong> says how many rows were read and how many values are absent, what Data quality found, and how many columns are described, with <strong>Quick look at the table</strong>, <strong>Data quality</strong> and <strong>Describe columns\u2026</strong>. If it names a Data quality finding, open it before relying on the table.</p><p><strong>Convert the source table on each run</strong>, in the dialog, keeps the file as published and melts it when the workflow runs, so the run's receipt names the columns it took. It can be changed without reading the file again.</p><h3>Excel workbooks</h3><p>A workbook of several sheets offers <strong>Sheet</strong>: choose the one holding the table, and it is set up as a CSV is. The dialog says which sheet it read, and the step keeps it, so a table fetched again reads the same sheet. Cells are read as written: a formula gives its saved result, and formatting is ignored, so a date Excel stores as a number stays that number. An older <code>.xls</code> file needs saving as <code>.xlsx</code> or CSV first.</p><h3>Stata files</h3><p>A Stata file, from Stata 8 onward, is read as Stata wrote it and then set up as a CSV is. Numbers are as stored. A missing value, <code>.</code> or <code>.a</code> to <code>.z</code>, is empty, never zero. A variable Stata formats as a date is read as a date. Value labels are not applied: codes stay as stored, and the import says which variables carry labels.</p><h3>From an address</h3><p>In the tab <strong>From an address</strong>, give the address of a CSV, a Stata file or a zip, and <strong>Fetch</strong>. For a zip, choose the file inside. The table is then set up as any other.</p><p>The project keeps where the table came from, the URL, the file inside and the digests, in place of its rows. An exported project carries no rows, so sharing it does not republish data whose terms do not allow that. On another device the step says its rows are not fetched yet, and <strong>Fetch the table</strong>, under Result, reads the same file again with the same settings. A file whose digest has changed is refused, and nothing is read.</p><p><strong>Downloaded once per device.</strong> What is fetched is kept on the device by its digest. Any table, in any project on the device, that names the same file reads it from there, checked again, instead of downloading it. Typed again in the dialog, a URL reads the copy and says when it was fetched; <strong>Fetch again from the source</strong> checks for a newer file. A source that has not finished after two minutes is stopped and said to be late.</p><h3>Census tables</h3><p>The tab <strong>Census tables</strong> lists the countries in <a href="https://github.com/digital-twin-ph/census-tables" target="_blank" rel="noopener noreferrer">census-tables</a>, counts as each national statistics office published them. For each it says the census, how many rows, the publisher, the terms of use and when the table is next reviewed. A table past its review date says so, and is still offered.</p><p>Choose a country. Its counts are fetched by address, as in <strong>From an address</strong>, and its data dictionary with them, so what each column holds is proposed for you to accept. Both are fetched at the commit this version of Fieldwork names, and each is checked against the digest recorded with it: a file that differs is refused, and nothing is kept.</p><p>Each country is offered in the units today's maps use. Where its census counted other units, the table offered is summed from them and says so: DR Congo's only census, of 1984, counted 9 regions and 44 cities and sub-regions (KIVU, SHABA) that match no map today, so it is offered <strong>Summed to today's 26 provinces (2015)</strong>, with each province's name as geoBoundaries spells it (<code>geoboundaries_name</code>) to relate to a map of today's provinces. Its counts are still 1984's. The line beside it links to the counts as printed, kept in the repository as the source, with how each unit was placed and what the placing does not establish. Rwanda's and Botswana's districts are offered the same way, each with the name geoBoundaries gives it in <code>geoboundaries_name</code>: Rwanda's are the census's own, and 8 of Botswana's are spelled differently.</p><p>Nigeria is offered as two tables, one button each: <strong>Its 37 states, with geoBoundaries' names</strong> and <strong>Its 774 LGAs, with geoBoundaries' names</strong>. The volume prints &quot;JIGAWA STATE&quot; where geoBoundaries writes &quot;Jigawa&quot;, and 31 LGAs are spelled differently in the two; <code>geoboundaries_name</code> gives each unit the map's spelling, and <code>geoboundaries_id</code> its ID. Choose the table at the level of your study area: the states for a map of states, the LGAs for a map of LGAs.</p><p>Sierra Leone is offered the same way, as its 14 districts and its 164 chiefdoms and areas. geoBoundaries cuts chiefdom names at 15 characters, and 41 are spelled differently; Kenema's Koya has no unit of its own there, so its <code>geoboundaries_name</code> is empty.</p><p>Malawi's census counts its four cities apart from their districts, but geoBoundaries draws each city inside a district, so <strong>Its 28 districts with their cities</strong> adds each city to the district it lies in, and <code>with_city</code> names it. Kenya's workbook prints its sub-counties only, and geoBoundaries' level below the counties holds the 290 constituencies, not the 349 sub-counties, so <strong>Its 47 counties, summed</strong> adds each county's sub-counties. Each of the two is also offered <strong>As printed</strong>, in the census's own units.</p><p>Brazil's states and municipalities are offered as printed, in the census's own units, each with the level it is at in <code>level</code>. Their names are the census's spelling: a map's may differ, and Relate says which do not match.</p><p>Where the data dictionary gives some numeric columns a unit, those are proposed as the values and every other column as a key, whether the dictionary is chosen before the table or after it. Sierra Leone's <code>printed_page</code> is written in digits but has no unit: it is the page the row was read from, so it is a key, and men, women and total, in persons, are the values.</p><h3>Tide gauges</h3><p>The tab <strong>Tide gauges</strong> holds the coastal countries in <a href="https://github.com/digital-twin-ph/coastal-sea-level" target="_blank" rel="noopener noreferrer">coastal-sea-level</a>, on a map of every gauge: filled where PSMSL computes a long-term trend, hollow where it holds the record only. The map is drawn here, with no network.</p><p>Choose a country on the map, by its outline or one of its gauges, or from the <strong>Country</strong> list above it. The map closes in on the country, and the line beneath says how many gauges it has, how many with a trend, and its latest year; <strong>The whole map</strong> goes back. Cabo Verde, Mauritius, S\xE3o Tom\xE9 and Pr\xEDncipe and the Seychelles are too small to have an outline at this scale, so their gauges, or the list, choose them.</p><p>Press <strong>Read</strong> for the country. Its index of its gauges is read, one row per station, with the data dictionary every country shares, fetched at the commit this version of Fieldwork names and checked against its digest. Each row gives the station's ID and name at PSMSL, its position, the years its record covers and how complete it is, the trend PSMSL computes where it computes one, its numbers at UHSLC, and how fast the land moves at the nearest GNSS station within 15 km, where one is.</p><p><strong>An index, not the records.</strong> The monthly and annual means are at PSMSL, and the hourly and daily values at UHSLC; neither states terms that allow copying them, so each row links to the station's page, where its record is.</p><p><strong>What a gauge measures.</strong> A tide gauge measures the sea against the land it stands on. Where the land sinks, the gauge shows more rise than the sea's own; where it rises, less. PSMSL's trends carry no correction for it, and PSMSL says they are not for planning or policy. A GNSS station near a gauge is not the gauge: the ground can move at different rates a few kilometres apart. A station on PSMSL's <em>metric</em> list is never to be used for a trend.</p><figure class="manual-figure"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 800" width="1200" height="800" role="img" aria-labelledby="t d" font-family="Helvetica, Arial, sans-serif">
  <title id="t">How terrain heights and sea levels are measured, and how they relate</title>
  <desc id="d">A cross-section of a low coast, not to scale. From the bottom: the WGS84 ellipsoid; the geoid, which EGM2008 and EGM96 model; local mean sea level over 1995 to 2014, the AR6 baseline, which sits above the geoid by an offset measured at a levelled tide gauge; and a projected sea level, the baseline plus the AR6 rise. On land, bare ground is what DeltaDTM and FABDEM model; the surface with roofs and trees is what Copernicus DEM GLO-30 and NASADEM model. At a place on land: h is its height above the ellipsoid; N is the geoid's height above the ellipsoid; H is its height above the geoid, which the terrain models give; so h equals H plus N. Its height above local sea is H minus the offset. This place is above today's sea but below the projected sea level.</desc>
  <defs>
    <marker id="a" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <path d="M0 0 L10 5 L0 10 z" fill="context-stroke"/>
    </marker>
  </defs>
  <rect width="1200" height="800" fill="#ffffff"/>
  <text x="40" y="44" font-size="26" font-weight="700" fill="#111">Heights on a low coast: what each is measured from</text>
  <text x="40" y="72" font-size="16" fill="#333">A cross-section, not to scale: vertical distances are exaggerated so each one can be seen.</text>
  <text x="40" y="94" font-size="16" fill="#333">The four heights at the place on land are drawn side by side; all four are of that one place.</text>

  <!-- Water up to local mean sea level, then land drawn over it -->
  <path d="M40 440 L600 440 L600 640 L40 640 Z" fill="#d6e8f7"/>
  <path d="M40 600 L300 595 C 400 585, 470 470, 560 440 C 640 420, 720 410, 800 404 C 900 395, 1000 340, 1160 300 L1160 650 L40 650 Z" fill="#efe4d2"/>

  <!-- Ellipsoid -->
  <path d="M40 650 L1160 650" stroke="#555" stroke-width="3" stroke-dasharray="14 8" fill="none"/>
  <text x="40" y="678" font-size="17" fill="#333"><tspan font-weight="700">Ellipsoid</tspan> (WGS84): a smooth mathematical surface. Satellite positioning (GNSS) gives heights above it.</text>

  <!-- Geoid -->
  <path d="M40 510 C 300 495, 500 515, 700 500 S 1000 485, 1160 495" stroke="#6a2fa8" stroke-width="3.5" stroke-dasharray="4 6" fill="none"/>
  <text x="60" y="532" font-size="17" fill="#5a2a8c"><tspan font-weight="700">Geoid</tspan> (EGM2008, EGM96):</text>
  <text x="60" y="552" font-size="16" fill="#5a2a8c">where the sea would rest under gravity alone</text>

  <!-- Local mean sea level: solid over the sea, dotted where it runs under the land -->
  <path d="M40 440 L560 440" stroke="#0b5aa6" stroke-width="4" fill="none"/>
  <path d="M560 440 L1160 440" stroke="#0b5aa6" stroke-width="2" stroke-dasharray="2 6" fill="none"/>
  <text x="60" y="466" font-size="17" fill="#0b4a88"><tspan font-weight="700">Local mean sea level</tspan>, 1995\u20132014:</text>
  <text x="60" y="486" font-size="16" fill="#0b4a88">the AR6 baseline</text>

  <!-- Projected sea level -->
  <path d="M40 360 L1160 360" stroke="#0b5aa6" stroke-width="3" stroke-dasharray="16 7" fill="none"/>
  <text x="60" y="350" font-size="17" fill="#0b4a88"><tspan font-weight="700">Projected sea level</tspan>: the baseline + the AR6 rise</text>
  <!-- The rise -->
  <line x1="250" y1="436" x2="250" y2="364" stroke="#0b4a88" stroke-width="2.5" marker-start="url(#a)" marker-end="url(#a)"/>
  <text x="260" y="406" font-size="17" font-weight="700" fill="#0b4a88">AR6 rise</text>

  <!-- Bare ground (DTM) -->
  <path d="M40 600 L300 595 C 400 585, 470 470, 560 440 C 640 420, 720 410, 800 404 C 900 395, 1000 340, 1160 300" stroke="#7b4a12" stroke-width="5" fill="none"/>
  <!-- Surface model (DSM): roofs and trees -->
  <path d="M800 404 C 830 402, 850 400, 870 398 L870 340 L930 340 L930 392 C 950 388, 965 384, 975 380
           C 978 345, 1010 330, 1030 336 C 1048 342, 1054 358, 1056 364 C 1075 356, 1090 350, 1100 346 L1100 296 L1160 296"
        stroke="#3d3d3d" stroke-width="3" stroke-dasharray="9 5" fill="none"/>
  <text x="860" y="250" font-size="17" fill="#3d3d3d"><tspan font-weight="700">Surface model</tspan>: roofs and trees included</text>
  <text x="860" y="272" font-size="16" fill="#3d3d3d">Copernicus DEM GLO-30, NASADEM</text>
  <text x="960" y="560" font-size="17" fill="#6b3d0c"><tspan font-weight="700">Bare ground</tspan></text>
  <text x="960" y="582" font-size="16" fill="#6b3d0c">DeltaDTM, FABDEM</text>

  <!-- Tide gauge, in the water at the shore -->
  <rect x="470" y="380" width="14" height="190" fill="#b0b0b0" stroke="#333" stroke-width="2"/>
  <text x="477" y="300" font-size="16" font-weight="700" fill="#111" text-anchor="middle">Tide gauge</text>
  <text x="477" y="320" font-size="15" fill="#333" text-anchor="middle">levelled, it gives</text>
  <text x="477" y="338" font-size="15" fill="#333" text-anchor="middle">the offset</text>
  <!-- Offset: geoid to local mean sea level, at the gauge -->
  <line x1="440" y1="506" x2="440" y2="444" stroke="#111" stroke-width="2.5" marker-start="url(#a)" marker-end="url(#a)"/>
  <text x="432" y="482" font-size="17" font-weight="700" fill="#111" text-anchor="end">offset</text>

  <!-- A place on land, x = 800: above today's sea, below the projected sea -->
  <line x1="800" y1="200" x2="800" y2="650" stroke="#999" stroke-width="1" stroke-dasharray="3 4"/>
  <text x="800" y="190" font-size="16" fill="#111" text-anchor="middle">a place on land</text>
  <circle cx="800" cy="404" r="6" fill="#7b4a12" stroke="#fff" stroke-width="1.5"/>
  <!-- h: ellipsoid to ground -->
  <line x1="700" y1="646" x2="700" y2="412" stroke="#111" stroke-width="2.5" marker-start="url(#a)" marker-end="url(#a)"/>
  <text x="690" y="580" font-size="22" font-weight="700" fill="#111" text-anchor="end">h</text>
  <!-- N: ellipsoid to geoid -->
  <line x1="740" y1="646" x2="740" y2="504" stroke="#5a2a8c" stroke-width="2.5" marker-start="url(#a)" marker-end="url(#a)"/>
  <text x="732" y="590" font-size="22" font-weight="700" fill="#5a2a8c" text-anchor="end">N</text>
  <!-- H: geoid to ground -->
  <line x1="770" y1="497" x2="770" y2="410" stroke="#6b3d0c" stroke-width="2.5" marker-start="url(#a)" marker-end="url(#a)"/>
  <text x="762" y="470" font-size="22" font-weight="700" fill="#6b3d0c" text-anchor="end">H</text>
  <!-- Height above local sea: local MSL to ground -->
  <line x1="830" y1="436" x2="830" y2="410" stroke="#0b4a88" stroke-width="2.5" marker-start="url(#a)" marker-end="url(#a)"/>
  <text x="840" y="430" font-size="16" fill="#0b4a88"><tspan font-weight="700">above local sea</tspan> = H \u2212 offset</text>

  <!-- Key -->
  <rect x="40" y="700" width="1120" height="84" rx="8" fill="#f4f4f4" stroke="#bbb"/>
  <text x="58" y="728" font-size="17" fill="#111"><tspan font-weight="700">h = H + N.</tspan> The terrain models give <tspan font-weight="700">H</tspan>, a height above the geoid: not above the sea.</text>
  <text x="58" y="752" font-size="17" fill="#111"><tspan font-weight="700">Height above local sea = H \u2212 offset.</tspan> This place is above today's sea and below the projected one.</text>
  <text x="58" y="776" font-size="17" fill="#111">That can be said only when the terrain model's datum <tspan font-weight="700">and</tspan> the offset are both sourced and stated.</text>
</svg><figcaption>How heights on a low coast are measured: local mean sea level sits above the geoid by an offset measured at a levelled tide gauge, and a projected sea level is that baseline plus the rise.</figcaption></figure><p>Cite the archives when using a row: PSMSL (Holgate et al., 2013) and the date of its extraction; UHSLC (Caldwell et al., 2015); SONEL ULR7a (Gravelle et al., 2023), whose velocities are CC BY 4.0. The repository's README gives each citation in full.</p><h3>DHIS2</h3><p>The tab <strong>DHIS2</strong> reads a DHIS2 server's analytics: aggregate values by data element or indicator, period and organisation unit, as a country's DHIS2 holds its routine surveillance.</p><p>1. Type the server's address, and choose its token from <strong>Credentials</strong> (provider <code>dhis2</code>). The token is never typed here and never kept in the project. 2. <strong>Connect.</strong> The tab says which DHIS2 version answered and how many levels of organisation units it has. 3. <strong>Find</strong> data elements and indicators by name, and tick those to read. Choose the level of the units, for example <em>District</em>, and the periods, for example <em>the last 12 months, by month</em>. 4. <strong>Read the table.</strong> It arrives long, one row per data, period and unit, with the names and DHIS2's IDs, its value in <code>value</code>, and a short data dictionary of its columns for you to accept.</p><p>The step keeps where the table came from: the server, the request and when it was read. The units read are the token's own: those its user is assigned to, and the level below them chosen.</p><p><strong>The server must list this page's address</strong> in its CORS allowlist, which its administrator sets; a public demonstration server does not. Without it, export a table from DHIS2's Data Visualizer and read it under <strong>Your file</strong>.</p><p>The step reopens on the tab its table came through. A new step opens on the tab last used on this device.</p><h3>Keys</h3><p><strong>A file with more than 12 columns</strong> lists them in a dialog of its own: Key columns shows how many are ticked and which, and <strong>Choose key columns\u2026</strong> opens the list, with <strong>Columns to keep</strong> (paste or type names, separated by commas, then <strong>Keep these</strong>), <strong>Find a column</strong>, <strong>Untick all</strong> and <strong>Ticked only</strong>. A name the file does not have is said. Read long, such a file starts with nothing ticked; a smaller one ticks every column but the value, and lists them inline. Value columns, for a wide read, work the same way.</p><p>Key columns are read as labels. Among them you decide what identifies a row:</p><table><thead><tr><th>Declaration</th><th>Means</th><th>Checked</th></tr></thead><tbody><tr><td><strong>Primary key</strong></td><td>One column or several together are unique</td><td>Yes</td></tr><tr><td><strong>Secondary key</strong></td><td>Groups or links rows, and may repeat</td><td>No</td></tr><tr><td><strong>Neither</strong></td><td>An answer or category</td><td>No</td></tr></tbody></table><p>With no primary key declared, the check is on all the key columns together.</p><p><strong>List the distinct values of</strong> ticks key columns whose values the table lists, for a step that needs them as a list. <strong>Assign projection site</strong> reads the sites it assigns against from <code>site_id</code> here, so tick it on the projections table. Nothing else changes: the rows are the same.</p><h3>What the columns mean</h3><p><strong>Describe columns\u2026</strong> on the node opens a dialog for every column the table keeps: a <strong>label</strong>, a <strong>unit</strong> and a <strong>description</strong>. The column's name stays as the file spells it; the label is shown beside it, in a regression's terms and a chart's panels. Describing the columns is your step, and a data quality check: a column nobody has described is a finding in Data quality and in the write-up's Methods, never a reason to refuse the table.</p><p><strong>From a data dictionary.</strong> Under <em>Propose from a data dictionary</em>, choose a CSV, Excel workbook or Stata file with one row per variable, or, for a table fetched from a zip, a file in the same archive (read from this device). Say which of its columns holds the variable name, label, description, unit and missing count; a first guess from its headers is filled in. <strong>Propose descriptions</strong> fills the columns it describes, marked <em>not yet accepted</em>, and checks it against the table: which kept columns it does not describe, and whether each missing count it states agrees with the table's. Accept each proposal, or <strong>Accept every proposal</strong>; typing in a field makes the description yours.</p><p>A Stata file's own variable labels are proposed the same way when it is imported.</p><p><strong>Its data dictionary, imported with it.</strong> Configure\u2026 takes a second, optional file beside the table: its data dictionary. The project keeps it, and <strong>View the data dictionary</strong> under Result shows it as it was published. What it says each column means is proposed, not yet accepted. A dictionary chosen later in Describe columns\u2026 is kept the same way; one inside a fetched archive is not, because the project keeps where a fetched source came from, not its contents.</p><p><strong>What kind of values.</strong> Each column can say its values are <em>categories in no order</em>, <em>categories in an order</em>, <em>numbers with no true zero</em> or <em>amounts counted from zero</em>, and list its codes: <code>0 = pre-school; 1 = first class</code>. For categories in an order, the list is the order. A dictionary written in R's words, <em>(factor: 0, preschool; 1, 1st class)</em>, proposes the codes and <strong>no order</strong>, because a factor is R's word for categories with none; whether they have one is yours to say. Data quality then counts a column of categories, in its order, with what each code means, and gives it no median.</p><h3>Data quality</h3><p>A file is not refused for a quality problem. Every row is kept, the step's Result names what Data quality found, and the <strong>Findings</strong> tab of Data quality lists:</p><ul><li>rows repeating a key value</li><li>rows with no value in a key column</li><li>values that are not numbers, kept as unknown and never as zero</li></ul><p>A finding left unresolved goes into the write-up as a machined limitation.</p><p>A file with no rows, too many rows or a missing column is still refused, because there is no table to look at.</p><p><strong>Read as wide, a repeated subject is kept.</strong> When the key columns repeat a subject, the dialog says the file may be long and offers to read it so. Usually it is. But a wide file can repeat a subject because the source has a fault, and the Brazil dengue file has one week twice for every municipality. Read as wide anyway, every row is kept and each repeat is a finding in Data quality.</p><h3>Editing a value by hand</h3><p><strong>Data quality</strong>'s <strong>Records</strong> tab shows the records as the steps after this one read them, a page at a time, each value in a box. Change a value and leave the box: it is kept as an <strong>edit</strong> on this step, with the value it replaced and when, and the run applies it to a copy of the records. The file is not changed. An empty value can be filled the same way; such edits are counted apart, because a supplied value is not a reading. <strong>Edits (n)</strong> lists every edit, newest first, each with <strong>Remove</strong>, which takes it back.</p><p>An edit is applied only where the record still holds the value it was made against. If the data has changed under it, after a new import, the edit is not applied and Data quality says so. The run's record states each edit, before and after (<code>fw:CellEdit</code>). Experiment 214.</p><h3>What it will not do</h3><p>It does not choose between rows that disagree. The table stays as read until a later step changes it.</p><h3>History</h3><h4>2026-11-25 \xB7 A display choice stays a display choice (0.25.0)</h4><p><em>Always show this table wide</em> was writing the field that says a file arrived wide. That field is not a preference: steps read it to rebuild one record per subject, and Apply ruleset then judges rules against those subjects instead of against rows. Keeping the preference quietly changed what was computed.</p><p>It is kept separately now, and only views read it. Two more from the same reading: a key that varies within a record \u2014 a year, say \u2014 is shown as its own column rather than only used to keep two records apart, and the offer to keep a reading still works after filtering the table, which it did not.</p><h4>2026-11-25 \xB7 Quick Look says when the shape is not the table's own (0.24.0)</h4><p>Quick Look has shown long tables wide since October, because a long table is hard to read. But every other view showed the same table as it is stored \u2014 so one table had two shapes a click apart, and nothing said which was which.</p><p>It now says so: <strong>this table is stored long</strong>, here is how it is being shown, and elsewhere it is shown as stored. If the wide reading is the one you want everywhere, <strong>Always show this table wide</strong> keeps it \u2014 and the choice travels with the table, so the steps below it read it the same way.</p><p>The note appears for a table a step computed too, where there is nothing to keep the choice on yet. Those were being widened with no explanation at all.</p><h4>2026-11-24 \xB7 A census brings its date with it (0.22.0)</h4><p>Take a table from Census tables and it now carries the census's reference date \u2014 2022 for Botswana, 2022-08 for Rwanda, 1984-07-01 for DR Congo \u2014 read from the catalogue rather than typed, and marked as <strong>enumerated</strong>: people were counted, not modelled.</p><p>Nothing is guessed. A table from a file states no period unless you say so, and the date is dropped if you choose a different file afterwards, so one source's date can never end up on another's rows.</p><h4>2026-11-23 \xB7 A coordinate is a key, and the count says what it counts (0.19.0)</h4><p>A column named as a <strong>latitude</strong> or a <strong>longitude</strong> is read as a key, beside the rule that an identifier written in digits is one. Proposed as a variable, both were melted into <code>measure</code> and <code>value</code>, so the table carried no coordinates and <strong>Point data</strong> had none to offer. Repetition does not make a poor key: repeats are judged on the whole combination of key columns, and on the African Bat Database carrying the coordinates took the repeated-key findings from 207 to 69.</p><p>The <strong>Result</strong> now says what it counts. A file of 18,409 records read wide was reported as <strong>92,045 rows</strong>, five per record, and that number reached the write-up's prose and the receipt. It reads <em>18,409 records</em>; the receipt asserts <code>fw:tableRecordCount</code> beside the row count, never in place of it.</p><h4>2026-11-23 \xB7 A column with no name, and a file that is not UTF-8 (0.18.0)</h4><p>A CSV whose first column has no name \u2014 what R writes for its row numbers \u2014 was refused whole, saying only that headers must be nonempty and unique. That column is now read as <strong>column_1</strong>, a name an earlier column already has takes <strong>_2</strong>, and each is said on the <strong>Data quality</strong> tab. A file that is not UTF-8 is read as Windows-1252, the encoding Excel on Windows writes, and that too is said: accented place names came through as replacement characters before.</p><h4>2026-11-21 \xB7 Sierra Leone, Malawi and Kenya by level (0.17.0)</h4><p><strong>Census tables</strong> offers Sierra Leone's districts and chiefdoms, Malawi's districts with their cities and Kenya's counties, each with geoBoundaries' names and IDs; Malawi and Kenya also as printed. A data dictionary chosen after its table proposes the values again.</p><h4>2026-11-21 \xB7 A table per level; the dictionary says which columns are counts (0.16.0)</h4><p><strong>Census tables</strong> offers a country's levels as separate tables where its census-tables folder does: Nigeria's 37 states and its 774 LGAs, each with geoBoundaries' name and ID for every unit, where Nigeria was one printed table of all its levels with names like &quot;JIGAWA STATE&quot;. In a wide read, a numeric column the data dictionary gives no unit, such as a printed page number, is proposed as a key rather than a value.</p><h4>2026-11-20 \xB7 Tide gauges chosen on the map; DHIS2 says what is missing (0.15.0)</h4><p><strong>Tide gauges</strong>: a country is chosen on the map, by its outline or one of its gauges, or from a short list, where it was a long list beneath the map. <strong>DHIS2</strong>: an empty or partial server address is named, where it was &quot;Invalid URL&quot;; the tokens are read again on <strong>Connect</strong>, each shown with the address it is for, and a token for another address is named with the address it is for.</p><h4>2026-11-20 \xB7 Tide gauges (0.14.0)</h4><p>The dialog's sources gain <strong>Tide gauges</strong>: the coastal countries in coastal-sea-level, over a map of every gauge, each country's index of its gauges read with the shared data dictionary at a pinned commit, checked by digest. A column named <em>id</em>, or ending in <em>_id</em>, <em>_code</em> or <em>_no</em>, is offered as a key in a wide read, though written in digits.</p><p>A long read can name its value, as a wide read could: DR Congo's census read long gave <em>total</em> beside three models' <em>population</em>. A long read reopens with its value column and keys as saved, where the guess had replaced them. <strong>After</strong> shows the rows as stored, one per key with its value, then the same table as a crosstab. The column a wide read makes for the variables' names is said as made by the read wherever it is offered.</p><p>Census tables gains Brazil (2022), Kenya (2019), Malawi (2018), Nigeria (2006) and Sierra Leone (2015), eight countries in all, each with its terms as found and its checks.</p><p><strong>DHIS2</strong>, a fifth source: a server's analytics read with a token from Credentials, long, with a dictionary of its columns, and the step keeping the server and the request.</p><h4>2026-11-20 \xB7 Census tables in today's units; a step's choices for its own table (0.13.0)</h4><p>DR Congo is offered as its 1984 counts summed to today's 26 provinces, with each province's name as geoBoundaries spells it, so the counts relate to a map of today's provinces; the 1984 units (KIVU, SHABA) match none of them. The counts as printed are linked, not offered.</p><p>A step reopened and given another table starts from that table's defaults. The key and value columns it was saved with had been carried over by name, so a column that had been a key could not be taken as a value. A step keeps its choices for its own table: the same address, or a file chosen again. A refused read no longer shows the last table read beside the refusal.</p><p>A table read from an address reopens read, where it opened empty until fetched again. One value column read wide is advice, not a refusal, so a census's total can be named as the value. The value column is guessed only where it holds numbers. The data dictionary picker is under <strong>Your file</strong> only: a census table brings its own. The second name box reads <em>Name for the column holding variable values</em>. The unit of the value is taken from the data dictionary where it states one for the columns read, and said so; typing one replaces it.</p><h4>2026-11-20 \xB7 Where the table comes from, as tabs; census tables (0.12.0)</h4><p>The dialog's sources are three tabs: <strong>Your file</strong>, <strong>From an address</strong> (until now <strong>Or fetch from a URL</strong>, a section that opened under the file box) and <strong>Census tables</strong>, new. The tab chosen shows only its own controls; what follows, the shape, the keys and the columns, is the same for all three.</p><p><strong>Census tables</strong> reads a country's counts and its data dictionary from the census-tables repository at a pinned commit, checked by digest. Three countries to begin with: Botswana (2022), DR Congo (1984) and Rwanda (2022).</p><p>The heading no longer repeats the widget's name when the step still has it: &quot;Tabular data&quot;, not &quot;Tabular data \xB7 Tabular data&quot;.</p><h4>2026-11-19 \xB7 A large table no longer stalls the dialog (0.11.1)</h4><p>Importing 250,000 rows of points to measure maps, ticking four key columns took over an hour (Chromium, development Mac). Two causes, both found by profiling one tick:</p><ul><li><strong>Rows that repeat a key were grouped by copying the group at every row.</strong> With a key of five values over 250,000</li></ul><p>rows, each group was copied tens of thousands of times. They are now added in place; the groups are the same. A finding names its first ten rows and how many more, not every row.</p><ul><li><strong>The table under the dialog drew every row.</strong> At 25,000 rows that was 325,971 elements on the page, and every</li></ul><p>click searched them. It now shows 200 rows at a time, with Previous and Next, as Results does.</p><p>After: a tick that rebuilds the table takes 0.4 to 0.6 s at 250,000 rows, measured by unticking and ticking a key column. A table of 200 rows or fewer looks as it did.</p>`,table_output:"<h2>Table</h2><h3>What it does</h3><p>Shows what you connect to it, as a table in its own Results tab.</p><p>It takes four different things, and it works out which it is showing from what you wire:</p><ul><li>a <strong>keyed table</strong> from any step that produces one \u2014 Relate a column, Total within groups, a rate,</li></ul><p>a two-by-two, an imported table;</p><ul><li><strong>point data</strong>, with coordinates and attributes: longitude and latitude as recorded, or easting and northing in</li></ul><p>metres in a UTM zone you choose;</p><ul><li><strong>a polygon layer</strong>: catchments, districts, clusters, with what each carries.</li></ul><p>A polygon layer is shown as a plain table, whichever input it arrives at: one row per polygon, its id, its name and its attributes, with what the step that made it says of each (a catchment's locations and totals, a band's minutes, a rule's conclusion, an area). There are no coordinate columns: a table has no geometry, and a polygon's shape stays on the map. Where coordinates for a polygon are wanted, a step that says what it computed has to supply them.</p><h3>What you connect</h3><p>The node shows what is connected to it and one port, <strong>+ Add an input</strong>, as Map does. Drop any result a table can show on it, or choose one under <strong>Inputs \u203A Add an input</strong>, and it is connected to the port its kind belongs to. There is nothing to choose first. Each connected input then shows its kind's symbol and the name of the step it came from.</p><p>Connect a step's output and the table shows it. If you wire more than one, the more specific wins: a keyed table before polygons, and the point path is the general one.</p><h3>How to use it</h3><p>1. Add it, or use <strong>Quick Look</strong> on a step and open its table from there. 2. Drag from the step's output to <strong>+ Add an input</strong>, or choose it under <strong>Inputs \u203A Add an input</strong>. 3. Name the Results tab.</p><p>The step's panel holds its <strong>Name</strong> and where it goes in the write-up, its <strong>Inputs</strong>, one sentence saying what it shows, <strong>Configure\u2026</strong>, and what the last run showed.</p><table><thead><tr><th>In Configure\u2026</th><th>When it is offered</th></tr></thead><tbody><tr><td><strong>Show totals: these values count the same thing</strong></td><td>A keyed table that states no unit. Tick it only where every cell counts the same thing; the figure says you asserted it</td></tr><tr><td><strong>Coordinates</strong>: longitude and latitude, or in metres in a UTM zone</td><td>Point data. The dialog suggests the zone that fits the workflow's coordinates and says how far the chosen one stretches distances. Points read from a UTM file are shown as they are</td></tr></tbody></table><p>Nothing is required. A table with nothing connected is <strong>unfinished</strong>, not broken, and says so.</p><p>A column that holds a number, such as a projection Relate brought beside each row, is always drawn as a column with its own heading, even where every row holds the same number.</p><h4>Presentation</h4><p>Every table follows the rules the table standards agree on: numbers right-aligned under right-aligned headings, in equal-width digits; a rule above, one under the headings and one below, none down the side; totals set off by a rule. In <strong>Configure\u2026</strong>, under <strong>Presentation</strong>:</p><ul><li><strong>Title</strong>: what, where and when, shown above the table. The Table's name when left empty.</li><li><strong>Decimal places for the values</strong>: the same in every row. Names, identifiers and coordinates keep their own.</li><li><strong>Thousands separators</strong> (1,234), never on a column read as years.</li><li><strong>An absent value is written</strong>: a dash, read aloud as &quot;no value&quot;; the word <em>unknown</em>; or left blank.</li><li><strong>Shade every other row</strong>, to follow a row across a wide table.</li><li><strong>Notes</strong> and <strong>Source</strong>, shown below the table.</li></ul><p>The <strong>Preview</strong> shows ten rows, or twenty, or all of them to review, as these settings write them.</p><h4>It states its own shape in the write-up</h4><p>Every run machines a note into <strong>Results</strong> on the Notes tab stating what this table is made of. It names the columns as the table spells them, says how many rows, reports empty cells as unknown rather than zero, and names the source file and digest where the table came in as a file. Not for the point and decision views, which are not published tables.</p><p>Column names are shown as they are, in <code>code</code>, rather than bent into a sentence. A generator cannot tell whether <code>measure</code> or <code>group</code> is a noun, so it states them and leaves the prose to you.</p><p><strong>The caption is yours.</strong> A caption states the subject, the population, the place and the period in your words, and none of that can be read off a table. What this writes is what the table declares about itself \u2014 the material you write the caption from, sitting beside it in the same section.</p><p><strong>And it carries no number.</strong> A figure's number depends on where it sits in the write-up and on the venue you are preparing \u2014 set one figure aside and the ones after it move up \u2014 so the number is worked out when the document is rendered. Nothing here says &quot;Figure 1&quot;.</p><p>Edit it and it forks into a note of your own, like any machined note; the machined one goes on being rewritten by every run.</p><h4>Where it goes in the write-up</h4><p><strong>In the write-up, under</strong>, just below <strong>Results tab name</strong> in the panel, chooses the part of the Notes write-up this output's figure and its note go in: Introduction, Methods, Results or Discussion. <strong>Results</strong> is the default. A map of the study area belongs in the Introduction; a figure that shows how the analysis was done can go in Methods. References is not offered, because it holds works and not figures. The run's receipt states the section and whether you chose it, and a validation rule checks that the note describing the figure is filed in that same section.</p><p><strong>Not in the write-up</strong>, the last choice, keeps the figure in Results and out of Notes and the publication: the run writes no note for it, and its receipt says it was left out. Hagelloch's day-by-day map is left out this way.</p><h3>What it will not do</h3><ul><li><strong>It will not ask you what shape your data is.</strong> There is no mode to set, and connecting</li></ul><p>something never removes a connection you already made. <strong>Map</strong> works the same way.</p><ul><li><strong>It will not chart the table.</strong> Charting one means choosing which key varies and whether to</li></ul><p>aggregate, which is a decision rather than a port. Use <strong>Chart</strong>.</p><ul><li><strong>It will not total anything you have not said can be added.</strong> Margins appear only with <strong>Show totals</strong>. To total</li></ul><p>rows into groups, use <strong>Total within groups</strong>.</p><h3>Where it is used</h3><p>The South London example, five times: the mortality rate table, both water-company tables and both contingency tables.</p><h3>How it was checked</h3><p>Unit tests over the port list, the renderer the connections imply, and the fallback to a stored mode for a workflow saved before the mode was removed. One pins the defect directly: a freshly added table offers a <code>table</code> port with no mode set.</p><p>What no test establishes is whether the four renderers should be one widget at all. The split is inherited and is recorded as open in [experiment 21](../experiments/21-shared-result-outputs.md).</p><h3>History</h3><h4>2026-11-27 \xB7 One blank port; the coverage port removed; a preview in Configure\u2026 (0.15.0)</h4><p><strong>Configure\u2026</strong> shows the table itself: ten rows, or twenty, or all of them to review, with the coordinates as the dialog sets them, before Apply. A polygon table shows its areas from the last run, wide, as Results does.</p><p><strong>Presentation</strong>, a new section of Configure\u2026: a title, decimal places, thousands separators, how an absent value is written, shading every other row, notes and source. Every table now follows the rules the standards agree on, read from the open guidance in [the research note](../research/table-presentation-standards-2026-11-27.md). An absent value is a dash by default, not a word a reader could take for data (2026-10-21). Coordinates show to one precision down their column.</p><p>The node shows each connected input as its kind's symbol and the name of the step it came from, and one blank port, <strong>+ Add an input</strong>, while something on the canvas could add another. The <strong>Or: Coverage result</strong> port is gone: nothing makes a coverage check since Check spatial coverage retired on 2026-10-21, and a workflow saved with one opens with Keep points inside the area feeding the points port instead.</p><h4>2026-11-22 \xB7 Coordinates in metres (0.14.0)</h4><p><strong>Configure\u2026</strong> offers point data's coordinates in metres, as easting and northing in a UTM zone, with the zone the workflow's coordinates suggest. This was the one job of <strong>Reproject points</strong>, which retired into it: nothing computed with its points, and every step that measures projects for itself. The table's receipt states the frame.</p><h4>2026-11-22 \xB7 Moved out of the application's main file (0.13.2)</h4><p>Its Inspector and its Configure\u2026 moved into a module of their own, unchanged. Nothing it does changed. The older <strong>Input mode</strong> choice, from before what is connected decided how a table is shown, is retired: a table of polygons is shown by the standard Inspector as any table is.</p><h4>2026-11-19 \xB7 No 2,000-record ceiling (0.13.0)</h4><p>A table of points refused more than 2,000 records across its point inputs. That ceiling is gone; Point data's own limit, 250,000, is the one that applies. A table of 250,000 points ran in 10 s and was shown in 5.5 s (Chromium, development Mac, <code>tests/measure-point-count.browser.mjs</code>).</p><h4>2026-11-19 \xB7 Long tables shown 200 rows at a time (0.13.1)</h4><p>A table shown as rows by subject, or as a cross-tabulation, drew every row: 25,000 rows were 325,971 elements on the page. It now shows 200 at a time, with Previous and Next; totals still count every row.</p>",study_design:"<h2>Study design</h2><p><strong>A workflow declares HOW as well as WHERE.</strong> <code>study_area</code> says where a study is; nothing said what kind of study it is. This declares the design and the study period, and states which measures that design can actually support.</p><h3>What it does</h3><p>It computes nothing. It declares one of five designs and the period the study covers, and the computations downstream find it by walking upstream from themselves.</p><table><thead><tr><th>Design</th><th>What one row counts</th><th>What a two-by-two may estimate under it</th></tr></thead><tbody><tr><td><strong>cohort</strong></td><td>a person</td><td>risk, risk ratio, risk difference, odds ratio</td></tr><tr><td><strong>case-control</strong></td><td>a person</td><td><strong>the odds ratio only</strong></td></tr><tr><td><strong>cross-sectional</strong></td><td>a person</td><td>prevalence, prevalence ratio, prevalence odds ratio</td></tr><tr><td><strong>ecological</strong></td><td><strong>a group</strong></td><td>the same measures, as group-level quantities</td></tr><tr><td><strong>case-series</strong></td><td>a person</td><td>counts and intervals \u2014 no comparison group, so no ratio</td></tr></tbody></table><p>Five, not the twenty-two of the reference survey. Each is one this application can actually serve with the widgets it has; a sixth that licensed no computation would be a declaration doing no work.</p><h3>Why case-control is the one that matters</h3><p>In a cohort you sample people and follow them, so the row totals <code>a+b</code> and <code>c+d</code> are populations at risk and <code>a/(a+b)</code> is a risk.</p><p><strong>In a case-control study you choose how many cases and how many controls to sample.</strong> The row totals are then artefacts of that choice \u2014 sample twice as many controls and <code>a+b</code> doubles while nothing about the disease changes. So <code>a/(a+b)</code> is not a risk, and the risk ratio and risk difference built from it are not estimable at all. The odds ratio survives because the cross-product <code>ad/bc</code> does not depend on how many of each group were sampled.</p><p>Without a declared design, a case-control table is offered all three. The arithmetic is right and two of the three answers mean nothing.</p><p><strong>What the odds ratio then means depends on how the controls were sampled</strong> \u2014 and this widget does not ask. Under incidence-density (risk-set) sampling an odds ratio estimates an incidence rate ratio without needing the outcome to be rare; under cumulative sampling it does not. So declaring <code>case-control</code> is enough to rule the risk measures out, and not enough to say which ratio the surviving one is. Record how you sampled controls in the note field until there is a field for it.</p><p><strong>Cross-sectional is the quieter failure.</strong> There the arithmetic keeps its value and loses its name: <code>a/(a+b)</code> is a prevalence, not a risk, and a prevalence ratio printed as <code>Risk Ratio (RR)</code> is correct to three decimals and wrong about what it measures. Nothing looks amiss, which is why it is the worse of the two.</p><p><strong>Ecological is the inference, not the arithmetic.</strong> The rows count groups. South London's <code>contingency</code> workflow attaches a water company to each of 32 sub-districts, so every measure over it is a statement about sub-districts \u2014 and a relation between group-level measures need not hold between individuals.</p><h3>The study period</h3><p>Declared here because it belongs to the <strong>study</strong>, not to a computation. <code>rate</code> carries a <code>numeratorPeriod</code> and a <code>denominatorVintage</code>, and <code>case_series</code> carries a period, all of which are properties of one calculation \u2014 which is backwards for a title, whose time element is the period of the study.</p><p>Written as it should read: <code>1854</code>, or <code>July\u2013September 1854</code>.</p><h3>How a computation finds it</h3><p>By walking <strong>upstream</strong> from itself. A design wired by an edge wins outright, because an edge is an explicit statement; otherwise the walk looks back through the graph.</p><p>Three consequences worth knowing:</p><ul><li><strong>Upstream only.</strong> A design declared downstream of a computation did not govern it, and a design</li></ul><p>on a parallel branch governs that branch and not this one.</p><ul><li><strong>Two different designs are refused, never resolved.</strong> Which study you are running is not a tie</li></ul><p>this application may break. Two nodes <em>agreeing</em> on one design is fine \u2014 what cannot be resolved is two answers to one question.</p><ul><li><strong><code>relate_table</code>, <code>group_table</code>, <code>derive_value</code> and <code>select_rows</code> carry nothing.</strong> The walk</li></ul><p>passes through them, so a declaration does not have to be threaded along a chain.</p><h3>How to use it</h3><p>1. <strong>Add it before the computations it governs.</strong> It takes no input, so it sits at the start of a branch the way a study area does. 2. <strong>Press Configure\u2026, and choose the design and its measures.</strong> The dialog shows what each design licenses before you choose it. What it cannot estimate has no box; untick anything it can estimate that the write-up should not carry. 3. <strong>Write the study period</strong>, on the dialog's first page, as it should read in a title: <code>1854</code>. 4. <strong>Say what one row counts</strong>, on the same page, if it is not a person. An ecological study counts groups \u2014 sub-districts, wards, districts \u2014 and this is where that is said once instead of in every caption. 5. <strong>Connect it, or leave it upstream.</strong> Wiring it to an epi widget's <code>design</code> port states which declaration governs that computation. Where there is no edge, anything downstream of it finds it by walking back through the graph.</p><p>If you are not sure which design you have, leave it out. Everything computes as it did before, and a guessed declaration is worse than none.</p><h3>What is asked after you select a design</h3><p><strong>Surveillance is not on the list.</strong> It says where data came from, and a study of any design can use such data. It is an answer to the source question below. A workflow that only describes surveillance counts declares no design.</p><p>For a cohort or an ecological study, the first page after the design is <strong>the table</strong>: you name the groups and the outcome and say what exposure is known for. The dialog draws the 2\xD72 in those words and marks the totals the study fixed. Select a cell to say what it counts and where it comes from, or that it was worked out from other cells. There are no numbers on this page: they come with the data, so it works for a study not yet begun. The other designs do not have this page yet.</p><p>The dialog runs one page at a time with <strong>Next</strong> and <strong>Back</strong>. Your answers are kept as a draft until <strong>Apply</strong>, which writes them all to the step; <strong>Cancel</strong>, \xD7 or Escape leave the step as it was, and ask first when something was answered. Selecting a design sets its questions. Where the table already says where each cell comes from, the first asks only whether any of it comes from a surveillance system. A blank for the group is filled from the table page, and you can change it. For a case-control study that means how cases arose, when controls were sampled, whether they were matched, and where they came from. Each answer writes a sentence into <strong>Methods</strong>, and some carry a caveat. Answer <em>not sure / not stated</em> when that is the truth: nothing stops, and the note says what is unknown. A blank you leave stays visible in the sentence as <code>\u2039blank\u203A</code>.</p><p>Answers stay stored if you change design, so trying another one loses nothing. Three questions come with every design: who or what decided who was exposed, how time is structured, and whether the outcome can spread or cluster. If exposure was decided outside the investigators, two more follow: what supports that claim, and whether to call this a natural experiment. That term has more than one definition, so the note always names which one it means, and it never licenses causal language. The wording of these questions is untested.</p><h3>The checklist</h3><p>The last page of the dialog reads your workflow against your design, and the Inspector gives the counts.</p><p><strong>Read from this workflow</strong> is checked against the canvas and changes as you build: whether a two-by-two reads the design, whether data are connected, whether each input says where it came from, whether the result reaches an output. It says the workflow holds these things, not that they are right.</p><p><strong>Declared by you</strong> is what you stated. Fieldwork records it and cannot check it.</p><p>The checklist reports and does not grade. Nothing on it stops a run. <em>Open</em> means no answer yet, and <em>stated as unknown</em> means you answered that you do not know, which is a different fact. <em>Differs</em> means your words and the computation's do not match: they may still be one group, and that is for you to judge.</p><h3>What it will not do</h3><ul><li><strong>It will not work out your design from your data.</strong> Four counts look identical whether they</li></ul><p>came from a cohort, a case-control study or a survey. Only you know which you ran.</p><ul><li><strong>It will not choose between two declarations.</strong> A computation has one design port, and it</li></ul><p>takes one connection. Connect each design to its own computation: a workflow may hold two, on separate branches.</p><ul><li><strong>It will not declare a study whose investigators allocated exposure.</strong> The five designs are</li></ul><p>observational, so answering that investigators allocated exposure stops the declaration, and computations run under neutral names.</p><ul><li><strong>It will not check that your period is consistent with your data.</strong> The period is text for a</li></ul><p>reader and a title. Whether a denominator covers the numerator's period is not checked.</p><ul><li><strong>It will not travel to another workflow.</strong> A design governs the workflow it is in. A project of</li></ul><p>six workflows may have six different designs, or none.</p><h3>What it does not do yet</h3><p><strong>It governs the two-by-two only.</strong> A connected design decides what <code>two_by_two</code> reports: case-control keeps the odds ratio and drops the word risk, cross-sectional reports prevalence measures, and a case series reports no comparison measure. <code>rate_ratio</code> carries the design and is not changed by it.</p><p><strong>An undeclared design is reported, not punished.</strong> With no design connected, every measure is still computed, under a name for its arithmetic: ratio of row proportions, cross-product ratio, difference of row proportions. A line says no design is connected. The numbers are the same as before; only the names differ, because <code>a/(a+b)</code> is a risk only under some designs. A practitioner with their own data may not be sure which design they have, and an application that refused to compute until told would be worse than one that stays quiet.</p><p><strong>It does not make a result correct.</strong> It makes a wrong measure refusable. Whether the groups are comparable, and whether a denominator's period covers its numerator's, are untouched \u2014 and the period check <code>rate</code> performs today is string equality where the condition is coverage.</p><p>See [experiment 154](../experiments/154-a-workflow-declares-how-as-well-as-where.md) for the admission review, and [the study-design audit](../audits/study-designs-and-our-computations.md) for how the designs were chosen.</p><h3>History</h3><h4>2026-11-22 \xB7 Answers kept until Apply (0.8.0)</h4><p>The dialog wrote each answer to the step as it was made, with Close and no Save. It is now the standard dialog: the answers are a draft until Apply, and Cancel, \xD7 or Escape ask before discarding them. The checklist on the last page reads the draft, so it shows what has just been answered.</p><h4>2026-11-22 \xB7 On the standard Inspector (0.7.0)</h4><p>The Inspector became the standard one: name, inputs, one sentence of the design, what it reports, its period and its unit, then <strong>Configure\u2026</strong>, and the checklist under Result. The period, the unit of analysis and the note moved from the Inspector into the dialog's first page, beside the design.</p><h3>More than one exposure</h3><p>Most investigations of a shared meal compare a whole menu. <strong>How were the exposures chosen?</strong> records whether they were named in advance or all compared as a screen. A screen raises a question and needs other evidence to answer it. With several exposures, describe the table's groups in general, such as <em>ate</em> and <em>did not eat</em>, because the same description applies to each. The checklist then says how many were compared, and does not compare each with the declared groups.</p>",two_by_two:"<h2>Two-by-two table</h2><p><strong>The analysis under the table.</strong> It takes four counts \u2014 two groups by two outcomes \u2014 and reports the risk in each group, the risk ratio, the odds ratio and the risk difference, each naming the method that produced it. Read as <strong>events and units at risk</strong> instead, it reports the rate ratio.</p><h3>What it does</h3><p>A two-by-two is the central table of field epidemiology, and this application could draw one for months before it could analyse one: it showed the four counts and their margins and stopped there.</p><p>On Snow's South London people, built inside the application from two of his tables:</p><table><thead><tr><th></th><th>died</th><th>survived</th><th></th></tr></thead><tbody><tr><td><strong>Southwark and Vauxhall only</strong></td><td>844</td><td>166,810</td><td>167,654</td></tr><tr><td><strong>Lambeth only</strong></td><td>18</td><td>19,115</td><td>19,133</td></tr></tbody></table><table><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td>Risk, exposed</td><td>5.03 per 1,000</td><td></td></tr><tr><td>Risk, unexposed</td><td>0.94 per 1,000</td><td></td></tr><tr><td><strong>Risk ratio</strong></td><td><strong>5.35</strong></td><td>3.36 to 8.53 \xB7 Katz log</td></tr><tr><td><strong>Odds ratio</strong></td><td><strong>5.37</strong></td><td>3.37 to 8.57 \xB7 Wald log</td></tr><tr><td><strong>Risk difference</strong></td><td><strong>4.09 per 1,000</strong></td><td>Wald unpooled</td></tr></tbody></table><h3>Why this exists, and the number to be careful about</h3><p>The same project carries a <strong>rate ratio of 8.40</strong> on Snow's houses. The risk ratio here, on his people, is <strong>5.35</strong>. Both are correct and they are 57% apart.</p><p>It is tempting to say that is because one is a rate ratio and the other a risk ratio. <strong>It is not.</strong> A risk ratio over the same houses is <strong>8.401853429780243</strong> \u2014 the rate ratio's value exactly, bit for bit. Deaths per house <em>is</em> a risk when a house can hold at most one death, so the two are the same division. Only the intervals differ, and only in the second decimal: <strong>6.84 to 10.32</strong> from the rate ratio against <strong>6.85 to 10.31</strong> here.</p><p>So what moves the number from 8.40 to 5.35 is the <strong>subject being counted</strong>: a house, or a person. And that is the one thing the familiar layout does not show. A reader who takes 8.40 for the risk ratio beside the houses table is right \u2014 and is thereby taught that the substitution is always safe, which it is not. Make the outcome common instead of rare and the two part company.</p><p>This widget supplies the estimate. <strong>Reading the denominator is still yours.</strong></p><p><strong>The names above assume a declared cohort.</strong> Connect a <em>Study design</em> and it decides what is reported. With none connected, every measure is still computed, named by its arithmetic:</p><table><thead><tr><th>With a cohort declared</th><th>With no design connected</th></tr></thead><tbody><tr><td>Risk ratio</td><td>Ratio of row proportions</td></tr><tr><td>Odds ratio</td><td>Cross-product ratio</td></tr><tr><td>Risk difference</td><td>Difference of row proportions</td></tr></tbody></table><p>The numbers do not change. A line under the estimates says no design is connected, and the receipt records it, because <em>&quot;risk ratio&quot;</em> over an undeclared table claims a design nobody chose.</p><h3>What you connect</h3><p><strong>records</strong> \u2014 a table holding <strong>one row per combination</strong> of the exposure and the outcome. Total it first with <em>Total within groups</em>: a cell matching more than one row is refused rather than added up here, because summing silently is how a two-by-two acquires subjects nobody counted.</p><p><strong>Or a line list.</strong> Tick <strong>Each row is one subject</strong> and connect it directly: a cell is how many rows agree. The tick is yours to make, because a table does not say which it is, and the two disagree about an empty cell. In a table of totals a missing row means nobody counted it, and it is refused. In a line list everybody is present, so a combination nobody fell into is a true zero.</p><p>This cannot tell whether a person appears on two rows.</p><p><strong>Several exposures.</strong> With a line list, tick more than one under <strong>Exposures to compare</strong>, and the result is one table with a row per exposure: the counts, the risk in each group, the ratio and its interval, and how many rows are <strong>left out</strong>, in neither group, whether nobody recorded the answer or the mapping did not name it. Oswego's 14 foods take one node. Under a declared case-control design the table shows the four cells and the odds ratio, and no attack rate, because the study fixed the columns. Choose a control group by choosing the non-case value; the others are named as left out.</p><p>Each cell's column says what it holds beside its letter: <strong>a: exposed cases</strong>, <strong>b: exposed controls</strong>, <strong>c: unexposed cases</strong>, <strong>d: unexposed controls</strong> under a case-control design, and <em>non-cases</em> in place of <em>controls</em> otherwise. The letters are the ones the equations in Notes use, and stay the columns' names. An exposure that cannot be read keeps the table's layout, its cells empty, so every row lines up.</p><p>The rows stay in the order you ticked them. Nothing is ranked or highlighted: seeing which exposure stands apart is the reading. The result says how many comparisons were made and that <strong>no interval is adjusted for that number</strong>. Exposures also overlap, so one food's association can belong to another, and this table cannot separate them.</p><p><strong>Which columns are offered.</strong> The widget does not know which columns are exposures: you tick them. It leaves out the outcome, any column with more than 12 distinct values, and any column with a different value on every row, so a numbered <code>ID</code> is not offered. Once Exposed and Unexposed are chosen, a column must hold both, whether they are <code>Y</code> and <code>N</code> or <code>1</code> and <code>0</code>. A column coded differently from those two is not offered, so recode it first.</p><p><strong>Events and units at risk: the rate ratio.</strong> Under <strong>The outcome column holds</strong>, choose <strong>events and units at risk</strong>, then name the value holding the events and the one holding the units at risk. Each group then needs two rows, not two outcomes: Snow's Table IX gives deaths and houses per company.</p><table><thead><tr><th></th><th>deaths</th><th>houses</th><th>rate</th></tr></thead><tbody><tr><td><strong>Southwark and Vauxhall Company</strong></td><td>$a_1$ = 1,263</td><td>$n_1$ = 40,046</td><td>0.031539</td></tr><tr><td><strong>Lambeth Company</strong></td><td>$a_0$ = 98</td><td>$n_0$ = 26,107</td><td>0.0037538</td></tr></tbody></table><p><strong>Rate ratio 8.40</strong>, 6.84 to 10.32, log-normal. A unit at risk is not a non-case: a house can hold more than one death, and person-time counts nobody, so this layout has no $b$ and $d$ and no risk ratio. Units at risk may be person-time and need not be whole numbers; events must be. A group with no events keeps its counts and says why there is no ratio. The interval treats events as independent, which a transmitted disease is not, so it is narrower than clustered events warrant.</p><p>A declared study design decides whether a rate ratio may be reported: a <strong>cohort</strong> or an <strong>ecological</strong> study, the same designs that license one from a Poisson regression. Under any other design the step stops and says why. With no design connected the rate ratio keeps its name, because events over units at risk is a rate under any design.</p><p>This replaced the <strong>Rate ratio with an interval</strong> widget on 2026-11-05. That widget read only a Rate step's result; this reads the table. The numbers are the same to the last digit.</p><p><strong>What it writes into the notes.</strong> A Methods note gives the four cells, each formula the declared design reports, the numbers substituted and the interval method, and cites the method. With several exposures on one node the formulas are written once, in symbols. The numbers are in the step's table, which a Table output connected to it draws in the write-up with a note of its own.</p><h3>How to use it</h3><p>Connect a table, then open <strong>Configure\u2026</strong>. The <strong>Preview</strong> shows the four cells your settings make, each with its letter and count, or what is wrong with it: no row with that combination, several rows, or an empty value. Nothing changes until <strong>Apply</strong>.</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Each row is one subject</strong></td><td>a line list: each cell is how many rows agree, and several exposures can be compared</td></tr><tr><td><strong>Exposures to compare</strong></td><td>with a line list, the columns ticked, each its own two-by-two</td></tr><tr><td><strong>Exposure column</strong></td><td>the column holding the groups</td></tr><tr><td><strong>Exposed</strong> / <strong>Unexposed</strong></td><td>which two of its values are being compared</td></tr><tr><td><strong>Outcome column</strong></td><td>the column holding the outcome</td></tr><tr><td><strong>The outcome column holds</strong></td><td>cases and non-cases, or events and units at risk</td></tr><tr><td><strong>Case</strong> / <strong>Non-case</strong></td><td>which value is the case</td></tr><tr><td><strong>Events</strong> / <strong>Units at risk</strong></td><td>in the rate layout, which value holds each</td></tr><tr><td><strong>Interval level</strong></td><td>90%, 95% or 99%</td></tr></tbody></table><h4>Why you name the two groups</h4><p>Because a table may hold more than two. Snow's people-denominated table has <strong>three</strong> supply categories: 16 of his 32 sub-districts were supplied by <em>both</em> companies. That stratum is not an exposure group, and it is the reason Snow's sub-district comparison could not settle the question and he went to the house level.</p><p>Whatever you leave out is <strong>named on the result</strong>, and the totals are of the two groups you chose rather than of the table. A stratum silently excluded is the commonest way a two-by-two misleads.</p><h3>Reading what you get</h3><p>The four cells as a table, with the estimates carried on it, and a receipt holding each estimate's value, bounds, level and <strong>method by name</strong>.</p><p><strong>Each estimate also carries the label the familiar layout prints for the same quantity</strong>, so you can find the row you were trained to look for:</p><table><thead><tr><th>this widget computes</th><th>printed as</th></tr></thead><tbody><tr><td>risk ratio \xB7 Katz log</td><td><code>Risk Ratio (RR)</code></td></tr><tr><td>odds ratio \xB7 Wald log</td><td><code>Odds Ratio (cross product)</code></td></tr><tr><td>risk difference \xB7 Wald unpooled</td><td><code>Risk Difference (RD%)</code></td></tr></tbody></table><p><strong>Read from an earlier engine's results panel, not from a classic analysis package.</strong> That is a sibling project whose epi kernel was synthesized from the original, so these are a good deduction and not a verification \u2014 and every estimate records which, in <code>conventionalLabelSource</code>. The receipt says <code>deduced</code>. If somebody reads the labels off a classic analysis package itself the source becomes <code>verified</code>, and the words may or may not change; that is a different claim and the field keeps the two apart.</p><p><code>Odds Ratio (cross product)</code> keeps its qualifier on purpose: the same panel prints an <code>Odds Ratio (conditional MLE)</code> beside it, which is a different estimator and is <strong>not</strong> computed here. Dropping the qualifier would make this label claim both.</p><p><strong>One scale difference, stated rather than reconciled.</strong> That panel prints the risk difference as a <em>percentage</em>. Snow's figure is <code>0.004093</code> here and <code>0.4093%</code> there \u2014 the same quantity on a different scale, and the estimate says so where the number is, so nobody reads the two screens side by side and concludes the implementations disagree.</p><h4>The equation, as a note for your Methods section</h4><p>Every run machines a note into <strong>Methods</strong> on the Notes tab, writing the four cells as <code>a</code>, <code>b</code>, <code>c</code> and <code>d</code> \u2014 the letters every textbook formula is in, and the ones an FETP trainee is taught \u2014 and then each measure twice: once as the formula, once with this run's numbers substituted.</p><p>$$\\mathrm{RR} = \\frac{a/(a+b)}{c/(c+d)} \\qquad \\mathrm{OR} = \\frac{ad}{bc}$$</p><p><strong>Why both forms.</strong> A formula on its own restates a textbook. The same formula with your numbers in it lets a reader check the arithmetic without rerunning anything, which is the thing a Methods section is for.</p><p><strong>Each interval method is cited, or it says no source has been read for it.</strong> A citation here is read off a source or it is absent; none is written from memory, because a plausible-looking reference is the kind of error a reader stops checking at.</p><table><thead><tr><th>method</th><th>source</th></tr></thead><tbody><tr><td>risk ratio \xB7 Katz log</td><td>Katz D, Baptista J, Azen SP, Pike MC. Obtaining confidence intervals for the risk ratio in cohort studies. Biometrics. 1978;34(3):469-474. doi:10.2307/2530610</td></tr><tr><td>odds ratio \xB7 Wald log</td><td>Woolf B. On estimating the relation between blood group and disease. Annals of Human Genetics. 1955;19(4):251-253. doi:10.1111/j.1469-1809.1955.tb01348.x</td></tr><tr><td>risk difference \xB7 Wald unpooled</td><td><strong>None read.</strong> The construction is standard and the implementations consulted state it without attributing it.</td></tr></tbody></table><p>The note is editable like any machined note: editing it forks it into a note of your own, and the machined one goes on being rewritten by every run.</p><h3>What it will not do</h3><ul><li><strong>It will not claim agreement with another package.</strong> These are standard methods, named honestly, with</li></ul><p>labels deduced from a project built from a classic analysis package. A parity claim needs a parity suite nobody has written.</p><ul><li><strong>It will not treat an empty cell as a zero.</strong> An empty cell is unknown, and a two-by-two</li></ul><p>computed as though it were zero would understate that group.</p><ul><li><strong>It will not add half a case to make a ratio computable.</strong> A group with no cases has no risk</li></ul><p>ratio, and this says so. The usual repair is an assumption, not a measurement.</p><ul><li><strong>It will not withhold the estimates it can still compute.</strong> A zero cell removes the odds ratio</li></ul><p>and leaves the risk difference perfectly well defined, so each estimate reports its own availability and its own reason.</p><ul><li><strong>It will not accept a table of rates or percentages.</strong> These estimates count subjects. A</li></ul><p>non-whole number is refused, except as units at risk in the rate layout, which may be person-time.</p><ul><li><strong>It will not adjust for anything.</strong> This is a contrast between two groups as they were supplied.</li></ul><p>The stratum you left out is excluded, not controlled for, and no estimate here is an effect.</p><ul><li><strong>It will not test a hypothesis.</strong> Chi-square, Mantel-Haenszel, Yates, Fisher exact and mid-P are</li></ul><p>not built. They are a larger piece and were not started to meet a date.</p><ul><li><strong>It will not check that the equation it prints is the one the source paper states.</strong> The</li></ul><p>formulas in the note were read off this widget's own code, so they state what it computes. That the code matches Katz and Woolf is a different question, and the computations audit that would answer it is not written.</p><h3>Where it is used</h3><p>The South London example: <em>Were deaths more common with one water supply than the other?</em>, and, in the rate layout, <em>How many died per house supplied by each water company?</em></p><p>The MERS-CoV example: <em>Death by sex, a two-by-two</em>.</p><h3>History</h3><h4>2026-11-19 \xB7 What to do is the application's, not the draft's (0.8.2)</h4><p>With no study design connected, the table says its measures are named by their arithmetic, in the application and in a draft. What to do about it, connecting a study design, is said in the application only. Found by the target outputs audit ([audit](../audits/target-outputs-audit.md)).</p>",voronoi:`<h2>Voronoi catchments</h2><p><strong>A spatial operation.</strong> It takes a study area and a set of sites, and gives back one polygon per site: the part of the area closer to that site than to any other, in a straight line.</p><h3>What it does</h3><p>Every place in the study area goes to its nearest site. The lines between catchments fall halfway between two sites, at right angles to the line joining them. John Snow's eight pumps, divided this way, give each pump the streets nearest to it.</p><p>It measures in metres, in the UTM zone you choose, so &quot;nearest&quot; is a true ground distance and not a difference of degrees.</p><h3>When it is the right question</h3><p>A straight-line catchment is a <strong>baseline</strong>: who would use a site if everyone went to the nearest one and could walk straight to it. It is quick, it needs nothing but the sites, and it is easy to explain. Compare it with a travel-time catchment from <strong>Network isochrone</strong>: where the two differ, roads, rivers and slopes are deciding who reaches what.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>area</strong></td><td>the study area to divide</td></tr><tr><td><strong>sites</strong></td><td>the sites: pumps, clinics, schools, up to 100</td></tr></tbody></table><p>Out come polygons, one per site. Count cases into them with <strong>Summarize points to polygons</strong>, and draw them on a Map.</p><h3>How to use it</h3><p>1. Connect the study area and the sites. 2. In <strong>Configure\u2026</strong>, check the UTM zone. The dialog says which zone this workflow's coordinates suggest, and how far the chosen one stretches distances here. Settings says so too when the two disagree. 3. Run. The Result says how many catchments were drawn.</p><h3>What it will not do</h3><ul><li><strong>It does not know about travel.</strong> Roads, rivers, hills, fees and opening hours are ignored. People often do not use</li></ul><p>the nearest site, and a catchment says who is nearest, not who goes.</p><ul><li><strong>It does not follow the study area's outline.</strong> The catchments fill a rectangle 100 m beyond the area's bounds;</li></ul><p>connect <strong>Clip polygons</strong> to cut them to the outline.</p><ul><li><strong>It does not take two sites at the same place.</strong> Merge them first; the run says which.</li><li><strong>It does not divide a large area.</strong> The area must be under 50 km across.</li></ul><h3>How it was checked</h3><p>The lab's <a href="https://digital-twin-ph.github.io/validation-lab/lab/index.html?path=15-voronoi-vs-shapely.ipynb" target="_blank" rel="noopener noreferrer">Voronoi notebook</a> rebuilds the catchments with Shapely and compares them to this widget's.</p><h3>History</h3><h4>2026-11-26 \xB7 Catchments in one fill (0.6.0)</h4><p>The last step shaded the catchments from light to dark, as if one were more than another. They carry no value, so they are now one fill, told apart by the lines between them.</p><h4>2026-11-25 \xB7 Show me how builds the division up (0.5.0)</h4><p>It used to follow one house to its nearest pump, and then show every dividing line and every finished cell at once \u2014 so the part worth watching happened between two steps.</p><p>Now you see two pumps and the single line between them: everywhere on one side is nearer one pump, everywhere on the other side the other, and the line is where they are equally near. Then the third pump joins, each pair gets its line, and the lines meet at the corner where three catchments touch.</p><h4>2026-11-23 \xB7 Show me how (0.3.0)</h4><p><strong>Configure\u2026</strong> offers <strong>Show me how it works</strong>: three made-up pumps in a study area: a house going to the nearest, the lines where two are equally near, and the cells the step makes, which fill the box around the area.</p><h4>2026-11-22 \xB7 On the standard (0.2.0)</h4><p>Moved to the standard Inspector: name, inputs, one sentence of what it allocates, the UTM zone in <strong>Configure\u2026</strong> with the zone the data suggests, and the number of catchments drawn.</p>`,regression:"<h2>Regression</h2><p><strong>A model.</strong> Logistic regression for a case-control or cross-sectional study, reporting odds ratios; Poisson regression for counts over time or area, reporting rate ratios. Each estimate is adjusted for the variables you add.</p><h3>What it does</h3><p>The two-by-two gives crude measures. A published study usually reports adjusted ones: the Salmonella outbreak's Galia melon odds ratio adjusted for age group and sex, NYC's ozone rate ratio adjusted for the other pollutants, temperature, holidays and time. This fits those models in Fieldwork's own kernel, by iteratively reweighted least squares, and builds the model's columns as R does, so the same model here and in R has the same columns and the same estimates.</p><h3>What you connect</h3><p><strong>records</strong> \u2014 a table. The outcome and every variable are its columns: its key columns and its value column alike. <strong>design</strong> \u2014 optional, the study design. A declared design decides what the result may be called, and which model it allows.</p><p>It gives back a table: one row per reported term, with the ratio, the interval limits and p (with several exposure columns, one row per model and term; see below). The table says which statistic is the ratio and which are its limits, so <strong>Chart</strong> draws each ratio with its interval without guessing from the names.</p><h3>How to use it</h3><p>The step's panel holds its <strong>Name</strong>, its input, one sentence saying what model it will fit, and <strong>Configure\u2026</strong>, where these are set and applied with <strong>Apply</strong>. After a run, the panel says the main estimate and how many rows were used and left out.</p><table><thead><tr><th>Setting</th><th>What it decides</th></tr></thead><tbody><tr><td><strong>Model</strong></td><td>Logistic (odds ratios) or Poisson (rate ratios)</td></tr><tr><td><strong>Outcome</strong></td><td>The column modelled. For logistic, tick which of its values are <strong>cases</strong> and which <strong>controls</strong>; rows with other values are left out</td></tr><tr><td><strong>Exposure</strong></td><td>The column whose ratio you want, as <strong>numeric</strong> (a ratio per unit), <strong>categorical</strong> (a ratio per value against a <strong>reference value</strong>) or a <strong>spline</strong></td></tr><tr><td><strong>Add a variable</strong></td><td>Each adjustment variable, one at a time, as numeric, categorical or <strong>Spline, 4 df</strong> (R's <code>bs(x, df = 4)</code>, for a curved relation such as temperature)</td></tr><tr><td><strong>Strata</strong> (Poisson)</td><td>Fixed effects for each value of a column, or for each combination of several: choose a column, then <strong>Together with</strong> for each further one. Municipality, year and month together compare each week only with weeks of the same municipality, month and year. Absorbed, so thousands of strata cost little</td></tr><tr><td><strong>Offset</strong> (Poisson)</td><td>A column holding the log of person-time or population</td></tr><tr><td><strong>Intervals</strong></td><td><strong>Likelihood-ratio</strong> (the default; R's <code>confint()</code>), <strong>Wald</strong>, Wald <strong>scaled for overdispersion</strong>, or Wald with <strong>HAC</strong> standard errors for counts that are correlated from day to day, with the number of lags and the column giving the rows' order</td></tr></tbody></table><p><strong>A row missing any variable the model uses is left out</strong>, as R does by default, and the result says how many and why.</p><h4>One model per exposure column</h4><p>Under <strong>Exposure</strong>, <strong>Also fit, one model each, with</strong> lists the table's other columns. Tick one or more, and the step fits one model per column: the same model each time, with only the exposure swapped. This is for a lag-response question, where <strong>Relate a column from another table</strong> has brought the temperature at several shifts, one column each.</p><ul><li><strong>Each model is fitted on its own rows.</strong> A week with no value at one shift is left out of that shift's model only.</li></ul><p>Fitting every model on the weeks that have a value at every shift would be a different analysis, and is not done.</p><ul><li><strong>The models come out as one table</strong>, one row per model, term and statistic. Its columns are <strong>exposure</strong> (the</li></ul><p>column the model is for), <strong>shift_days</strong> (the shift Relate recorded, as a number of days; only when there is one), <strong>role</strong> (<em>exposure</em> or <em>adjusted for</em>), <strong>term</strong> and <strong>statistic</strong>. To chart one point per lag, keep the rows whose role is <em>exposure</em> with <strong>Select rows by value</strong>, and choose <strong>shift_days</strong> as the chart's category column.</p><ul><li><strong>A column that cannot be fitted is a row saying so</strong>, with empty values, and the result says why. The step stops</li></ul><p>only when no column can be fitted.</p><ul><li><strong>The result says how many intervals there are</strong>, and that none is adjusted for the number of comparisons.</li></ul><p><strong>An adjusted variable can follow the shift.</strong> With several models, each adjusted variable has a box, <em>follows the shift: each model is adjusted for its own column</em>. Tick it, and a column is chosen for each model, filled in Relate's order and each one changeable. The 2010\u20132025 Brazil workflow uses it: the model of the temperature 2 weeks before is adjusted for the rainfall 2 weeks before, from a second Relate that brings the rain at the same lags. The result says <em>each adjusted for precip_total_semana at its own shift</em>.</p><p>Untick every column to go back to one model.</p><h3>What it will not do</h3><p><strong>It will not choose the variables.</strong> It fits what it is given; deciding what to adjust for is the investigator's.</p><p><strong>It will not report a model that did not converge</strong>, or one whose columns carry the same information twice (collinear). It says which.</p><p><strong>A declared study design decides the measure</strong>, read from the same declaration the Two-by-two table reads:</p><table><thead><tr><th>Design</th><th>Logistic</th><th>Poisson</th></tr></thead><tbody><tr><td>cohort</td><td>odds ratio</td><td>rate ratio</td></tr><tr><td>case-control</td><td>odds ratio</td><td>stops: case-control sampling fixes the number of cases, so there is no population for a rate</td></tr><tr><td>cross-sectional</td><td>prevalence odds ratio</td><td>stops: each subject is measured once, so there is no follow-up time</td></tr><tr><td>ecological</td><td>odds ratio, of groups</td><td>rate ratio, of groups</td></tr><tr><td>case series</td><td>stops: no comparison group</td><td>stops</td></tr></tbody></table><p>With no design connected the measure keeps its plain name, odds ratio or rate ratio, and the receipt says no design was declared. The NYC study, a time series of daily counts, is none of these five and is run without one. Experiment 176.</p><p><strong>In the N3 &amp; evidence view</strong> the fit is a <code>fw:RegressionModel</code>: the family, the outcome, the exposure and each adjustment with how it entered the model, strata, an offset, how the intervals were made, and the rows used. Each coefficient is an <code>fw:EpiEstimate</code> naming its term, interval method and level, and two SHACL shapes check that it says so.</p><p><strong>It does not do</strong> model selection, interaction terms, random effects, conditional logistic regression for individually matched studies, or exact methods.</p><h3>Checked against published results</h3><table><thead><tr><th>Example</th><th>Published</th><th>Fieldwork</th></tr></thead><tbody><tr><td>NYC, ozone per 10 ppb, Poisson with 840 strata, a temperature spline and HAC errors (14 lags)</td><td>1.061 (1.035\u20131.088)</td><td>1.0609 (1.0348\u20131.0877); coefficient and HAC standard error equal to the authors' archived R result to 12 significant figures</td></tr><tr><td>Brazil, two municipalities 2010\u20132025, cases on weekly air temperature and rainfall, strata of municipality \xD7 year \xD7 month, overdispersed</td><td>statsmodels, one indicator per stratum (Validation Lab check 37)</td><td>The same 1,613 rows and 364 strata; coefficients and Pearson-scaled standard errors equal to the digits printed, in CPython and Pyodide</td></tr><tr><td>Salmonella, Galia melon in April against classical controls, adjusted for age group and sex, likelihood-ratio interval</td><td>96 (15\u20132100)</td><td>96.4 (15.4\u20132067)</td></tr><tr><td>The same, against panel controls</td><td>18 (4.6\u2013100)</td><td>18.4 (4.6\u2013101)</td></tr></tbody></table><p>Experiment 167.</p><h3>What this does not establish</h3><p>That a model is well specified. A ratio adjusted for the wrong variables is precise and wrong, and nothing in the fit can tell.</p><h3>History</h3><h4>2026-11-26 \xB7 Each model\u2019s own sample, and one reading of a cell (0.9.0)</h4><p>With several exposure columns this step fits one model for each, and every model leaves out only the rows its own variables are missing on. The Preview reported the first column's sample as though it were all of them.</p><p>It now reports each. And the case count reads a cell the way the fit does: a value padded with spaces was being admitted as a case by one part of the Preview and counted as a non-case by another.</p><h4>2026-11-25 \xB7 The Preview counts the rows the fit will use (0.8.0)</h4><p>It counted rows that had something in every column the model names. The fit asks for more than that: an outcome has to be a case or a control, a category written NA is not a category, and a number has to be a number. The Preview was promising a larger sample than the run would use.</p><p>Both now ask the same question of a row, and the Preview says why the others are left out, in the same words the run uses.</p><h4>2026-11-25 \xB7 The Preview counts the rows the model would be fitted on (0.7.0)</h4><p>The Preview read the plan back and never said whether a model could be fitted at all. That turns on how many rows carry every column the plan names, how the outcome divides, and whether a level of the exposure is left with too few rows to estimate on.</p><p>Those are counted now, from the table connected, without fitting anything: a fit is iterative and belongs in the run, while completeness is a single pass over the rows and is the part to act on while the settings are still in view.</p>",find_satellite_products:`<h2>Find satellite products</h2><p><strong>Which satellites and products measure a variable, and what each one measures.</strong> It chooses where satellite data will come from. It downloads nothing.</p><h3>What it does</h3><p>Type a research topic or a measurement, such as <em>NO2 air pollution in New York City</em>, or pick a topic. The dialog shows the chain from the question to a provider's collection, a caution about what a satellite measures, and one card per product:</p><table><thead><tr><th>On each card</th><th>Why it is there</th></tr></thead><tbody><tr><td><strong>Sign-in</strong></td><td>No sign-in, no account (an anonymous token), or needs an account. Products needing none come first</td></tr><tr><td><strong>Measures</strong></td><td>A column through the atmosphere, an optical depth, an index, or a near-surface value</td></tr><tr><td><strong>Unit</strong></td><td>As read from the product's own file, or &quot;read from the file when it is opened&quot;</td></tr><tr><td><strong>Licence</strong></td><td>As read from the licence itself, with the date it was read; or &quot;not yet read&quot;</td></tr><tr><td><strong>Citation</strong></td><td>The dataset citation the producer asks for, with its DOI, the files it covers and the date it was read; or &quot;not yet read&quot;</td></tr><tr><td><strong>In a browser</strong></td><td>Whether a browser has been shown to read it, and how that was checked</td></tr><tr><td><strong>Quality</strong></td><td>The product's own quality rule, where it has been read</td></tr></tbody></table><p>Choose a product and the Inspector summarises it. Its output is a satellite product, which only a catalog search can take.</p><h3>How to use it</h3><p>1. Add <strong>Find satellite products</strong> from Sources. It needs no input. 2. In the Inspector, press <strong>Configure\u2026</strong>. 3. Type a topic or a measurement, or press a topic. Read the caution, then the cards: open products are first. 4. Press <strong>Choose this product</strong> on the one you want, then <strong>Done</strong>. The Inspector says your choice in one sentence, with its card under Result. 5. Run the workflow: the run records which product was chosen and what was and was not read about it, in the N3 &amp; evidence view.</p><h3>Why it matters which quantity a product measures</h3><p>A ground monitor measures air at the surface. A satellite NO\u2082 product measures the NO\u2082 in a column of air from the ground to the top of the troposphere; an aerosol optical depth measures how much the whole column dims light; most ozone products measure the whole atmosphere, mostly the stratosphere. They can move together with the monitors over time. They do not agree in value, and a card never lets them look as if they should.</p><h3>Why the licence is read, not taken from the catalog</h3><p>Planetary Computer gives Sentinel-5P's licence as <em>proprietary</em> and links an address that no longer exists. The licence itself, read at its new address, grants free, full and open access with attribution. So a card states the licence as read, where and when, and says when nobody has read it.</p><h3>Where the products come from</h3><p>The topics and most routes are JLT's, from the <a href="https://github.com/jltobias/JupyterLite-EO-Satellite-Guide" target="_blank" rel="noopener noreferrer">EO Satellite Guide</a> (MIT), vendored unchanged at commit <code>684833c</code>. Fieldwork adds the routes that need no sign-in, an ozone topic, and the facts on each card, read in [experiment 179](../experiments/179-eo-and-stac-for-the-nyc-monitors.md).</p><h3>What it will not do</h3><ul><li><strong>It will not download anything</strong>, or say that a product has data for your place and dates. That is the catalog</li></ul><p>search's question.</p><ul><li><strong>It will not cite a product nobody has read a citation for.</strong> The three Sentinel-5P products on Planetary Computer</li></ul><p>carry ESA's citations, read from the TROPOMI product pages on 2026-11-06. ESA gives one DOI per processor version, and these are Version 02, for the processor 2.x files Planetary Computer serves for June 2023. Every other card says &quot;not yet read&quot;.</p><ul><li><strong>It will not choose for you.</strong> The order puts open products first; which one suits a study is yours to decide.</li><li><strong>It covers what has been curated.</strong> A topic with no curated product says so rather than guessing one.</li></ul><h3>Where it is used</h3><p>The NYC example, <em>Did the satellite see the city's NO\u2082?</em> (1 to 14 June 2023).</p><h3>History</h3><h4>2026-11-22 \xB7 On the standard Inspector (0.4.0)</h4><p>It had its own label field and a <strong>Find satellite products\u2026</strong> button. It now has the standard Inspector: its name, one sentence saying the product chosen, <strong>Configure\u2026</strong>, which opens the same chooser, and the product's card under Result. Its code moved out of the application's main file.</p>`,search_satellite_catalog:`<h2>Search a satellite catalog</h2><p>_Created 2026-11-05 \xB7 Updated 2026-11-05 (0.2.0)_</p><p><strong>Where the files are</strong>, for the satellite product you chose, over an area and dates. It reads catalog records only. No data file is downloaded.</p><h3>What it does</h3><p>It takes the product chosen in <strong>Find satellite products</strong> and an area, and searches that product's STAC collection for the items covering the area's extent between two dates. The area is a connected <strong>Study area</strong>'s extent or, with none connected, four edges you type in the dialog: west, south, east and north, in decimal degrees. Each item is a satellite overpass with one or more files.</p><table><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>01 \xB7 Connect &amp; discover</strong></td><td>The catalog, collection and product, from the chosen product; the study area's extent, or the four edges to type; the dates; <strong>Search</strong></td></tr><tr><td><strong>02 \xB7 Coverage, in context</strong></td><td>The area searched and each item's footprint, and the list of items, each kept or dropped</td></tr><tr><td><strong>03 \xB7 Inspect &amp; reuse</strong></td><td>The selected item's files, with sign-in, the licence as read, whether a browser can read it, and the attribution sentence to use, and the dataset citation with its DOI where it has been read</td></tr></tbody></table><h3>How to use it</h3><p>1. Add <strong>Find satellite products</strong> and choose a product. 2. Add <strong>Search a satellite catalog</strong>, and connect the product to <strong>product</strong>. If the workflow has a <strong>Study area</strong>, connect it to <strong>area</strong> and its extent is searched. 3. In the Inspector, press <strong>Search the catalog\u2026</strong>. With no Study area connected, type <strong>West</strong>, <strong>South</strong>, <strong>East</strong> and <strong>North</strong>; the dialog says what is wrong with an edge until all four make an extent. Choose <strong>From</strong> and <strong>Until</strong>, and press <strong>Search</strong>. 4. Select an item, on the map or in the list, to inspect its files. Untick any item you do not want to keep. 5. Press <strong>Done</strong>, then run the workflow. The run records the search and how many items were returned, matched and kept.</p><h3>What a search can and cannot tell you</h3><p>A search tells you <strong>whether there was an overpass</strong>: which dates have an item over your area. It cannot tell you whether that overpass holds a usable value over your area. Clouds remove retrievals, and a product's quality flags mark others as unreliable. On 7 June 2023, the one Sentinel-5P NO\u2082 overpass of New York City came as two items, and the near-real-time one measured had no pixel passing the usual quality threshold. So every item says its completeness is not known until a reader opens the file, and the run records that it was not read. <strong>Sample satellite files at points</strong> is the reader.</p><h3>One overpass can be two items</h3><p>A Sentinel-5P orbit is published in more than one processing stream: <strong>near real time</strong> (<code>NRTI</code>, within hours, in five-minute pieces) and <strong>offline</strong> (<code>OFFL</code>, days later, the whole orbit, with better inputs). Each is an item, so one overpass can appear twice. Each item says its stream and orbit. Where an orbit has an offline item, its near-real-time items are not kept by default, so a reading is never counted twice; the product recommends the offline stream for time series. Tick one back if you need it.</p><h3>What it will not do</h3><ul><li><strong>It will not download a file.</strong> Reading the pixels at your points is a separate step, not yet built.</li><li><strong>It does not stop at a number of items.</strong> Sixteen years of MODIS over Rio de Janeiro state is 2,891 items, read in</li></ul><p>29 pages in about 19 s. Up to 0.40.0 it stopped at 500, the bound of the STAC Browser it was adapted from.</p><ul><li><strong>It keeps only the files a reader reads.</strong> A MODIS item lists 15 files and the reader uses 6, so the other 9 are</li></ul><p>not stored; the search says which were kept and how many each item offered. A product with no reader keeps them all.</p><ul><li><strong>It will not search all time.</strong> It needs dates.</li><li><strong>It will not search across the antimeridian or by the outline of the area</strong>: the area's extent is searched, so</li></ul><p>items over nearby water or another country can appear. West must be less than east; split an area across the antimeridian into two searches.</p><ul><li><strong>It will not cite a product nobody has read a citation for.</strong> It shows the citation Find satellite products</li></ul><p>carries, and says &quot;not yet read&quot; otherwise.</p><h3>Where it comes from</h3><p>The search, its messages, its 500-item bound and the typed W/S/E/N extent are adapted from JLT's <a href="https://github.com/jltobias/JupyterLite-STAC-Browser" target="_blank" rel="noopener noreferrer">STAC Browser</a> (MIT, commit <code>945d8b3</code>), in Fieldwork's dialog style. [Experiment 179](../experiments/179-eo-and-stac-for-the-nyc-monitors.md) records why each file says what it says.</p><h3>Where it is used</h3><p>The NYC example, <em>Did the satellite see the city's NO\u2082?</em> (1 to 14 June 2023).</p><h3>History</h3><h4>2026-11-19 \xB7 A month at a time, and the standard Inspector (0.5.0)</h4><p>Planetary Computer answered the first page of a year of MODIS over Rio de Janeiro state in a second, and the second page with a timeout after 15 seconds and no cross-origin header, so a browser could say only that it could not reach the catalog. A search longer than a month is now made a month at a time, each month fitting one page: the year's 180 items in 12 requests and about five seconds. An item spanning two months is kept once. A request that fails is tried twice more, after a pause; one the catalog refuses is not.</p><p>Moved to the standard Inspector (experiment 186): Name, Inputs, one sentence and Configure\u2026, which opens the search, and what was found. Its code moved out of <code>app.ts</code> into its own module, as every touched widget's now does.</p>`,transmission_chains:"<h2>Transmission chains</h2><p><strong>Each case its chain.</strong> It takes a table of cases, each naming its recorded source, follows the sources back to the case each chain starts with, and hands on every row with four more columns.</p><h3>What it does</h3><table><thead><tr><th>Column</th><th>What it holds</th></tr></thead><tbody><tr><td><code>chain</code></td><td>the id of the case the chain starts with</td></tr><tr><td><code>generation</code></td><td>0 for that case, 1 for the cases it is the source of, and so on</td></tr><tr><td><code>offspring</code></td><td>how many cases name this one as their source</td></tr><tr><td><code>chain_size</code></td><td>how many cases are in its chain</td></tr></tbody></table><p>MERS, 2015: the 162 cases with their recorded sources make 67 chains. One starts with SK_1 and holds 94 cases over 4 generations; one starts with SK_76 and holds 3; 65 cases have no source recorded and are chains of one. Split an epidemic curve by <code>generation</code> and it shows the waves inside SK_1's chain; total by <code>chain</code> and it lists the chains by size.</p><h3>What you connect</h3><p>A table on <strong>Cases, each with its recorded source</strong>: one row per case, or several rows for a case with several recorded sources. The step after it can be anything that reads a table: <strong>Case series</strong> split by <code>generation</code> or <code>chain</code>, <strong>Total within groups</strong>, <strong>Relate a column</strong>, a <strong>Table</strong> or a <strong>Chart</strong>.</p><h3>How to use it</h3><ul><li><strong>Each case is named in</strong>: the case id column.</li><li><strong>Its recorded source is in</strong>: the column naming each case's source, by the same ids.</li><li><strong>Written for &quot;no source recorded&quot;</strong>: a value such as <code>none recorded</code>, where the table writes one. An empty cell</li></ul><p>always means no source.</p><ul><li><strong>Order each case's children by</strong>: a date, optional; it only orders the cases under each source.</li></ul><p>The preview shows what the last run's table makes with these settings.</p><h3>What it will not do</h3><ul><li><strong>It will not drop a case.</strong> A case naming no source, naming a source the table does not hold, or caught in a loop</li></ul><p>of sources starts a chain of its own, and the step's sentence counts each. A row with no case id is handed on without a chain, and counted.</p><ul><li><strong>It will not choose between sources.</strong> A case recording more than one source is placed under the first, and the</li></ul><p>sentence says how many did.</p><ul><li><strong>It will not overwrite a column.</strong> A table already holding a column named <code>chain</code>, <code>generation</code>, <code>offspring</code> or</li></ul><p><code>chain_size</code> is refused; rename it upstream.</p><ul><li><strong>It does not establish who infected whom.</strong> It follows the links the record holds. A recorded link is not a proven</li></ul><p>infection, and the step's note in Methods says so.</p><p>Chart's <strong>Who infected whom</strong> tree is drawn by the same computation, so the tree and these columns agree.</p><h3>History</h3><h4>2026-11-22 \xB7 Out of the application's main file (0.1.1)</h4><p>Its Inspector and its dialog moved into a module of their own. Nothing it does changed.</p>",detect_unusual_counts:"<h2>Detect unusual counts</h2><p><strong>An epidemiology widget.</strong> It reads a table of counts per period, such as Cases by period gives, and flags each period whose count passes a threshold set from the series' own past. A signal says a count passed a threshold set for few false alarms; whether it is an outbreak is for the person who looks at the cases behind it.</p><h3>What it does</h3><p>For each period it takes a baseline from the same series' past, either the periods just before it or the first periods of the series, and sets a threshold from the baseline's mean and spread. A period whose count passes the threshold signals. CUSUM adds up small excesses so that a modest rise that persists signals; EWMA smooths the series so that a slow shift signals; the EARS methods react to a sudden rise within days.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>records</strong></td><td>a table of counts: one row per period, or per period and series</td></tr></tbody></table><p>Its output is a table: for each period (and series), six rows under a <code>measure</code> column: <strong>observed</strong>, <strong>expected</strong>, <strong>threshold</strong> (in counts), <strong>statistic</strong> and <strong>limit</strong> (on the method's own scale), and <strong>signal</strong> (1 where the period signals, 0 where it does not, empty before there is a baseline). A Chart draws it; a Table lists it; Select rows keeps the signals.</p><h3>How to use it</h3><p>In <strong>Configure\u2026</strong>:</p><p>1. <strong>Column holding each period</strong>: dates, weeks or numbers; periods are put in order. 2. <strong>A series for each</strong> (optional): a column such as syndrome or district, each value its own series. 3. <strong>Method</strong>, and its settings. <strong>After</strong> draws the counts as bars, the threshold as a dashed line and the periods that signal as dark bars, and lists every period, before anything is applied.</p><table><thead><tr><th>Method</th><th>Compares each period with</th><th>Settings</th></tr></thead><tbody><tr><td><strong>EARS C1</strong></td><td>the mean of the 7 periods before it</td><td>baseline, \u03B1 (0.001), least standard deviation</td></tr><tr><td><strong>EARS C2</strong></td><td>the 7 periods ending 3 before it, so a rise does not lift its own threshold</td><td>as C1</td></tr><tr><td><strong>EARS C3</strong></td><td>C2's excess over the period and the 2 before it, added</td><td>as C1, \u03B1 0.025</td></tr><tr><td><strong>CUSUM</strong></td><td>the mean of the first periods; each period's excess over it is added up</td><td>baseline periods (7), slack k (1.04), signal at h (2.26), start again after a signal</td></tr><tr><td><strong>EWMA</strong></td><td>the mean and spread of the first periods; a weighted average leaning on recent periods</td><td>baseline periods (7), \u03BB (0.3), L (3)</td></tr></tbody></table><p>Beneath it, <strong>the method's own computation</strong>: its statistic over time as a solid line, its decision limit dashed, and a triangle on each day that signals. For CUSUM the line is the running sum against h; for EWMA the smoothed level against a limit that widens from narrow; for the EARS methods the day's count in standard deviations against z(1\u2212\u03B1).</p><p><strong>Show me how it works</strong> walks the chosen method through ten made-up days.</p><h3>What it will not do</h3><ul><li><strong>It will not say a signal is an outbreak.</strong> \u03B1, h and L are decisions about how many false alarms to accept.</li><li><strong>It will not guess missing periods.</strong> A period a series has no row for is counted as 0, and the step's sentence says</li></ul><p>how many were.</p><ul><li><strong>It will not read two counts for one period.</strong> A series with two rows for a period is refused: choose the column that</li></ul><p>splits the series, or select one measure first.</p><ul><li><strong>It has no seasonal baseline.</strong> A series with a yearly cycle needs a baseline from the same weeks of past years</li></ul><p>(Farrington), which is not here.</p><h3>How it was checked</h3><p>Against R's <code>surveillance</code> package (1.25.0) on a series with five days of excess: EARS C1 and C2 thresholds within 7e-8 and the same signals; CUSUM's sums, bounds and signals the same. EARS C3 follows the published definition, which counts the current period; R's bound does not, so this step can signal a day earlier. EWMA is checked against its formula. Sources: Hutwagner and colleagues, J Urban Health 2003 (EARS, open at PubMed Central); Page, Biometrika 1954 (CUSUM); Roberts, Technometrics 1959 (EWMA).</p><h3>History</h3><h4>2026-11-21 \xB7 The method's computation drawn (0.2.0)</h4><p>A <code>limit</code> measure, the decision limit on the statistic's own scale, and a chart of the statistic against it in Configure\u2026; Show me how for each method.</p><h4>2026-11-21 \xB7 First release (0.1.0)</h4><p>EARS C1, C2 and C3, CUSUM and EWMA, on one series or one per value of a column, with the counts and threshold drawn in Configure\u2026 and Show me how. See experiment 228.</p>",line_input:"<h2>Line layer</h2><p><strong>A source.</strong> It holds lines: a vaccination team's GPS track, a planned route, a road, or the border two study areas share. Map draws them over the study area and under the points.</p><h3>What it does</h3><p>It reads lines from a file, or takes them from two study areas:</p><ul><li><strong>From a file.</strong> GPX tracks and routes, from a GPS device or a phone app; KML or KMZ lines, from Google Earth and many</li></ul><p>field apps; GeoJSON lines. Each line keeps its name and attributes. Points and areas in the file are counted and said, and left out: Point data reads the points.</p><ul><li><strong>The border of two study areas.</strong> The stretch of the first area's outline that lies within a distance of the</li></ul><p>second's. Two countries' outlines, drawn apart, rarely meet exactly, so the distance is what lets them meet. It is 500 m unless changed: on Rwanda's border with DR Congo, from two sources, that found the whole border, and more found no stretch that is not border.</p><p>All positions are longitude and latitude on WGS84, as every one of these formats states them; nothing is converted.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>area</strong></td><td>in border mode only: a study area</td></tr><tr><td><strong>area_2</strong></td><td>in border mode only: the study area it borders</td></tr></tbody></table><p>Read from a file, it takes no input. Its output is <strong>lines</strong>, which Map takes on its <strong>lines</strong> port.</p><h3>How to use it</h3><p>In <strong>Configure\u2026</strong>:</p><p>1. <strong>Where the lines come from</strong>: a file, or the border of two study areas. 2. <strong>A file</strong>: choose it. <strong>After</strong> draws the lines and lists each with its length. 3. <strong>A border</strong>: connect the two study areas on the canvas, or choose them under <strong>Inputs</strong> in the Inspector. <strong>Before</strong> draws the two areas; <strong>After</strong> draws the border over them and gives its length. Change <strong>Outlines within, metres</strong> where the border is broken into pieces or does not appear.</p><p>Nothing reaches the workflow until <strong>Apply</strong>.</p><h3>What it will not do</h3><ul><li><strong>Route along its lines.</strong> A line is not a street network: no routing step takes it.</li><li><strong>Find roads in OpenStreetMap.</strong> Not built yet; read a GeoJSON of roads instead.</li><li><strong>Draw on every map.</strong> Map draws lines on a map with a study area and on a map of lines alone; on a map that leads</li></ul><p>with polygons, a raster or a street network the lines are carried and not yet drawn, and the key does not list them.</p><h3>How it was checked</h3><ul><li><code>tests/line-layer.test.mjs</code> (Node): a GeoJSON file read with its points and areas counted; lengths on the sphere; the</li></ul><p>border of two drawn areas 50 m apart found within 100 m and not within 10 m.</p><ul><li><code>tests/line-layer.browser.mjs</code>, Chromium and WebKit: a GPX file's tracks and routes read in Configure\u2026, its waypoint</li></ul><p>counted; the border of two study areas drawn After and run; lines drawn on Map, static and interactive.</p><ul><li>Measured on Rwanda's Western Province and DR Congo's Kivus: [experiment 229](../experiments/229-a-line-layer.md).</li></ul><h3>History</h3><h4>2026-11-24 \xB7 Reopening shows your lines, not the whole world (0.5.0)</h4><p>Open a layer you had already drawn on and the map opened zoomed right out. It was fitting your lines into a panel that had no size yet, then being told its real size afterwards and keeping the zoom it had already chosen. The fit now waits until the panel is really there.</p><p>It fits <strong>once</strong>. After that the view is yours: resizing the dialog or going full screen will not drag you back to where it decided to start.</p><h4>2026-11-24 \xB7 The map pans until you start a line (0.4.0)</h4><p>Press <strong>Start a line</strong>, then click to lay down each position. Until you press it, dragging pans the map and a click does nothing.</p><p>Before this, every click laid down a position \u2014 and a press-and-release that barely moves <em>is</em> a click as far as the map is concerned, so there was no way to look around without leaving a point behind. Finishing a line now returns the map to panning, so the next click starts nothing you did not ask for.</p><p>You can still pan while drawing: drag to move the map, click to lay down a position. A route can be longer than one screen, so that had to keep working.</p><p>The mode is shown three ways \u2014 the button looks pressed, the pointer becomes a crosshair, and the map gets an outline \u2014 because one small visual cue is easy to miss. The line of text under the map says what the mouse will do next, and it was blank when the dialog opened until now.</p><h4>2026-11-24 \xB7 An arrowhead, and a map that shows (0.3.0)</h4><p>The line you are drawing now ends in an <strong>arrowhead</strong> pointing the way it runs, instead of a filled dot. The hollow marker at the start is unchanged, so one glance tells you both which end is which and which way the line goes \u2014 and it is the same arrowhead Map draws when you set it to mark direction, so what you draw here is what the figure shows.</p><p>The drawing map also used to open as a single tile in one corner with grey around it. It was measuring a panel that had no size yet; it now waits for the layout, and keeps up when the panel changes size or goes full screen.</p><h4>2026-11-24 \xB7 Routes and flows drawn on a map (0.2.0)</h4><p>A third way to make a layer, beside a file and a border: <strong>draw it</strong>. Click the map to lay down each position of a route or a flow, press <strong>Finish the line</strong>, and name it. It is what pushpins are for points.</p><p><strong>The order you click is the direction.</strong> A flow drawn from a camp to a clinic is not the same as one drawn from the clinic to the camp, so the map shows where each line starts and where it ends, and <strong>Reverse</strong> turns one round rather than making you draw it again. Nothing else had to be invented for this: a line is an ordered sequence already.</p><p>A drawn layer names no file, because there is none \u2014 what it has instead is you and the day you drew it. One click is a place rather than a route, so a line of one position is refused and says how to continue it. Two hundred lines is as many as drawing one by one is good for; past that, read them from a file.</p><h4>2026-11-22 \xB7 First release (0.1.0)</h4><p>Lines read from a file or taken as the border of two study areas, and drawn on Map. Its first use, a buffer along a border to find the health facilities just inside it, waits on Geometry buffer taking lines.</p>",travel_over_ground:"<h2>Travel time over ground</h2><p><strong>A spatial operation.</strong> It takes a friction surface, the places a walk starts from and the places you want an answer for, and writes onto each of those places the time to the nearest starting point.</p><h3>What it does</h3><p>A <strong>friction surface</strong> is a raster whose value in each cell is the cost of crossing one metre of that cell \u2014 minutes per metre. The Malaria Atlas Project publishes one for walking, worldwide, at about a kilometre.</p><p>The step starts at every starting point at once and spreads outwards across the cells, always continuing from the cheapest cell reached so far. A step between two neighbouring cells costs the metres between their centres times the average of the two cells' friction. Because every starting point is seeded together, the time a cell settles at is the time from the <strong>nearest</strong> of them, and you do not have to ask which one that was.</p><p>Then it reads the settled time at each place you asked about and writes it into a column you name.</p><p>Use this instead of <strong>Reachable junctions</strong> where the walk is mostly not on a mapped road. Use Reachable junctions instead where the streets are how people move and the network is published.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>Friction surface</strong></td><td>a raster of cost per metre, from <strong>Raster input</strong> or <strong>Clip raster</strong></td></tr><tr><td><strong>Start from</strong></td><td>the points a walk begins at: health facilities, vaccination posts, a team's base</td></tr><tr><td><strong>Places</strong></td><td>the points you want an answer for: settlements, schools, households</td></tr></tbody></table><p>All three are needed. A street network cannot be connected here \u2014 that is a different operation.</p><h3>How to use it</h3><p>1. Read the friction surface with <strong>Raster input</strong>, and clip it to your area with <strong>Clip raster</strong> if it is large. 2. Connect it, the starting points and the places. 3. In <strong>Configure\u2026</strong>, name the column the minutes go into, and set a ceiling if you only care up to an hour. 4. Run. The Result says how many places were reached and how many were not.</p><h3>What it will not do</h3><ul><li><strong>It does not give a route.</strong> Nobody walks the line this grid implies. The walk steps between cell centres in eight</li></ul><p>directions; it is a model of crossing ground, and the minutes are what the surface says the ground costs.</p><ul><li><strong>It does not tell two places in one cell apart.</strong> The cell is the finest distinction the answer can make.</li><li><strong>It does not drop a place it cannot reach.</strong> That place keeps its row, with nothing in the time column and</li></ul><p><code>_why</code> beside it saying whether it fell outside the surface or no path reached it. A settlement nobody can reach is usually the finding you are looking for.</p><ul><li><strong>It does not choose a speed.</strong> The surface states the cost of the ground, which is the reason for using one.</li><li><strong>It does not give back a surface.</strong> The answer is at the places you asked about, not as a new raster. A computed</li></ul><p>raster would have no file behind it, and the evidence would end up citing a digest for values those bytes do not produce.</p><ul><li><strong>It does not cross more than 16,000,000 cells in one pass.</strong> Past that it refuses and says the figure. Clip the</li></ul><p>surface, or read a coarser one.</p><h3>What this does not establish</h3><p>That the surface is right about the ground. A road built since it was made, a river in flood, a season \u2014 any of these makes every minute wrong, and nothing in this step can tell. Where a ceiling is set, a place past it is unreached <em>here</em>, which is not the same as unreachable.</p><h3>How it was checked</h3><p>Unit tests on made-up grids: zero minutes standing on a starting point, a known time one cell away, the nearest of several starting points found in one pass, cheap ground against dear, a wall of no-data leaving a place unreached with its reason, a starting point on no-data named rather than quietly dropped, the ceiling leaving a place unreached rather than given a large number, and the cell limit refused with its figure.</p><p>It has never been run against a published friction surface. Whether its minutes resemble a real walk is open.</p><h3>History</h3><h4>2026-11-24 \xB7 First release (0.1.0)</h4><p>Added for campaign microplanning, where most of the walk to a settlement is not on a mapped road ([experiment 231](../experiments/231-travel-time-over-ground.md)).</p><p><strong>The cell limit was measured, not chosen.</strong> The first version found the next cell to continue from by scanning a list, which on a 250,000-cell grid was 94% of the whole time \u2014 so the first limit measured the list and not the ground. With an ordinary heap in its place, the cost is linear at about a quarter of a microsecond a cell in Chromium, and what binds is memory rather than patience: the walk keeps eight bytes a cell beside the raster's own values, so 16,000,000 cells is 128 MB in one browser tab. For scale, a Nigerian LGA at this resolution is a few thousand cells and all of Nigeria about 924,000.</p>",map_terms_to_vocabulary:"<h2>Map a column\u2019s terms to a vocabulary</h2><p><strong>A semantic operation.</strong> It takes a table, and gives each term in a column you choose the Wikidata entity <strong>you</strong> judged that term to name. The rows come out with a link that means something outside your workflow.</p><h3>What it does</h3><p>Every term in a Fieldwork workflow is, until now, a string that means something only inside that workflow. &quot;Kano&quot; in your table and &quot;Kano&quot; in somebody else's are the same six letters and nothing more. A Wikidata entity \u2014 <code>Q682571</code> \u2014 is an identifier the rest of the world shares, so a reader of your receipt can follow it and see exactly which thing you meant.</p><p><strong>You choose each link, one term at a time.</strong> The step does not search and take the best answer, and the reason is measured rather than cautious: on four terms taken from work in hand, Wikidata's own first result was the <strong>wrong one once in four</strong>. Searching &quot;Kano&quot; returns the <em>city</em> first; a table of Nigerian local government areas means the <em>state</em>, which comes fourth. Three of the four terms had a competing entity of a different kind in the top four \u2014 a ward against the local government area containing it, a pathogen against the disease it causes.</p><p>A step that took the first hit would be quietly wrong about a quarter of your rows, in a column that then travels into every receipt after it.</p><p><strong>A run asks Wikidata nothing.</strong> The choosing happens in <strong>Configure\u2026</strong>; what the step keeps is your decisions. So a run is the same every time, needs no network, waits on nobody's server, and a workflow saved today gives the same answer in five years. What it cannot do is notice that Wikidata has changed its mind \u2014 the date of each decision is recorded so a reader knows how old it is.</p><h3>What you connect</h3><table><thead><tr><th>Port</th><th>What goes there</th></tr></thead><tbody><tr><td><strong>Table</strong></td><td>any table. Run the workflow once first, so the step knows which terms it is being asked about</td></tr></tbody></table><h3>How to use it</h3><p>1. Connect the table and run once. 2. In <strong>Configure\u2026</strong>, choose the column whose terms you want linked. 3. Type what kind of thing the terms name \u2014 <em>state</em>, <em>district</em>, <em>disease</em> \u2014 in the filter box. This <strong>reorders</strong> the candidates and removes none, so narrowing can never hide the right entity. 4. Beside a term, choose <strong>Look up</strong>. Wikidata's candidates appear with the name and description it gives each one. 5. Choose the right one, or <strong>None of these name it</strong>. 6. <strong>Apply</strong>, then run. Each row gains a link in <code>&lt;column&gt;_wikidata</code>.</p><p>You can also add the bare identifier and the name Wikidata gives it as columns of their own.</p><h3>What it will not do</h3><ul><li><strong>It will not choose for you.</strong> That is the whole design, for the reason measured above.</li><li>**It will not claim the row <em>is</em> that entity.** It records that you, on a date, judged this term to name it. The</li></ul><p>receipt says so, and says how many candidates you were choosing among \u2014 one of one is a different thing from one of ten.</p><ul><li><strong>It will not treat &quot;none of these&quot; as a failure.</strong> A term you looked up and judged absent from Wikidata is a</li></ul><p>finding about the term. It is held apart from a term nobody has looked at yet, and the result says which is which.</p><ul><li><strong>It will not re-check.</strong> Wikidata is edited by anyone. An entity you cite may later be merged, split or removed,</li></ul><p>and this step keeps what you decided rather than what is current.</p><ul><li><strong>It will not look anything up during a run.</strong></li></ul><h3>What this does not establish</h3><p>That Wikidata is right. It is edited by anyone, its coverage of African administrative units is uneven, and an entity can disappear after you cite it. Nothing here measures what share of a country's units can be resolved at all \u2014 that is a question about Wikidata, not about this step.</p><h3>How it was checked</h3><p>Unit tested offline: the distinct terms you are asked about; a deliberate &quot;none of these&quot; held apart from a term nobody looked up; the link column added, and refused where it would overwrite an existing one; Wikidata's answer parsed with properties and id-less rows rejected; and the filter reordering candidates without removing any.</p><p>No parity check is owed. A parity check asks whether another implementation gets the same number from the same input, and here the input <em>is</em> the answer: the judgement is yours and the arithmetic is a lookup.</p>","surface:credentials":`<h2>Credentials</h2><h3>What it does</h3><p>Your credentials file holds the keys Fieldwork uses to reach other services, such as a GitHub token for a shared project. It is a file on your computer, encrypted with a passphrase only you know. Fieldwork never keeps a key in a project, a backup or a repository.</p><p><strong>One file per computer is fine.</strong> A token is not tied to a computer, but you can make a separate one for each laptop. Then, if a laptop is lost, you delete only that laptop's token on GitHub.</p><h3>How to use it</h3><h4>Start a credentials file on this computer</h4><p>1. Press <strong>Credentials</strong>, then <strong>Start a new collection</strong>. 2. Add each key, as below. 3. Type a long passphrase, at least 12 characters, in <strong>File passphrase</strong>, and again in <strong>Confirm download passphrase</strong>. 4. Press <strong>Download encrypted credentials</strong>. Keep the file in your Downloads folder, named for you and the computer, for example <code>FWCRED-&lt;your name&gt;-windows.fwcredentials</code>.</p><p>There is no way to recover a forgotten passphrase. Write it in your password manager.</p><h4>Open it next time</h4><p>1. Press <strong>Credentials</strong>. 2. <strong>Encrypted credential file</strong>: choose your file. 3. <strong>File passphrase</strong>: type it. 4. Press <strong>Unlock and activate</strong>.</p><p>It stays unlocked for 15 minutes after you last use it, or until you press <strong>Lock and discard session</strong>. Using it means working in this dialog, or Fieldwork reading a key for a request; working elsewhere in Fieldwork does not keep it open. The button says how many keys are unlocked. <strong>Start a new collection</strong> opens an empty one, shown as <em>Credentials: new, empty</em>, until you add a key.</p><h3>Make a GitHub token for one repository</h3><p>&gt; <strong>The step people miss: Resource owner.</strong> At the top of GitHub's token form, <strong>Resource owner</strong> starts as your own &gt; name. For a shared project it must be the <strong>organization that owns the repository</strong>, <code>digital-twin-ph</code> for &gt; <code>digital-twin-ph/project-test-collaboration</code>. Left as your name, the repository never appears when you choose it, &gt; and GitHub says only &quot;No repositories found&quot;. Change it first (step 5).</p><p>On GitHub, signed in as yourself:</p><p>1. Your picture, top right, then <strong>Settings</strong>. 2. At the bottom of the left column, <strong>Developer settings</strong>. 3. <strong>Personal access tokens</strong>, then <strong>Fine-grained tokens</strong>, then <strong>Generate new token</strong>. 4. <strong>Token name</strong>: the project and the computer, for example <code>fieldwork measles-2026 windows</code>. 5. <strong>Resource owner: change it before anything else.</strong> It is the drop-down at the top of the form, above <strong>Expiration</strong>, and it starts as <strong>your own name</strong>. Set it to whoever owns the repository, shown before the slash in its address: for <code>digital-twin-ph/project-test-collaboration</code> that is <code>digital-twin-ph</code>, not you. <strong>Left as your name, the project's repository never appears in step 7, however you search for it.</strong> The organization is offered only once you are a member of it; if it is missing from the drop-down, ask one of its owners to add you. 6. <strong>Expiration</strong>: 90 days. GitHub emails you before it ends. 7. <strong>Repository access</strong>: <strong>Only select repositories</strong>, and choose the project's repository. Only that one. 8. <strong>Permissions</strong>, <strong>Repository permissions</strong>: - <strong>Contents</strong>: Read and write. - <strong>Discussions</strong>: Read and write. - Leave everything else at <strong>No access</strong>. Never give <strong>Workflows</strong>. GitHub adds <strong>Metadata: Read-only</strong> by itself. 9. <strong>Generate token</strong>. Copy it at once: GitHub shows it only this time.</p><p>If the owner is an organization, an owner of that organization may have to approve the token before it works (next section). GitHub shows the token as pending until then, and emails you when it is approved or denied.</p><h3>For an organization's owner: approve a member's token</h3><p>A project shared through an organization's repository works for a member only once their token is approved, where the organization asks for approval. Tokens made by the organization's own owners need none.</p><p>1. On GitHub, the organization's page (for example <code>github.com/digital-twin-ph</code>), then <strong>Settings</strong>. 2. In the left column, under <strong>Personal access tokens</strong>, <strong>Pending requests</strong>. 3. Open the member's request. Check <strong>which repository</strong> it asks for (only the project's) and <strong>which permissions</strong> (<strong>Contents</strong> and <strong>Discussions</strong>, read and write; never <strong>Workflows</strong>). 4. <strong>Approve</strong>, or <strong>Deny</strong> with a reason, which GitHub sends to the member.</p><p>GitHub emails the organization's owners once a day while any request waits. To take a token's access away later: <strong>Personal access tokens</strong>, <strong>Active tokens</strong>, then <strong>Revoke</strong>. Steps from GitHub's own pages, read 2026-11-19: <em>Managing requests for personal access tokens in your organization</em> and <em>Reviewing and revoking personal access tokens in your organization</em> (docs.github.com).</p><h3>Fill in the form for a GitHub token</h3><p>Under <strong>Add or replace a credential</strong>:</p><table><thead><tr><th>Field</th><th>What to type</th><th>Example</th></tr></thead><tbody><tr><td><strong>Reference</strong></td><td>A short name of your own, unique in this file. The same reference replaces an existing key.</td><td><code>project-test-collaboration</code></td></tr><tr><td><strong>Provider identifier</strong></td><td>Exactly <code>github</code>, lower case.</td><td><code>github</code></td></tr><tr><td><strong>Label</strong></td><td>Optional: what you will recognise in a list.</td><td><code>Test collaboration, Windows</code></td></tr><tr><td><strong>Allowed HTTPS origin</strong></td><td>Exactly <code>https://api.github.com</code>, with no slash at the end.</td><td><code>https://api.github.com</code></td></tr><tr><td><strong>Repository it is for</strong></td><td>The repository, as owner/name, exactly as in its address.</td><td><code>digital-twin-ph/project-test-collaboration</code></td></tr><tr><td><strong>API key</strong></td><td>Paste the token you just copied.</td><td>(starts <code>github_pat_</code>)</td></tr></tbody></table><p>Then:</p><p>1. Press <strong>Add and activate</strong>. The list shows it, &quot;for&quot; the repository you named. 2. Press <strong>Download encrypted credentials</strong> to keep it, as above. A key you add and do not download is gone when the page is closed.</p><p>Fieldwork checks the token with GitHub as it unlocks it, and shows whose it is.</p><h3>Make a CARTO basemap key</h3><p>A CARTO key lets the interactive map show CARTO's light and dark basemaps (Positron, Voyager, Dark Matter), which keep your data in front, while your credentials are unlocked.</p><p>You do not need a CARTO account. CARTO's Workspace has its own <strong>Create new credential</strong> page: that is for CARTO's data platform, not for basemaps, so do not use it.</p><p>1. Go to <a href="https://carto.com/basemaps/apikey/" target="_blank" rel="noopener noreferrer">carto.com/basemaps/apikey</a>. 2. <strong>Request a key</strong> with your email address. Say the use is <strong>not commercial</strong>: research, teaching and non-profit work count. That allows 5 million requests a month. 3. Copy the key from the email. 4. To limit the key to Fieldwork, sign in at <a href="https://dashboard.basemaps.carto.com/" target="_blank" rel="noopener noreferrer">dashboard.basemaps.carto.com</a> with the link CARTO emails you, and add the website <code>fieldwork-app.github.io</code>. Type the host only: no <code>https://</code>, no path. A key limited this way does not work on your own computer's test server (<code>localhost</code>).</p><h3>Fill in the form for a CARTO key</h3><table><thead><tr><th>Field</th><th>What to type</th><th>Example</th></tr></thead><tbody><tr><td><strong>Reference</strong></td><td>A short name of your own, unique in this file.</td><td><code>carto</code></td></tr><tr><td><strong>Provider identifier</strong></td><td>Exactly <code>carto</code>, lower case.</td><td><code>carto</code></td></tr><tr><td><strong>Label</strong></td><td>Optional: what you will recognise in a list.</td><td><code>CARTO basemaps</code></td></tr><tr><td><strong>Allowed HTTPS origin</strong></td><td>Exactly <code>https://basemaps.cartocdn.com</code>, with no slash at the end.</td><td><code>https://basemaps.cartocdn.com</code></td></tr><tr><td><strong>Repository it is for</strong></td><td>Leave empty.</td><td></td></tr><tr><td><strong>API key</strong></td><td>Paste the key from CARTO's email.</td><td></td></tr></tbody></table><p>Then press <strong>Add and activate</strong>, and <strong>Download encrypted credentials</strong> to keep it.</p><p>A CARTO key travels in the address of every tile, so anyone watching the network can read it. CARTO asks that a key not be shared between unrelated projects: everyone makes their own.</p><h3>Make an Esri basemap key</h3><p>An Esri key lets the interactive map show Esri's satellite imagery and its street and outdoor maps. It is optional, and takes longer to make than a CARTO key: make one if you want satellite imagery. For street maps, CARTO is simpler.</p><p>Use an <strong>ArcGIS Location Platform</strong> account. An ArcGIS Online account, or the license strings for Esri's app kits, will not work. New accounts have pay-as-you-go <strong>off</strong>: the maps then stop for the month if the free 2 million tiles run out, and nothing is charged. Leave it off.</p><p>Esri's pages do not say whether signing up asks for a card. If it does, you can still leave pay-as-you-go off.</p><p>1. Go to <a href="https://location.arcgis.com/sign-up/" target="_blank" rel="noopener noreferrer">location.arcgis.com/sign-up</a> and create a free account. 2. Sign in and open <strong>Create developer credentials</strong> (in <strong>My portal</strong>: <strong>Content</strong>, <strong>New item</strong>, <strong>Developer credentials</strong>). 3. <strong>Select credential type</strong>: <strong>API key credentials</strong>. <strong>Next</strong>. 4. <strong>Where will you use these credentials?</strong>: <strong>Public application</strong>. Never either <em>Private application</em> choice: those give the key your own account's powers. <strong>Next</strong>. 5. <strong>Item access</strong>: <strong>No item access</strong>. <strong>Next</strong>. 6. <strong>Privileges</strong>: turn on the <strong>Basemaps</strong> switch only, so it reads 2 of 2. Not the <em>Location services</em> switch above it, and not <em>Static maps</em>. <strong>Next</strong>. 7. <strong>Settings</strong>: - <strong>Expiration date</strong>: the latest the calendar allows, a year from today. Put the date in your calendar. - <strong>Referrer URLs</strong>: <code>https://fieldwork-app.github.io</code>, with no path and no slash at the end. <strong>Next</strong>. 8. Give it a title, such as <code>Fieldwork basemaps</code>, and finish. 9. The page then shows a <strong>client ID</strong> and a <strong>client secret</strong>. Fieldwork needs neither: do not copy them anywhere. Generate the <strong>API key</strong> on that page and copy it at once. Esri shows it only this one time.</p><p>These are Esri's screens as of November 2026. If they change, follow Esri's names and tell us, so this page can be corrected.</p><h3>Fill in the form for an Esri key</h3><table><thead><tr><th>Field</th><th>What to type</th><th>Example</th></tr></thead><tbody><tr><td><strong>Reference</strong></td><td>A short name of your own, unique in this file.</td><td><code>esri</code></td></tr><tr><td><strong>Provider identifier</strong></td><td>Exactly <code>esri</code>, lower case.</td><td><code>esri</code></td></tr><tr><td><strong>Label</strong></td><td>Optional: what you will recognise in a list.</td><td><code>Esri basemaps</code></td></tr><tr><td><strong>Allowed HTTPS origin</strong></td><td>Exactly <code>https://static-map-tiles-api.arcgis.com</code>, with no slash at the end.</td><td><code>https://static-map-tiles-api.arcgis.com</code></td></tr><tr><td><strong>Repository it is for</strong></td><td>Leave empty.</td><td></td></tr><tr><td><strong>API key</strong></td><td>Paste the key you copied.</td><td></td></tr></tbody></table><p>Then press <strong>Add and activate</strong>, and <strong>Download encrypted credentials</strong> to keep it.</p><p>Before the key expires, make a new one on the same page (Esri lets a key hold two at once) and replace it here.</p><h3>Make a DHIS2 personal access token</h3><p>1. Sign in to the DHIS2 server, open your profile (your initials, top right), then <strong>Edit profile</strong>, then <strong>Personal access tokens</strong>. 2. <strong>Generate new token</strong>: choose <strong>Browser context</strong>, since Fieldwork reads the server from your browser. Give it a name and an expiry. Leave <strong>Allowed referrers</strong> empty, and tick <strong>GET</strong> only under <strong>Allowed HTTP methods</strong>: Fieldwork only reads. (A server/script context token works too.) 3. Copy the token: DHIS2 shows it once.</p><p>The server must also list Fieldwork's address, <code>https://fieldwork-app.github.io</code>, in its CORS allowlist (<strong>System Settings</strong>, <strong>Access</strong>), which its administrator sets. Without it the page cannot read the server, and DHIS2's own exports can be read under Your file instead.</p><h3>Fill in the form for a DHIS2 token</h3><table><thead><tr><th>Field</th><th>What to type</th><th>Example</th></tr></thead><tbody><tr><td><strong>Reference</strong></td><td>A short name of your own, unique in this file.</td><td><code>dhis2-country</code></td></tr><tr><td><strong>Provider identifier</strong></td><td>Exactly <code>dhis2</code>, lower case.</td><td><code>dhis2</code></td></tr><tr><td><strong>Label</strong></td><td>Optional: what you will recognise in a list.</td><td><code>National DHIS2</code></td></tr><tr><td><strong>Allowed HTTPS origin</strong></td><td>The server's address up to the first slash after its name: no path, no slash at the end. Plain <code>http</code> is accepted only for <code>localhost</code>, <code>127.0.0.1</code> or <code>[::1]</code>, a server on this computer.</td><td><code>https://dhis2.example.org</code></td></tr><tr><td><strong>Repository it is for</strong></td><td>Leave empty.</td><td></td></tr><tr><td><strong>API key</strong></td><td>Paste the token you copied.</td><td></td></tr></tbody></table><p>Then press <strong>Add and activate</strong>, and <strong>Download encrypted credentials</strong> to keep it.</p><h3>Make a Supabase project and its publishable key</h3><p>Supabase is a hosted database with sign-in, which a shared training session could keep its moves in (experiment 233, a spike: nothing in Fieldwork uses it yet beyond the check below). Put no real patient data in it.</p><p>The free plan allows two active projects. <strong>A free project pauses after a week without use</strong>; restore it from the dashboard before a session.</p><p>1. Go to <a href="https://supabase.com/dashboard" target="_blank" rel="noopener noreferrer">supabase.com/dashboard</a> and sign up, or sign in. 2. Create an organization if asked, on the <strong>Free</strong> plan. 3. <strong>New project</strong>: choose the organization, give the project a name such as <code>fieldwork-training</code>, and a database password. Keep the password in your password manager: Fieldwork never needs it. Choose the region nearest the people who will use it. <strong>Create new project</strong>, and wait while it is set up. 4. Open the project's <strong>Settings</strong>: the gear at the bottom of the left column. Not <strong>Connect</strong> at the top: it does not show what Fieldwork needs. Under <strong>Configuration</strong>: - <strong>General</strong>: copy the <strong>Project ID</strong>. The project's address is <code>https://</code>, then the Project ID, then <code>.supabase.co</code>: for the ID <code>abcdefghijklmnopqrst</code>, <code>https://abcdefghijklmnopqrst.supabase.co</code>. - <strong>API Keys</strong>: copy the <strong>publishable key</strong>, which starts <code>sb_publishable_</code>.</p><p><strong>Never copy a secret key</strong> (it starts <code>sb_secret_</code>, or is the legacy <code>service_role</code> key). A secret key gets past every protection on the project's data and must never be in a browser. Fieldwork refuses one.</p><p>These are Supabase's screens as followed on 2026-11-27. If they change, follow Supabase's names and tell us, so this page can be corrected.</p><h3>Fill in the form for a Supabase key</h3><table><thead><tr><th>Field</th><th>What to type</th><th>Example</th></tr></thead><tbody><tr><td><strong>Reference</strong></td><td>A short name of your own, unique in this file.</td><td><code>supabase-training</code></td></tr><tr><td><strong>Provider identifier</strong></td><td>Exactly <code>supabase</code>, lower case.</td><td><code>supabase</code></td></tr><tr><td><strong>Label</strong></td><td>Optional: what you will recognise in a list.</td><td><code>Training sessions</code></td></tr><tr><td><strong>Allowed HTTPS origin</strong></td><td><code>https://</code>, then the <strong>Project ID</strong> from <strong>Settings</strong>, <strong>General</strong>, then <code>.supabase.co</code>, with no slash at the end.</td><td><code>https://abcdefghijklmnopqrst.supabase.co</code></td></tr><tr><td><strong>Repository it is for</strong></td><td>Leave empty.</td><td></td></tr><tr><td><strong>API key</strong></td><td>Paste the publishable key.</td><td>(starts <code>sb_publishable_</code>)</td></tr></tbody></table><p>Then:</p><p>1. Press <strong>Add and activate</strong>. 2. Press <strong>Check</strong> beside it in the list. Fieldwork asks the project once and says what came back: <em>the project is running and accepted this key</em>, or why not. 3. Press <strong>Download encrypted credentials</strong> to keep it.</p><h3>When something does not work</h3><ul><li><strong>&quot;No repositories found&quot; when choosing the repository on GitHub's token page</strong>: the <strong>Resource owner</strong> at the top of</li></ul><p>the form is still your own name. Change it to the repository's owner, <code>digital-twin-ph</code> for example, and search again.</p><ul><li><strong>The repository is not listed in Open shared GitHub project</strong>: check <strong>Repository it is for</strong> is spelled exactly</li></ul><p>as the repository's address, and <strong>Provider identifier</strong> is <code>github</code>.</p><ul><li><strong>GitHub refuses the token</strong>: it may have expired, or still be waiting for the organization's approval, or have</li></ul><p>been given the wrong <strong>Resource owner</strong>. Make a new one.</p><ul><li><strong>CARTO maps do not appear</strong>: check <strong>Provider identifier</strong> is <code>carto</code> and <strong>Allowed HTTPS origin</strong> is exactly</li></ul><p><code>https://basemaps.cartocdn.com</code>. A key limited to Fieldwork's address works only there. Fieldwork moved to <code>fieldwork-app.github.io</code> on 27 November 2026: a key limited to <code>digital-twin-ph.github.io</code> needs <code>fieldwork-app.github.io</code> added on CARTO's dashboard.</p><ul><li><strong>Esri maps do not appear</strong>: the key may have expired, or the free tiles for the month are used up. Check</li></ul><p><strong>Provider identifier</strong> is <code>esri</code> and <strong>Allowed HTTPS origin</strong> is exactly <code>https://static-map-tiles-api.arcgis.com</code>. A key whose <strong>Referrer URLs</strong> list only <code>https://digital-twin-ph.github.io</code>, Fieldwork's address before 27 November 2026, needs <code>https://fieldwork-app.github.io</code> added in its settings on Esri's site.</p><ul><li><strong>DHIS2 says it could not be reached</strong>: the server does not list this page's address, <code>https://fieldwork-app.github.io</code>,</li></ul><p>in its CORS allowlist. A server set up before 27 November 2026 may list <code>https://digital-twin-ph.github.io</code> only. Ask its administrator to add the new one, or export a table from DHIS2 and read it under Your file.</p><ul><li><strong>DHIS2 refuses the token</strong>: it may have expired or been revoked. Make a new one in your DHIS2 profile.</li><li><strong>Fieldwork says &quot;This is a Supabase secret key&quot;</strong>: you copied the secret key. Copy the publishable key instead,</li></ul><p>which starts <code>sb_publishable_</code>.</p><ul><li><strong>Supabase refused the key (401)</strong>: copy the publishable key again from <strong>Settings</strong>, <strong>API Keys</strong>. It may have been</li></ul><p>deleted or replaced there.</p><ul><li><strong>Supabase answered with another number, or could not be reached</strong>: a free project pauses after a week without use.</li></ul><p>Open it in Supabase's dashboard and restore it. Check too that <strong>Allowed HTTPS origin</strong> is <code>https://</code>, the Project ID and <code>.supabase.co</code>, exactly.</p><ul><li><strong>A lost laptop</strong>: on GitHub, <strong>Fine-grained tokens</strong>, delete that laptop's token. The file on the laptop is then</li></ul><p>useless even to someone who learns its passphrase.</p>`,"surface:notes":"<h2>Notes</h2><h3>What it does</h3><p>The Notes tab is the project's write-up. It shows every note from every workflow in the project, filed under the four parts of the body (Introduction, Methods, Results, Discussion), followed by References.</p><p>A note is one of four kinds:</p><ul><li><strong>quoted</strong>: an author's own sentence, carried verbatim.</li><li><strong>derived</strong>: restated from what an input declares, such as its source.</li><li><strong>machined</strong>: written by a widget about what it did; the next run rewrites it.</li><li><strong>authored</strong>: written by you.</li></ul><p>Each note has a <strong>function</strong>, which says what it does for a reader (context, rationale, objective, source, method, verification, finding, limitation). An authored note can also answer two questions about its sources: <strong>whose words</strong> and <strong>whose argument</strong>.</p><h3>How to use it</h3><p>1. Choose <strong>Add note</strong> under the part of the write-up where the note belongs. 2. Write the note. The dialog shows questions to ask of that part; hide them once they are habit. 3. Choose its function. If it draws on literature, answer whose words and whose argument. 4. Add the works it cites under <strong>Citations</strong>. They are marked on the note and listed in References. 5. To show a picture with the note, open <strong>Image</strong> and choose a PNG, JPEG, WebP or SVG file. Write its <strong>alt text</strong>, what the picture shows for someone who cannot see it, and its <strong>caption</strong>, what a reader is to take from it. Both are required. 6. Choose <strong>Add note</strong> (or <strong>Save</strong> when editing) to keep it on the project.</p><p>A picture goes above the note's words, on the board and in the write-up. It is kept on this device by its digest, and an exported project carries it. A note whose picture is not on this device says so, with its caption.</p><p>A note can be moved to another part by dragging its card. Editing a machined note does not change it: the edit becomes an authored note that keeps the wording it was taken from.</p><h3>The parts of the write-up</h3><p>Each part has a job, and the questions under it are for checking a draft, not for structuring one. They are the same questions the Add note dialog shows for that part.</p><h4>Introduction</h4><p>Shows the gap in knowledge, why filling it matters, and what this study adds. Build it in two moves: the problem (background to the gap, why it matters, what earlier studies left open), then the purpose (the approach, what is new in it). Funnel from broad to narrow and end on the objective. About three paragraphs. It is not a history of the issue or a full literature review, and it holds no results.</p><ul><li>What is the gap in knowledge, and why does filling it matter?</li><li>What did earlier studies leave open that this study addresses?</li><li>Does the last sentence state the objective?</li><li>Is anything here background a reader does not need, or a result?</li></ul><h4>Methods</h4><p>Says exactly how the study was done, so someone could repeat it and judge it. Use subheadings, define every variable and how it was measured, describe original methods in detail and cite standard ones. A flow diagram can show how the rows or people studied were reached. Describe what was done, not what was found: a result belongs here only where it explains a choice of method, with the reason first.</p><ul><li>Could someone repeat the study from what is written here?</li><li>Is every variable defined, with how it was measured?</li><li>Does every method have a result that answers it?</li><li>Is anything here a finding rather than what was done?</li></ul><h4>Results</h4><p>States the findings that bear on the objective, without interpreting them. Mirror the Methods: every measurement described there has a finding here, in the same order. Let the tables and figures carry the numbers, and say in a sentence or two what each shows. Use the past tense.</p><ul><li>Does each result answer a method, in the same order?</li><li>Is any sentence interpreting rather than reporting?</li><li>Does the text say in a sentence or two what each table or figure shows, without restating it?</li><li>Do the numbers add up, and agree with the tables?</li></ul><h4>Discussion</h4><p>Interprets the results and justifies the interpretation, against what other studies found and the gap the study set out to fill. One plan is four paragraphs: the key result and the main conclusion; the results beside comparable studies; the major limitations, stated plainly; and recommendations for practice and for further study. It holds no new results.</p><ul><li>Is each conclusion beside the result that supports it?</li><li>Does any conclusion or recommendation go further than the results support?</li><li>How do these results compare with similar studies?</li><li>Are the major limitations stated plainly, with what was done about them?</li></ul><h4>References</h4><p>Assembled from what the notes cite: a source an input declares, a method a computation uses, and a work a note cites from its Citations tab. Cite a work from the note that relies on it.</p><p>These parts and their questions follow the CDC/TEPHINET scientific writing course for Field Epidemiology Training Program residents, in this application's own words.</p><h3>Whose words, and whose argument</h3><p>A note that draws on published work answers two questions. They are separate: a note can use a source's exact words and still be your argument, or be in your own words and only report.</p><p><strong>Whose words?</strong> How much of the source's wording the note carries.</p><table><thead><tr><th>Answer</th><th>What it means</th><th>A reader checks it against</th></tr></thead><tbody><tr><td><strong>the source's exact words</strong></td><td>A quotation. Put it in quotation marks and cite the page</td><td>The source, word for word</td></tr><tr><td><strong>close to the source's wording</strong></td><td>Your sentence still follows the source's words and order. Common while learning to paraphrase; revise it into your own words, or quote it</td><td>The passage, which it may copy more than it should</td></tr><tr><td><strong>my words: one passage</strong></td><td>A paraphrase of one passage</td><td>That passage</td></tr><tr><td><strong>my words: the main points</strong></td><td>A summary of one work or several</td><td>Each work it cites</td></tr><tr><td><strong>not sure</strong></td><td>You looked and could not tell</td><td>A reviewer can help decide</td></tr></tbody></table><p><strong>Whose argument?</strong> Whether the note reports the works or argues from them.</p><table><thead><tr><th>Answer</th><th>What it means</th><th>A reader judges it by</th></tr></thead><tbody><tr><td><strong>what the works say</strong></td><td>Reporting what others found</td><td>Whether the works say it</td></tr><tr><td><strong>what I make of them</strong></td><td>Your analysis, reasoning or synthesis, which may cite works in support</td><td>Whether the reasoning holds, and whether the works support it</td></tr><tr><td><strong>not sure</strong></td><td>You looked and could not tell</td><td>A reviewer can help decide</td></tr></tbody></table><p>Both are optional and read <strong>unstated</strong> until answered. A note on your own data, a step or a result draws on no literature and needs neither. When a note both reports and argues, consider writing two notes, one reporting and one with your reading, and linking them, so each can be checked on its own terms.</p><h4>What each answer commits you to</h4><ul><li><strong>Exact words</strong>: the passage itself, copied exactly. If the exact words do not matter, put it in your own.</li><li><strong>One passage</strong>: read the passage in full. Watch for staying so close to its wording that it becomes &quot;close to the source's wording&quot;.</li><li><strong>The main points</strong>: read enough of each work to state its main point; an abstract can serve if the note says so. Watch for making works agree more than they do.</li><li><strong>What I make of them</strong>: make the turn from the works to your reading visible (<em>which suggests</em>, <em>for this study, that means</em>). Watch for claiming more than the evidence allows, most of all causation from an association.</li></ul><h4>Examples</h4><ul><li><strong>The source's exact words</strong>, from Snow, 1855: &quot;no experiment could have been devised which would more thoroughly test the effect of water supply on the progress of cholera than this&quot;.</li><li><strong>Close to the source's wording</strong>, the same passage: <em>No experiment could have been devised which would test the effect of the water supply on cholera more thoroughly than this one.</em> The wording and order are still Snow's.</li><li><strong>My words: one passage</strong>, the same passage: <em>Because the two companies' customers did not differ in their houses or their surroundings, the arrangement circumstances had produced tested the water supply more thoroughly than any designed experiment could have.</em></li><li><strong>My words: one passage</strong>, from Murdock and colleagues, 2017, on their summer measurements: <em>In summer, the city's weather station read warmer than loggers in the vegetation where mosquitoes rest, by 3.0 to 4.2 \xB0C in daily maximum.</em></li><li><strong>My words: the main points</strong>, of Mordecai and colleagues, 2017: <em>Transmission by</em> Aedes aegypti <em>peaks near 29 \xB0C and stops below about 18 \xB0C and above about 35 \xB0C, with adult survival setting the upper limit.</em></li><li><strong>My words: the main points</strong>, of Murdock 2017 and Wimberly 2020: <em>Where temperature was logged at the places mosquitoes rest, it differed from the weather station's by enough to change modelled transmission, and the difference varied with season and land cover.</em></li><li><strong>What I make of them</strong>, from the Brazil example: <em>The leads match lag 0, so an association of that size arises without temperature causing cases, and lag 0 cannot be read as transmission.</em> It reports nothing a work says; it is a reading of this study's own results.</li></ul><h3>The outline: what the project is writing towards</h3><p>A project names what it is writing towards, with its question: in <strong>New project</strong>, or later on the <strong>Project</strong> tab under <strong>Writing towards</strong>. One or more: a publication, a situation report, a surveillance report. None yet is fine.</p><p>Once one is named, Notes opens on its <strong>outline</strong>: every part those products need, in reading order. Each part says:</p><ul><li><strong>how much fills it</strong>: the notes that fill it, or that it is written in the draft, or <strong>empty</strong>;</li><li><strong>which products use it</strong>, and the heading and length it takes in each: a background of 150 to 300 words in the</li></ul><p>publication is one or two sentences in the situation report.</p><p>Above the parts, each product's <strong>coverage</strong>: how many of its parts are filled.</p><p>A note fills a part by its section and its function together: a note in Methods whose function is <em>verification</em> fills <strong>Data checks</strong>. <strong>Write it</strong>, beside an empty part, adds a note with that section and function already set.</p><p><strong>Objectives</strong> are one note, function <em>objective</em>, listing its objectives as numbered items, each answerable by a result. In the note's dialog, <strong>Add an objective</strong> adds an item; each can be moved up or removed.</p><p>A note's dialog also shows, under <strong>In each target</strong>, the heading and length its section and function take in each product the project writes towards.</p><p><strong>Objectives come first; workflows answer them later.</strong> A new project can write its objectives before it has any workflow. Under the Objectives part, each objective says whether a note answers it, how many tables, charts and maps support it, and which workflow answers it, or <strong>no workflow yet</strong>. <strong>Write its answer</strong> adds a note in Results that answers that objective.</p><ul><li><strong>The objective a workflow answers</strong> is chosen on the <strong>Project</strong> tab, under the workflow's name, once the project has</li></ul><p>objectives. A workflow answers one objective at most.</p><ul><li><strong>Answers</strong>, in a Results note's dialog, says which objective the note answers.</li><li><strong>Tables, charts and maps shown with this note</strong>, in any note of your own: ticked ones are drawn after that note in</li></ul><p>the draft, wherever it sits, and not in their own place. A map can support a point in the Introduction.</p><p>In the draft's Results, each objective is a numbered subsection, in the objectives' order: the notes that answer it, then the results of the workflow that answers it. Results that answer no objective come first. An objective with nothing yet says what belongs there.</p><h3>The plan: what each part will hold</h3><p>Once a project names what it is writing towards, Notes shows its <strong>plan</strong> above the outline. It has one part for each slot of the outline, shared by the targets that use it. Each part starts empty, with the slot's heading and length.</p><ul><li><strong>Plan it</strong> opens a box for what that part will hold. Write it before the analysis, in a line or two.</li><li><strong>The objectives part is your objectives note.</strong> It is the one part a product shows, as the numbered objectives.</li><li>Each part says how much fills it so far: notes, objectives, or the draft's own part.</li><li><strong>Mark the plan complete</strong> when you judge it done. Fieldwork keeps a dated version of every part. If a part changes</li></ul><p>afterwards, the plan says so. <strong>Undo complete</strong> removes the mark and keeps the versions.</p><ul><li>Add or drop a target at any time. An added target brings its parts, empty. A dropped target's written parts stay,</li></ul><p>under <em>Planned for a target no longer chosen</em>.</p><ul><li>A part can list the <strong>tables, charts and maps</strong> it will show, one a line, such as <em>map: cases by village</em>. Each is</li></ul><p>marked made once a note that fills the part names a map, chart or table of that kind.</p><ul><li><strong>Start a note from this</strong> copies a part's words into a new note of the part's section, ready to rewrite. The note</li></ul><p>keeps which part it came from.</p><ul><li>The plan says how many parts have notes and no plan: written, not planned.</li></ul><p>The plan is never part of any product: not the draft, the publication, a report or a download.</p><h3>The notes audit</h3><p><strong>Notes audit</strong>, beside the draft buttons and in the draft's own bar, shows where a target's write-up has gaps. It opens on request and never stops a draft. One target at a time, as tabs:</p><ul><li>How many of the target's parts are written, as a number and a bar.</li><li>Each part marked <em>written</em> (\u25CF), <em>planned, not written</em> (\u25D0) or <em>empty</em> (\u25CB), with the length it asks for. Where the</li></ul><p>length is given in words or sentences, the written part is counted against it: <em>shorter than asked</em>, <em>within the length</em> or <em>longer than asked</em>.</p><ul><li>Parts planned and not written; parts written and not planned; notes this target does not use.</li><li>Each objective, answered or not, and how many tables, charts and maps support it.</li><li>How many tables, charts and maps there are, and how many a note names as resting on them.</li><li>How many works are cited, and how many are named but not read.</li></ul><p>It scores no sentence and writes none.</p><h3>Draft as a document</h3><p><strong>Publication</strong>, at the top of Notes, lays the write-up out as a document on a page, to read and to print. <strong>Draft as</strong> chooses the kind:</p><table><thead><tr><th>Format</th><th>Follows</th><th>Its parts</th></tr></thead><tbody><tr><td>Publication</td><td>a journal article</td><td>Title, abstract, Introduction, Methods, Results, Discussion, data availability, references, appendix</td></tr><tr><td>Situation report, WHO style</td><td>WHO situation reports</td><td>Report number, data as of, highlights, situation in numbers, background, epidemiological update, risk assessment, preparedness and response, recommendations, data notes, references</td></tr><tr><td>Situation report, OCHA style</td><td>UN OCHA situation reports</td><td>Report number, as of, highlights, key figures, situation overview, response, gaps and challenges, notes on the data, references, contacts</td></tr><tr><td>Surveillance report, ECDC style</td><td>ECDC annual epidemiological reports</td><td>Reporting period, key facts, introduction, methods, epidemiology, discussion, public health implications, references</td></tr><tr><td>Surveillance summary</td><td>CDC's surveillance summaries</td><td>Period covered, summary, introduction, methods, results, discussion, limitations, public health action, references</td></tr><tr><td>Full report, with a three-question summary</td><td>CDC's full reports</td><td>A summary box of three questions (what is already known, what this adds, implications for practice), abstract, introduction, methods, results, discussion, limitations, public health implications, references</td></tr></tbody></table><p>Each format is filled from the same notes. The parts you write, such as highlights or recommendations, are written in place with <strong>Write</strong>; until then the part shows what it is for and how long it runs, and prints nothing. <strong>What you write follows you between formats</strong>: highlights written for a WHO-style sit rep are the key facts of an ECDC-style report. A part one format has and another does not is named on screen, not lost.</p><p><strong>Each figure and table has a width and a place</strong>, set above it:</p><ul><li><strong>Width</strong>: full, half or a third of the text column.</li><li><strong>Place</strong>: on its own line; side by side with the next figure, which is drawn beside it; or with the text running</li></ul><p>round it, on the left or the right, as in Word; or left out of this kind of document.</p><p>The format and each figure's place are kept with the project, a figure's place separately for each format, so it can be half width in the situation report and full width in the publication. The controls do not print. <strong>Print or save as PDF</strong> prints the document alone. A worked example that ships with Fieldwork shows its document as it was set, with no controls.</p><p><strong>What a draft attaches rather than prints:</strong></p><ul><li><strong>A table too long to print whole</strong>, more than 50 rows such as a line list, is attached as a CSV file. A line in its</li></ul><p>place names it: <em>Table S1. Each case with its chain, 162 rows: attached as S1-each-case-with-its-chain.csv.</em></p><ul><li><strong>In the two situation reports, the surveillance summary and the full report</strong>, equations and the tables an input</li></ul><p>reads go to an annex file, <code>annex.html</code>, and one line at the end of the draft says what it holds. The publication and the ECDC-style report keep their equations printed.</p><ul><li><strong>Rows fetched from elsewhere are never attached.</strong> Where a workflow's table was fetched, as NYC's is from Zenodo,</li></ul><p>the line says where it came from and no file is written.</p><p><strong>Download the attached files</strong> gives the annex and the CSV files in one zip. The PDF comes from <strong>Print or save as PDF</strong>; a browser cannot put it in the zip.</p><p><strong>In print</strong>, a heading over a part you have not written does not print, a table wraps rather than being cut at the margin, and the date under the title says <em>Drafted</em>: it is the day the draft was made, not the date of the data. Findings about the data, such as columns with no stated meaning, are stated once under the methods or data notes, not as the study's limitations.</p><h3>What it will not do</h3><ul><li>It does not check that a note is faithful to the works it cites, or that &quot;my words&quot; are. That is for the author and the reader; it seldom holds the source's text.</li><li>It does not quote for you. A sentence carried word for word from a source belongs in quotation marks, with its page.</li><li>The questions do not grade a note. A note that answers all of them can still be wrong.</li><li>It does not check that alt text describes the picture, or that you may publish it. The picture's source and terms</li></ul><p>belong in the note or its citations.</p>","surface:shared-projects":"<h2>Shared through GitHub</h2><h3>What it does</h3><p>A project shared through GitHub is kept in a GitHub repository as well as in your browser. Your co-authors open the same repository in their own Fieldwork. Each person works on their own computer, and saves to the repository when they choose. Nothing is sent until someone presses <strong>Save to the repository</strong>.</p><p>The header's &quot;Saved on this device&quot; is about your browser only. A project saved to GitHub can still say &quot;Not backed up&quot;: a backup is a file on your computer, which is a separate thing.</p><p>You need:</p><ul><li>a repository made from the project template, <code>digital-twin-ph/fieldwork-project-template</code>, on GitHub;</li><li>a GitHub token for that repository, unlocked in <strong>Credentials</strong> (see the Credentials manual);</li><li>for your name to appear in the project: your identity file (the <strong>Identity</strong> button at the right of the header).</li></ul><h3>How to use it</h3><p>Everything below is in the <strong>Project</strong> tab (next to <strong>Workflow</strong>, above the canvas), in the section <strong>Shared through GitHub</strong>.</p><h4>Share a project you have made here</h4><p>1. Under <strong>Repository</strong>, type the repository as <code>owner/name</code>, for example <code>digital-twin-ph/project-test-collaboration</code>. 2. Under <strong>GitHub token</strong>, choose the token for that repository. 3. Press <strong>Share through this repository</strong>.</p><p>If it answers &quot;It already holds a project&quot;, someone has already saved a project there. Open that one instead (below), so neither project is lost.</p><h4>Open a project someone has shared</h4><p>1. Press <strong>+ New project</strong>, then choose <strong>Open shared GitHub project</strong>. 2. Choose your token, or type the repository, and press <strong>Check the repository</strong>. 3. Press <strong>Load the project</strong>.</p><h4>Save your work to the repository</h4><p>1. Under <strong>What this save is</strong>, type a few words, for example &quot;first question, DRC study area&quot;. 2. Press <strong>Save to the repository</strong>. 3. It answers <strong>Saved.</strong>, with a link to see the save on GitHub.</p><p>If it answers &quot;Someone saved to GitHub since&quot;, press <strong>Get the latest</strong> first, then save.</p><h4>Encrypted on GitHub</h4><p>A project shared from now on is <strong>encrypted on GitHub</strong>: each file is locked so that only the project's members can read it, each with their own identity. GitHub's pages show that the files are there, not what they say.</p><ul><li><strong>Open your identity before you save.</strong> A save locks the files for you and for every member who has a key.</li><li><strong>A member gives their key</strong> by pressing <strong>This is me</strong> under <strong>People</strong>, with their identity open. Someone who</li></ul><p>cannot open the project yet sends you their key (they find it under <strong>Identity</strong>, <em>Your key for encrypted files</em>); paste it beside their name under <strong>People</strong> and press <strong>Add</strong>. Your next save includes them.</p><ul><li><strong>A member with no key yet</strong> is named when you save. The save still goes ahead.</li><li><strong>To make a project open</strong>, for a worked example anyone may read, untick <strong>Encrypted on GitHub</strong>. The next save</li></ul><p>writes plain files and removes the locked ones.</p><p>Someone removed from the project keeps what they could already read. To shut someone out completely, move the project to a new repository.</p><h4>Get your co-authors' work</h4><p>Press <strong>Get the latest</strong>. What changed on GitHub comes in. What you changed here is kept, for you to save. If the same workflow was changed in both places, you choose which to keep.</p><h4>See where things stand</h4><p>Press <strong>Check GitHub</strong>. Two lines answer:</p><ul><li><strong>Nothing changed here since last read or saved</strong>, or what has changed;</li><li><strong>GitHub has nothing newer</strong>, or that someone saved since.</li></ul><h4>Say who you are</h4><p>GitHub records the login of whoever saves. The project can also carry your name, ORCID iD and affiliation, signed with your identity file so others can check it is you.</p><p>1. Press <strong>Check GitHub</strong>, so the <strong>People</strong> list shows who has access. 2. On the row with your login, choose your <strong>Project role</strong>. 3. Press <strong>This is me</strong>. If your identity file is not open, Fieldwork opens it for you: open it, then press <strong>This is me</strong> again. 4. Save to the repository, so your co-authors see it.</p><p>Until you do, your row says &quot;Has not said who they are yet&quot;, and each save reminds you. A save is never refused for it.</p><p>Your row shows what your identity file holds. To add your ORCID iD or an affiliation with its ROR ID, press <strong>Identity</strong>, open <strong>Change your avatar, ORCID iD or affiliations</strong>, fill them in, choose your identity file, enter its passphrase and press <strong>Save the new file</strong>. Keep the new file in place of the old one: your key is the same. Then press <strong>This is me</strong> again and save to the repository.</p><h4>Give a co-author a project role</h4><p>On their row under <strong>People</strong>, choose a <strong>Project role</strong>. The role is saved with the project. Inviting them to the repository, and what they may do there, is done on GitHub. If their GitHub access is too low for their role, the row says so.</p><h4>Talk about the project</h4><p>Under <strong>Discussions</strong>, press <strong>Check GitHub</strong> to see the latest. To start one, choose a category, write a title and a message, and press <strong>Post to Discussions</strong>.</p><h4>Stop sharing</h4><p><strong>Stop sharing on this device</strong> keeps the project here and leaves the repository as it is.</p><h3>What it will not do</h3><ul><li>It does not save by itself. Only <strong>Save to the repository</strong> sends your work.</li><li>It does not send your keys. Tokens stay in your credentials file, never in the repository.</li><li>It does not invite people or change their access. That is done on GitHub, by the repository's owner.</li><li>It does not refuse a save because you have not said who you are. It reminds you.</li><li>It does not encrypt Discussions, file names, sizes or the words of a save. Those stay visible to anyone who can see the</li></ul><p>repository.</p><h3>When something does not work</h3><ul><li><strong>&quot;GitHub refused the token&quot;</strong>: the token has expired or was made again. Make a new one (Credentials manual).</li><li><strong>&quot;The token may not write the repository's files&quot;</strong>: the token needs <strong>Contents: Read and write</strong> on this</li></ul><p>repository. If the repository belongs to an organization, its owner may also need to approve the token.</p><ul><li><strong>No &quot;This is me&quot; button on your row</strong>: unlock your GitHub token in <strong>Credentials</strong>, or open your identity file,</li></ul><p>so Fieldwork knows which row is yours.</p>","surface:utm-zone":"<h2>The UTM zone</h2><h3>What it does</h3><p>Some widgets measure in metres: Mean center, Compare point sets, Combined area, Convex hull, Snap to street network, Reachable corridor, Voronoi catchments and Network isochrone. Longitude and latitude are angles, not lengths. So these widgets first move every point onto a flat grid in metres. That move is a projection.</p><p>Fieldwork uses UTM. UTM divides the world into 60 zones, each six degrees of longitude wide, north and south of the equator. Inside its own zone, UTM keeps distances true to about one part in a thousand. Outside its zone, the error grows fast.</p><p>The zone you choose is part of how the answer is computed.</p><ul><li><strong>Two zones can both be reasonable.</strong> Gaborone, near 25.9\xB0 E, sits close to the line between zones 34 and 35.</li></ul><p>Measured in zone 34, an area there comes out about 0.6% different from the same area measured in zone 35.</p><ul><li><strong>That difference is not an error in either.</strong> It comes from the projection's scale, which grows with distance</li></ul><p>from the middle of the zone. It is small, but it does not average out: it moves every length, area and centre in the workflow the same way.</p><ul><li><strong>Coordinates from two zones cannot be mixed.</strong> The same easting and northing mean different places in different</li></ul><p>zones, and in both hemispheres.</p><h3>How to use it</h3><p>1. In <strong>Configure\u2026</strong>, check the zone. The dialog says which zone this workflow's points suggest: the one whose middle is closest to them. 2. Use the same zone in every step of the workflow that measures in metres. A run that finds two zones stops and names the steps and the zones. 3. Write the zone down with your results, so a reader can measure the same way.</p><h3>What it will not do</h3><ul><li>It will not choose a zone for an area that spans two. If your study area crosses a zone line and needs one frame,</li></ul><p>UTM is the wrong tool. An equal-area projection chosen for the region is better, and these widgets do not offer one.</p><ul><li>It will not convert coordinates from another projection or datum for you, other than WGS84 UTM zones.</li></ul>"};var c=g,x=e=>Object.hasOwn(c,e),h=e=>e.startsWith("surface:")?e.slice(8):void 0,y=e=>h(e)?`docs/surfaces/${h(e)}.md`:`docs/widgets/${e}.md`,A=e=>`https://github.com/fieldwork-app/fieldwork/blob/main/${y(e)}`;function C(e,s,n){let t=c[e];if(!t)return;let o=document.createElement("dialog");o.id="manual-dialog",o.setAttribute("aria-labelledby","manual-title"),o.innerHTML=`<div class="manual-head"><h2 id="manual-title">${n(s)}</h2><div class="inspector-actions"><button class="button" id="manual-detach-page">Detach</button><button class="button" id="manual-close">Close</button></div></div>`+f(e,t,n),document.body.append(o);let a=()=>{o.close(),o.remove()};o.querySelector("#manual-close").onclick=a,o.querySelector("#manual-detach-page").onclick=()=>{let r=o.scrollTop;a(),l({nodeType:e,title:s}),b(r)},o.addEventListener("cancel",r=>{r.preventDefault(),a()}),o.showModal()}var f=(e,s,n)=>`<article class="manual-body">${s}</article><p class="muted">This page is part of the manual carried in this build. Its source is <a href="${A(e)}" target="_blank" rel="noopener noreferrer">${n(y(e))}</a>`+(h(e)?".</p>":", and the widget's ontology entry points at it with <code>fw:userManual</code>.</p>"),d="fieldwork-widget-manual-detached-v1",m=()=>{try{let e=localStorage.getItem(d);return e?JSON.parse(e):void 0}catch{return}},l=e=>{try{e?localStorage.setItem(d,JSON.stringify(e)):localStorage.removeItem(d)}catch{}},w=p;function b(e=0){let s=m(),n=s?c[s.nodeType]:void 0,t=document.getElementById("widget-manual-float");if(!s||!n){t?.remove();return}t||(t=document.createElement("aside"),t.id="widget-manual-float",t.className="manual-float widget-manual-float",t.setAttribute("role","dialog"),t.setAttribute("aria-label",`Manual: ${s.title}`),document.body.append(t)),t.innerHTML=`<header class="manual-float-head"><strong>Manual \xB7 ${w(s.title)}</strong><button class="button small" id="widget-manual-float-close">Close</button></header><div class="manual-float-body">${f(s.nodeType,n,w)}</div>`,s.left!==void 0&&s.top!==void 0&&(t.style.left=`${Math.max(0,Math.min(s.left,innerWidth-120))}px`,t.style.top=`${Math.max(0,Math.min(s.top,innerHeight-60))}px`,t.style.right="auto",t.style.bottom="auto"),t.querySelector(".manual-float-body").scrollTop=e,t.querySelector("#widget-manual-float-close").onclick=()=>{l(void 0),b()};let o=t.querySelector(".manual-float-head");o.onpointerdown=a=>{if(a.target.closest("button"))return;let r=t.getBoundingClientRect(),v=a.clientX-r.left,k=a.clientY-r.top;o.setPointerCapture(a.pointerId),o.onpointermove=i=>{t.style.left=`${i.clientX-v}px`,t.style.top=`${i.clientY-k}px`,t.style.right="auto",t.style.bottom="auto"},o.onpointerup=()=>{o.onpointermove=null,o.onpointerup=null;let i=t.getBoundingClientRect(),u=m();u&&l({...u,left:Math.round(i.left),top:Math.round(i.top)})}}}export{c as a,x as b,A as c,C as d,b as e};
